		public static int GetSectorX(float x,float z)
		{
			int xx = (int)(x + z)/50;
			return xx;
		}
		
		public static int GetSectorZ(float x,float z)
		{
			int zz = (int)(x - z)/50;
			return zz;
		}
		
		public static int NearSector(int x1, int z1,int x2,int z2)
		{
			int dist = 8;
			if(x1==0 && z1==0) //in case not set...
			{
				return 1;
			}
			if(Math.Abs(x1-x2)<dist+1 && Math.Abs(z1-z2)<dist)
			{
				return 1;
			}
			return 0;
		}

