			GameUI.DrawText("(6) Blur Filter:"+blurfilter,10,330,20,Color.White);
			GameUI.DrawText("(7) Debug Info:"+Profile.debugon,10,360,20,Color.White);
			GameUI.DrawText("(8) No_Optimisations:"+no_opt,10,390,20,Color.White);
			GameUI.DrawText("(9) Global Illumination:"+globalillumination,10,420,20,Color.White);
			GameUI.DrawText("(0) Debug Lighting:"+debuglighting,10,450,20,Color.White);
			//
			GameUI.DrawText("(m) Music:"+GameUI.musicon,10,480,20,Color.White);
			GameUI.DrawText("(n) Audio:"+GameUI.audioon,10,510,20,Color.White);
			GameUI.DrawText("(r) Restart",10,540,20,Color.White);
			GameUI.DrawText("(f) Show FPS:"+GameUI.showfps,10,570,20,Color.White);
			GameUI.DrawText("(e) Environment Mapping:"+debugenvmapping,10,600,20,Color.White);
			GameUI.DrawText("(a) Auto Play/Demo:"+autoplay,10,630,20,Color.White);
			GameUI.DrawText("(z) Autooptimise:"+autooptimise,10,660,20,Color.White);
			GameUI.DrawText("(p) Dump Debug Data",10,690,20,Color.White);
			
			if(Raylib.IsKeyReleased(KeyboardKey.P))
			{
				int odebug = Profile.dumpdebug;
				Profile.dumpdebugdata();
				Profile.dumpdebug = odebug;
			}
			if(Raylib.IsKeyReleased(KeyboardKey.Z))
			{
				autooptimise++;
				if(autooptimise>4)
				{
					autooptimise = 0;
				}
			}
			
			if(Raylib.IsKeyReleased(KeyboardKey.A))
			{
				if(autoplay==0)
				{
					autoplay = 1;
				}
				else
				{
					autoplay = 0;
				}
			}
			if(Raylib.IsKeyReleased(KeyboardKey.E))
			{
				debugenvmapping = 1 - debugenvmapping;
			}
			
			if(Raylib.IsKeyReleased(KeyboardKey.Zero))
			{
				Program.debuglighting++;
				Program.debuglighting%=3;
				DoDebugLighting();
			}
			
			if(Raylib.IsKeyReleased(KeyboardKey.F))
			{
				GameUI.showfps = 1 - GameUI.showfps;
			}
			
			
			if(Raylib.IsKeyReleased(KeyboardKey.R))
			{
				for(int b=0;b<10;b++)
				{
					if(Building.buildingarray[b].hp>0)
					{
						Building.buildingarray[b].hp = 0;
					}
				}
			}
		
			if(Raylib.IsKeyReleased(KeyboardKey.M))
			{
				GameUI.musicon = 1 - GameUI.musicon;
			}
			if(Raylib.IsKeyReleased(KeyboardKey.N))
			{
				GameUI.audioon = 1 - GameUI.audioon;
			}
			if(Raylib.IsKeyReleased(KeyboardKey.Seven))
			{
				Profile.debugon = 1 - Profile.debugon;
			}
		
			if(Raylib.IsKeyReleased(KeyboardKey.Eight))
			{
				no_opt = 1 - no_opt;
			}
					
			if(Raylib.IsKeyReleased(KeyboardKey.Nine))
			{
				globalillumination = 1 - globalillumination;
			}
			
		
			//if(Raylib.IsKeyReleased(KeyboardKey.Six))
			//{
			//	debuglighting = 1 - debuglighting;
			//}
			
			if(Raylib.IsKeyReleased(KeyboardKey.Five))
			{
				debugambient = 1 - debugambient;
			}
					
			if(Raylib.IsKeyReleased(KeyboardKey.Four))
			{
				ambientocclusion = 1 - ambientocclusion;
			}
			
			if(Raylib.IsKeyReleased(KeyboardKey.Three))
			{
				maxlod++;
				maxlod%=3;
			}
			
			if(Raylib.IsKeyReleased(KeyboardKey.Two))
			{
				baselod++;
				baselod%=3;
			}
			
			if(Raylib.IsKeyReleased(KeyboardKey.Six))
			{
				blurfilter = 1 - blurfilter;
				
			}
			
		}
		
