		public static long ReleaseTime(int race, int i)
		{
			for(int j=0;j<20;j++)
			{
				if(race==1)
				{
					if(friendly_release[j]!=0 && i==j)
					{
						return friendly_release[j]*1000 - 1000;
					}
				}
				if(race==2)
				{
					if(enemy_release[j]!=0 && i==j)
					{
						return enemy_release[j]*1000 - 1000;
					}
				}
			}
			return 0;
		}
		
		public static int GuiFlashOnRelease(int race, int i, long time)
		{
			if(GameUI.sandbox!=0)
			{
				return 2;
			}
			if(IsReleased(race,i,time)==1)
			{
				if(time < ReleaseTime(race,i)+100)
				{
					GameUI.portraiton = GameUI.researchportraitid;
					Audio.Notification();
				}
				if(time % 650 < 325 || time > ReleaseTime(race,i)+3000)
				{
					if(time > ReleaseTime(race,i)+3000)
					{
						return 2;
					}
					return 1;
				}
				else
				{
					return 0;
				}
			}
			else
			{
				return 0;
			}
		}
		
		public static int IsReleased(int race,int i,long time)
		{
			for(int j=0;j<20;j++)
			{
				if(race==1)
				{
					if(friendly_release[j]!=0 && i==j)
					{
						if(time>friendly_release[j]*1000 - 1000)
						{
							return 1;
						}
					}
				}
				if(race==2)
				{
					if(enemy_release[j]!=0 && i==j)
					{
						if(time>enemy_release[j]*1000 - 1000)
						{
							return 1;
						}
					}
				}
			}
			if(GameUI.sandbox!=0)
			{
				return 1;
			}
			return 0;
		}
		
		
		static void config(string configfile)
		{
			try
			{
				string[] cdata = System.IO.File.ReadAllLines(configfile);
				for(int i=0;i<cdata.Length;i++)
				{
					if(cdata[i].IndexOf("=")>0)
					{
						switch(cdata[i].Substring(0,cdata[i].IndexOf("=")))
						{
							case "flyby": //28jul2025
								flybys = readint(cdata[i]);
								if(flybys!=0)
								{
									flybys = 1;
								}
							break;
							case "weather":
								doweather = readint(cdata[i]); //temporarily disable this in case it wasn't working properly - I experienced some crashes that I don't
								//know if the crashes were simply my PC is dying or if this was related.
								if(doweather!=0)
								{
									doweather = 1;
								}
								
							break;
							case "maxlod":
								maxlod = readint(cdata[i]);
								if(maxlod<0)
								{
									maxlod = 0;
								}
							break;
							case "baselod":
								baselod = readint(cdata[i]);
								if(baselod<0)
								{
									baselod = 0;
								}
							break;
							case "noenemies":
								noenemies = readint(cdata[i]);
							break;
							case "blurfilter":
								blurfilter = readint(cdata[i]);
							break;
							case "difficulty":
								difficulty = readint(cdata[i]);
								if(difficulty<1)
								{
									difficulty = 1;
								}
								if(difficulty>5)
								{
									difficulty = 5;
								}
							break;
							case "extrafoliage":
								GameUI.extrafoliage = readint(cdata[i]);
							break;
							case "randomspacescreenshot":
								randomspacescreenshot = readint(cdata[i]);
							break;
							case "randomgroundscreenshot":
								randomgroundscreenshot = readint(cdata[i]);
							break;
							//case "smoker":
								//smoker = readint(cdata[i]);
								//if(smoker!=0)
								//{
								//	smoker = 1;
								//}
							//break;
							case "textbackground":
								textbk = readint(cdata[i]);
								if(textbk!=0)
								{
									textbk = 1;
								}
							break;
							case "autoendgame":
								autoendgame = readint(cdata[i]);
								if(autoendgame<0)
								{
									autoendgame = 0;
								}
							break;
