								if(debuglighting!=0)
								{
									debuglighting = 1;
								}
							break;
							case "debugambient":
								debugambient = readint(cdata[i]);
								if(debugambient!=0)
								{
									debugambient = 1;
								}
							break;
							case "soundvolume":
								Audio.mvolume = (float)readint(cdata[i]) / 100f;
								if(Audio.mvolume<0)
								{
									Audio.mvolume=0;
								}
								if(Audio.mvolume>1)
								{
									Audio.mvolume = 1;
								}
							break;
							case "stresstest":
								if(readint(cdata[i])==1)
								{
									Profile.stresstest = 1;
								}
							break;
							case "dumpdebug":
								if(readint(cdata[i])==1)
								{
