			float ofogb = GameUI.fogb;
			float ofoga = GameUI.foga;
			float osnowing = 0;
			float ogroundfog = 0;//library change ^
			float battletime = 0;
			int skytime = 0;
			int snowday = 0;
			Vector3 oldcfwd = new Vector3(0,0,0);
			Vector3 oldcpos = new Vector3(0,0,0);
			float[] bushdist = new float[(resx/10)*(resy/10)];
			int treesdrawn = 0;
			Vector3 position = new Vector3(0,0,0);
			Vector2 screenpos = new Vector2(0,0);
			int consolemode = 0;
			exitmission = 0;
			//main game loop
			intromode = 1;
			if(autoplay!=0 || autorts!=0 || autospace!=0 || autoboth!=0)
			{
				intromode = 0;
			}
			else
			{
				autoplay = 1;
			}
			cdifficulty = difficulty;
			int omtime = 0;
			//int errortime = 0;
			string errormessage = "";
			float gametimeframe = 0;
			float logotime = 0;
			Texture2D logo = Raylib.LoadTexture("media/gui/logo.png");
			UnloadHelper.AddTexture(logo);
			float titlealpha = -23f;
			while(!Raylib.WindowShouldClose())
			{
				///At the start of the loop we handle some gamestates relating to automodes, weather and the like.
				fps = Raylib.GetFPS();
				gametimeframe+=ship.delta;
				titlealpha+=ship.delta*0.01f;
				if(titlealpha>1)
				{
					titlealpha = 1;
				}
				//if(gametimeframe > autoendgame * 60 && autoendgame!=0)
				//{
				//		Console.WriteLine("Game Ended Due to Thermal Safe Guard Because MY PC IS OLD And DYING");
				//		QUITGAME = 1;
				//}
				Profile.updatedebugdata();
				/*
				//not needed anymore.
				if(gamestate==GROUNDBATTLE)
				{
					if(fps<4)
					{
						errortime++;
						if(errortime>10)
						{
							errorcondition = 1;
							errormessage = "Error";
							Profile.dumpdebugdata();
						}
						else
						{
							errorcondition = 0;
						}
					}
					else
					{
						errortime = 0;
						errorcondition = 0;
					}
				}
				else
				{
					errorcondition = 0;
					errortime = 0;
				}
				*/
				if(lodchangetime>0) //this is to prevent flicker switching back and forth between lod levels 
				{
					lodchangetime--;
				}
				int tmpdummyrandom = ship.random.Next(0,10); //just to mess with the seed since I don't set it when I first create the random number generator....
				int changedstate = 0;
				if(Program.autoboth!=0)
				{
					if(ship.random.Next(0,2000)>1997)
					{
						Program.autorts = 1 - Program.autorts;
						changedstate = 1;
					}
				}
				if(GameUI.mousehasmoved!=0 || gamestate!=MENU)
				{
					omtime=0;
				}
				if(gamestate==MENU)
				{
					exitmission = 0;
					if(inprogress==0 && substate==0)
					{
						omtime++;
						if(omtime > 60 * 60)
						{
							intromode = 1;
							autoplay = 1;
							omtime = 0;
						}
					}
				}
				if(gamestate!=MENU && doweather!=0)
				{
					if(battletime > 60 * 60)
					{
						battletime=0;
						int startb = 0;
						if(skytime==-1)
						{
							startb = 1;
							
							if(tournamentmode!=0 && intromode==0 && autoplay==0)
							{
								difficulty = 4;
							}
							exitmission = 0;
						}
						if(skytime==3 && tournamentmode!=0 && difficulty>1 && intromode==0)
						{
							difficulty--;
						}
						skytime++;
						skytime%=4;
						if(skytime==0)
						{
							if(difficulty>1)
							{
								if(autoplay!=0 || autorts!=0 || autoboth!=0)
								{
									if(intromode==0)
									{
										difficulty--;
									}
								}
							}
							snowday++;
							snowday%=5;
							if(snowday==2)
							{
								GameUI.snowing = 1 - GameUI.snowing;
							}
						}
						if(skytime==0)
						{
							GameUI.groundfog = 0;
							if(snowday==2 || snowday==4)
							{
								GameUI.groundfog = 1;
							}
						}
						else
						{
							GameUI.groundfog = 0;
						}
						switch(skytime)
						{
							case 0: //dark brown
								GameUI.fogr = 0.35f;//0.62f;
								GameUI.fogg = 0.5f;//0.8f;
								GameUI.fogb = 0.5f;//0.86f;
								GameUI.foga = 80;
									
							break;
							case 1: //bright blue
								GameUI.fogr = 0.55f;//0.62f;
								GameUI.fogg = 0.79f;//0.8f;
								GameUI.fogb = 0.79f;//0.86f;
								GameUI.foga = 80;
							break;
							case 2: //light blue
								GameUI.fogr = 0.5f;//0.62f;
								GameUI.fogg = 0.58f;//0.8f;
								GameUI.fogb = 0.58f;//0.86f;
								GameUI.foga = 80;
							break;
							case 3: //orange
								GameUI.fogr = 0.91f;//0.62f;
								GameUI.fogg = 0.65f;//0.8f;
								GameUI.fogb = 0.37f;//0.86f;
								GameUI.foga = 80;
							break;
						}
						if(startb!=0)
						{
							ofogr = GameUI.fogr;
							ofogb = GameUI.fogb;
							ofogg = GameUI.fogg;
							ofoga = GameUI.foga;
							ogroundfog = GameUI.groundfog;
						}
					}
				}
				
				if(Program.autoenv!=0)
				{
					if(ship.random.Next(0,1000)>997)
					{
						changedstate = 1;
						Ground.SwitchTexture(ship.random.Next(0,4));
						GameUI.snowing = ship.random.Next(0,2);
						GameUI.groundfog = ship.random.Next(0,2);
						int sky = ship.random.Next(0,4);
						switch(sky)
						{
							case 0:
								GameUI.fogr = 0.42f;//0.62f;
								GameUI.fogg = 0.44f;//0.8f;
								GameUI.fogb = 0.38f;//0.86f;
								GameUI.foga = 80;
									
							break;
							case 1:
								GameUI.fogr = 0.55f;//0.62f;
								GameUI.fogg = 0.79f;//0.8f;
								GameUI.fogb = 0.79f;//0.86f;
								GameUI.foga = 80;
							break;
							case 2:
								GameUI.fogr = 0.5f;//0.62f;
								GameUI.fogg = 0.58f;//0.8f;
								GameUI.fogb = 0.58f;//0.86f;
								GameUI.foga = 80;
							break;
							case 3:
								GameUI.fogr = 0.91f;//0.62f;
								GameUI.fogg = 0.65f;//0.8f;
								GameUI.fogb = 0.37f;//0.86f;
								GameUI.foga = 80;
							break;
						}
					}
				}
				if(Program.autoplay!=0)
				{
					Program.autoplay++;
					if(Program.autoplay>60*240)
					{
						Program.autoplay = 1;
					}
				}
				if(Program.autospace!=0)
				{
					if(Program.autoplay>10)
					{
						if(Program.gamestate==Program.GROUNDBATTLE)
						{
							Program.gamestate = Program.SPACEBATTLE;
							GameUI.togglespace = 1;
						}
					}
				}
				fframe++;
				if(substate!=oosubstate || gamestate!=oogamestate)
				{
					oosubstate = substate;
					oogamestate = gamestate;
					transitiontime = 0.01f;
				}
				if(transitiontime>0)
				{
					transitiontime+=ship.delta;
				}
				if(transitiontime>40)
				{
					transitiontime = 0;
				}
				altframe++;
				//We handle screen resolution changes here.
				if(GameUI.otogglewindow!=-1)
				{
					Raylib.ToggleFullscreen();
					resx = Raylib.GetScreenWidth();
					resy = Raylib.GetScreenHeight();
					aspect = (float)resx / (float)resy;
					Raylib.UnloadRenderTexture(screentexture);
					Raylib.UnloadRenderTexture(ui);
					Raylib.UnloadRenderTexture(lasertexture);
					Raylib.UnloadRenderTexture(explosiontexture);
					Raylib.UnloadRenderTexture(firetexture);
					Raylib.UnloadRenderTexture(additivetexture);
					Raylib.UnloadRenderTexture(compositetexture);
					Raylib.UnloadRenderTexture(spacetexture);
					Raylib.UnloadRenderTexture(ambientocclusiontex);
					for(int i=0;i<maxlayer;i++)
					{
						Raylib.UnloadRenderTexture(layertexture[i]);
					}
					ui = Raylib.LoadRenderTexture(resx,resy);
					screentexture = Raylib.LoadRenderTexture(resx, resy);
					lasertexture = Raylib.LoadRenderTexture(resx,resy);
					explosiontexture = Raylib.LoadRenderTexture(resx,resy);
					firetexture = Raylib.LoadRenderTexture(resx,resy);
					additivetexture = Raylib.LoadRenderTexture(resx,resy);
					compositetexture = Raylib.LoadRenderTexture(resx,resy);
					spacetexture = Raylib.LoadRenderTexture(resx,resy);
					ambientocclusiontex = Raylib.LoadRenderTexture(resx / 2,resy / 2); //ambient occlusion tex is half size
					for(int i=0;i<maxlayer;i++)
					{
						layertexture[i] = Raylib.LoadRenderTexture(resx,resy);
					}
					bushdist = new float[(resx/10)*(resy/10)];
					GameUI.otogglewindow = -1;
				}
				if(wavedelay>0)
				{
					wavedelay-=ship.delta;
				}
				//delta timing values get set here. There's a lot of redundant variables but they're there for historical reasons.
				frametimer.Stop();
				long frametime = frametimer.ElapsedMilliseconds;
				frametimer.Reset();
				frametimer.Start();
				float delta = (float)frametime / (1000f / (float)targetfps);
				delta*= 60f / (float)targetfps;
				if(delta <0.5f)
				{
					delta = 0.5f;
				}
				if(delta > 20)
				{
					delta = 20;
				}
				if(Program.videomode!=0)
				{
					delta = 1;
				}
				if(autooptimise!=0)
				{
					if(delta<=1)
					{
						optimisefactor+=0.001f;
					}
					else
					{
						optimisefactor-=0.01f;
					}
				}
				else
				{
					optimisefactor = 14;
				}
				if(optimisefactor>14)
				{
					optimisefactor = 20;
				}
				if(optimisefactor<5)
				{
					optimisefactor = 5;
				}
				lasers.delta = delta;
				dust.delta = delta;
				explosion.delta = delta;
				ship.delta = delta;
				Unit.delta = delta;
				if(logotime<180)
				{
					logotime+=ship.delta;
					Raylib.BeginDrawing();
					Raylib.DrawRectangle(0,0,resx,resy,Color.Black);
					float logoalpha = logotime / 90f;
					if(logoalpha>1)
					{
						logoalpha = ((180f-logotime)/90f);
					}
					if(logoalpha<0)
					{
						logoalpha = 0;
					}
					if(logoalpha>1)
					{
						logoalpha = 1;
					}
					int logoi = (int)(logoalpha*255f);
					Raylib.DrawTextureEx(logo,new Vector2(GameUI.RescaleX((1920-400)/2),GameUI.RescaleY((1080-100)/2)),0,GameUI.gscale,new Color(255,255,255,logoi));
					Raylib.EndDrawing();
					continue;
				}
				//camera shake.
				if(gamestate!=MENU && togglepause==0){battletime+=ship.delta;}
				if(camerashake>0)
				{
					camshakex = ship.random.Next(-(int)camerashake-1,(int)camerashake+1);
					camshakey = ship.random.Next(-(int)camerashake-1,(int)camerashake+1);
					camerashake-=delta;
				}
				else
				{
					camerashake = 0;
					camshakex = 0;
					camshakey = 0;
				}
				//audio initialisation
				if(audiook<=0 && audiook>-300)
				{
					audiook = 1;
					Audio.InitAudio();
				}
				if(audiook!=0)
				{
					tmpdummyrandom = Audio.random.Next(0,10);
				}
				//audio music controller
				Audio.UpdateMusic();
				//debugging profile time stuff
				Profile.timer.Stop();
				Profile.timer.Reset();
				Profile.timer.Start();
				Profile.updatetime = 0;
				Profile.rendertime = 0;
				Profile.updatetime = Profile.timer.ElapsedMilliseconds;
				//some more 'gamestate' stuff
				if(gamestate!=ogamestate)
				{
					changedstate = 1;
					//"flush mouse" (since no such function exists)
					for(int i=0;i<10;i++)
					{
						Raylib.IsMouseButtonReleased(MouseButton.Left);
						Raylib.IsMouseButtonReleased(MouseButton.Right);
					}
					if(ogamestate==MENU && doweather!=0)
					{
						if(gamestate==GROUNDBATTLE)
						{
							battletime = 60*60+1;
							skytime = -1;
							if(autoplay!=0 || autorts!=0 || autoboth!=0)
							{
								difficulty = ship.random.Next(1,5);
							}
						}
					}
					ogamestate = gamestate;
				}
				//general input stuff - most of the important clicks and keypresses get stored here.
				GameUI.lclick = 0;
				GameUI.ldown = 0;
				GameUI.rclick = 0;
				GameUI.lpress = 0;
				if(Raylib.IsKeyReleased(KeyboardKey.F6))
				{
					renderframe = 1 - renderframe;
					if(videomode==0)
					{
						renderframe = 0;
					}
				}
				if(Raylib.IsKeyReleased(KeyboardKey.F1)) 
				{
					if(Program.gamestate==Program.GROUNDBATTLE)
					{
						consolemode = 1 - consolemode;
					}
				}
				if(Raylib.IsKeyReleased(KeyboardKey.F5)) 
				{
					if(Program.gamestate!=Program.MENU)
					{
						Program.demomode = 1 - Program.demomode;
						changedstate = 1;
						RTSInput.deselectbuildings();
						RTSInput.deselectall();
					}
				}
				if(Program.autoplay!=0 && Program.gamestate!=Program.MENU)
				{
					if(Program.demomode==0)
					{
						changedstate = 0;
					}
					Program.demomode = 1;
				}
				if(Raylib.IsKeyReleased(KeyboardKey.Tab)) //follow a different unit if Tab key pressed.
				{
					if(Program.demomode!=0)
					{
						followu = 0;
					}
				}
				if(Program.demomode == 1 && RTSInput.selectedunits!=null)
				{
					RTSInput.deselectall();
				}
				if(Program.gamestate==Program.MENU)
				{
					if(Program.demomode==1)
					{
						changedstate = 1;
					}
					Program.demomode = 0;
				}
				if(Program.videomode!=0)
				{
					GameUI.audioon = 0;
					GameUI.musicon = 0;
				}
				if(Raylib.IsMouseButtonPressed(MouseButton.Left))
				{
					GameUI.lpress = 1;
				}
				if(GameUI.JustClickedSelectionIcon<0)
				{
					GameUI.JustClickedSelectionIcon = 0;
				}
				if(Raylib.IsMouseButtonReleased(MouseButton.Left))
				{
					GameUI.lclick = 1;
					errormessage = "";
					if(GameUI.JustClickedSelectionIcon>0)
					{
						GameUI.lclick = 0;
						GameUI.JustClickedSelectionIcon = -1;
					}
				}
				if(Raylib.IsMouseButtonReleased(MouseButton.Right))
				{
					GameUI.rclick = 1;
				}
				if(Raylib.IsMouseButtonDown(MouseButton.Left))
				{
					GameUI.ldown = 1;
				}
				if(transitiontime>0)
				{
					GameUI.lclick = 0;
					GameUI.ldown = 0;
					GameUI.lpress = 0;
					GameUI.rclick = 0;
				}
				if(intromode!=0)
				{
					if(GameUI.lclick!=0 || GameUI.rclick!=0)
					{
						intromode = 0;
						exitmission = -1;
						difficulty = cdifficulty;
					}
				}
				if((demomode==1 || videomode==1) && Program.gamestate==Program.GROUNDBATTLE)
				{
					GameUI.lclick = 0;
					GameUI.ldown = 0;
					GameUI.rclick = 0;
					GameUI.lpress = 0;
				}
				if(videomode==1)
				{
					GameUI.sandbox = 1;
				}
				if(treetest!=0)
				{
					GameUI.sandbox = 1;
					demomode = 1;
				}
				if(renderframe!=0 && screenshot>60*240)
				{
					Program.QUITGAME = 1;
				}
				if(Program.QUITGAME!=0)
				{
					break;
				}
				//updating
				if(deploying>0)
				{
					deploying-=ship.delta;
				}
				ship.frame++;
				gframe++;
				gframe%=(60 * 40);
				//this next bit is for a type of demo mode if we're running in a very specific demo mode. Not really used.
				if(intromode!=0)
				{
					if(intromode<5)
					{
						for(int i=0;i<Building.buildingarray.Length;i++)
						{
							if(i!=4 && i!=5 && i!=1)
							{
								if(Building.buildingarray[i].hp>0)
								{
									Building.buildingarray[i].ohp = 1;
								}
								Building.buildingarray[i].hp = 0;
								
							}
						}
					}
					if(intromode<4000 && intromode%7==0)
					{
						GameUI.BuildUnit(1);
						GameUI.BuildUnit(1);
						GameUI.BuildUnit(1);
						GameUI.BuildUnit(11);
						GameUI.BuildUnit(11);
						if(intromode==600)
						{
							GameUI.BuildUnit(5);
							GameUI.BuildUnit(2);
							GameUI.BuildUnit(5);
							GameUI.BuildUnit(2);
							GameUI.BuildUnit(5);
							GameUI.BuildUnit(2);
						}
					}
					intromode++;
					if(intromode<4000 && intromode%10==0)
					{
						GameUI.BuildEnemy(1);
						GameUI.BuildEnemy(11);
						GameUI.BuildEnemy(11);
						GameUI.BuildEnemy(1);
						GameUI.BuildEnemy(11);
						GameUI.BuildEnemy(1);
						GameUI.BuildEnemy(1);
						GameUI.BuildEnemy(1);
						GameUI.BuildEnemy(1);
						GameUI.BuildEnemy(1);
						if(intromode==300)
						{
							GameUI.BuildEnemy(2);
							GameUI.BuildEnemy(4);
							GameUI.BuildEnemy(2);
							GameUI.BuildEnemy(4);
							GameUI.BuildEnemy(4);
							GameUI.BuildEnemy(2);
							GameUI.BuildEnemy(4);
							GameUI.BuildEnemy(2);
							GameUI.BuildEnemy(4);
						}
					}
					if(intromode==1200)
					{
						GameUI.BuildEnemy(6);
					}
					if(intromode>4000)
					{
						intromode = 1;
					}
				}
				if(videomode!=0 && (gframe % (60*9)==0))
				{
					for(int ii=0;ii<3;ii++)
					{
						GameUI.BuildEnemy(1);
						GameUI.BuildEnemy(1);
						GameUI.BuildEnemy(1);
						GameUI.BuildEnemy(1);
						GameUI.BuildEnemy(11);
						GameUI.BuildEnemy(11);
						GameUI.BuildEnemy(11);
						GameUI.BuildEnemy(1);
						GameUI.BuildEnemy(2);
						GameUI.BuildEnemy(2);
						GameUI.BuildEnemy(4);
						GameUI.BuildEnemy(4);
					}
					for(int ii=0;ii<2;ii++)
					{
						GameUI.BuildUnit(1);
						GameUI.BuildUnit(1);
						GameUI.BuildUnit(1);
						GameUI.BuildUnit(11);
						GameUI.BuildUnit(11);
						GameUI.BuildUnit(2);
						GameUI.BuildUnit(2);
						GameUI.BuildUnit(2);
					}
				}
				//this handles waves of enemies
				int gframe2 = 0;
				if(gamelength>60*10)
				{
					if(gframe % 300==0)
					{
						gframe2 = 1;
					}
				}
				if(gamestate!=MENU)
				{
					if(gamelength>6*60)
					{
						if(gamelength % 200==0)
						{
							//random? should it be random?
							{
								GameUI.BuildEnemy(6);
							}
						}
					}
				}
				//more enemy wave handling
				if(gframe==0 || gframe==1200 || gframe==600 || gframe==1800 || gframe2>0)
				{
					if(gamestate!=MENU)
					{
						wavenum++;
						qrs_preferred = ship.random.Next(-2,5);
						Program.deploy = 0;
						for(int i=0;i<wavenum;i++)
						{
							Program.deploy += ship.random.Next(1,7);
						}
						if(Program.deploy > 32 && gframe2<=0)
						{
							Program.deploy = 32;
						}
					}
					else
					{
						Program.deploy = 0;
						wavenum = 0;
					}
				}
				//in battle mode update states (updating ships/units etc)
				if(gamestate!=MENU)
				{
					if(togglepause==0)
					{
						if(Profile.stresstest!=0){Program.orbitalbombardment = 240;}
						ship.updateships();
						Unit.updateunits(camera);
						Unit.updateanimals(camera);
						
						if(gamestate==GROUNDBATTLE)
						{
							float ovolume = Audio.mvolume;
							Audio.mvolume = 0.1f;
							if(ship.random.Next(0,200)<4){Audio.Battle();}
							Audio.mvolume = ovolume;
						}
						Building.updatebuildings();
						if(orbitalbombardment>0)
						{
							orbitalbombardment-=ship.delta;
							//bomb the shit out of the player.......on the 'groundbattle'.......
							lasers.orbitalbombardment();
						}
						lasers.updatelasers(); //this has to come after - for the colour multiplier....
						explosion.campos = new Vector3(camera.Position.X,camera.Position.Y,camera.Position.Z);
						explosion.updateexplosions(); //29jul2025 moved inside this if block
						smoke.updatesmoke();
						spark.updatespark();
						debris.updatedebris();
						scorchmark.updatebombers();
						Scoring.updatescore();
					}
				}
				if(gamestate==MENU)
				{
					//we do this to clear out the stuff that might be left over if the user exits
					//a battle early...it prevents explosions from hanging around in the map after the battle ends when we restart a new battle
					explosion.updateexplosions(); 
					smoke.updatesmoke();
					spark.updatespark();
					debris.updatedebris();
					scorchmark.updatebombers();
					Scoring.updatescore();
				}
				//next bit is for handling the ships that get followed by the camera in the space battle
				if(followichangetime>0)
				{
					followichangetime-=ship.delta;
				}
				if(ship.shiparray[followi].hp<=0 && ship.frame > 45)
				{
					followichangetime=0;
					ship.frame = 240*3 + 1;
				}
				int ocamtype = camtype;
				float ozoomtype = zoomtype;
				if(ship.frame > 240* 3 && followichangetime<=0 && (Program.tutorial==0 || Program.tutorialstage>=7))
				{
					ship.frame = 0;
					followi++;
					followu = 0;
					followi%=ship.maxships;
					camtype = ship.random.Next(0,4);
					if(ocamtype==camtype)
					{
						camtype = ship.random.Next(0,4);
					}
					zoomtype = ship.random.Next(1,4);
					if(ozoomtype==zoomtype)
					{
						zoomtype = ship.random.Next(1,4);
					}
					//Program.msg = " ";
					if(ship.shiparray[followi].shiptype>1)
					{
						followichangetime = 300;
					}
				}
				if(Program.tutorial==0)
				{
					if(followi==0)
					{
						followi++;
					}
				}
				if(camtype>3)
				{
					camtype=0;
				}
				if(zoomtype>3)
				{
					zoomtype = 1;
				}
				//followi = 1;
				Profile.updatetime-=Profile.timer.ElapsedMilliseconds;
				//Game timer - used for measuring the battle length which is kind of our player's score in a battle.
				TimeSpan ts = gametimer.Elapsed;
				gamelength = gametimer.ElapsedMilliseconds / 1000; //seconds
				// Format and display the TimeSpan value.		
				if(ts.Hours>0 || ts.Minutes>0 || ts.Seconds>0 || ts.Milliseconds>0)
				{
					msg = Translation.translate("Time:")+String.Format("{0:00}:{1:00}:{2:00}", ts.Hours, ts.Minutes, ts.Seconds);// + " Score:"+(Scoring.score/10000);
					GameUI.survivaltime = msg;
					int gamelength = ts.Seconds + ts.Minutes * 60 + ts.Hours * 3600;
					if(Scenario.ms.mission_length!=-1)
					{
						if(gamelength > Scenario.ms.mission_length && GameUI.gameovertime==0)
						{
							GameUI.gameovertime = 1;
							GameUI.victory = 1;
						}
					}
					if(ts.Minutes>=10)
					{
						Scoring.EndGame();
						msg = Translation.translate("Time:")+String.Format("{0:00}:{1:00}:{2:00}", ts.Hours, ts.Minutes, ts.Seconds) + " Score:"+(Scoring.score/10000);
					}
					else
					{
						if(GameUI.gameovertime>0)
						{
							Scoring.score = 0;
						}
					}
				}
				if(GameUI.juststarted!=0) //we should be in ground battle.....
				{
					GameUI.juststarted = 0;
					camera.FovY = 45;
				}
				//really basic 2d menu handling....
				if(gamestate==MENU)
				{
					if(transitiontime==0 || transitiontime>20)
					{
						//Raylib.BeginDrawing();
						Raylib.BeginTextureMode(ui);
						Raylib.ClearBackground(Color.Black);
						GameUI.DoShitAndDrawInterface(camera);
						GameUI.Messages();
						Profile.drawdebuginfo();
						if(GameUI.showfps!=0)
						{
							GameUI.DrawText(""+Program.fps,GameUI.RescaleX(1790+55-20),GameUI.RescaleY(925+35),40,Color.Yellow);							
						}
						if(Profile.debugon==2){GameUI.DrawText("Load Models Time(ms):"+debuggingtime,260,540,60,Color.White);}
						if(errormessage!="")
						{
							GameUI.DrawText("Conflict 3049 - Error Occurred, Sorry about that. You'll have to restart the mission/scenario.",GameUI.RescaleX(resx/2),GameUI.RescaleY(resy/2),25,Color.White);														
						}
						Raylib.EndTextureMode();
						//Raylib.EndDrawing();
						if(transitiontime==0)
						{
							Raylib.BeginDrawing();
							//Raylib.BeginShaderMode(uitransitionshader);
							//float ttime = (float)transitiontime;
							//unsafe
							//{
							//	Raylib.SetShaderValueV(uitransitionshader,ui_transition,&ttime,ShaderUniformDataType.Float,1);
							//}
							Raylib.DrawTextureRec(ui.Texture, new Rectangle(0,0,resx,-resy), new Vector2(0,0),Color.White);				
							//Raylib.EndShaderMode();
							if(intromode!=0)
							{
								Raylib.DrawRectangle(0,0,resx,resy,Color.Black);
							}
							Raylib.EndDrawing();
						}
						continue;
					}
					if(transitiontime>0)
					{
						Raylib.BeginDrawing();
						Raylib.BeginShaderMode(uitransitionshader);
						float ttime = (float)transitiontime;
						unsafe
						{
							Raylib.SetShaderValueV(uitransitionshader,ui_transition,&ttime,ShaderUniformDataType.Float,1);
						}
						Raylib.DrawTextureRec(ui.Texture, new Rectangle(0,0,resx,-resy), new Vector2(0,0),Color.White);				
						Raylib.EndShaderMode();
						if(transitiontime<20)
						{
							Color ccc = new Color(0,0,0,(int)(transitiontime*255f/20f));
							Raylib.DrawRectangle(0,0,resx,resy,ccc);
						}
						else
						{
							float alpha = 255f*(20 - (transitiontime-20))/20f;
							if(alpha>255)
							{
								alpha = 255;
							}
							if(alpha<0)
							{
								alpha = 0;
							}
							Color ccc = new Color(0,0,0,(int)(alpha));
							Raylib.DrawRectangle(0,0,resx,resy,ccc);
							if(transitiontime>40)
							{
								transitiontime = 0;
							}
						}
						if(intromode!=0)
						{
							Raylib.DrawRectangle(0,0,resx,resy,Color.Black);
						}
						Raylib.EndDrawing();
						continue;
					}
					
				}
				//ground battle rendering and camera positioning
				
				if(gamestate==GROUNDBATTLE && GameUI.juststarted==0)
				{
					int cammoved = 0;
					float mwheel = Raylib.GetMouseWheelMove();
					Grass.oldcameraposition = new Vector3(camera.Position.X,camera.Position.Y,camera.Position.Z);
					if(mwheel!=0 && briefingframe<=0)
					{
						cammoved = 1;
					}
					else
					{
						mwheel = 0;
					}
					if(mwheel!=0)
					{
						Grass.oldcameraposition = new Vector3(10000,10000,10000);
					}
					if(GameUI.mx > 1200 && GameUI.my > 820 && GameUI.mx < 1560 && GameUI.my < 1040 && videomode==0)
					{
						camera2.FovY-=mwheel*5.0f;
						if(camera2.FovY<10)
						{
							camera2.FovY = 10;
						}
						if(camera2.FovY>45)
						{
							camera2.FovY=45;
						}
					}
					else
					{
						if(videomode==0)
						{
							camera.FovY-=mwheel*5.0f;
							if(camera.FovY<20)
							{
								camera.FovY = 20;
							}
							if(camera.FovY>45)
							{
								camera.FovY=45;
							}
							if(camera.FovY>35) //20250727 //library change, made 35
							{
								camera.FovY = 35;
							}
						}
					}
					//although this isn't needed I'm not deleting it in case it does serve some function that's long been lost from my memory.
					if(briefingframe>0 && videomode==0)
					{
						if(Program.togglepause==0){briefingframe-=ship.delta;}
						changedstate = 1;
						int[] npc = new int[3];
						npc[0] = -1;
						npc[1] = -1;
						npc[2] = -1;
						
						int jj = 0;
						for(int i=0;i<Unit.maxunits;i++)
						{
							if(Unit.unitarray[i].race==1 && Unit.unitarray[i].hp>0 && Unit.unitarray[i].shiptype==1 && npc[jj]==-1)
							{
								npc[jj]=i;
								jj++;
								if(jj>2)
								{
									break;
								}
							}
						}
						for(int i=0;i<3;i++)
						{
							if(npc[i]!=-1)
							{
								if(i==1)
								{
									Unit.unitarray[npc[i]].soldiertype = Unit.sergeant;
									Unit.unitarray[npc[i]].rank = "Sgt.";
									//Unit.unitarray[npc[i]].leader = npc[i];
									//Unit.unitarray[npc[0]].leader = npc[i];
									//Unit.unitarray[npc[2]].leader = npc[i];
								}
								if(i==0)
								{
									Unit.unitarray[npc[i]].soldiertype = Unit.medic;
									Unit.unitarray[npc[i]].rank = "Mdc.";
								}
								if(i==2)
								{
									Unit.unitarray[npc[i]].soldiertype = Unit.engineer;
									Unit.unitarray[npc[i]].rank = "Eng.";
								}
								Unit.unitarray[npc[i]].x = camera.Target.X + 20 * (i - 1) - 30;
								Unit.unitarray[npc[i]].z = camera.Target.Z + (20 * (i - 1)) + 25;
								Unit.unitarray[npc[i]].amode = 0;
								Unit.unitarray[npc[i]].angle = (float)Math.Atan2(-Unit.unitarray[npc[i]].z,Unit.unitarray[npc[i]].x) + 3.14159f/2f;
							}
						}	
						briefingframe = 0;
					}
					if(camera.FovY<=0)
					{
						camera.FovY = 45;
					}
					Program.ZOOM = camera.FovY;
					//handle a click on the mini map if we tell the camera to move to a new location.
					if(GameUI.cameramoveto!=0)
					{
						float mspeed = 1;
						float dist = 0;
						float ndist = 0;
						GameUI.cameramoveto = 0;
						float factor = 0.75f;
						int goleft = 0;
						int goright = 0;
						int goup = 0;
						int godown = 0;
						//this is because there's no obvious camerapick command like in blitz3d and the calculation to get the ground position is tricky for me....brain not working when I wrote this...so I did it this way instead
						for(int cloop=0;cloop<500;cloop++) //there's a reason we do it like this....to home in on it since moving in x and z different amounts will result motion along each axis...
						{
							if(cloop % 5==0)
							{
								goleft = 0;
								goright = 0;
								goup = 0;
								godown = 0;
							}
							//go left
							dist = (float)((GameUI.cameramovetox-camera.Target.X)*(GameUI.cameramovetox-camera.Target.X)+(GameUI.cameramovetoz-camera.Target.Z)*(GameUI.cameramovetoz-camera.Target.Z));	
							if(dist<10)
							{
								break;
							}
							if(cloop % 3==0)
							{
								mspeed = 1;
							}
							if(cloop % 3 ==2)
							{
								mspeed = 3;
							}
							if(cloop % 5==0)
							{
								mspeed = 5;
							}
							if(goleft==0)
							{
								while(true)
								{
									cammoved = 1;
									ndist = (float)((GameUI.cameramovetox-camera.Target.X)*(GameUI.cameramovetox-camera.Target.X)+(GameUI.cameramovetoz-camera.Target.Z)*(GameUI.cameramovetoz-camera.Target.Z));	
									if(ndist > dist)
									{
										//goleft = 1;
										unsafe
										{
											Raylib.CameraMoveRight(&camera,1f*mspeed*ship.delta,false);
										}
										break;
									}
									unsafe
									{
										Raylib.CameraMoveRight(&camera,-1f*mspeed*ship.delta,false);
									}
								}
							}
							dist = (float)((GameUI.cameramovetox-camera.Target.X)*(GameUI.cameramovetox-camera.Target.X)+(GameUI.cameramovetoz-camera.Target.Z)*(GameUI.cameramovetoz-camera.Target.Z));									
							if(goright==0)
							{
								while(true)
								{
									cammoved = 1;
									ndist = (float)((GameUI.cameramovetox-camera.Target.X)*(GameUI.cameramovetox-camera.Target.X)+(GameUI.cameramovetoz-camera.Target.Z)*(GameUI.cameramovetoz-camera.Target.Z));	
									if(ndist>dist)
									{
										//goright=1;
										unsafe
										{
											Raylib.CameraMoveRight(&camera,-1f*mspeed*ship.delta,false);
										}
										break;
									}
									unsafe
									{
										Raylib.CameraMoveRight(&camera,1f*mspeed*ship.delta,false);
									}
								}
							}
							dist = (float)((GameUI.cameramovetox-camera.Target.X)*(GameUI.cameramovetox-camera.Target.X)+(GameUI.cameramovetoz-camera.Target.Z)*(GameUI.cameramovetoz-camera.Target.Z));	
							if(goup==0)
							{
								while(true)
								{
									ndist = (float)((GameUI.cameramovetox-camera.Target.X)*(GameUI.cameramovetox-camera.Target.X)+(GameUI.cameramovetoz-camera.Target.Z)*(GameUI.cameramovetoz-camera.Target.Z));	
									if(ndist>dist)
									{
										//goup=1;
										unsafe
										{
											Raylib.CameraMoveUp(&camera,0.514496f*mspeed*ship.delta*factor);
											Raylib.CameraMoveForward(&camera,0.485071f*mspeed*ship.delta,false);
										}
										break;
									}
									unsafe
									{
										Raylib.CameraMoveUp(&camera,-0.514496f*mspeed*ship.delta*factor);
										Raylib.CameraMoveForward(&camera,-0.485071f*mspeed*ship.delta,false);
									}
									cammoved = 1;
								}
							}
							dist = (float)((GameUI.cameramovetox-camera.Target.X)*(GameUI.cameramovetox-camera.Target.X)+(GameUI.cameramovetoz-camera.Target.Z)*(GameUI.cameramovetoz-camera.Target.Z));	
							if(godown==0)
							{
								while(true)
								{
									ndist = (float)((GameUI.cameramovetox-camera.Target.X)*(GameUI.cameramovetox-camera.Target.X)+(GameUI.cameramovetoz-camera.Target.Z)*(GameUI.cameramovetoz-camera.Target.Z));	
									if(ndist>dist)
									{
										//godown = 1;
										unsafe
										{
											Raylib.CameraMoveUp(&camera,-0.514496f*mspeed*factor*ship.delta);
											Raylib.CameraMoveForward(&camera,-0.485071f*mspeed*ship.delta,false);
										}	
										break;
									}
									cammoved = 1;
									unsafe
									{
										Raylib.CameraMoveUp(&camera,0.514496f*mspeed*factor*ship.delta);
										Raylib.CameraMoveForward(&camera,0.485071f*mspeed*ship.delta,false);
									}
								}
							}
						}	
					}
					//mouse movement of camera (and wasd keys)
					if(changedstate==0)
					{
						cammovespeed+=0.012f;
						cammovespeed*=1.0025f;
						if(cammovespeed>2.5f)
						{
							cammovespeed = 2.5f;
						}
						if(cammovespeed<1.0f)
						{
							cammovespeed = 1.0f;
						}
						float movespeed = 8f * cammovespeed;
						if(GameUI.NoMoveCam==0)
						{
							if(Raylib.GetMouseX()<50 || Raylib.IsKeyDown(KeyboardKey.A) )
							{
								if((camera.Target.X)>-450)
								{
									cammoved = 1;
									unsafe
									{
											Raylib.CameraMoveRight(&camera,-1f*movespeed*ship.delta,false);
									}
								}
							}
							if(Raylib.GetMouseX()>Program.resx - 50  || Raylib.IsKeyDown(KeyboardKey.D))
							{
								if((camera.Target.X)<450)
								{
									unsafe
									{
											Raylib.CameraMoveRight(&camera,1f*movespeed*ship.delta,false);
									}
									cammoved = 1;
								}
							}
							float factor = 0.75f;
							if(Raylib.GetMouseY()<50  || Raylib.IsKeyDown(KeyboardKey.W))
							{
								if((camera.Target.Z)>-450)
								{
									unsafe
									{
										Raylib.CameraMoveUp(&camera,0.514496f*movespeed*ship.delta*factor);
										Raylib.CameraMoveForward(&camera,0.485071f*movespeed*ship.delta,false);
									}
									cammoved = 1;
								}
							}
							if(Raylib.GetMouseY()>Program.resy - 50 - (1 - Program.fullscreen)*50  || Raylib.IsKeyDown(KeyboardKey.S))
							{
								if((camera.Target.Z)<450)
								{
									cammoved = 1;
									unsafe
									{
										Raylib.CameraMoveUp(&camera,-0.514496f*movespeed*factor*ship.delta);
										Raylib.CameraMoveForward(&camera,-0.485071f*movespeed*ship.delta,false);
									}
								}
							}
						}
					}
					if(cammoved==0)
					{
						cammovespeed = 0;
					}
					Profile.rendertime = Profile.timer.ElapsedMilliseconds;
					//position camera appropriately
					if(changedstate!=0)
					{
						cammoved = 1;
						//camera position (static camera)
						otx = camera.Target.X ;
						oty = camera.Target.Y ;
						otz = camera.Target.Z ;
						tx = -200f;
						ty = 300;
						tz = 200f;
						pointatx = 0 ;
						pointaty = 0;
						pointatz = 0 ;
						//SetCameraXYZ(camera,tx,ty,tz);
						otx = camera.Target.X - camera.Position.X;
						oty = camera.Target.Y - camera.Position.Y;
						otz = camera.Target.Z - camera.Position.Z;
						camera.Target = new Vector3(tx,ty, tz);
						dd = Raymath.Vector3Subtract(camera.Target,camera.Position);
						unsafe
						{
							Raylib.CameraMoveForward(&camera,Raymath.Vector3Length(dd),false);
						}
						camera.Target = new Vector3(otx + camera.Position.X,oty + camera.Position.Y, otz + camera.Position.Z);
						camera.Target = new Vector3(pointatx,pointaty,pointatz);
						v1 = Raymath.Vector3Subtract(camera.Target,camera.Position);
						v1 = Raymath.Vector3Normalize(v1);
						v2 = new Vector3(0,0,0);
						unsafe
						{
							v2 = Raylib.GetCameraForward(&camera);
						}
						v11 = new Vector2(v1.X,v1.Z);
						v11 = Raymath.Vector2Normalize(v11);
						v22 = new Vector2(v2.X,v2.Z);
						v22 = Raymath.Vector2Normalize(v22);
						yaw = Raymath.Vector2Angle(v11,v22);
						unsafe
						{
							Raylib.CameraYaw(&camera,yaw,false);
						}
						changedstate = 0;
					}
					//Raylib.BeginDrawing();
					if(Program.demomode==0 && videomode==0){RTSInput.updatemouse(camera);}
					if(Program.autorts!=0)
					{
						if(ship.random.Next(0,2000)<9)
						{
							//if(RTSInput.selectedunits!=null)
							//{
								//int uu = RTSInput.selectedunits[0];
								GameUI.cameramovetox = ship.random.Next(-280,280);//Unit.unitarray[uu].x;
								GameUI.cameramovetoz = ship.random.Next(-280,280);//Unit.unitarray[uu].z;
								GameUI.cameramoveto = 1;
							//}
						}
					}
					//move the camera about in automode. 
					if(intromode!=0)
					{
						cammoved = 1;
						//camera position (static camera)
						pointatx = 0 ;
						pointaty = 0;
						pointatz = 0 ;
						tx = -50;
						ty = 0;
						tz = -50;
						pointatx = 300.0f * (float)Math.Sin((double)fframe * 0.002) - 250f * (float)Math.Cos((double)fframe * -0.0005);
						pointatz = 300.0f * (float)Math.Cos((double)fframe * 0.002) - 250f * (float)Math.Sin((double)fframe * -0.0005);
						pointaty = 5f;
						ty = pointaty + 10f;
						tx = pointatx + 150.0f * (float)Math.Sin((double)fframe * 0.002) - 75f * (float)Math.Cos((double)fframe * 0.003);
						tz = pointatz + 150.0f * (float)Math.Cos((double)fframe * 0.00075) - 75f * (float)Math.Sin((double)fframe * 0.0035);
						if(Program.demomode!=0)
						{
							if(gframe % 200==0)
							{
								followu = 0;
							}
						}
						if(gframe % (60*5)<90)
						{
							ty+=(float)(gframe % (60*7))/3f;
						}
						if(gframe %(60*5)>=90 && gframe%(60*5)<150)
						{
							ty+=50;
						}
						if(gframe % (60*5)>150)
						{
							ty+=(float)(420-(gframe % (60*6)))/4f;
							if(ty<0)
							{
								ty = 0;
							}
						}
						if(gframe % (60*6)==0)
						{
							camera.FovY = 15f + 5f * ship.random.Next(0,4);
						}
						if(gframe % (50*5)==0)
						{
							followu = 0;
						}
						if(followu==-1)
						{
							for(int jj=0;jj<150;jj++)
							{
								if(followu==0)
