						cfwd = Raymath.Vector3Normalize(Raylib.GetCameraForward(&camera));
					}
					//camnoshift means "camera has not shifted" which we use to determine if the camera has moved sufficiently to force a recheck of things inview/not in view of the camera.
					int camnoshift = 0;
					if(demomode!=0)
					{
						camnoshift = 1;
					}
					if((Raymath.Vector3Distance(cfwd,oldcfwd)>0.25 || Raymath.Vector3Distance(camera.Position,oldcpos)>5.5) && demomode!=0)
					{
						camnoshift = 0;
						oldcpos = new Vector3(camera.Position.X,camera.Position.Y,camera.Position.Z);
						oldcfwd = new Vector3(cfwd.X,cfwd.Y,cfwd.Z);	
					}
					
					//small bushes that hang around the bottom of the trees that we want to decide which are in view or not.
					if(demomode!=0 || (Grass.bushorderarray[0]==0 && Grass.bushorderarray[1]==0))
					{
						//sort the bushes by distance from camera....
						//first get their distance from the camera
						int numdrawn = 0;
						for(int i=0;i<Grass.maxbush;i++)
						{
							//check if we're within the view frustrum and exclude if not...
							erelc = Raymath.Vector3Normalize(Raymath.Vector3Subtract(Grass.bushpos[i],camera.Position)); //31jul2025 at library (culling bit)
							edotc = Raymath.Vector3DotProduct(erelc,cfwd); //cfwd should already be defined.
							if(edotc<minedotc) //minedotc should already be defined.
							{
								Grass.bushorderarray[i] = -1;
								continue;
							}
							else
							{
								Grass.bushorderarray[i] = i;
							}
							if(Grass.bushdrawn[i]!=0)
							{
								numdrawn++;
								if(demomode==0 || camnoshift==0)
								{
									Grass.bushdistfromcamera[i] = Raymath.Vector3Distance(Grass.bushpos[i],camera.Position);
								}
							}
							else
							{
								Grass.bushorderarray[i] = i;
							}
							if(i>0) //maybe don't include this...check how it looks first...
							{
								if(Grass.bushorderarray[i-1]!=-1 && Grass.bushorderarray[i]!=-1)
								{
									if(Grass.bushdistfromcamera[Grass.bushorderarray[i-1]]<Grass.bushdistfromcamera[Grass.bushorderarray[i]])
									{
										int tmpi = Grass.bushorderarray[i-1];
										Grass.bushorderarray[i - 1] = Grass.bushorderarray[i];
										Grass.bushorderarray[i] = tmpi;
									}
								}
							}
						}
						
						int imin = -1;
						float bmindist = -1;
						for(int i=0;i<300;i++)
						{
							if(Grass.bushorderarray[i]!=-1)
							{
								if(Grass.bushdistfromcamera[i]<bmindist || bmindist==-1)
								{
									bmindist = Grass.bushdistfromcamera[i];
									imin = i;
								}
							}
						}
						if(imin!=-1)
						{
							Grass.bushorderarray[imin] = Grass.bushorderarray[299];
							Grass.bushorderarray[299] = imin;
						}
					}
					int lotstorender = 0;
					//i took this out, but we might put it back in if we can get it working the way we want. might change it to a 2d vector function instead.
					/*
					if(demomode!=0 || videomode!=0)
					{
						float camdist = Raymath.Vector3Length(camera.Position); //from the origin
						if(camdist > 150)
						{
							//check if we're looking inwards....
							Vector3 cpos = Raymath.Vector3Normalize(camera.Position);
							cpos.X = - cpos.X;
							cpos.Z = - cpos.Z;
							cpos = Raymath.Vector3Normalize(cpos);
							float cdot = Raymath.Vector3DotProduct(cfwd,cpos);
							//if we're looking towards the origin then the value of this will
							//be greater than 0.7 approximately..
							if(cdot>0.7)
							{
								//make sure our camera.Position.Y is not significantly higher than camera.Target.Y
								float ydrop = camera.Position.Y - camera.Target.Y;
								if(ydrop < 20) //fairly flat looking
								{
									lotstorender = 1;
								}
							}
						}
					}
					*/
					if(Program.autorts!=0)
					{
						Program.demomode=0;
					}
					int total_entities = 0;
					int drawn_entities = 0;
					//when ambient occlusion is on we draw everything (the important stuff) a second time but output the normals rather than colours to the render texture
					for(int ambient=0;ambient<ambientocclusion+1;ambient++)
					{
						ambiento = ambient;
						ambientof = (float) ambient;
						if(ambient==1)
						{
								Raylib.BeginTextureMode(ambientocclusiontex);
								Raylib.ClearBackground(Color.White);
								Raylib.BeginMode3D(camera);
						}
						else
						{
							Raylib.BeginTextureMode(ambientocclusiontex);
							Raylib.ClearBackground(Color.White);
							Raylib.EndTextureMode();
						}
						if(Program.demomode!=0 || Program.videomode!=0)
						{
							cammoved = 1;
						}
						float groundfog = (9.0f * ogroundfog + (1.0f - (float) GameUI.groundfog))*0.1f; //library change
						if(doweather!=0)
						{
							groundfog = (299.0f * ogroundfog + (1.0f - (float) GameUI.groundfog))*(1f/300f); //library change
						}
						ogroundfog = groundfog; //library change
						//set uniforms that won't change //23jul2025
						//units
						int orace = -1;
						int oshiptype = -1;
						float envmapping = debugenvmapping;
						//Yeah in this next big block we go through and set all the uniforms for all the shaders that are about to be used.
						//So we don't have to do them one at a time for each element.
						for(int i=0;i<Unit.maxunits;i++)
						{
							if(Unit.unitarray[i].race!=orace || Unit.unitarray[i].shiptype!=oshiptype)
							{
								orace = Unit.unitarray[i].race;
								oshiptype = Unit.unitarray[i].shiptype;
								Raylib.BeginShaderMode(Unit.unitarray[i].shader);
								unsafe
								{
									Raylib.SetShaderValueMatrix(Unit.unitarray[i].shader,Unit.unitarray[i].projectionMatrix,Raylib.GetCameraProjectionMatrix(&camera, Program.aspect));
									Raylib.SetShaderValueMatrix(Unit.unitarray[i].shader,Unit.unitarray[i].viewMatrix,Raylib.GetCameraViewMatrix(&camera));
									Raylib.SetShaderValueV(Unit.unitarray[i].shader,Unit.unitarray[i].eyepos,&camera.Position,ShaderUniformDataType.Vec3,3);
									Raylib.SetShaderValueV(Unit.unitarray[i].shader,Unit.unitarray[i].ambientocclusion,&ambientof,ShaderUniformDataType.Float,1);
									Raylib.SetShaderValueV(Unit.unitarray[i].shader,Unit.unitarray[i].groundfog,&groundfog,ShaderUniformDataType.Float,1);
									Raylib.SetShaderValueV(Unit.unitarray[i].shader,Unit.unitarray[i].fogr,&fogr,ShaderUniformDataType.Float,1);
									Raylib.SetShaderValueV(Unit.unitarray[i].shader,Unit.unitarray[i].fogg,&fogg,ShaderUniformDataType.Float,1);
									Raylib.SetShaderValueV(Unit.unitarray[i].shader,Unit.unitarray[i].fogb,&fogb,ShaderUniformDataType.Float,1);
