								Raylib.SetShaderValueV(Unit.animals[iii].shader,Unit.animals[iii].ambientocclusion,&ambientof,ShaderUniformDataType.Float,1);
								Raylib.SetShaderValueV(Unit.animals[iii].shader,Unit.animals[iii].groundfog,&groundfog,ShaderUniformDataType.Float,1);
								Raylib.SetShaderValueV(Unit.animals[iii].shader,Unit.animals[iii].fogr,&fogr,ShaderUniformDataType.Float,1);
								Raylib.SetShaderValueV(Unit.animals[iii].shader,Unit.animals[iii].fogg,&fogg,ShaderUniformDataType.Float,1);
								Raylib.SetShaderValueV(Unit.animals[iii].shader,Unit.animals[iii].fogb,&fogb,ShaderUniformDataType.Float,1);
								Raylib.SetShaderValueV(Unit.animals[iii].shader,Unit.animals[iii].foga,&foga,ShaderUniformDataType.Float,1);
								Raylib.SetShaderValueV(Unit.animals[iii].shader,Unit.animals[iii].envmapping,&envmapping,ShaderUniformDataType.Float,1);								
							}
							Raylib.EndShaderMode();
						}
						//obstacles
						for(int i=0;i<Obstacle.maxobstacles;i++)
