								{
									Raylib.SetShaderValueMatrix(Obstacle.obstaclearray[i].shader,Obstacle.obstaclearray[i].projectionMatrix,Raylib.GetCameraProjectionMatrix(&camera, Program.aspect));
									Raylib.SetShaderValueMatrix(Obstacle.obstaclearray[i].shader,Obstacle.obstaclearray[i].viewMatrix,Raylib.GetCameraViewMatrix(&camera));
									Raylib.SetShaderValueV(Obstacle.obstaclearray[i].shader,Obstacle.obstaclearray[i].ambientocclusion,&ambientof,ShaderUniformDataType.Float,1);								
									Raylib.SetShaderValueV(Obstacle.obstaclearray[i].shader,Obstacle.obstaclearray[i].groundfog,&groundfog,ShaderUniformDataType.Float,1);
									Raylib.SetShaderValueV(Obstacle.obstaclearray[i].shader,Obstacle.obstaclearray[i].fogr,&fogr,ShaderUniformDataType.Float,1);
									Raylib.SetShaderValueV(Obstacle.obstaclearray[i].shader,Obstacle.obstaclearray[i].fogg,&fogg,ShaderUniformDataType.Float,1);
									Raylib.SetShaderValueV(Obstacle.obstaclearray[i].shader,Obstacle.obstaclearray[i].fogb,&fogb,ShaderUniformDataType.Float,1);
									Raylib.SetShaderValueV(Obstacle.obstaclearray[i].shader,Obstacle.obstaclearray[i].foga,&foga,ShaderUniformDataType.Float,1);
									Raylib.SetShaderValueV(Obstacle.obstaclearray[i].shader,Obstacle.obstaclearray[i].envmapping,&envmapping,ShaderUniformDataType.Float,1);
								}
								Raylib.EndShaderMode();	
								break;
							}
						}
						for(int i=0;i<Obstacle.maxobstacles;i++)
						{
							if(Obstacle.obstaclearray[i].razorwire!=0)
							{								
								Raylib.BeginShaderMode(Obstacle.obstaclearray[i].shader);
								unsafe
								{
									Raylib.SetShaderValueMatrix(Obstacle.obstaclearray[i].shader,Obstacle.obstaclearray[i].projectionMatrix,Raylib.GetCameraProjectionMatrix(&camera, Program.aspect));
									Raylib.SetShaderValueMatrix(Obstacle.obstaclearray[i].shader,Obstacle.obstaclearray[i].viewMatrix,Raylib.GetCameraViewMatrix(&camera));
									Raylib.SetShaderValueV(Obstacle.obstaclearray[i].shader,Obstacle.obstaclearray[i].ambientocclusion,&ambientof,ShaderUniformDataType.Float,1);								
									Raylib.SetShaderValueV(Obstacle.obstaclearray[i].shader,Obstacle.obstaclearray[i].groundfog,&groundfog,ShaderUniformDataType.Float,1);
