							Raylib.SetShaderValueMatrix(Grass.bushshader,Grass.bprojectionMatrix,Raylib.GetCameraProjectionMatrix(&camera, Program.aspect));
							Raylib.SetShaderValueMatrix(Grass.bushshader,Grass.bviewMatrix,Raylib.GetCameraViewMatrix(&camera));
							Raylib.SetShaderValueV(Grass.bushshader,Grass.bgroundfog,&groundfog,ShaderUniformDataType.Float,1);
							Raylib.SetShaderValueV(Grass.bushshader,Grass.bfogr,&fogr,ShaderUniformDataType.Float,1);
							Raylib.SetShaderValueV(Grass.bushshader,Grass.bfogg,&fogg,ShaderUniformDataType.Float,1);
							Raylib.SetShaderValueV(Grass.bushshader,Grass.bfogb,&fogb,ShaderUniformDataType.Float,1);
							Raylib.SetShaderValueV(Grass.bushshader,Grass.bfoga,&foga,ShaderUniformDataType.Float,1);
							Raylib.SetShaderValueV(Grass.bushshader,Grass.benvmapping,&envmapping,ShaderUniformDataType.Float,1);
							Raylib.SetShaderValueV(Grass.bushshader,Grass.bambientocclusion,&ambientof,ShaderUniformDataType.Float,1);
						}
						Raylib.EndShaderMode();						
						//alientrees
						Raylib.BeginShaderMode(alientree.cshader);
