						{
							Raylib.SetShaderValueMatrix(alientree.cshader,alientree.cprojectionMatrix,Raylib.GetCameraProjectionMatrix(&camera, Program.aspect));
							Raylib.SetShaderValueMatrix(alientree.cshader,alientree.cviewMatrix,Raylib.GetCameraViewMatrix(&camera));
							Raylib.SetShaderValueV(alientree.cshader,alientree.cgroundfog,&groundfog,ShaderUniformDataType.Float,1);
							Raylib.SetShaderValueV(alientree.cshader,alientree.cfogr,&fogr,ShaderUniformDataType.Float,1);
							Raylib.SetShaderValueV(alientree.cshader,alientree.cfogg,&fogg,ShaderUniformDataType.Float,1);
