							Raylib.SetShaderValueV(alientree.cshader,alientree.ambientocclusion,&ambientof,ShaderUniformDataType.Float,1);
						}
						Raylib.EndShaderMode();						
						//lasers
						Raylib.BeginShaderMode(lasers.rshader);
						unsafe
						{
							Raylib.SetShaderValueMatrix(lasers.rshader,lasers.rprojectionMatrix,Raylib.GetCameraProjectionMatrix(&camera, Program.aspect));
							Raylib.SetShaderValueMatrix(lasers.rshader,lasers.rviewMatrix,Raylib.GetCameraViewMatrix(&camera));
						}
						Raylib.EndShaderMode();
						Raylib.BeginShaderMode(lasers.gshader);
						unsafe
						{
							Raylib.SetShaderValueMatrix(lasers.gshader,lasers.gprojectionMatrix,Raylib.GetCameraProjectionMatrix(&camera, Program.aspect));
							Raylib.SetShaderValueMatrix(lasers.gshader,lasers.gviewMatrix,Raylib.GetCameraViewMatrix(&camera));
						}
						Raylib.EndShaderMode();

						//ground
						Raylib.BeginShaderMode(Ground.shader);
						unsafe
						{
							Raylib.SetShaderValueV(Ground.shader,Ground.ambientocclusion,&ambientof,ShaderUniformDataType.Float,1);
							Raylib.SetShaderValueV(Ground.shader,Ground.snowing,&issnowing,ShaderUniformDataType.Float,1);
							Raylib.SetShaderValueV(Ground.shader,Ground.groundfog,&groundfog,ShaderUniformDataType.Float,1);
							Raylib.SetShaderValueV(Ground.shader,Ground.fogr,&fogr,ShaderUniformDataType.Float,1);
							Raylib.SetShaderValueV(Ground.shader,Ground.fogg,&fogg,ShaderUniformDataType.Float,1);
							Raylib.SetShaderValueV(Ground.shader,Ground.fogb,&fogb,ShaderUniformDataType.Float,1);
							Raylib.SetShaderValueV(Ground.shader,Ground.foga,&foga,ShaderUniformDataType.Float,1);
							Raylib.SetShaderValueMatrix(Ground.shader,Ground.projectionMatrix,Raylib.GetCameraProjectionMatrix(&camera, Program.aspect));
							Raylib.SetShaderValueMatrix(Ground.shader,Ground.viewMatrix,Raylib.GetCameraViewMatrix(&camera));
							Raylib.SetShaderValueV(Ground.shader,Ground.eyepos,&camera.Position,ShaderUniformDataType.Vec3,3);
