							Raylib.SetShaderValueMatrix(Ground.skyshader,Ground.skyviewMatrix,Raylib.GetCameraViewMatrix(&camera));
							Raylib.SetShaderValueV(Ground.skyshader,Ground.skyfogr,&fogr,ShaderUniformDataType.Float,1);
							Raylib.SetShaderValueV(Ground.skyshader,Ground.skyfogg,&fogg,ShaderUniformDataType.Float,1);
							Raylib.SetShaderValueV(Ground.skyshader,Ground.skyfogb,&fogb,ShaderUniformDataType.Float,1);
							Raylib.SetShaderValueV(Ground.skyshader,Ground.skyfoga,&foga,ShaderUniformDataType.Float,1);
							
						}
