						//scorchmarks
						Raylib.BeginShaderMode(scorchmark.cshader);
						unsafe
						{
							Raylib.SetShaderValueMatrix(scorchmark.cshader,scorchmark.cprojectionMatrix,Raylib.GetCameraProjectionMatrix(&camera, Program.aspect));
							Raylib.SetShaderValueMatrix(scorchmark.cshader,scorchmark.cviewMatrix,Raylib.GetCameraViewMatrix(&camera));
							Raylib.SetShaderValueV(scorchmark.cshader,scorchmark.cgroundfog,&groundfog,ShaderUniformDataType.Float,1);
							Raylib.SetShaderValueV(scorchmark.cshader,scorchmark.cfogr,&fogr,ShaderUniformDataType.Float,1);
							Raylib.SetShaderValueV(scorchmark.cshader,scorchmark.cfogg,&fogg,ShaderUniformDataType.Float,1);
							Raylib.SetShaderValueV(scorchmark.cshader,scorchmark.cfogb,&fogb,ShaderUniformDataType.Float,1);
							Raylib.SetShaderValueV(scorchmark.cshader,scorchmark.cfoga,&foga,ShaderUniformDataType.Float,1);
						}
						Raylib.SetShaderValueMatrix(scorchmark.cshader,scorchmark.cmodelMatrix,scorchmark.cmodel.Transform);
						Raylib.EndShaderMode();						
						Raylib.BeginShaderMode(scorchmark.bshader);
						unsafe
						{
							Raylib.SetShaderValueMatrix(scorchmark.bshader,scorchmark.bprojectionMatrix,Raylib.GetCameraProjectionMatrix(&camera, Program.aspect));
							Raylib.SetShaderValueMatrix(scorchmark.bshader,scorchmark.bviewMatrix,Raylib.GetCameraViewMatrix(&camera));
							Raylib.SetShaderValueV(scorchmark.bshader,scorchmark.bgroundfog,&groundfog,ShaderUniformDataType.Float,1);
							Raylib.SetShaderValueV(scorchmark.bshader,scorchmark.bfogr,&fogr,ShaderUniformDataType.Float,1);
							Raylib.SetShaderValueV(scorchmark.bshader,scorchmark.bfogg,&fogg,ShaderUniformDataType.Float,1);
							Raylib.SetShaderValueV(scorchmark.bshader,scorchmark.bfogb,&fogb,ShaderUniformDataType.Float,1);
							Raylib.SetShaderValueV(scorchmark.bshader,scorchmark.bfoga,&foga,ShaderUniformDataType.Float,1);
						}
						Raylib.EndShaderMode();
						//unit selections
						Raylib.BeginShaderMode(Unit.cshader);
