							Raylib.SetShaderValueMatrix(Unit.cshader,Unit.cviewMatrix,Raylib.GetCameraViewMatrix(&camera));
						}
						Raylib.EndShaderMode();
						Raylib.BeginShaderMode(Building.cshader);
						unsafe
						{
							Raylib.SetShaderValueMatrix(Building.cshader,Building.cprojectionMatrix,Raylib.GetCameraProjectionMatrix(&camera, Program.aspect));
							Raylib.SetShaderValueMatrix(Building.cshader,Building.cviewMatrix,Raylib.GetCameraViewMatrix(&camera));
						}
						Raylib.EndShaderMode();
						//smoke
						Raylib.BeginShaderMode(smoke.cshader);
						unsafe
						{
							Raylib.SetShaderValueMatrix(smoke.cshader,smoke.cprojectionMatrix,Raylib.GetCameraProjectionMatrix(&camera, Program.aspect));
							Raylib.SetShaderValueMatrix(smoke.cshader,smoke.cviewMatrix,Raylib.GetCameraViewMatrix(&camera));
						}
						
						Raylib.EndShaderMode();
						//sparks
						Raylib.BeginShaderMode(spark.cshader);
						unsafe
						{
							Raylib.SetShaderValueMatrix(spark.cshader,spark.cprojectionMatrix,Raylib.GetCameraProjectionMatrix(&camera, Program.aspect));
							Raylib.SetShaderValueMatrix(spark.cshader,spark.cviewMatrix,Raylib.GetCameraViewMatrix(&camera));
						}
						Raylib.EndShaderMode();
						int drewlast = 0;
						//layers are really only used for RTS view, for immersive view we do most of the stuff all on one layer.
						//each layer we draw into a different rendertexture and then combine them later (stack them on top of each other)
						for(int layer=0;layer<maxlayer;layer++)
						{
							//a few little optimisations that say "don't draw a layer if it hasn't changed and we haven't moved"
							if(ambient==0)
							{
								if(layer==0 && cammoved==0 && Program.demomode==0 && Program.videomode==0) //we can reuse the old texture
								{
									continue;
								}
								if(layer==1 && cammoved==0 && Program.demomode==0 && Program.videomode==0) //we can reuse the old texture
								{
									if(scorchmark.oldelement==scorchmark.newelement)
									{
										continue;
									}
									scorchmark.oldelement = scorchmark.newelement;
								}
								
								if(layer==4 && cammoved==0 && Program.demomode==0 && Program.videomode==0)
								{
									if(explosion.changed==0)
									{
										continue;
									}
								}
								if(layer==5 && cammoved==0 && Program.demomode==0 && Program.videomode==0)
								{
									if(smoke.changed==0)
									{
										continue;
									}
								}
								Raylib.BeginTextureMode(layertexture[layer]);
								if(layer==0 || ((demomode!=0 || videomode!=0) && layer==3))
								{
									Raylib.ClearBackground(new Color(ofogr,ofogg,ofogb,1));
								}
								else
								{
									Raylib.ClearBackground(new Color(0,0,0,0));
								}
								Raylib.BeginMode3D(camera);
							}
							//draw the ground and sky
							if((layer==3 && (Program.demomode==1 || Program.videomode==1)) || (layer==0 && Program.demomode==0 && Program.videomode==0))//ground
							{
								Profile.shadertime[0]=Profile.timer.ElapsedMilliseconds;	
								if(Ground.useshader!=0)
								{
									//if(Ground.transformset==0)
									//{
									int skydrawn = 0;
									for(float xx=-40;xx<=40;xx+=40)
									{
										for(float zz=-40;zz<=40;zz+=40)
										{
											if(Program.recordframe!=0)
											{
												Program.outtxt+="BEGIN" + Environment.NewLine;
												Program.outtxt+=Ground.objfile + Environment.NewLine;
												Program.outtxt+=Ground.texfile + Environment.NewLine;
												Program.outtxt+=Ground.specfile + Environment.NewLine;
												Program.outtxt+=xx+Environment.NewLine;
												Program.outtxt+="0"+Environment.NewLine;
												Program.outtxt+=zz+Environment.NewLine;
												Program.outtxt+="0"+Environment.NewLine;
												Program.outtxt+="30"+Environment.NewLine;
												Program.outtxt+="24"+Environment.NewLine;
												Program.outtxt+="30"+Environment.NewLine;
												Program.outtxt+="END" + Environment.NewLine;
											}
											Ground.model.Transform = Raymath.MatrixIdentity();
											Ground.model.Transform = Raymath.MatrixMultiply(Raymath.MatrixScale(30,1,30),Ground.model.Transform);
											Ground.model.Transform = Raymath.MatrixMultiply(Raymath.MatrixTranslate(xx,-1f,zz),Ground.model.Transform);
											Ground.transformset = 1;
											//}
											Raylib.BeginShaderMode(Ground.shader);
											float shadow = 0;
												
											unsafe
											{
												Raylib.SetShaderValueV(Ground.shader,Ground.shadow,&shadow,ShaderUniformDataType.Float,1);
												Raylib.SetShaderValueMatrix(Ground.shader,Ground.modelMatrix,Ground.model.Transform);
											}
											Raylib.EndShaderMode();
											
											unsafe
											{	
												Raylib.DrawMesh(Ground.model.Meshes[0],Ground.model.Materials[0],Ground.model.Transform);
											}
											drawn_entities++;
											//sky model
											if((Program.demomode!=0 || Program.videomode!=0) && ambient==0 && skydrawn==0)
											{
												skydrawn = 1;
												Ground.skymodel.Transform = Raymath.MatrixIdentity();
												Ground.skymodel.Transform = Raymath.MatrixMultiply(Raymath.MatrixScale(1.4f,2,1.4f),Ground.skymodel.Transform);
												Ground.skymodel.Transform = Raymath.MatrixMultiply(Raymath.MatrixTranslate(camera.Position.X*0.7f,0,camera.Position.Z*0.7f),Ground.skymodel.Transform);
												Ground.transformset = 1;
												//
												Raylib.BeginShaderMode(Ground.skyshader);
												shadow = 0;
												float step = 1;
												{
													unsafe
													{
														Raylib.SetShaderValueV(Ground.skyshader,Ground.skystep,&step,ShaderUniformDataType.Float,1);
														Raylib.SetShaderValueMatrix(Ground.skyshader,Ground.skymodelMatrix,Ground.skymodel.Transform);
													}
													Raylib.EndShaderMode();
													
													unsafe
													{	
														Raylib.DrawMesh(Ground.skymodel.Meshes[0],Ground.skymodel.Materials[0],Ground.skymodel.Transform);
													}
													drawn_entities++;
												}
											}
										}
									}
								}
								Profile.shadertime[0]=-Profile.timer.ElapsedMilliseconds;	
							}
							//draw the scorch marks and other things that are right on top of the ground layer and are flat.
							if((layer==1 && Program.demomode==0 && Program.videomode==0) || (layer==3 && (Program.demomode==1 || Program.videomode==1)))//scorches
							{
								Profile.shadertime[1]=Profile.timer.ElapsedMilliseconds;	
								//Scorches....
								if(ambient==0 && treetest==0)
								{
									Raylib.BeginBlendMode(BlendMode.Alpha);
									//alltransforms = new Matrix4x4[scorchmark.maxcreated];
									//instances = 0;
									for(int i=0;i<=scorchmark.maxcreated;i++)
									{
										if(scorchmark.scorches[i].y<0)
										{
											continue;
										}
										drewlast = 0;
										if((cammoved==0 || camnoshift!=0) && scorchmark.scorches[i].inview==0)
										{
											continue;
										}
										scorchmark.scorches[i].inview = 0;
										screenpos = Raylib.GetWorldToScreen(scorchmark.scorches[i].position, camera);
										if(drewlast==0)
										{
											if(screenpos.X<-resx/2 || screenpos.X>resx+resx/2 || screenpos.Y<-resy/2 || screenpos.Y>resy+resy/2)
											{
												scorchmark.scorches[i].inview = 0;
												continue;
											}
											if(videomode==0 && demomode==0)
											{
												if(screenpos.X<0 || screenpos.X>resx || screenpos.Y<0 || screenpos.Y>resy+resy/4)
												{
													scorchmark.scorches[i].inview = 0;
													continue;
												}
												if(NearSector(scorchmark.scorches[i].sectorx,scorchmark.scorches[i].sectorz,camera_sectorx,camera_sectorz)==0)
												{
													continue;
												}
											}
											else
											{
												//erelc
												//erelc
												float dist = Raymath.Vector3Distance(scorchmark.scorches[i].position,camera.Position);
												if(dist>350)
												{
													if(no_opt==0)
													{
														continue;
													}
												}
												if(dist>200)
												{
													if(screenpos.X<0 || screenpos.X>resx || screenpos.Y<0 || screenpos.Y>resy)
													{
														continue;
													}
												}
												if(camnoshift!=0)
												{
													int bx = (int)(screenpos.X/10);
													int by = (int)(screenpos.Y/10);
													if(bx>=0 && by>=0 && bx<resx/10 && by<resy/10)
													{
														if(bushdist[bx+by*(resx/10)]!=0 && bushdist[bx+by*(resx/10)]<dist)
														{
															continue;
														}
													}
													if(dist>150 && treesdrawn>15)
													{
														continue;
													}
												}	
											
												erelc = Raymath.Vector3Normalize(Raymath.Vector3Subtract(scorchmark.scorches[i].position,camera.Position));
												edotc = Raymath.Vector3DotProduct(erelc,cfwd);
												if(edotc<minedotc)
												{
													if(edotc<0)
													{
														continue;
													}
													if(dist>50)
													{
														continue;
													}
													
												}
											}
										}
										scorchmark.scorches[i].y = 0.01f;
										float msc = 7.5f * scorchmark.scorches[i].scale;
										if(scorchmark.scorches[i].transformset==0)
										{
											scorchmark.cmodel.Transform = Raymath.MatrixIdentity();
											scorchmark.cmodel.Transform = Raymath.MatrixMultiply(Raymath.MatrixScale(msc,msc,msc),scorchmark.cmodel.Transform);
											scorchmark.cmodel.Transform = Raymath.MatrixMultiply(Raymath.MatrixTranslate(scorchmark.scorches[i].x/msc,(scorchmark.scorches[i].y+scorchmark.scorches[i].offy)/msc,scorchmark.scorches[i].z/msc),scorchmark.cmodel.Transform);
											scorchmark.cmodel.Transform = Raymath.MatrixMultiply(Raymath.MatrixRotate(new Vector3(0,1,0), scorchmark.scorches[i].angle),scorchmark.cmodel.Transform);	
											scorchmark.scorches[i].transformset = 1;
											scorchmark.scorches[i].transform = scorchmark.cmodel.Transform;
										}
										else
										{
											scorchmark.cmodel.Transform = scorchmark.scorches[i].transform;
										}
										{
											Raylib.BeginShaderMode(scorchmark.cshader);
											Raylib.SetShaderValueMatrix(scorchmark.cshader,scorchmark.cmodelMatrix,scorchmark.cmodel.Transform);
											Raylib.EndShaderMode();
											unsafe
											{	
												Raylib.DrawMesh(scorchmark.cmodel.Meshes[0],scorchmark.cmodel.Materials[0],scorchmark.cmodel.Transform);
											}
											drawn_entities++;
											scorchmark.scorches[i].inview = 1;
										}								
									}
									Raylib.EndBlendMode();
								}
								Profile.shadertime[1]-=Profile.timer.ElapsedMilliseconds;
								//Alien Trees
								Profile.shadertime[3]=Profile.timer.ElapsedMilliseconds;	
								if(treetest==0)
								{
								//draw the alien trees - little alien flowers and stuff....I bought the texture from shutterstock a long time ago and decided to make some 3d models out of them.	
								for(int aa=0;aa<alientree.maxalientrees;aa++)
								{
									int i = alientree.orderarray[aa];
									drewlast = 0;
									if(camnoshift!=0 && alientree.alientrees[i].drawn!=0)
									{
										drewlast = 1; //this means we drew us last frame and the camera hasn't moved
									}
									if(ambiento==0)
									{
										if(camnoshift!=0 && alientree.alientrees[i].drawn==0)
										{
											continue;
										}
										if(cammoved==0 && alientree.alientrees[i].drawn==0)
										{
											continue;
										}
										alientree.alientrees[i].drawn = 0;
									}
									else
									{
										if(alientree.alientrees[i].drawn==0)
										{
											continue;
										}
									}
									if(alientree.alientrees[i].y<0)
									{
										continue;
									}
									if(demomode==0 && Grass.incover(alientree.alientrees[i].x,alientree.alientrees[i].z)!=0)
									{
										continue;
									}
									if(Program.recordframe!=0)
									{
										float xmsc = 20f * alientree.alientrees[i].scale;
										Program.outtxt+="BEGIN" + Environment.NewLine;
										Program.outtxt+=alientree.alientrees[i].objfile + Environment.NewLine;
										Program.outtxt+=alientree.alientrees[i].texfile + Environment.NewLine;
										Program.outtxt+=alientree.alientrees[i].specfile + Environment.NewLine;
										Program.outtxt+=alientree.alientrees[i].x+Environment.NewLine;
										Program.outtxt+=alientree.alientrees[i].y+Environment.NewLine;
										Program.outtxt+=alientree.alientrees[i].z+Environment.NewLine;
										Program.outtxt+=alientree.alientrees[i].angle+Environment.NewLine;
										Program.outtxt+=xmsc+Environment.NewLine;
										Program.outtxt+=xmsc+Environment.NewLine;
										Program.outtxt+=xmsc+Environment.NewLine;
										Program.outtxt+="END" + Environment.NewLine;
									}
									if(cammoved==0 && alientree.alientrees[i].inview==0 && videomode==0 && demomode==0)
									{
										continue;
									}
									if(camnoshift!=0 && alientree.alientrees[i].inview==0)
									{
										continue;
									}
									screenpos = Raylib.GetWorldToScreen(alientree.alientrees[i].position, camera);
									if(screenpos.X<0 || screenpos.X>resx || screenpos.Y<0 || screenpos.Y>resy)
									{
										if(drewlast==0)
										{
											if(demomode==1)
											{
												if(screenpos.X<-resx/8 || screenpos.X>resx+resx/8 || screenpos.Y<-resy/8 || screenpos.Y>resy+resy/8)
												{
													alientree.alientrees[i].inview = 0;
													continue;
												}
											}
											else
											{
												alientree.alientrees[i].inview = 0;
												continue;
											}
										}
									}
									if(demomode!=0 && drewlast==0)
									{
										float dist = Raymath.Vector3Distance(alientree.alientrees[i].position,camera.Position);
										if(camnoshift!=0)
										{
											int bx = (int)(screenpos.X/10);
											int by = (int)(screenpos.Y/10);
											if(bx>=0 && by>=0 && bx<resx/10 && by<resy/10)
											{
												if(bushdist[bx+by*(resx/10)]!=0 && bushdist[bx+by*(resx/10)]<dist)
												{
													continue;
												}
											}
											if(dist>150 && treesdrawn>15)
											{
												continue;
											}
										}	
										erelc = Raymath.Vector3Normalize(Raymath.Vector3Subtract(alientree.alientrees[i].position,camera.Position));
										edotc = Raymath.Vector3DotProduct(erelc,cfwd);
										if(edotc<minedotc)
										{
											if(edotc<0)
											{
												continue;
											}
											if(Raymath.Vector3Distance(alientree.alientrees[i].position,camera.Position)>50)
											{
												continue;
											}
											
										}
										if(dist>300 && no_opt==0)
										{
											continue;
										}
										if(dist>200)
										{
											if(screenpos.X<0 || screenpos.X>resx || screenpos.Y<0 || screenpos.Y>resy)
											{
												continue;
											}
										}
									}
									alientree.alientrees[i].y = 0.01f;
									float msc = 20f * alientree.alientrees[i].scale;
									if(alientree.alientrees[i].transformset == 0)
									{
										alientree.cmodel[i%6].Transform = Raymath.MatrixIdentity();
										alientree.cmodel[i%6].Transform = Raymath.MatrixMultiply(Raymath.MatrixScale(msc,msc,msc),alientree.cmodel[i%6].Transform);
										alientree.cmodel[i%6].Transform = Raymath.MatrixMultiply(Raymath.MatrixTranslate(alientree.alientrees[i].x/msc,(alientree.alientrees[i].y+(float)i/500f)/msc,alientree.alientrees[i].z/msc),alientree.cmodel[i%6].Transform);
										alientree.cmodel[i%6].Transform = Raymath.MatrixMultiply(Raymath.MatrixRotate(new Vector3(0,1,0), alientree.alientrees[i].angle),alientree.cmodel[i%6].Transform);	
										alientree.alientrees[i].transform = alientree.cmodel[i%6].Transform;
										alientree.alientrees[i].transformset = 1;
									}
									else
									{
										alientree.cmodel[i%6].Transform = alientree.alientrees[i].transform;
									}
									
									fshadow = 0f;
									{
										Raylib.BeginShaderMode(alientree.cshader);
										Raylib.SetShaderValueMatrix(alientree.cshader,alientree.cmodelMatrix,alientree.cmodel[i%6].Transform);
										Raylib.EndShaderMode();
										unsafe
										{	
											Raylib.DrawMesh(alientree.cmodel[i%6].Meshes[0],alientree.cmodel[i%6].Materials[0],alientree.cmodel[i%6].Transform);
										}
										drawn_entities++;
										alientree.alientrees[i].drawn = 1;
										alientree.alientrees[i].inview=1;
									}								
								}
								}
								Profile.shadertime[3]-=Profile.timer.ElapsedMilliseconds;
							}
							//draw the unit circles and other flat things next....
							if(layer==2 && ambient==0 && treetest==0)//unit circles
							{
								//put bombers over the map....
								if(ambient==0)
								{
									for(int i=0;i<3;i++)
									{
										if(scorchmark.bombers[i].position.X>1010)
										{
											continue;
										}
										scorchmark.bombers[i].inview = 1;
										screenpos = Raylib.GetWorldToScreen(scorchmark.bombers[i].position, camera);
										if(screenpos.X<-200 || screenpos.X>resx+200 || screenpos.Y<-200 || screenpos.Y>resy+200 && videomode==0 && demomode==0)
										{
											scorchmark.bombers[i].inview = 0;
											continue;
										}
										scorchmark.bombers[i].y = 0.01f;
										float msc = 35f;
										scorchmark.bmodel.Transform = Raymath.MatrixIdentity();
										scorchmark.bmodel.Transform = Raymath.MatrixMultiply(Raymath.MatrixScale(msc,msc,msc),scorchmark.bmodel.Transform);
										scorchmark.bmodel.Transform = Raymath.MatrixMultiply(Raymath.MatrixTranslate(scorchmark.bombers[i].position.X/msc,scorchmark.bombers[i].position.Y/msc,scorchmark.bombers[i].position.Z/msc),scorchmark.bmodel.Transform);
										scorchmark.bmodel.Transform = Raymath.MatrixMultiply(Raymath.MatrixRotate(new Vector3(0,1,0), scorchmark.bombers[i].angle),scorchmark.bmodel.Transform);	
										scorchmark.bombers[i].transform = scorchmark.bmodel.Transform;
										{
											Raylib.BeginShaderMode(scorchmark.bshader);
											Raylib.SetShaderValueMatrix(scorchmark.bshader,scorchmark.bmodelMatrix,scorchmark.bmodel.Transform);
											Raylib.EndShaderMode();
											unsafe
											{	
												Raylib.DrawMesh(scorchmark.bmodel.Meshes[0],scorchmark.bmodel.Materials[0],scorchmark.bmodel.Transform);
											}
											drawn_entities++;
										}								
									}
								}
								if(RTSInput.selectedunits!=null)
								{
									RTSInput.deselectbuildings();
								}
								Profile.shadertime[2]=Profile.timer.ElapsedMilliseconds;	
								if(GameUI.eselect!=-1 && RTSInput.selectedunits==null)
								{
									RTSInput.selectedunits = new int[1];
									RTSInput.selectedunits[0] = GameUI.eselect;
								}
								if(RTSInput.selectedunits!=null)
								{
									float scd = 1.1f + 0.075f * (float)Math.Sin((float)Unit.uframe/20f);
									for(int uu=0;uu<RTSInput.selectedunits.Length;uu++)
									{
										int i = RTSInput.selectedunits[uu];
										
										if(Unit.unitarray[i].amode==100)
										{
											continue;
										}
										if((Unit.unitarray[i].shiptype==2 || Unit.unitarray[i].shiptype==4 || Unit.unitarray[i].shiptype==12) && Unit.unitarray[i].hp<=0)
										{
											continue;
										}
										if(Unit.unitarray[i].shiptype==5)
										{
											offangle = 3.14159f;
										}
										else
										{
											offangle = 0;
										}
										if(Unit.unitarray[i].shiptype==6)
										{
											offangle = -1.57f;
										}
										if(Unit.unitarray[i].hp>0 || (Unit.unitarray[i].amode == 3))// && Unit.unitarray[i].unborn==0))
										{
											Unit.unitarray[i].inview = 1;
											stype = Unit.unitarray[i].soldiertype;
											float msc = 7.5f;
											if(Unit.unitarray[i].shiptype==1)
											{
												msc+=(float)Unit.unitarray[i].level*0.25f;
												if(Unit.unitarray[i].race==2)
												{
													msc += ((float)((i % 20)-10)/10.0f)*0.5f;
												}
												if(Unit.unitarray[i].level<2)
												{
													if(Unit.unitarray[i].kills>0)
													{
														float kl = (float)Unit.unitarray[i].kills;
														if(kl>15)
														{
															kl = 15;
														}
														msc+=kl*0.05f;
													}
												}
											}
									
											int animframe = (int)Unit.unitarray[i].aframe;
											if(Unit.unitarray[i].shiptype==1)
											{
												if(animframe>920 && animframe < 1020) //idle is a special case....
												{
													animframe-=animframe%10;
												}
												if(animframe>=465 && animframe <=520)
												{
													animframe-=animframe%5;
												}
											}
											if(Unit.unitarray[i].shiptype==11)
											{
												if(animframe>=10 && animframe <=90)
												{
													animframe-=animframe%5;
												}
											}
											if(Unit.unitarray[i].shiptype==21)
											{
												if(animframe>=920 && animframe <=1010)
												{
													animframe-=animframe%10;
												}
											}
											if(animframe >= 730 && animframe <= 840 && Unit.unitarray[i].shiptype==5)
											{
												animframe-=animframe%5;
											}
											if(Unit.unitarray[i].shiptype==2)
											{
												animframe = 0;
											}
											if(Unit.unitarray[i].shiptype==3)
											{
												animframe = 0;
												msc*=1f;
											}
											if(Unit.unitarray[i].shiptype==4)
											{
												animframe = 0;
												msc*=0.41f; 
												msc*=7f;
												if(Unit.unitarray[i].race==1)
												{
													//to add (at library added this)
												}
											}
											if(Unit.unitarray[i].shiptype==12)
											{
												animframe = 0;
												msc = 7.5f*0.35f;
											}
											Unit.unitarray[i].y = 0.01f;
											if(Unit.unitarray[i].shiptype==2 || Unit.unitarray[i].shiptype==3)
											{
												Unit.unitarray[i].y+=2;
											}
											if(Unit.unitarray[i].shiptype==2)
											{
												msc*=3.5f;
											}
											if(Unit.unitarray[i].shiptype==5)
											{
												msc*=2.5f;
											}
											if(Unit.unitarray[i].shiptype==6)
											{
												//msc*=0.1f;
												msc*=2f;
											}
											if(Unit.ValidAnim(i,animframe)==0)//27feb2025 - attempt to fix an issue that occurs rarely but does crash the game from time to time....
											{
												continue; //should fix an issue that crops up from time to time...
											}
											msc*=scd;
											int cflag = 0;
											if(Unit.unitarray[i].race==2 && i==GameUI.eselect)
											{
												cflag = 1;
											}
											Unit.unitarray[i].model[animframe].Transform = Raymath.MatrixIdentity();
