															{
																unsafe
																{	
																	Raylib.DrawMesh(Building.buildingarray[i].model.Meshes[0],Building.buildingarray[i].model.Materials[0],Building.buildingarray[i].model.Transform);
																}
															}
														}
													}
													sc = 7.5f*0.85f;
