														Building.buildingarray[i].model.Transform = Raymath.MatrixMultiply(Raymath.MatrixTranslate(Building.buildingarray[i].x/sc,(Building.buildingarray[i].y)/(sc*0.8f),Building.buildingarray[i].z/sc),Building.buildingarray[i].model.Transform);
