														Raylib.BeginShaderMode(Building.buildingarray[i].shader);
														unsafe
														{
															Raylib.SetShaderValueMatrix(Building.buildingarray[i].shader,Building.buildingarray[i].projectionMatrix,Raylib.GetCameraProjectionMatrix(&camera, Program.aspect));
															Raylib.SetShaderValueMatrix(Building.buildingarray[i].shader,Building.buildingarray[i].viewMatrix,Raylib.GetCameraViewMatrix(&camera));
															Raylib.SetShaderValueV(Building.buildingarray[i].shader,Building.buildingarray[i].eyepos,&camera.Position,ShaderUniformDataType.Vec3,3);
															Raylib.SetShaderValueV(Building.buildingarray[i].shader,Building.buildingarray[i].ambientocclusion,&ambientof,ShaderUniformDataType.Float,1);
															Raylib.SetShaderValueV(Building.buildingarray[i].shader,Building.buildingarray[i].shadow,&fshadow,ShaderUniformDataType.Float,1);											
															Raylib.SetShaderValueV(Building.buildingarray[i].shader,Building.buildingarray[i].groundfog,&groundfog,ShaderUniformDataType.Float,1);
															Raylib.SetShaderValueV(Building.buildingarray[i].shader,Building.buildingarray[i].fogr,&fogr,ShaderUniformDataType.Float,1);
															Raylib.SetShaderValueV(Building.buildingarray[i].shader,Building.buildingarray[i].fogg,&fogg,ShaderUniformDataType.Float,1);
															Raylib.SetShaderValueV(Building.buildingarray[i].shader,Building.buildingarray[i].fogb,&fogb,ShaderUniformDataType.Float,1);
															Raylib.SetShaderValueV(Building.buildingarray[i].shader,Building.buildingarray[i].foga,&foga,ShaderUniformDataType.Float,1);
															Raylib.SetShaderValueV(Building.buildingarray[i].shader,Building.buildingarray[i].envmapping,&envmapping,ShaderUniformDataType.Float,1);
															Raylib.SetShaderValueV(Building.buildingarray[i].shader,Building.buildingarray[i].healy,&healy,ShaderUniformDataType.Float,1);//6aug2025
															Raylib.SetShaderValueV(Building.buildingarray[i].shader,Building.buildingarray[i].muzzle,&muzzleflash,ShaderUniformDataType.Float,1);//6aug2025
														}
														Raylib.SetShaderValueMatrix(Building.buildingarray[i].shader,Building.buildingarray[i].modelMatrix,Building.buildingarray[i].model.Transform);
														Raylib.EndShaderMode();
														if(demomode==0)
														{
															unsafe
															{	
																Raylib.DrawMesh(Building.buildingarray[i].lod.Meshes[0],Building.buildingarray[i].lod.Materials[0],Building.buildingarray[i].model.Transform);
															}
															
														}
														else
