														Program.outtxt+=Building.buildingarray[i].specfile + Environment.NewLine;
														Program.outtxt+=Building.buildingarray[i].x+Environment.NewLine;
														Program.outtxt+=Building.buildingarray[i].y+Environment.NewLine;
														Program.outtxt+=Building.buildingarray[i].z+Environment.NewLine;
														Program.outtxt+="0"+Environment.NewLine;
														Program.outtxt+=sc+Environment.NewLine;
														Program.outtxt+=sc+Environment.NewLine;
														Program.outtxt+=sc+Environment.NewLine;
														Program.outtxt+="END" + Environment.NewLine;
