										}
									}
								}
								Profile.shadertime[6]=Profile.timer.ElapsedMilliseconds;	
								muzzleflash = 0;
								float[] bdist = new float[10]; //distance to buildings
								Vector3[] bcpos = new Vector3[10];//vector to buildings//normalised
								for(int i=0;i<Building.maxbuildings;i++)
								{
									bdist[i] = 10000f;
									bcpos[i] = new Vector3(0,0,10000);
									if(Building.buildingarray[i].hp>0)
