										bcpos[i] = Raymath.Vector3Normalize(Raymath.Vector3Subtract(new Vector3(Building.buildingarray[i].x,Building.buildingarray[i].y,Building.buildingarray[i].z),camera.Position));
									}
								}
								
								Profile.shadertime[9]-=Profile.timer.ElapsedMilliseconds;	
								Profile.shadertime[4]=Profile.timer.ElapsedMilliseconds;	
								
								//obstacles //draw the obstacles (razor wire and tank traps)
								if(Obstacle.any!=0)
								{
									if(ambient==0)
									{
										int firstundrawnaa = -1;
										int lastdrawnaa = -1;
										for(int aa=0;aa<Obstacle.maxobstacles;aa++)
										{
											int i = Obstacle.orderarray[aa];
											if(Obstacle.obstaclearray[i].drawn==0)
											{
												if(firstundrawnaa==-1)
												{
													firstundrawnaa = aa;
												}
											}
											else
											{
												lastdrawnaa = aa;
											}
										}
										if(lastdrawnaa!=-1 && firstundrawnaa!=-1)
										{
											int tmpaa = Obstacle.orderarray[firstundrawnaa];
											Obstacle.orderarray[firstundrawnaa] = Obstacle.orderarray[lastdrawnaa];
											Obstacle.orderarray[lastdrawnaa] = tmpaa;
										}
									}
									//draw the shadows first since they're beneath the units..
									for(float rangebin=0;rangebin<3;rangebin++)
									{
									//	if(demomode==0 && rangebin==2)
