												}
												int i = Obstacle.orderarray[aa];
												float camdist = Raymath.Vector3Distance(camera.Position,Obstacle.obstaclearray[i].position);
												if(camdist<(rangebin+1)*333f && camdist>=rangebin*333f)
												{
													//we want this
												}
												else
												{
													continue;
												}
												drewlast = 0;
												if(camnoshift!=0 && Obstacle.obstaclearray[i].drawn!=0)
												{
													drewlast = 1;
												}
												if(ambiento==0)
												{
													Obstacle.obstaclearray[i].drawn = 0;
												}
												else
												{
													if(Obstacle.obstaclearray[i].drawn==0)
													{
														continue;
													}
												}
												float sc = 1f;
												if(Obstacle.obstaclearray[i].tanktrap==1)
												{
													sc = 0.65f;
												}
												if(Obstacle.obstaclearray[i].hp<=0 || Obstacle.obstaclearray[i].y<=0)
												{
													continue;
												}
												if(Program.recordframe!=0)
												{
													Program.outtxt+="BEGIN" + Environment.NewLine;
													Program.outtxt+=Obstacle.obstaclearray[i].objfile + Environment.NewLine;
													Program.outtxt+=Obstacle.obstaclearray[i].texfile + Environment.NewLine;
													Program.outtxt+=Obstacle.obstaclearray[i].specfile + Environment.NewLine;
													Program.outtxt+=Obstacle.obstaclearray[i].x+Environment.NewLine;
													Program.outtxt+=Obstacle.obstaclearray[i].y+Environment.NewLine;
													Program.outtxt+=Obstacle.obstaclearray[i].z+Environment.NewLine;
													Program.outtxt+=Obstacle.obstaclearray[i].angle+Environment.NewLine;
													Program.outtxt+=sc+Environment.NewLine;
													Program.outtxt+=sc+Environment.NewLine;
													Program.outtxt+=sc+Environment.NewLine;
													Program.outtxt+="END" + Environment.NewLine;
												}
												total_entities++;
												if(cammoved==0 && Obstacle.obstaclearray[i].inview==0 && videomode==0 && demomode==0)
												{
													continue;
												}
												if(camnoshift!=0 && Obstacle.obstaclearray[i].inview==0)
												{
													continue;
												}
												if(demomode==0 && videomode==0)
												{
													if(NearSector(Obstacle.obstaclearray[i].sectorx,Obstacle.obstaclearray[i].sectorz,camera_sectorx,camera_sectorz)==0)
													{
														continue;
													}
												}
												screenpos = Raylib.GetWorldToScreen(Obstacle.obstaclearray[i].position, camera);
												Obstacle.obstaclearray[i].distfromedge = Raymath.Vector2Distance(new Vector2(screenpos.X,screenpos.Y),new Vector2(resx/2,resy/2));
												float dist = Raymath.Vector3Distance(Obstacle.obstaclearray[i].position,camera.Position);
												if(ambient!=0 && demomode!=0)
												{
													if(dist>350)
													{
														continue;
													}
												}
												if(drewlast==0)
												{
													if(ambient==0)
													{
														if(screenpos.X<-resx/2 || screenpos.X>resx+resx/2 || screenpos.Y<-resy/2 || screenpos.Y>resy+resy/2)
														{
															Obstacle.obstaclearray[i].inview = 0;
															continue;
														}
														if(demomode!=0)
														{
															erelc = Raymath.Vector3Normalize(Raymath.Vector3Subtract(Obstacle.obstaclearray[i].position,camera.Position));
															edotc = Raymath.Vector3DotProduct(erelc,cfwd);
															if(edotc<minedotc)
															{
																if(edotc<0)
																{	
																	continue;
																}
																if(Raymath.Vector3Distance(Obstacle.obstaclearray[i].position,camera.Position)>50)
																{
																	continue;
																}
																
															}
														}
														if(demomode==0)
														{
															if(screenpos.Y>(float)resy*guiocclusion) //gui is obstructing view.
															{
																continue;	
															}
														}
														else
														{
															//a really simplistic form of occlusion culling
															//based on the fact buildings are big and block
															//view when in demomode especially for things far away.
															if(dist>700 && no_opt==0)//fog range
															{
																continue;
															}
															if(dist>300)
															{
																if(screenpos.X<0 || screenpos.X>resx || screenpos.Y<0 || screenpos.Y>resy)
																{
																	continue;
																}	
															}
															for(int bb=0;bb<Building.maxbuildings;bb++)
															{
																if(bdist[bb]<10000 && bdist[bb] < dist && dist > 200)
																{
																	objreltocam = Raymath.Vector3Normalize(Raymath.Vector3Subtract(new Vector3(Obstacle.obstaclearray[i].x,Obstacle.obstaclearray[i].y,Obstacle.obstaclearray[i].z),camera.Position));
																	bdot = Raymath.Vector3DotProduct(bcpos[bb],objreltocam);
																	if(bdot > minbdot)
																	{
																		continue;
																	}
																}
															}
														}
													}
												}
												fshadow = 0.65f;
