												float angle = (3.14159f / 180f) * (Obstacle.obstaclearray[i].angle);
												Matrix4x4 rotationmatrix = Raymath.MatrixRotateX(angle);
												Obstacle.obstaclearray[i].model.Transform = Raymath.MatrixMultiply(rotationmatrix,Obstacle.obstaclearray[i].model.Transform);
												if(shadowlayer==0 && ambient==0)
												{
													Raylib.BeginShaderMode(Obstacle.obstaclearray[i].shader);
													unsafe
													{
