													checkundertree[ctree] = i + 1;
													ctree++;
												}
											}
										}
									}
								}
								//animals
								muzzleflash = 0;
								for(float rangebin=0;rangebin<3;rangebin++)
								{
									//if(demomode==0 && rangebin==2)
									//{
									//	continue;
									//}
									
									for(int shadowlayer=0;shadowlayer<2;shadowlayer++)
									{
										for(int i=0;i<Unit.maxanimals;i++)
										//for(int i=0;i<-1;i++)
										{
											float camdist = Raymath.Vector3Distance(camera.Position,Unit.animals[i].pos);
											if(camdist<(rangebin+1f)*333f && camdist>=rangebin*333f)
											{
												
											}
											else
											{
												continue;
											}
											
											total_entities++;
											if(treetest!=0)
											{
												break;
											}
											if(demomode==0 && videomode==0)
											{
												if(NearSector(Unit.animals[i].sectorx,Unit.animals[i].sectorz,camera_sectorx,camera_sectorz)==0)
												{
													continue;
												}
											}
											drewlast = 0;
											if(camnoshift!=0 && Unit.animals[i].drawn!=0)
											{
												drewlast = 1;
											}
											if(ambiento==0)
											{
												if(cammoved==0 && Unit.animals[i].drawn==0)
												{
													continue;
												}
												if(cammoved!=0 && Unit.animals[i].drawn==0 && demomode==0)
												{
													//maybe the camera moved a lot.....
													//distance we moved.....
													float cdist = Raymath.Vector3Distance(Grass.oldcameraposition,camera.Position);
													if(Unit.animals[i].distfromedge!=0)
													{
														float screensize = Raymath.Vector2Length(new Vector2(resx,resy));
														float fraction = cdist / (Unit.animals[i].distfromedge/screensize);
														//if fraction is larger than a certain value
														//then we should go through the various checks
														//but if fraction is smaller than a certain value
														//we should not
														if(fraction < drawmovetolerance)
														{
															continue;
														}
													}
												}
												Unit.animals[i].drawn = 0;
											}
											else
											{
												if(Unit.animals[i].drawn==0)
												{
													continue;
												}
											}
											position = new Vector3(Unit.animals[i].x,Unit.animals[i].y,Unit.animals[i].z);
											screenpos = Raylib.GetWorldToScreen(position, camera);
											Unit.animals[i].distfromedge = Raymath.Vector2Distance(new Vector2(screenpos.X,screenpos.Y),new Vector2(resx/2,resy/2));
											float dist = Raymath.Vector3Distance(position,camera.Position);
											if(ambient!=0 && demomode!=0)
											{
												if(dist>350)
												{
													continue;
												}
											}
											if(drewlast==0)
											{
												if(ambient==0)
												{
													if(screenpos.X<-resx/2 || screenpos.X>resx+resx/2 || screenpos.Y<-resy/2 || screenpos.Y>resy+resy/2)
													{
														continue;
													}					
													if(demomode!=0)
													{
														erelc = Raymath.Vector3Normalize(Raymath.Vector3Subtract(position,camera.Position));
														edotc = Raymath.Vector3DotProduct(erelc,cfwd);
														if(edotc<minedotc)
														{
															if(edotc<0)
															{
																continue;
															}
															if(Raymath.Vector3Distance(position,camera.Position)>50)
															{
																continue;
															}
															
														}
													}
													if(demomode==0)
													{
														if(screenpos.Y>(float)resy*guiocclusion) //gui is obstructing view.
														{
															continue;	
														}
														if(screenpos.X<-resx/8 || screenpos.X>resx+resx/8)
														{
															continue;
														}
													}
													else
													{
														//a really simplistic form of occlusion culling
															//based on the fact buildings are big and block
															//view when in demomode especially for things far away.
															if(dist>700 && no_opt==0)
															{
																continue;
															}
															if(dist>200)
															{
																if(screenpos.X<0 || screenpos.X>resx || screenpos.Y<0 || screenpos.Y>resy)
																{
																	continue;
																}
															}
															for(int bb=0;bb<Building.maxbuildings;bb++)
															{
																if(bdist[bb]<10000 && bdist[bb] < dist && dist > 200)
																{
																	objreltocam = Raymath.Vector3Normalize(Raymath.Vector3Subtract(new Vector3(Unit.animals[i].x,Unit.animals[i].y,Unit.animals[i].z),camera.Position));
																	bdot = Raymath.Vector3DotProduct(bcpos[bb],objreltocam);
																	if(bdot > minbdot)
																	{
																		continue;
																	}
																}
															}
													}
												}
											}
											offangle = 3.14159f/2f;
											Unit.animals[i].inview=1;
											stype = 0;
											float msc = 7.5f;
											float healy = -100;
											int animframe = (int)Unit.animals[i].aframe;
											//draw shadow.....
											Unit.animals[i].y = 0.01f;
											Unit.animals[i].model[animframe].Transform = Raymath.MatrixIdentity();
											Unit.animals[i].model[animframe].Transform = Raymath.MatrixMultiply(Raymath.MatrixScale(msc,msc,msc),Unit.animals[i].model[animframe].Transform);
											Unit.animals[i].model[animframe].Transform = Raymath.MatrixMultiply(Raymath.MatrixTranslate(Unit.animals[i].x/msc,(Unit.animals[i].y)/msc,Unit.animals[i].z/msc),Unit.animals[i].model[animframe].Transform);
											Unit.animals[i].model[animframe].Transform = Raymath.MatrixMultiply(Raymath.MatrixRotate(new Vector3(0,1,0), Unit.animals[i].angle+offangle),Unit.animals[i].model[animframe].Transform);	
											if(shadowlayer==0 && ((dist<200 && no_opt==0) || demomode==0) && ambient==0)
											{
												Raylib.BeginShaderMode(Unit.animals[i].shader);
												fshadow = 0.65f;
												unsafe
												{
													Raylib.SetShaderValueV(Unit.animals[i].shader,Unit.animals[i].shadow,&fshadow,ShaderUniformDataType.Float,1);
													Raylib.SetShaderValueV(Unit.animals[i].shader,Unit.animals[i].healy,&healy,ShaderUniformDataType.Float,1);
													Raylib.SetShaderValueV(Unit.animals[i].shader,Unit.animals[i].muzzle,&muzzleflash,ShaderUniformDataType.Float,1);
												}
												Raylib.SetShaderValueMatrix(Unit.animals[i].shader,Unit.animals[i].modelMatrix,Unit.animals[i].model[animframe].Transform);
												Raylib.EndShaderMode();
												int noshadow = 0;
												if(autooptimise>1 && no_opt==0)
												{
													if(demomode==0 && fps<targetfps-targetfps/3 && Grass.incover(Unit.animals[i].x,Unit.animals[i].z)!=0)
													{
														noshadow = 1;
													}
												}
												
												int bx = (int)(screenpos.X/10);
												int by = (int)(screenpos.Y/10);
												if(bx>=0 && by>=0 && bx<resx/10 && by<resy/10)
												{
													if(bushdist[bx+by*(resx/10)]!=0 && bushdist[bx+by*(resx/10)]<dist)
													{
														noshadow=1;
													}
													if(dist>150 && treesdrawn>15)
													{
														noshadow = 1;
													}
												}
												
												if((demomode==0 || (dist < 400 && no_opt==0)) && noshadow==0)
												{
													if(ambient==0)
													{
														unsafe
														{	
															Raylib.DrawMesh(Unit.animals[i].model[animframe].Meshes[0],Unit.animals[i].model[animframe].Materials[0],Unit.animals[i].model[animframe].Transform);
														}
													}
												}
											}
											//draw main animal
											Unit.animals[i].model[animframe].Transform = Raymath.MatrixIdentity();
											Unit.animals[i].model[animframe].Transform = Raymath.MatrixMultiply(Raymath.MatrixScale(msc,msc,msc),Unit.animals[i].model[animframe].Transform);
											Unit.animals[i].model[animframe].Transform = Raymath.MatrixMultiply(Raymath.MatrixTranslate(Unit.animals[i].x/msc,(Unit.animals[i].y)/msc,Unit.animals[i].z/msc),Unit.animals[i].model[animframe].Transform);
											Unit.animals[i].model[animframe].Transform = Raymath.MatrixMultiply(Raymath.MatrixRotate(new Vector3(0,1,0), Unit.animals[i].angle+offangle),Unit.animals[i].model[animframe].Transform);	
											if(shadowlayer==1)
											{
												Raylib.BeginShaderMode(Unit.animals[i].shader);
												fshadow = 0;
												unsafe
												{
													//these won't have changed from the last call...
													Raylib.SetShaderValueV(Unit.animals[i].shader,Unit.animals[i].shadow,&fshadow,ShaderUniformDataType.Float,1);
													Raylib.SetShaderValueV(Unit.animals[i].shader,Unit.animals[i].healy,&healy,ShaderUniformDataType.Float,1);
													Raylib.SetShaderValueV(Unit.animals[i].shader,Unit.animals[i].stype,&stype,ShaderUniformDataType.Int,1);
													Raylib.SetShaderValueV(Unit.animals[i].shader,Unit.animals[i].muzzle,&muzzleflash,ShaderUniformDataType.Float,1);
												}
												Raylib.SetShaderValueMatrix(Unit.animals[i].shader,Unit.animals[i].modelMatrix,Unit.animals[i].model[animframe].Transform);
												Raylib.EndShaderMode();
												unsafe
												{	
													Raylib.DrawMesh(Unit.animals[i].model[animframe].Meshes[0],Unit.animals[i].model[animframe].Materials[0],Unit.animals[i].model[animframe].Transform);
												}
											}
											Unit.animals[i].drawn = 1;
											drawn_entities++;
											if(Program.recordframe!=0)
											{
												Program.outtxt+="BEGIN" + Environment.NewLine;
												Program.outtxt+=Unit.animals[i].objfile[animframe]+ Environment.NewLine;
												Program.outtxt+=Unit.animals[i].texfile + Environment.NewLine;
												Program.outtxt+=Unit.animals[i].specfile + Environment.NewLine;
												Program.outtxt+=Unit.animals[i].x+Environment.NewLine;
												Program.outtxt+=Unit.animals[i].y+Environment.NewLine;
												Program.outtxt+=Unit.animals[i].z+Environment.NewLine;
												Program.outtxt+=(Unit.animals[i].angle)+Environment.NewLine;
												Program.outtxt+=msc+Environment.NewLine;
												Program.outtxt+=msc+Environment.NewLine;
												Program.outtxt+=msc+Environment.NewLine;
												Program.outtxt+="END" + Environment.NewLine;
											}
										}
									}
								}
								//end of animals
								Profile.shadertime[5]-=Profile.timer.ElapsedMilliseconds;	
								
								
								
								//Grasses.....
								voffset = new Vector3(-100,0,100);
								voffset = Raymath.Vector3Subtract(camera.Target,voffset);
								Vector2 vscreen = new Vector2(resx,resy);
								Vector2 vscreenon2 = new Vector2(resx/2,resy/2);
								gscreenpos = new Vector2(0,0);
								added = 0;
								Raylib.BeginBlendMode(BlendMode.Alpha);
								bushdist = new float[(resx/10)*(resy/10)]; //reset it
								//draw the bushes first if the camera is above their height...
								if(camera.Position.Y > 10)
								{
									for(float rangebin=2;rangebin>=0;rangebin--)
									{
										if(demomode==0 && rangebin==2)
										{
											continue;
										}
									
										for(int j=0;j<Grass.maxbush;j++)
										{
											int i = Grass.bushorderarray[j];
											if(i<0)
											{
												continue;
											}
											float camdist = Raymath.Vector3Distance(camera.Position,Grass.bushpos[i]);
											if(camdist<(rangebin+1f)*333f && camdist>=rangebin*333f)
											{
												
											}
											else
											{
												continue;
											}
											if(Grass.bushposangle[i]!=0)
											{
												float sc = 1.75f*0.1f;
												fshadow = 0;
												if(i%(GameUI.reducefoliage+1)!=0 && no_opt==0) //less foliage //note it gets set to the gameui version, which is semirandom....
												{
													continue;
												}
												float dist = 0;
												total_entities+=2;
												drewlast = 0;
												if(camnoshift!=0 && Grass.bushdrawn[i]!=0)
												{
													drewlast = 1;
												}
												if(ambiento==0)
												{
													if(cammoved==0 && Grass.bushdrawn[i]==0)
													{
														//we didn't draw it last time
														//and the camera hasn't moved
														//so....skip it
														continue;
													}
													if(cammoved!=0 && Grass.bushdrawn[i]==0 && demomode==0)
													{
														//maybe the camera moved a lot.....
														//distance we moved.....
														float cdist = Raymath.Vector3Distance(Grass.oldcameraposition,camera.Position);
														if(Grass.bushdistfromedge[i]!=0)
														{
															float screensize = Raymath.Vector2Length(vscreen);
															float fraction = cdist / (Grass.bushdistfromedge[i]/screensize);
															//if fraction is larger than a certain value
															//then we should go through the various checks
															//but if fraction is smaller than a certain value
															//we should not
															if(fraction < drawmovetolerance)
															{
																continue;
															}
														}
													}
													Grass.bushdrawn[i] = 0;
												}
												else
												{
													if(Grass.bushdrawn[i]==0)
													{
														continue;
													}
												}
												//upto
												if(ambient==0 && drewlast==0)
												{
													if(demomode!=0)
													{
														erelc = Raymath.Vector3Normalize(Raymath.Vector3Subtract(Grass.bushpos[i],camera.Position));
														edotc = Raymath.Vector3DotProduct(erelc,cfwd);
														if(edotc<minedotc)
														{
															if(edotc<0)
															{
																continue;
															}
															if(Raymath.Vector3Distance(Grass.bushpos[i],camera.Position)>50)
															{
																continue;
															}
															
														}
													}
													
													dist = Raymath.Vector3Distance(Grass.bushpos[i],camera.Position);					
													if(ambient!=0 && demomode!=0)
													{
														if(dist>350)
														{
															continue;
														}
													}
														
													if(Program.recordframe==0 && Raymath.Vector3Distance(Grass.bushpos[i],voffset)>400 && Program.demomode==0 && Program.videomode==0 && no_opt==0) //guesstimate of the distance...
													{
														continue;
													}
													gscreenpos = Raylib.GetWorldToScreen(Grass.bushpos[i], camera);
													Grass.bushdistfromedge[i] = Raymath.Vector2Distance(gscreenpos,vscreenon2);
													if(gscreenpos.X<-resx/2 || gscreenpos.X>resx+resx/2 || gscreenpos.Y<-resy/2 || gscreenpos.Y>resy+resy/2)
													{
														continue;
													}
													if(demomode==0)
													{
														if(gscreenpos.Y>(float)resy*guiocclusion) //gui is obstructing view.
														{
															continue;	
														}
													}
													if(demomode==0 && videomode==0)
													{
														if(gscreenpos.X<0 || gscreenpos.X>resx || gscreenpos.Y<0 || gscreenpos.Y>resy+resy/4)
														{
															continue;
														}
													}
													else
													{
														if(dist>700 && no_opt==0)
														{
															continue;
														}
														if(dist>300)
														{
															if(gscreenpos.X<0 || gscreenpos.X>resx || gscreenpos.Y<0 || gscreenpos.Y>resy)
															{
																continue;
															}
														}
														erelc = Raymath.Vector3Normalize(Raymath.Vector3Subtract(Grass.bushpos[i],camera.Position));
														edotc = Raymath.Vector3DotProduct(erelc,cfwd);
														if(edotc<minedotc)
														{
															//if(Raymath.Vector3Distance(Grass.bushpos[i],camera.Position)>50)
															//{
															//	continue;
															//}
															continue;
														}
														//a really simplistic form of occlusion culling
														//based on the fact buildings are big and block
														//view when in demomode especially for things far away.
														{
															for(int bb=0;bb<Building.maxbuildings;bb++)
															{
																if(bdist[bb]<10000 && bdist[bb] < dist && dist > 200)
																{
																	objreltocam = Raymath.Vector3Normalize(Raymath.Vector3Subtract(Grass.bushpos[i],camera.Position));
																	bdot = Raymath.Vector3DotProduct(bcpos[bb],objreltocam);
																	if(bdot > minbdot)
																	{
																		continue;
																	}
																}
															}
														}
													}
													int bx = (int)(gscreenpos.X/10);
													int by = (int)(gscreenpos.Y/10);
													int ax = 0;
													int ay = 0;
													if(bx+ax>=0 && by+ay>=0 && bx+ax<resx/10 && by+ay<resy/10)
													{
														if(bushdist[bx+ax+(by+ay)*(resx/10)]>dist || bushdist[(bx+ax)+(by+ay)*(resx/10)]==0)
														{
															bushdist[bx+ax+(by+ay)*(resx/10)] = dist;
														}
													}
													if(dist<100)
													{
														for(ax=-1;ax<=1;ax++)
														{
															for(ay=-1;ay<=1;ay++)
															{
																if(ax!=0 || ay!=0)
																{
																	if(bx+ax>=0 && by+ay>=0 && bx+ax<resx/10 && by+ay<resy/10)
																	{
																		if(bushdist[bx+ax+(by+ay)*(resx/10)]>dist || bushdist[(bx+ax)+(by+ay)*(resx/10)]==0)
																		{
																			bushdist[bx+ax+(by+ay)*(resx/10)] = dist;
																		}
																	}
																}
															}
														}
													}
												}
												Grass.bush.Transform = Raymath.MatrixIdentity();
												Grass.bush.Transform = Raymath.MatrixMultiply(Raymath.MatrixScale(sc,sc,sc),Grass.bush.Transform);
												Grass.bush.Transform = Raymath.MatrixMultiply(Raymath.MatrixTranslate((Grass.bushposx[i])/sc,(0.01f)/sc,(Grass.bushposz[i])/sc),Grass.bush.Transform);
												Grass.bush.Transform = Raymath.MatrixMultiply(Raymath.MatrixRotateY(Grass.bushposangle[i]),Grass.bush.Transform);
												Raylib.BeginShaderMode(Grass.bushshader);
												unsafe
												{
													Raylib.SetShaderValueV(Grass.bushshader,Grass.bambientocclusion,&ambientof,ShaderUniformDataType.Float,1);
												}
												Raylib.SetShaderValueMatrix(Grass.bushshader,Grass.bmodelMatrix,Grass.bush.Transform);
												Raylib.EndShaderMode();
												unsafe
												{	
													Raylib.DrawMesh(Grass.bush.Meshes[0],Grass.bush.Materials[0],Grass.bush.Transform);
												}
												Grass.bush.Transform = Raymath.MatrixIdentity();
												Grass.bush.Transform = Raymath.MatrixMultiply(Raymath.MatrixScale(sc,sc,sc),Grass.bush.Transform);
												Grass.bush.Transform = Raymath.MatrixMultiply(Raymath.MatrixTranslate((Grass.bushposx[i])/sc,(0.01f)/sc,(Grass.bushposz[i])/sc),Grass.bush.Transform);
												Grass.bush.Transform = Raymath.MatrixMultiply(Raymath.MatrixRotateY(Grass.bushposangle[i]+1.57f),Grass.bush.Transform);
												Raylib.BeginShaderMode(Grass.bushshader);
												unsafe
												{
													Raylib.SetShaderValueV(Grass.bushshader,Grass.bambientocclusion,&ambientof,ShaderUniformDataType.Float,1);
												}
												Raylib.SetShaderValueMatrix(Grass.bushshader,Grass.bmodelMatrix,Grass.bush.Transform);
												Raylib.EndShaderMode();
												unsafe
												{	
													Raylib.DrawMesh(Grass.bush.Meshes[0],Grass.bush.Materials[0],Grass.bush.Transform);
												}
												Grass.bushdrawn[i] = 1;
												drawn_entities++;
											}
										}
									}
								}
								for(int i=0;i<Grass.maxgtype;i++)
								{
									Raylib.BeginShaderMode(Grass.grassarray[i].shader);
									unsafe
									{
										Raylib.SetShaderValueMatrix(Grass.grassarray[i].shader,Grass.grassarray[i].projectionMatrix,Raylib.GetCameraProjectionMatrix(&camera, Program.aspect));
										Raylib.SetShaderValueMatrix(Grass.grassarray[i].shader,Grass.grassarray[i].viewMatrix,Raylib.GetCameraViewMatrix(&camera));
										//if(treetest==0)
										{	
											Raylib.SetShaderValueV(Grass.grassarray[i].shader,Grass.grassarray[i].ambientocclusion,&ambientof,ShaderUniformDataType.Float,1);								
											Raylib.SetShaderValueV(Grass.grassarray[i].shader,Grass.grassarray[i].snowing,&issnowing,ShaderUniformDataType.Float,1);								
											Raylib.SetShaderValueV(Grass.grassarray[i].shader,Grass.grassarray[i].eyepos,&camera.Position,ShaderUniformDataType.Vec3,3);
											Raylib.SetShaderValueV(Grass.grassarray[i].shader,Grass.grassarray[i].groundfog,&groundfog,ShaderUniformDataType.Float,1);
											Raylib.SetShaderValueV(Grass.grassarray[i].shader,Grass.grassarray[i].fogr,&fogr,ShaderUniformDataType.Float,1);
											Raylib.SetShaderValueV(Grass.grassarray[i].shader,Grass.grassarray[i].fogg,&fogg,ShaderUniformDataType.Float,1);
											Raylib.SetShaderValueV(Grass.grassarray[i].shader,Grass.grassarray[i].fogb,&fogb,ShaderUniformDataType.Float,1);
											Raylib.SetShaderValueV(Grass.grassarray[i].shader,Grass.grassarray[i].foga,&foga,ShaderUniformDataType.Float,1);											
											Raylib.SetShaderValueV(Grass.grassarray[i].shader,Grass.grassarray[i].envmapping,&envmapping,ShaderUniformDataType.Float,1);
										}
										
									}
									Raylib.EndShaderMode();
								}
								
								//extra grasses
								if(demomode!=0 || videomode!=0)
								{
									float[] adx = new float[8];
									float[] adz = new float[8];
									float aangle = 0;
									for(int a=0;a<8;a++)
									{
										aangle+=0.75f;
										adx[a] = 45.0f * (float)Math.Cos(aangle);
										adz[a] = 45.0f * (float)Math.Sin(aangle);
									}
									for(float rangebin=2;rangebin>=0;rangebin--)
									{
										if(demomode==0 && rangebin==2)
										{
											continue;
										}
										for(int j=0;j<Grass.maxbush;j++)
										{
											int i = Grass.bushorderarray[j];
											if(i<0)
											{
												continue;
											}
											float camdist = Raymath.Vector3Distance(camera.Position,Grass.bushpos[i]);
											if(camdist<(rangebin+1f)*333f && camdist>=rangebin*333f)
											{
												
											}
											else
											{
												continue;
											}
											if(Grass.bushposangle[i]!=0)
											{
												float sc = Grass.grassarray[5].sc;
												fshadow = 0;
												if(i%(GameUI.reducefoliage+1)!=0 && no_opt==0) //less foliage //note it gets set to the gameui version, which is semirandom....
												{
													continue;
												}
												total_entities+=8;
												float dist = 0;
												if(demomode!=0)
												{
													erelc = Raymath.Vector3Normalize(Raymath.Vector3Subtract(Grass.bushpos[i],camera.Position));
													edotc = Raymath.Vector3DotProduct(erelc,cfwd);
													if(edotc<minedotc)
													{
														if(edotc<0)
														{
															continue;
														}
														if(Raymath.Vector3Distance(Grass.bushpos[i],camera.Position)>50)
														{
															continue;
														}
														
													}
												}
												dist = Raymath.Vector3Distance(Grass.bushpos[i],camera.Position);					
												if(ambient!=0 && demomode!=0)
												{
													if(dist>350)
													{
														continue;
													}
												}
												if(Program.recordframe==0 && no_opt==0 && Raymath.Vector3Distance(Grass.bushpos[i],voffset)>400 && Program.demomode==0 && Program.videomode==0) //guesstimate of the distance...
												{
													continue;
												}
												gscreenpos = Raylib.GetWorldToScreen(Grass.bushpos[i], camera);
												if(gscreenpos.X<-resx/2 || gscreenpos.X>resx+resx/2 || gscreenpos.Y<-resy/2 || gscreenpos.Y>resy+resy/2)
												{
													continue;
												}
												{
													if(dist>250 && no_opt==0)
													{
														continue;
													}
													erelc = Raymath.Vector3Normalize(Raymath.Vector3Subtract(Grass.bushpos[i],camera.Position));
													edotc = Raymath.Vector3DotProduct(erelc,cfwd);
													if(edotc<minedotc)
													{
														continue;
													}
													//a really simplistic form of occlusion culling
													//based on the fact buildings are big and block
													//view when in demomode especially for things far away.
												}
												fshadow = 0;
												for(int a=0;a<8;a++)
												{												
													Grass.bush.Transform = Raymath.MatrixIdentity();
													Grass.bush.Transform = Raymath.MatrixMultiply(Raymath.MatrixScale(sc,sc,sc),Grass.bush.Transform);
													Grass.bush.Transform = Raymath.MatrixMultiply(Raymath.MatrixTranslate((Grass.bushposx[i]+adx[a])/sc,(0.01f)/sc,(Grass.bushposz[i]+adz[a])/sc),Grass.bush.Transform);
													Grass.bush.Transform = Raymath.MatrixMultiply(Raymath.MatrixRotateY(Grass.bushposangle[i]),Grass.bush.Transform);
													Raylib.BeginShaderMode(Grass.grassarray[5].shader);
													
													unsafe
													{
														Raylib.SetShaderValueV(Grass.grassarray[5].shader,Grass.grassarray[5].shadow,&fshadow,ShaderUniformDataType.Float,1);
													}
													Raylib.SetShaderValueMatrix(Grass.grassarray[5].shader,Grass.grassarray[5].modelMatrix,Grass.bush.Transform);
													Raylib.EndShaderMode();
													unsafe
													{	
														Raylib.DrawMesh(Grass.grassarray[5].model.Meshes[0],Grass.grassarray[5].model.Materials[0],Grass.bush.Transform);
													}
													drawn_entities++;
												}
											}
										}
									}
								}
								//end of extra grasses
									int tmpopt = 0;
									if(no_opt==0)
									{
										no_opt = 1;
										tmpopt = 1;
									}
									treesdrawn = 0;
									float distmin = -1f;
									float distmax = -1f;
									int tmpggmin = -1;
									int tmpggmax = -1;
									for(float rangebin=2;rangebin>=0;rangebin--)
									{
										if(demomode==0 && rangebin==2)
										{
											continue;
										}
										for(int gg=0;gg<Grass.maxgrasses;gg++)
										{
											if(gg%(GameUI.reducefoliage+1)!=0 && no_opt==0 && Grass.grassarray[Grass.orderarray[gg]].gtype!=3 && Grass.grassarray[Grass.orderarray[gg]].gtype!=6) //less foliage //note it gets set to the gameui version, which is semirandom....
											{
												continue;
											}
											total_entities++;
											float dist = 0;
											int noshadow = 0;
											int i = Grass.orderarray[gg];
											float camdist = Raymath.Vector3Distance(camera.Position,Grass.grassarray[i].grassposition);
											if(camdist<(rangebin+1f)*333f && camdist>=rangebin*333f)
											{
												
											}
											else
											{
												continue;
											}
											if(demomode==0 && videomode==0)
											{
												if(NearSector(Grass.grassarray[i].sectorx,Grass.grassarray[i].sectorz,camera_sectorx,camera_sectorz)==0)
												{
													Grass.grassarray[i].drawn = 0;
													continue;
												}
											}
											drewlast = 0;
											if(camnoshift!=0 && Grass.grassarray[i].drawn!=0)
											{
												drewlast = 1;
											}
											if(ambiento==0)
											{
												if(camnoshift!=0 && Grass.grassarray[i].drawn==0)
												{
													if(Grass.grassarray[i].gtype!=4) //these are the worst offenders
													{
														continue;
													}
												}
												if(cammoved==0 && Grass.grassarray[i].drawn==0)
												{
													//we didn't draw it last time
													//and the camera hasn't moved
													//so....skip it
													continue;
												}
												if(cammoved!=0 && Grass.grassarray[i].drawn==0 && demomode==0)
												{
													//maybe the camera moved a lot.....
													//distance we moved.....
													float cdist = Raymath.Vector3Distance(Grass.oldcameraposition,camera.Position);
													if(Grass.grassarray[i].distfromedge!=0)
													{
														float screensize = Raymath.Vector2Length(vscreen);
														float fraction = cdist / (Grass.grassarray[i].distfromedge/screensize);
														//if fraction is larger than a certain value
														//then we should go through the various checks
														//but if fraction is smaller than a certain value
														//we should not
														if(fraction < drawmovetolerance)
														{
															continue;
														}
													}
												}
												Grass.grassarray[i].drawn = 0;
											}
											else
											{
												if(Grass.grassarray[i].drawn==0)
												{
													continue;
												}
											}
											int lod = 0;
											Grass.treetype = (i % 11) % 3;
											float gdist = Raymath.Vector3Distance(Grass.grassarray[i].grassposition,camera.Position);
											Grass.grassarray[i].distfromcamera = gdist;
											if(ambient!=0 && demomode!=0 && Grass.grassarray[i].gtype!=3 && Grass.grassarray[i].gtype!=6)
											{
												if(gdist>350)
												{
													continue;
												}
											}
												
											if(Grass.grassarray[i].gtype==5)
											{
												Grass.treetype = i % 2;
											}
											if(ambient==0)
											{
											if(Grass.grassarray[i].gtype==4 && Grass.grassarray[i].y<-10)
											{
												continue;
											}
											Grass.grassarray[i].y = 0.01f;
											if(Grass.grassarray[i].offscreen>0 && cammoved==0 && Program.recordframe==0 && Program.videomode==0 && Program.demomode==0)
											{
												continue;
											}
											if(drewlast==0)
											{
												if(demomode!=0)// && no_opt==0)
												{
													erelc = Raymath.Vector3Normalize(Raymath.Vector3Subtract(Grass.grassarray[i].grassposition,camera.Position));
													edotc = Raymath.Vector3DotProduct(erelc,cfwd);
													if(edotc<minedotc)
													{
														if(edotc<0)
														{
															if(gdist>15)
															{
																continue;
															}
														}
														if(gdist>50)
														{
															continue;
														}
														
													}
													
												}
											}
											Grass.grassarray[i].offscreen = 0;
											}
											dist = gdist;
											if(ambient==0 && drewlast==0)
											{
												if(Program.recordframe==0  && no_opt==0 && Raymath.Vector3Distance(Grass.grassarray[i].grassposition,voffset)>400 && Program.demomode==0 && Program.videomode==0) //guesstimate of the distance...
												{
													continue;
												}
												gscreenpos = Raylib.GetWorldToScreen(Grass.grassarray[i].grassposition, camera);
												Grass.grassarray[i].distfromedge = Raymath.Vector2Distance(gscreenpos,vscreenon2);
												if(gscreenpos.X<-resx/2 || gscreenpos.X>resx+resx/2 || gscreenpos.Y<-resy/2 || gscreenpos.Y>resy+resy/2)
												{
													continue;
												}
												if(demomode!=0 && Grass.grassarray[i].gtype!=3 && Grass.grassarray[i].gtype!=6 && camera.Position.Y<40)
												{
													//what this does is says it's behind a bush, so don't draw it.
													int bx = (int)(gscreenpos.X/10);
													int by = (int)(gscreenpos.Y/10);
													if(bx>=0 && by>=0 && bx<resx/10 && by<resy/10)
													{
														if(bushdist[bx+by*(resx/10)]!=0 && bushdist[bx+by*(resx/10)]<gdist)
														{
															continue;
														}
													}
												}
												if(demomode==0 && Grass.grassarray[i].gtype<3)
												{
													if(gscreenpos.Y>(float)resy*guiocclusion) //gui is obstructing view.
													{
														continue;	
													}
												}
											}
											if(demomode==0 && videomode==0)
											{
												if(ambient==0 && drewlast==0)
												{
													if(gscreenpos.X<0 || gscreenpos.X>resx || gscreenpos.Y<0 || gscreenpos.Y>resy+resy/4)
													{
														continue;
													}
													if(Grass.grassarray[i].gtype==0)// && no_opt==0) //single elements of grass//28jul2025
													{
														//these are so tiny that unless you're zoomed in you'll never see them
														//so in other words - if FovY is >=30 don't draw them.
														if(camera.FovY>=30)
														{
															continue;
														}
													}
													if(Grass.grassarray[i].gtype==5 || Grass.grassarray[i].gtype<3 && no_opt==0) // clumps of grass //28jul2025 and small rocks
													{
														if(camera.FovY>=30)
														{
															noshadow = 1;
														}
													}
												}	
												if(Grass.grassarray[i].gtype==3 || Grass.grassarray[i].gtype==6)
												{
													lod = oldlod;
													if(fps<targetfps-targetfps/3 - 5 && lodchangetime<=0)// && no_opt==0)
													{
														lod++;//library change
														if(lod>2)
														{
															lod = 2;
														}
														lodchangetime = targetfps*4;
														oldlod = lod;
													}
													if(fps>=targetfps-targetfps/3 + 5 && lodchangetime<=0)// && no_opt==0)
													{
														lod--;//library change
														if(lod<0)
														{
															lod = 0;
														}
														lodchangetime = targetfps*4;
														oldlod = lod;
													}
													
													if(((resx/2 - Math.Abs(gscreenpos.X-(resx/2)))<resx/4 || (resy/2 - Math.Abs(gscreenpos.Y-(resy/2)))<resy/4))// && no_opt==0)
													{
														lod++;//library change
														if(lod>2)
														{
															lod = 2;
														}
													}
												}
												
											}
											else
											{
												if(dist>700 && no_opt==0 && ambient==0 && drewlast==0)
												{
													continue;
												}
												if(dist>200 && Grass.grassarray[i].gtype!=3 && Grass.grassarray[i].gtype!=6 && drewlast==0)
												{
													if(gscreenpos.X<0 || gscreenpos.X>resx || gscreenpos.Y<0 || gscreenpos.Y>resy)
													{
														continue;
													}
												}
												
												erelc = Raymath.Vector3Normalize(Raymath.Vector3Subtract(Grass.grassarray[i].grassposition,camera.Position));
												edotc = Raymath.Vector3DotProduct(erelc,cfwd);
												if(edotc<minedotc)// && no_opt==0)
												{
													if(drewlast==0)
													{
														if(edotc<0)
														{
															continue;
														}
														if(gdist>50)
														{
															continue;
														}
														if(Grass.grassarray[i].gtype < 3) //single grass, rocks (small stuff)
														{
															continue;
														}
													}
												}
												else
												{
													if(gdist>400)// && no_opt==0)
													{
														lod = 2; //library change
													}
													else
													{
														if(Grass.grassarray[i].gtype==3 || Grass.grassarray[i].gtype==6)
														{
															if(gdist>200)// && no_opt==0)
															{
																if(fps<targetfps - targetfps/3 || lotstorender!=0)
																{
																	lod = 1; //library change
																}
															}
														}
													}
													if(fps<targetfps/2 + 5)// && no_opt==0)
													{
														lod++;
													}
												}
												//a really simplistic form of occlusion culling
												//based on the fact buildings are big and block
												//view when in demomode especially for things far away.
												if(Grass.grassarray[i].gtype!=3 && Grass.grassarray[i].gtype!=6 && ambient==0 && drewlast==0)// && no_opt==0)
												{
													for(int bb=0;bb<Building.maxbuildings;bb++)
													{
														if(bdist[bb]<10000 && bdist[bb] < dist && dist > 200)
														{
															objreltocam = Raymath.Vector3Normalize(Raymath.Vector3Subtract(Grass.grassarray[i].grassposition,camera.Position));
															bdot = Raymath.Vector3DotProduct(bcpos[bb],objreltocam);
															if(bdot > minbdot)
															{
																continue;
															}
														}
													}
												}
											}
											if(autooptimise>1 && ambient==0 && drewlast==0)// && no_opt==0)
											{
												if(demomode==0 && Grass.incover(Grass.grassarray[i].x,Grass.grassarray[i].z)!=0)//optimisation
												{
													if(Grass.grassarray[i].gtype<1) //plain grasses
													{
														if(fps<targetfps-targetfps/3)
														{
															//continue;
														}
													}
												}
											}
											if(lod<baselod)//library change
											{
												lod = baselod;
											}
											if(lod>maxlod)//library change
											{
												lod = maxlod;
											}
											if(gdist>400 && demomode!=0)// && no_opt==0)
											{
												noshadow = 1;
											}
											if(gdist<100 && (Grass.grassarray[i].gtype==3 || Grass.grassarray[i].gtype==6))
											{
												//close range trees
												treesdrawn++;
											}
											float sc = Grass.grassarray[i].sc;
											if(Grass.grassarray[i].gtype==4)
											{
												sc = 1;
											}
											if(Grass.grassarray[i].gtype==3 || Grass.grassarray[i].gtype==6)
											{
												if(dist<50)
												{
													if(dist<distmin || distmin==-1)
													{
														distmin = dist;
														tmpggmin = gg;
													}
												}
												if(dist>100)
												{
													if(dist>distmax || distmax==-1)
													{
														distmax = dist;
														tmpggmax = gg;
													}
												}
											}
											if(Grass.useshader!=0)
											{
												float xstep = 1;
												float zstep = 1;
												if((Grass.grassarray[i].gtype==5 || Grass.grassarray[i].gtype==1 || Grass.grassarray[i].gtype==2) && GameUI.extrafoliage!=0)
												{
													xstep = 20;
													zstep = 20;
												}
												if(Program.videomode==1 && Program.renderframe!=0)
												{
													xstep = 25;//todo
													zstep = 25;//todo
												}
												if(Grass.grassarray[i].gtype==4)
												{
													xstep = 1;
													zstep = 1;
												}
												
												if(xstep==1)
												{
													for(float xx = 0;xx<1;xx+=1)
													{
														for(float zz = 0;zz<1;zz+=1)
														{
															float angle = 0;
															Matrix4x4 rotationmatrix = Raymath.MatrixRotateX(angle);
															fshadow = 0.65f;
															if(Grass.grassarray[i].gtype!=4 && ambient==0 && noshadow==0) //not a crater....//28jul2025 added noshadow
															{
																Grass.grassarray[i].shadowtransform = Raymath.MatrixIdentity();
																Grass.grassarray[i].shadowtransform = Raymath.MatrixMultiply(Raymath.MatrixScale(sc,sc,sc),Grass.grassarray[i].shadowtransform);
																Grass.grassarray[i].shadowtransform = Raymath.MatrixMultiply(Raymath.MatrixTranslate((Grass.grassarray[i].x+xx)/sc,Grass.grassarray[i].y/sc,(Grass.grassarray[i].z+zz)/sc),Grass.grassarray[i].shadowtransform);
																angle = (3.14159f / 180f) * (Grass.grassarray[i].angle);
																rotationmatrix = Raymath.MatrixRotateX(angle);
																if(Grass.grassarray[i].gtype==1 || Grass.grassarray[i].gtype==2)
																{
																	rotationmatrix = Raymath.MatrixRotateY(Grass.grassarray[i].angle);
																}
																Grass.grassarray[i].model.Transform = Raymath.MatrixMultiply(rotationmatrix,Grass.grassarray[i].shadowtransform);
																{
																	{
																		Raylib.BeginShaderMode(Grass.grassarray[i].shader);
																		unsafe
																		{
																			Raylib.SetShaderValueV(Grass.grassarray[i].shader,Grass.grassarray[i].shadow,&fshadow,ShaderUniformDataType.Float,1);
																		}
																		Raylib.SetShaderValueMatrix(Grass.grassarray[i].shader,Grass.grassarray[i].modelMatrix,Grass.grassarray[i].model.Transform);
																		Raylib.EndShaderMode();
																		//24april2025 commented out lod for the shadows because
																		//shadow mesh can easily get away with los res mesh
																		//it will create some dead code below, but that doesn't really matter much
																		if((demomode==0 || dist < 400 || Grass.grassarray[i].gtype==3 || Grass.grassarray[i].gtype==6) && noshadow==0) //28jul2025
																		{
																			if((Grass.grassarray[i].gtype==3 || Grass.grassarray[i].gtype==6))// && lod!=0)
																			{
																				if(Grass.treetype>1)
																				{
																					unsafe
																					{
																						Raylib.DrawMesh(Grass.grassarray[i].lod_3.Meshes[0],Grass.grassarray[i].lod_3.Materials[0],Grass.grassarray[i].model.Transform);															
																					}
																					Grass.grassarray[i].drawn = 1;
																				}
																				else
																				{
																					if(Grass.treetype==0)
																					{
																						unsafe
																						{
																							
																							Raylib.DrawMesh(Grass.grassarray[i].lod_1.Meshes[0],Grass.grassarray[i].lod_1.Materials[0],Grass.grassarray[i].model.Transform);
																						}
																						Grass.grassarray[i].drawn = 1;
																					}
																					else
																					{
																						unsafe
																						{
																							Raylib.DrawMesh(Grass.grassarray[i].lod_2.Meshes[0],Grass.grassarray[i].lod_2.Materials[0],Grass.grassarray[i].model.Transform);																	
																						}
																						Grass.grassarray[i].drawn = 1;
																					}
																				}
																			}
																			else
																			{
																				if((Grass.grassarray[i].gtype==3 || Grass.grassarray[i].gtype==6 || Grass.grassarray[i].gtype==5) && Grass.treetype>=1)
																				{
																					if(Grass.treetype>1)
																					{
																						unsafe
																						{	
																							Raylib.DrawMesh(Grass.grassarray[i].model3.Meshes[0],Grass.grassarray[i].model3.Materials[0],Grass.grassarray[i].model.Transform);
																						}
																						Grass.grassarray[i].drawn = 1;
																					}
																					else
																					{
																						if(Grass.grassarray[i].gtype!=5) 
																						{
																							unsafe
																							{	
																								Raylib.DrawMesh(Grass.grassarray[i].model2.Meshes[0],Grass.grassarray[i].model2.Materials[0],Grass.grassarray[i].model.Transform);
																							}
																							Grass.grassarray[i].drawn = 1;
