																			}
																			else
																			{
																				break;
																			}
																		}
																	}
																}
															}
															Grass.grassarray[i].transform = Raymath.MatrixIdentity();
															if(Grass.grassarray[i].gtype==0 || Grass.grassarray[i].gtype==5)
															{
																Grass.grassarray[i].transform = Raymath.MatrixMultiply(Raymath.MatrixScale(sc,sc*0.8f,sc),Grass.grassarray[i].transform);
																Grass.grassarray[i].transform = Raymath.MatrixMultiply(Raymath.MatrixTranslate((Grass.grassarray[i].x+xx)/sc,(Grass.grassarray[i].y)/(sc*0.8f),(Grass.grassarray[i].z+zz)/sc),Grass.grassarray[i].transform);											
															}
															else
															{
																Grass.grassarray[i].transform = Raymath.MatrixMultiply(Raymath.MatrixScale(sc,sc,sc),Grass.grassarray[i].transform);
																Grass.grassarray[i].transform = Raymath.MatrixMultiply(Raymath.MatrixTranslate((xx+Grass.grassarray[i].x)/sc,(Grass.grassarray[i].y)/sc,(zz+Grass.grassarray[i].z)/sc),Grass.grassarray[i].transform);
															}
															Grass.grassarray[i].transformset = 1;
															angle = (3.14159f / 180f) * (Grass.grassarray[i].angle);
															rotationmatrix = Raymath.MatrixRotateX(angle);
															if(Grass.grassarray[i].gtype==1 || Grass.grassarray[i].gtype==2)
															{
																rotationmatrix = Raymath.MatrixRotateY(Grass.grassarray[i].angle);
															}
																
															Grass.grassarray[i].model.Transform = Raymath.MatrixMultiply(rotationmatrix,Grass.grassarray[i].transform);
															issnowing = GameUI.snowing;
															if(issnowing!=0)
															{
																if(i%5<2)
																{
																	issnowing=0;
																}
															}
															float issway = 0;
															if(Grass.grassarray[i].gtype==4)
															{
																issway = 1;
															}
															{
																Raylib.BeginShaderMode(Grass.grassarray[i].shader);
																unsafe
																{
																	Raylib.SetShaderValueV(Grass.grassarray[i].shader,Grass.grassarray[i].shadow,&fshadow,ShaderUniformDataType.Float,1);
																	Raylib.SetShaderValueV(Grass.grassarray[i].shader,Grass.grassarray[i].snowing,&issnowing,ShaderUniformDataType.Float,1);								
																	Raylib.SetShaderValueV(Grass.grassarray[i].shader,Grass.grassarray[i].sway,&issway,ShaderUniformDataType.Float,1);
																}
																Raylib.SetShaderValueMatrix(Grass.grassarray[i].shader,Grass.grassarray[i].modelMatrix,Grass.grassarray[i].model.Transform);
																Raylib.EndShaderMode();
																if((Grass.grassarray[i].gtype==3 || Grass.grassarray[i].gtype==6) && lod!=0)
																{
																	if(lod<2)
																	{
																		if(Grass.treetype>1)
																		{
																			unsafe
																			{
																				Raylib.DrawMesh(Grass.grassarray[i].lod_3.Meshes[0],Grass.grassarray[i].lod_3.Materials[0],Grass.grassarray[i].model.Transform);															
																			}
																			Grass.grassarray[i].drawn = 1;
																		}
																		else
																		{
																			if(Grass.treetype==0)
																			{
																				unsafe
																				{
																					Raylib.DrawMesh(Grass.grassarray[i].lod_1.Meshes[0],Grass.grassarray[i].lod_1.Materials[0],Grass.grassarray[i].model.Transform);
																				}
																				Grass.grassarray[i].drawn = 1;
																			}
																			else
																			{
																				unsafe
																				{
																					Raylib.DrawMesh(Grass.grassarray[i].lod_2.Meshes[0],Grass.grassarray[i].lod_2.Materials[0],Grass.grassarray[i].model.Transform);																	
																				}
																				Grass.grassarray[i].drawn = 1;
																			}
																		}
																	}
																	else
																	{
																		if(Grass.treetype>1)
																		{
																			unsafe
																			{
																				Raylib.DrawMesh(Grass.grassarray[i].lod3.Meshes[0],Grass.grassarray[i].lod3.Materials[0],Grass.grassarray[i].model.Transform);															
																			}
																			Grass.grassarray[i].drawn = 1;
																		}
																		else
																		{
																			if(Grass.treetype==0)
																			{
																				unsafe
																				{
																					Raylib.DrawMesh(Grass.grassarray[i].lod.Meshes[0],Grass.grassarray[i].lod.Materials[0],Grass.grassarray[i].model.Transform);
																				}
																				Grass.grassarray[i].drawn = 1;
																			}
																			else
																			{
																				unsafe
																				{
																					Raylib.DrawMesh(Grass.grassarray[i].lod2.Meshes[0],Grass.grassarray[i].lod2.Materials[0],Grass.grassarray[i].model.Transform);																	
																				}
																				Grass.grassarray[i].drawn = 1;
																			}
																		}
																		
																	}
																}
																else
																{
																	if((Grass.grassarray[i].gtype==3 || Grass.grassarray[i].gtype==6 || Grass.grassarray[i].gtype==5) && Grass.treetype>=1)
																	{
																		if(Grass.treetype>1)
																		{
																			unsafe
																			{	
																				Raylib.DrawMesh(Grass.grassarray[i].model3.Meshes[0],Grass.grassarray[i].model3.Materials[0],Grass.grassarray[i].model.Transform);
																			}
																			Grass.grassarray[i].drawn = 1;
																		}
																		else
																		{
																			unsafe
																			{	
																				Raylib.DrawMesh(Grass.grassarray[i].model2.Meshes[0],Grass.grassarray[i].model2.Materials[0],Grass.grassarray[i].model.Transform);
																			}
																			Grass.grassarray[i].drawn = 1;
																		}
																	}
																	else
																	{
																		unsafe
																		{	
																			Raylib.DrawMesh(Grass.grassarray[i].model.Meshes[0],Grass.grassarray[i].model.Materials[0],Grass.grassarray[i].model.Transform);
																		}
																		Grass.grassarray[i].drawn = 1;
																	}
																}
															}
														}
													}
												}
												Raylib.EndBlendMode();
												Profile.shadertime[6]-=Profile.timer.ElapsedMilliseconds;	
												GameUI.treealpha = otreealpha;
												//library change - removed ground fog method that was here since it's not used...never was.
											}
											if(gg>0) //really weak sorting algorithm.....slowly sort the list  (it's really, really weak....barely useful at all really....but it does have a use.
											{
												int ii = Grass.orderarray[gg-1];
												if(ii!=-1 && i!=-1)
												{
													if(Grass.grassarray[ii].gtype==Grass.grassarray[i].gtype)
													{
														if(Grass.grassarray[ii].distfromcamera < Grass.grassarray[i].distfromcamera)
														{
															Grass.orderarray[gg-1] = i;
															Grass.orderarray[gg] = ii;
														}
													}
												}
											}
										}
									}
									//now draw the bushes if the camera is beneath 10 units in height - means we might be able to see under the leaves and stuff causing transparency problems.
									if(camera.Position.Y<=10)
									{
										for(int j=0;j<Grass.maxbush;j++)
										{
											int i = Grass.bushorderarray[j];
											if(i<0)
											{
												continue;
											}
											if(Grass.bushposangle[i]!=0)
											{
												float sc = 1.75f*0.1f;
												fshadow = 0;
												if(i%(GameUI.reducefoliage+1)!=0 && no_opt==0) //less foliage //note it gets set to the gameui version, which is semirandom....
												{
													continue;
												}
												float dist = 0;
												total_entities+=2;
												drewlast = 0;
												if(camnoshift!=0 && Grass.bushdrawn[i]!=0)
												{
													drewlast = 1;
												}
												if(ambiento==0)
												{
													if(cammoved==0 && Grass.bushdrawn[i]==0)
													{
														//we didn't draw it last time
														//and the camera hasn't moved
														//so....skip it
														continue;
													}
													if(cammoved!=0 && Grass.bushdrawn[i]==0 && demomode==0)
													{
														//maybe the camera moved a lot.....
														//distance we moved.....
														float cdist = Raymath.Vector3Distance(Grass.oldcameraposition,camera.Position);
														if(Grass.bushdistfromedge[i]!=0)
														{
															float screensize = Raymath.Vector2Length(vscreen);
															float fraction = cdist / (Grass.bushdistfromedge[i]/screensize);
															//if fraction is larger than a certain value
															//then we should go through the various checks
															//but if fraction is smaller than a certain value
															//we should not
															if(fraction < drawmovetolerance)
															{
																continue;
															}
														}
													}
													Grass.bushdrawn[i] = 0;
												}
												else
												{
													if(Grass.bushdrawn[i]==0)
													{
														continue;
													}
												}
												//upto
												if(ambient==0 && drewlast==0)
												{
													if(demomode!=0)
													{
														erelc = Raymath.Vector3Normalize(Raymath.Vector3Subtract(Grass.bushpos[i],camera.Position));
														edotc = Raymath.Vector3DotProduct(erelc,cfwd);
														if(edotc<minedotc)
														{
															if(edotc<0)
															{
																continue;
															}
															if(Raymath.Vector3Distance(Grass.bushpos[i],camera.Position)>50)
															{
																continue;
															}
														}
													}
													dist = Raymath.Vector3Distance(Grass.bushpos[i],camera.Position);					
													if(ambient!=0 && demomode!=0)
													{
														if(dist>350)
														{
															continue;
														}
													}
													if(Program.recordframe==0 && Raymath.Vector3Distance(Grass.bushpos[i],voffset)>400 && Program.demomode==0 && Program.videomode==0 && no_opt==0) //guesstimate of the distance...
													{
														continue;
													}
													gscreenpos = Raylib.GetWorldToScreen(Grass.bushpos[i], camera);
													Grass.bushdistfromedge[i] = Raymath.Vector2Distance(gscreenpos,vscreenon2);
													if(gscreenpos.X<-resx/2 || gscreenpos.X>resx+resx/2 || gscreenpos.Y<-resy/2 || gscreenpos.Y>resy+resy/2)
													{
														continue;
													}
													if(demomode==0)
													{
														if(gscreenpos.Y>(float)resy*guiocclusion) //gui is obstructing view.
														{
															continue;	
														}
													}
													if(demomode==0 && videomode==0)
													{
														if(gscreenpos.X<0 || gscreenpos.X>resx || gscreenpos.Y<0 || gscreenpos.Y>resy+resy/4)
														{
															continue;
														}
													}
													else
													{
														if(dist>700 && no_opt==0)
														{
															continue;
														}
														if(dist>300)
														{
															if(gscreenpos.X<0 || gscreenpos.X>resx || gscreenpos.Y<0 || gscreenpos.Y>resy)
															{
																continue;
															}
														}
														erelc = Raymath.Vector3Normalize(Raymath.Vector3Subtract(Grass.bushpos[i],camera.Position));
														edotc = Raymath.Vector3DotProduct(erelc,cfwd);
														if(edotc<minedotc)
														{
															continue;
														}
														//a really simplistic form of occlusion culling
														//based on the fact buildings are big and block
														//view when in demomode especially for things far away.
														{
															for(int bb=0;bb<Building.maxbuildings;bb++)
															{
																if(bdist[bb]<10000 && bdist[bb] < dist && dist > 200)
																{
																	objreltocam = Raymath.Vector3Normalize(Raymath.Vector3Subtract(Grass.bushpos[i],camera.Position));
																	bdot = Raymath.Vector3DotProduct(bcpos[bb],objreltocam);
																	if(bdot > minbdot)
																	{
																		continue;
																	}
																}
															}
														}
													}
													int bx = (int)(gscreenpos.X/10);
													int by = (int)(gscreenpos.Y/10);
													int ax = 0;
													int ay = 0;
													if(bx+ax>=0 && by+ay>=0 && bx+ax<resx/10 && by+ay<resy/10)
													{
														if(bushdist[bx+ax+(by+ay)*(resx/10)]>dist || bushdist[(bx+ax)+(by+ay)*(resx/10)]==0)
														{
															bushdist[bx+ax+(by+ay)*(resx/10)] = dist;
														}
													}
													if(dist<100)
													{
														for(ax=-1;ax<=1;ax++)
														{
															for(ay=-1;ay<=1;ay++)
															{
																if(ax!=0 || ay!=0)
																{
																	if(bx+ax>=0 && by+ay>=0 && bx+ax<resx/10 && by+ay<resy/10)
																	{
																		if(bushdist[bx+ax+(by+ay)*(resx/10)]>dist || bushdist[(bx+ax)+(by+ay)*(resx/10)]==0)
																		{
																			bushdist[bx+ax+(by+ay)*(resx/10)] = dist;
																		}
																	}
																}
															}
														}
													}
												}
												Grass.bush.Transform = Raymath.MatrixIdentity();
												Grass.bush.Transform = Raymath.MatrixMultiply(Raymath.MatrixScale(sc,sc,sc),Grass.bush.Transform);
												Grass.bush.Transform = Raymath.MatrixMultiply(Raymath.MatrixTranslate((Grass.bushposx[i])/sc,(0.01f)/sc,(Grass.bushposz[i])/sc),Grass.bush.Transform);
												Grass.bush.Transform = Raymath.MatrixMultiply(Raymath.MatrixRotateY(Grass.bushposangle[i]),Grass.bush.Transform);
												Raylib.BeginShaderMode(Grass.bushshader);
												unsafe
												{
													Raylib.SetShaderValueV(Grass.bushshader,Grass.bambientocclusion,&ambientof,ShaderUniformDataType.Float,1);
												}
												Raylib.SetShaderValueMatrix(Grass.bushshader,Grass.bmodelMatrix,Grass.bush.Transform);
												Raylib.EndShaderMode();
												unsafe
												{	
													Raylib.DrawMesh(Grass.bush.Meshes[0],Grass.bush.Materials[0],Grass.bush.Transform);
												}
												Grass.bush.Transform = Raymath.MatrixIdentity();
												Grass.bush.Transform = Raymath.MatrixMultiply(Raymath.MatrixScale(sc,sc,sc),Grass.bush.Transform);
												Grass.bush.Transform = Raymath.MatrixMultiply(Raymath.MatrixTranslate((Grass.bushposx[i])/sc,(0.01f)/sc,(Grass.bushposz[i])/sc),Grass.bush.Transform);
												Grass.bush.Transform = Raymath.MatrixMultiply(Raymath.MatrixRotateY(Grass.bushposangle[i]+1.57f),Grass.bush.Transform);
												Raylib.BeginShaderMode(Grass.bushshader);
												unsafe
												{
													Raylib.SetShaderValueV(Grass.bushshader,Grass.bambientocclusion,&ambientof,ShaderUniformDataType.Float,1);
												}
												Raylib.SetShaderValueMatrix(Grass.bushshader,Grass.bmodelMatrix,Grass.bush.Transform);
												Raylib.EndShaderMode();
												unsafe
												{	
													Raylib.DrawMesh(Grass.bush.Meshes[0],Grass.bush.Materials[0],Grass.bush.Transform);
												}
												Grass.bushdrawn[i] = 1;
												drawn_entities++;
											}
										}
										
									}
									if(tmpggmin!=-1 && tmpggmax!=-1) //a very weak attempt to make sure the closest tree is rendered last
									{
										int ggswap = Grass.orderarray[tmpggmin];
										Grass.orderarray[tmpggmin] = Grass.orderarray[tmpggmax];
										Grass.orderarray[tmpggmax] = ggswap;
									}
									if(tmpopt!=0)
									{
										no_opt = 0;
									}
								//}
								//flybys //28jul2025
								if(flybys!=0 && ambient==0)
								{
									//17aug2025 updated this to handle the rest of the ships in the airstrike
									for(int flyer=0;flyer<11;flyer++) //there's so few of them don't even worry about culling them from the view...won't affect framerate at all. Pretty much.
									{
										if(flyer>=3)//17aug2025
										{
											if(flyby.airstrike[flyer]==0)
											{
												continue;
											}
										}
										//they'll fly by whenever one gets built, from the corner to the other corner...at a height of about 45 units....
										//no idea how big they are unscaled, so you might need to adjust sc=1 to something else below.
										//I don't have any way of measuring them at the library, so just have to do this later...
										//fair enough.
										int i = flyby.id[flyer];
										//technically you should be using xaxis, yaxis and zaxis, since they were built for this
										//but you wrote this code when you couldn't see the top of the program because of your constraints
										//so you created new vector variables. Maybe you should change it now....
										zaxis.X = 3;
										zaxis.Y = 0;
										zaxis.Z = 1;
										if(flyer>=3) //17aug2025
										{
											zaxis.X = flyby.vx[flyer];
											zaxis.Z = flyby.vz[flyer];
											zaxis.Y = flyby.vy[flyer];
										}
										zaxis = Raymath.Vector3Normalize(zaxis);
										yaxis.X = 0;
										yaxis.Y = 1;
										yaxis.Z = 0;
										yaxis = Raymath.Vector3Normalize(yaxis);
										xaxis = Raymath.Vector3CrossProduct(yaxis,zaxis);
										xaxis = Raymath.Vector3Normalize(xaxis);
										Matrix4x4 flyer_rotation_matrix = new Matrix4x4(xaxis.X,yaxis.X,zaxis.X,0,xaxis.Y,yaxis.Y,zaxis.Y,0,xaxis.Z,yaxis.Z,zaxis.Z,0,0,0,0,1);
										float sc = 1; //adjust as needed
										ship.shiparray[i].model.Transform = Raymath.MatrixIdentity();
										ship.shiparray[i].model.Transform = Raymath.MatrixMultiply(Raymath.MatrixScale(sc,sc,sc),ship.shiparray[i].model.Transform);
										ship.shiparray[i].model.Transform = Raymath.MatrixMultiply(Raymath.MatrixTranslate(flyby.x[flyer]/sc,flyby.y[flyer]/sc,flyby.z[flyer]/sc),ship.shiparray[i].model.Transform);
										ship.shiparray[i].model.Transform = Raymath.MatrixMultiply(flyer_rotation_matrix,ship.shiparray[i].model.Transform);
										Raylib.BeginShaderMode(ship.shiparray[i].shader);
										float colormultiplier = 2.75f;
										float ambientf = 0;//(float)ambiento;
										unsafe
										{
											Raylib.SetShaderValueMatrix(ship.shiparray[i].shader,ship.shiparray[i].projectionMatrix,Raylib.GetCameraProjectionMatrix(&camera, Program.aspect));
											Raylib.SetShaderValueMatrix(ship.shiparray[i].shader,ship.shiparray[i].viewMatrix,Raylib.GetCameraViewMatrix(&camera));
											Raylib.SetShaderValueV(ship.shiparray[i].shader,ship.shiparray[i].eyepos,&camera.Position,ShaderUniformDataType.Vec3,3);
											Raylib.SetShaderValue(ship.shiparray[i].shader,ship.shiparray[i].colormultiplier,&colormultiplier,ShaderUniformDataType.Float);
											Raylib.SetShaderValue(ship.shiparray[i].shader,ship.shiparray[i].ambientocclusion,&ambientf,ShaderUniformDataType.Float);
										}
										Raylib.SetShaderValueMatrix(ship.shiparray[i].shader,ship.shiparray[i].modelMatrix,ship.shiparray[i].model.Transform);
										Raylib.EndShaderMode();
										unsafe
										{	
											Raylib.DrawMesh(ship.shiparray[i].model.Meshes[0],ship.shiparray[i].model.Materials[0],ship.shiparray[i].model.Transform);
										}
									}
								}
								//
								Profile.shadertime[7]-=Profile.timer.ElapsedMilliseconds;
							}
							//now we draw smoke and sparks.....and explosions
							if((layer==4 && ambient==0 && Program.demomode==0 && Program.videomode==0) || (layer==3 && ambient==0 && (Program.demomode==1 || Program.videomode==1)))//explosions
							{
								added = 0;
								//smoke and sparks
								Raylib.BeginBlendMode(BlendMode.Alpha);
								Profile.shadertime[11]=Profile.timer.ElapsedMilliseconds;	
								//sparks
								added = 0;
								for(int i=0;i<spark.maxspark;i++)
								{
									if(treetest!=0)
									{
										break;
									}
									if(i>spark.highest)
									{
										break;
									}
									if(i%10>optimisefactor && videomode==0 && no_opt==0)
									{
										continue;
									}
									if(spark.sparks[i].maxpi>spark.maxp)
									{
										spark.sparks[i].maxpi = spark.maxp;
									}
									for(int p=0;p<spark.sparks[i].maxpi;p++)
									{
										if(spark.sparks[i].lifetime[p]<=0)
										{
											continue;
										}
										if(spark.sparks[i].inview==0 && cammoved==0 && videomode==0)
										{
											continue;
										}
										if(camnoshift!=0 && spark.sparks[i].inview==0)
										{
											continue;
										}
										if(demomode==0 && videomode==0)
										{
											if(NearSector(spark.sparks[i].sectorx,spark.sparks[i].sectorz,camera_sectorx,camera_sectorz)==0)
											{
												continue;
											}
										}
										screenpos = Raylib.GetWorldToScreen(spark.sparks[i].position, camera);
										if(screenpos.X<0 || screenpos.X>resx || screenpos.Y<0 || screenpos.Y>resy && videomode==0)
										{
											spark.sparks[i].inview = 0;
											continue;
										}
										if(demomode==0)
										{
											if(screenpos.Y>(float)resy*guiocclusion) //gui is obstructing view.
											{
												continue;	
											}
										}
										if(demomode!=0)
										{
											erelc = Raymath.Vector3Normalize(Raymath.Vector3Subtract(spark.sparks[i].position,camera.Position));
											edotc = Raymath.Vector3DotProduct(erelc,cfwd);
											if(edotc<minedotc)
											{
												if(edotc<0)
												{
													continue;
												}
												if(Raymath.Vector3Distance(spark.sparks[i].position,camera.Position)>50)
												{
													continue;
												}
											}
										}
										if(Raymath.Vector3Length(spark.sparks[i].position)>550 && no_opt==0)
										{
											continue;
										}
										if(Raymath.Vector3Distance(spark.sparks[i].position,camera.Position)>300 && demomode!=0 && no_opt==0)
										{
											continue;
										}
										spark.sparks[i].inview = 1;
										float msc = 7.5f * 1f;
										msc*=0.05f;
										spark.cmodel.Transform = Raymath.MatrixIdentity();
										spark.cmodel.Transform = Raymath.MatrixMultiply(Raymath.MatrixScale(msc,msc,msc),spark.cmodel.Transform);
										spark.cmodel.Transform = Raymath.MatrixMultiply(Raymath.MatrixTranslate(spark.sparks[i].x[p]/msc,spark.sparks[i].y[p]/msc,spark.sparks[i].z[p]/msc),spark.cmodel.Transform);
										Matrix4x4 rotationmatrix = Raymath.MatrixRotateY(-3.14159f/4f);
										spark.cmodel.Transform = Raymath.MatrixMultiply(rotationmatrix,spark.cmodel.Transform);
										float alpha = (float)spark.sparks[i].lifetime[p]/20f;
										if(alpha<0)
										{
											alpha = 0;
										}
										if(alpha>1)
										{
											alpha = 1;
										}
										{
											Raylib.BeginShaderMode(spark.cshader);
											unsafe
											{
												Raylib.SetShaderValueV(spark.cshader,spark.calpha,&alpha,ShaderUniformDataType.Float,1);								
											}
											Raylib.SetShaderValueMatrix(spark.cshader,spark.cmodelMatrix,spark.cmodel.Transform);
											Raylib.EndShaderMode();
											unsafe
											{	
												Raylib.DrawMesh(spark.cmodel.Meshes[0],spark.cmodel.Materials[0],spark.cmodel.Transform);
											}
											drawn_entities++;
										}								
									}
								}
								Profile.shadertime[11]-=Profile.timer.ElapsedMilliseconds;	
								Profile.shadertime[8]=Profile.timer.ElapsedMilliseconds;	
								//now we draw explosions as well
								if(explosion.useshader!=0 && ambient==0)
								{
									//if(Unit.uframe % 10==0){explosion.orderarray = explosion.QuickSort(explosion.orderarray);} //this should work.
									for(float rangebin=2;rangebin>=0;rangebin--)
									{
										for(int ee=0;ee<explosion.maxexplosions;ee++)
										//for(int ee=explosion.maxexplosions-1;ee>=0;ee--)
										{
											if(treetest!=0)
											{
												break;
											}
											int i = explosion.orderarray[ee];
											float camdist = explosion.explosionarray[i].camdist;
											if(camdist<(rangebin+1f)*333f && camdist>=rangebin*333f)
											{
												//we want this one...
											}
											else
											{
												continue;
											}
											if(i%10>optimisefactor && videomode==0 && no_opt==0) //this should be removed really....if performance isn't affected then we should remove this...
											{
												continue;
											}
											if(explosion.explosionarray[i].inspace==1)
											{
												continue;
											}
											if(explosion.explosionarray[i].onground==0)
											{
												continue;
											}
											if(explosion.explosionarray[i].issmoke==0 && i%8==7)
											{
												continue;
											}
											float yoffset = 0;
											if(demomode==0 && videomode==0)
											{
												if(NearSector(explosion.explosionarray[i].sectorx,explosion.explosionarray[i].sectorz,camera_sectorx,camera_sectorz)==0)
												{
													continue;
												}
												yoffset = 1.6f - 0.002f * (float)ee;
											}
											if(Raymath.Vector3Length(new Vector3(explosion.explosionarray[i].x,explosion.explosionarray[i].y,explosion.explosionarray[i].z))>550 && no_opt==0)
											{
												continue;
											}
											if(demomode!=0)
											{
												position = new Vector3(explosion.explosionarray[i].x,explosion.explosionarray[i].y,explosion.explosionarray[i].z);
												erelc = Raymath.Vector3Normalize(Raymath.Vector3Subtract(position,camera.Position));
												edotc = Raymath.Vector3DotProduct(erelc,cfwd);
												if(edotc<minedotc)
												{
													if(edotc<0)
													{
														continue;
													}
													if(Raymath.Vector3Distance(position,camera.Position)>50)
													{
														continue;
													}
													
												}
											}
											if(explosion.explosionarray[i].animframe >=0 && explosion.explosionarray[i].animframe < 64)
											{
												if(explosion.explosionarray[i].animframe <8 && explosion.explosionarray[i].size >= 2)
												{
													Program.explosion_effects[ship.random.Next(0,8)] = new Vector3(explosion.explosionarray[i].x,explosion.explosionarray[i].y,explosion.explosionarray[i].z);
												}
												if(explosion.explosionarray[i].transformset==0)
												{
													explosion.explosionarray[i].model.Transform = Raymath.MatrixIdentity();
													explosion.explosionarray[i].scale = 0.75f;
													explosion.explosionarray[i].model.Transform = Raymath.MatrixMultiply(Raymath.MatrixScale(explosion.explosionarray[i].scale*explosion.explosionarray[i].size,explosion.explosionarray[i].scale*explosion.explosionarray[i].size,explosion.explosionarray[i].scale*explosion.explosionarray[i].size),explosion.explosionarray[i].model.Transform);
													explosion.explosionarray[i].model.Transform = Raymath.MatrixMultiply(Raymath.MatrixTranslate(explosion.explosionarray[i].x/(explosion.explosionarray[i].size * explosion.explosionarray[i].scale),(explosion.explosionarray[i].y+yoffset)/(explosion.explosionarray[i].size * explosion.explosionarray[i].scale),explosion.explosionarray[i].z/(explosion.explosionarray[i].size * explosion.explosionarray[i].scale)),explosion.explosionarray[i].model.Transform);
													Matrix4x4 rotationmatrix = Raymath.MatrixRotateY(-3.14159f/4f);
													if(demomode==0 && videomode==0){explosion.explosionarray[i].model.Transform = Raymath.MatrixMultiply(rotationmatrix,explosion.explosionarray[i].model.Transform);}
													explosion.explosionarray[i].transform = explosion.explosionarray[i].model.Transform;
													explosion.explosionarray[i].transformset = 1;
												}
												else
												{
													explosion.explosionarray[i].model.Transform = explosion.explosionarray[i].transform;
												}
												if(demomode==1 || videomode==1)
												{
													unsafe
													{
														zaxis = Raylib.GetCameraForward(&camera);
													}
													unsafe
													{
														xaxis = Raylib.GetCameraRight(&camera);
													}
													//zaxis = forwards
													//yaxis = up vector
													//xaxis = right vector
													if(zaxis.Z!=0)
													{
														yaxis = new Vector3(zaxis.Y,- zaxis.X,0);
													}
													else
													{
														yaxis = new Vector3(0,0,1);
													}
													yaxis = Raymath.Vector3Normalize(yaxis);
													xaxis = Raymath.Vector3CrossProduct(yaxis,zaxis);
													xaxis = Raymath.Vector3Normalize(xaxis);
													Matrix4x4 rotationmatrix = new Matrix4x4(yaxis.X,xaxis.X,zaxis.X,0,yaxis.Y,xaxis.Y,zaxis.Y,0,yaxis.Z,xaxis.Z,zaxis.Z,0,0,0,0,1);
													explosion.explosionarray[i].model.Transform = Raymath.MatrixMultiply(rotationmatrix,explosion.explosionarray[i].model.Transform);
												}
												//
												int animframe = ((int)explosion.explosionarray[i].animframe)%64;
												
												int grey = 0;
												Raylib.BeginShaderMode(explosion.explosionarray[i].shader);
												unsafe
												{
													Raylib.SetShaderValueMatrix(explosion.explosionarray[i].shader,explosion.explosionarray[i].projectionMatrix,Raylib.GetCameraProjectionMatrix(&camera, Program.aspect));
													Raylib.SetShaderValueMatrix(explosion.explosionarray[i].shader,explosion.explosionarray[i].viewMatrix,Raylib.GetCameraViewMatrix(&camera));
													Raylib.SetShaderValue(explosion.explosionarray[i].shader,explosion.explosionarray[i].shaderframe,&animframe,ShaderUniformDataType.Int);
													Raylib.SetShaderValue(explosion.explosionarray[i].shader,explosion.explosionarray[i].grey,&grey,ShaderUniformDataType.Int);
												}
												Raylib.SetShaderValueMatrix(explosion.explosionarray[i].shader,explosion.explosionarray[i].modelMatrix,explosion.explosionarray[i].model.Transform);
												Raylib.EndShaderMode();	
												unsafe
												{	
													Raylib.DrawMesh(explosion.explosionarray[i].model.Meshes[0],explosion.explosionarray[i].model.Materials[0],explosion.explosionarray[i].model.Transform);
												}
												drawn_entities++;
											}
										}
									}
								}
								Profile.shadertime[8]-=Profile.timer.ElapsedMilliseconds;								
								Raylib.EndBlendMode();
							}
							//smoke on a separate layer
							if((layer==5 && ambient==0 && Program.demomode==0 && Program.videomode==0) || (layer==3 && ambient==0 && (Program.demomode==1 || Program.videomode==1)))//smoke
							{
								//Smoke....
								added = 0;
								Profile.shadertime[9]=Profile.timer.ElapsedMilliseconds;	
								Raylib.BeginBlendMode(BlendMode.Alpha);
								if(smoker!=0)
								{
									if(Unit.uframe%15==0 || fps>targetfps-5)
									{
										smoke.smokes = smoke.QuickSort(smoke.smokes);
									}
									for(int i=0;i<smoke.maxsmoke;i++) 
									{
										if(treetest!=0)
										{
											break;
										}
										if(i>smoke.highest)
										{
											break;
										}
										if(smoke.smokes[i].inview==0 && cammoved==0 && videomode==0 && demomode==0)
										{
											continue;
										}
										if(camnoshift!=0 && smoke.smokes[i].inview==0)
										{
											continue;
										}
										if(demomode==0 && videomode==0)
										{
											if(NearSector(smoke.smokes[i].sectorx,smoke.smokes[i].sectorz,camera_sectorx,camera_sectorz)==0)
											{
												continue;
											}
										}
										screenpos = Raylib.GetWorldToScreen(smoke.smokes[i].position, camera);
										if(screenpos.X<0 || screenpos.X>resx || screenpos.Y<0 || screenpos.Y>resy && videomode==0)
										{
											smoke.smokes[i].inview = 0;
											continue;
										}
										if(demomode!=0)
										{
											erelc = Raymath.Vector3Normalize(Raymath.Vector3Subtract(smoke.smokes[i].position,camera.Position));
											edotc = Raymath.Vector3DotProduct(erelc,cfwd);
											if(edotc<minedotc)
											{
												if(edotc<0)
												{
													continue;
												}
												if(Raymath.Vector3Distance(smoke.smokes[i].position,camera.Position)>50)
												{
													continue;
												}
											}
										}
										if(demomode==0)
										{
											if(screenpos.Y>(float)resy*guiocclusion) //gui is obstructing view.
											{
												continue;	
											}
										}
										if(Raymath.Vector3Length(smoke.smokes[i].position)>550 && no_opt==0)
										{
											continue;
										}
										if(smoke.smokes[i].maxpi>smoke.maxp)
										{
											smoke.smokes[i].maxpi = smoke.maxp;
										}
										smoke.smokes[i].inview = 1;
										for(int p=0;p<smoke.smokes[i].maxpi;p++)
										{
											if(smoke.smokes[i].lifetime[p]<=0)
											{
												continue;
											}
											float sc = 1f + (float)((((i+p) % 10)-5))/15f;
											sc*=(200f - (float)(smoke.smokes[i].lifetime[p]))/100f;
											if(sc<0.5)
											{
												sc = 0.5f;
											}
											sc*=1.25f;
											float msc = 7.5f * sc;
											smoke.cmodel.Transform = Raymath.MatrixIdentity();
											smoke.cmodel.Transform = Raymath.MatrixMultiply(Raymath.MatrixScale(msc,msc,msc),smoke.cmodel.Transform);
											smoke.cmodel.Transform = Raymath.MatrixMultiply(Raymath.MatrixTranslate(smoke.smokes[i].x[p]/msc,(smoke.smokes[i].y[p]*0.67f)/msc,smoke.smokes[i].z[p]/msc),smoke.cmodel.Transform);
											//Matrix4x4 rotationmatrix = Raymath.MatrixRotateY(-3.14159f/4f);
											//if(demomode==0 && videomode==0)
											//{
											//	smoke.cmodel.Transform = Raymath.MatrixMultiply(rotationmatrix,smoke.cmodel.Transform);
											//}
											//else
											{
												unsafe
												{
													zaxis = Raylib.GetCameraForward(&camera);
												}
												unsafe
												{
													xaxis = Raylib.GetCameraRight(&camera);
												}
												//zaxis = forwards
												//yaxis = up vector
												//xaxis = right vector
												if(zaxis.Z!=0)
												{
													yaxis = new Vector3(zaxis.Y,- zaxis.X,0);
												}
												else
												{
													yaxis = new Vector3(0,0,1);
												}
												yaxis = Raymath.Vector3Normalize(yaxis);
												xaxis = Raymath.Vector3CrossProduct(yaxis,zaxis);
												xaxis = Raymath.Vector3Normalize(xaxis);
												Matrix4x4 rotationmatrix = new Matrix4x4(xaxis.X,zaxis.X,yaxis.X,0,xaxis.Y,zaxis.Y,yaxis.Y,0,xaxis.Z,zaxis.Z,yaxis.Z,0,0,0,0,1);
												smoke.cmodel.Transform = Raymath.MatrixMultiply(rotationmatrix,smoke.cmodel.Transform);
											}
											float alpha = (float)smoke.smokes[i].lifetime[p]/150f;
											if(smoke.smokes[i].dirt[p]==1)
											{
												msc*=0.65f;
												alpha*=0.85f;
											}
											alpha*=2.5f;
											if(demomode!=0)
											{
												alpha*=0.125f;
											}
											else
											{
												alpha*=0.65f;
											}									
											
											if(alpha<0)
											{
												alpha = 0;
											}
											if(alpha>1)
											{
												alpha = 1;
											}
											{
												Raylib.BeginShaderMode(smoke.cshader);
												unsafe
												{
													Raylib.SetShaderValueV(smoke.cshader,smoke.calpha,&alpha,ShaderUniformDataType.Float,1);								
												}
												Raylib.SetShaderValueMatrix(smoke.cshader,smoke.cmodelMatrix,smoke.cmodel.Transform);
												Raylib.EndShaderMode();
											//	if(added==0)
											//	{
											//		Raylib.EndTextureMode();
											//		Raylib.BeginTextureMode(additivetexture);
											//		Raylib.ClearBackground(new Color(0,0,0,0));
											//	}
												unsafe
												{	
													Raylib.DrawMesh(smoke.cmodel.Meshes[0],smoke.cmodel.Materials[0],smoke.cmodel.Transform);
												}
												drawn_entities++;
												added++;
											//	maxadditive = 16;
											//	if(added>maxadditive)
											//	{
											//		Raylib.EndTextureMode();
											//		added++;
											//		Raylib.BeginTextureMode(layertexture[layer]);
											//		Raylib.DrawTextureRec(additivetexture.Texture,new Rectangle(0,0,resx,-resy),origin,Color.White);
											//		added = 0;
											//	}
											}								
										}
									}
								}
								//if(added>0)
								//{
								//	Raylib.EndTextureMode();
								//	Raylib.BeginTextureMode(layertexture[layer]);
								//	Raylib.DrawTextureRec(additivetexture.Texture,new Rectangle(0,0,resx,-resy),origin,Color.White);									
								//}	
								Raylib.EndBlendMode();
							}
							//lasers (used to be drawn with models, now we draw with shaders)
							if((layer==3 && (Program.demomode==1 || Program.videomode==1)) || (layer==6 && Program.demomode==0 && Program.videomode==0)) 
							{
								//use shaders for lasers
								Raylib.BeginShaderMode(lasers.rshader);
								int ramb = ambient;
								unsafe
								{
									Raylib.SetShaderValue(lasers.rshader,lasers.rambient,&ramb,ShaderUniformDataType.Int);
								}
								Raylib.EndShaderMode();
								Raylib.BeginShaderMode(lasers.gshader);
								unsafe
								{
									Raylib.SetShaderValue(lasers.gshader,lasers.gambient,&ramb,ShaderUniformDataType.Int);
								}
								Raylib.EndShaderMode();
								for(int i=0;i<lasers.laserarray.Length;i++)
								{
									screenpos = Raylib.GetWorldToScreen(lasers.laserarray[i].position, camera);
									if(screenpos.X<0 || screenpos.X>Program.resx || screenpos.Y<0 || screenpos.Y>Program.resy)
									{
										continue;
									}
									if(Program.demomode==0)
									{
										if(screenpos.Y>(float)Program.resy*Program.guiocclusion) //gui is obstructing view.
										{
											continue;	
										}
									}
									if(lasers.laserarray[i].lifetime>0 && lasers.laserarray[i].onground==1)
									{
										if(lasers.laserarray[i].isrocket==0)
										{
											if(lasers.laserarray[i].isbeam==0)
											{
												//lasers.laserarray[i].position.Y = 6;
												zaxis.X = lasers.laserarray[i].direction.X;
												zaxis.Y = lasers.laserarray[i].direction.Y;
												zaxis.Z = lasers.laserarray[i].direction.Z;
												zaxis = Raymath.Vector3Normalize(zaxis);
												yaxis.X = 0;
												yaxis.Y = 1;
												yaxis.Z = 0;
												yaxis = Raymath.Vector3Normalize(yaxis);
												xaxis = Raymath.Vector3CrossProduct(yaxis,zaxis);
												xaxis = Raymath.Vector3Normalize(xaxis);
												Matrix4x4 flyer_rotation_matrix = new Matrix4x4(xaxis.X,yaxis.X,zaxis.X,0,xaxis.Y,yaxis.Y,zaxis.Y,0,xaxis.Z,yaxis.Z,zaxis.Z,0,0,0,0,1);
												float sc = 1; //adjust as needed
												lasers.rmodel.Transform = Raymath.MatrixIdentity();
												sc = 7.5f;
												lasers.rmodel.Transform = Raymath.MatrixMultiply(Raymath.MatrixScale(sc,sc,sc),lasers.rmodel.Transform);
												lasers.rmodel.Transform = Raymath.MatrixMultiply(Raymath.MatrixTranslate(lasers.laserarray[i].position.X/sc,lasers.laserarray[i].position.Y/sc,lasers.laserarray[i].position.Z/sc),lasers.rmodel.Transform);
												lasers.rmodel.Transform = Raymath.MatrixMultiply(flyer_rotation_matrix,lasers.rmodel.Transform);
												if(lasers.laserarray[i].race==1)
												{
													Raylib.BeginShaderMode(lasers.rshader);
													Raylib.SetShaderValueMatrix(lasers.rshader,lasers.rmodelMatrix,lasers.rmodel.Transform);
													Raylib.EndShaderMode();
													unsafe
													{	
														Raylib.DrawMesh(lasers.rmodel.Meshes[0],lasers.rmodel.Materials[0],lasers.rmodel.Transform);
													}
													drawn_entities++;
												}
												else
												{
													Raylib.BeginShaderMode(lasers.gshader);
													Raylib.SetShaderValueMatrix(lasers.gshader,lasers.gmodelMatrix,lasers.rmodel.Transform);
													Raylib.EndShaderMode();
													unsafe
													{	
														Raylib.DrawMesh(lasers.gmodel.Meshes[0],lasers.gmodel.Materials[0],lasers.rmodel.Transform);
													}
													drawn_entities++;
												}
												if(lasers.laserarray[i].smoketrail!=0)
												{
													explosion.createexplosiononground(lasers.laserarray[i].position.X,20,lasers.laserarray[i].position.Z,0.3f);									
												}
											}
										}
									}
									if(lasers.laserarray[i].lifetime>0 && lasers.laserarray[i].onground==2)
									{
										if(lasers.laserarray[i].isrocket==0)
										{
											if(lasers.laserarray[i].isbeam==0)
											{
												zaxis.X = lasers.laserarray[i].direction.X;
												zaxis.Y = lasers.laserarray[i].direction.Y;
												zaxis.Z = lasers.laserarray[i].direction.Z;
												zaxis = Raymath.Vector3Normalize(zaxis);
												yaxis.X = 0;
												yaxis.Y = 1;
												yaxis.Z = 0;
												yaxis = Raymath.Vector3Normalize(yaxis);
												xaxis = Raymath.Vector3CrossProduct(yaxis,zaxis);
												xaxis = Raymath.Vector3Normalize(xaxis);
												Matrix4x4 flyer_rotation_matrix = new Matrix4x4(xaxis.X,yaxis.X,zaxis.X,0,xaxis.Y,yaxis.Y,zaxis.Y,0,xaxis.Z,yaxis.Z,zaxis.Z,0,0,0,0,1);
												float sc = 1; //adjust as needed
												lasers.rmodel.Transform = Raymath.MatrixIdentity();
												sc = 7.5f*2f;
												lasers.rmodel.Transform = Raymath.MatrixMultiply(Raymath.MatrixScale(sc,sc,sc),lasers.rmodel.Transform);
												lasers.rmodel.Transform = Raymath.MatrixMultiply(Raymath.MatrixTranslate(lasers.laserarray[i].position.X/sc,lasers.laserarray[i].position.Y/sc,lasers.laserarray[i].position.Z/sc),lasers.rmodel.Transform);
												lasers.rmodel.Transform = Raymath.MatrixMultiply(flyer_rotation_matrix,lasers.rmodel.Transform);
												if(lasers.laserarray[i].race==1)
												{
													Raylib.BeginShaderMode(lasers.rshader);
													Raylib.SetShaderValueMatrix(lasers.rshader,lasers.rmodelMatrix,lasers.rmodel.Transform);
													Raylib.EndShaderMode();
													unsafe
													{	
														Raylib.DrawMesh(lasers.rmodel.Meshes[0],lasers.rmodel.Materials[0],lasers.rmodel.Transform);
													}
													drawn_entities++;
												}
												else
												{
