						ty = (ship.shiparray[followi].y - ship.shiparray[followi].vy * 265 * 1) * ship.shiparray[followi].scale;
						tz = ((ship.shiparray[followi].z - ship.shiparray[followi].vz * 265 * 1)* ship.shiparray[followi].scale);
						if(camtype==0)
