									explosion.explosionarray[i].model.Transform = Raymath.MatrixIdentity();
									explosion.explosionarray[i].scale = 0.1f;
									explosion.explosionarray[i].model.Transform = Raymath.MatrixMultiply(Raymath.MatrixScale(explosion.explosionarray[i].scale*explosion.explosionarray[i].size,explosion.explosionarray[i].scale*explosion.explosionarray[i].size,explosion.explosionarray[i].scale*explosion.explosionarray[i].size),explosion.explosionarray[i].model.Transform);
									explosion.explosionarray[i].model.Transform = Raymath.MatrixMultiply(Raymath.MatrixTranslate(explosion.explosionarray[i].x/explosion.explosionarray[i].size,explosion.explosionarray[i].y/explosion.explosionarray[i].size,explosion.explosionarray[i].z/explosion.explosionarray[i].size),explosion.explosionarray[i].model.Transform);
									unsafe
									{
										zaxis = Raylib.GetCameraForward(&camera);
									}
									unsafe
									{
										xaxis = Raylib.GetCameraRight(&camera);
									}
									//zaxis = forwards
									//yaxis = up vector
									//xaxis = right vector
									if(zaxis.Z!=0)
									{
										yaxis = new Vector3(zaxis.Y,- zaxis.X,0);
									}
									else
									{
										yaxis = new Vector3(0,0,1);
									}
									yaxis = Raymath.Vector3Normalize(yaxis);
									xaxis = Raymath.Vector3CrossProduct(yaxis,zaxis);
									xaxis = Raymath.Vector3Normalize(xaxis);
									Matrix4x4 rotationmatrix = new Matrix4x4(yaxis.X,xaxis.X,zaxis.X,0,yaxis.Y,xaxis.Y,zaxis.Y,0,yaxis.Z,xaxis.Z,zaxis.Z,0,0,0,0,1);
									explosion.explosionarray[i].model.Transform = Raymath.MatrixMultiply(rotationmatrix,explosion.explosionarray[i].model.Transform);
									//
									int animframe = ((int)explosion.explosionarray[i].animframe)%64;
									int grey = explosion.explosionarray[i].isrocket;
									
									Raylib.BeginShaderMode(explosion.explosionarray[i].shader);
									unsafe
									{
										Raylib.SetShaderValueMatrix(explosion.explosionarray[i].shader,explosion.explosionarray[i].projectionMatrix,Raylib.GetCameraProjectionMatrix(&camera, Program.aspect));
										Raylib.SetShaderValueMatrix(explosion.explosionarray[i].shader,explosion.explosionarray[i].viewMatrix,Raylib.GetCameraViewMatrix(&camera));
										Raylib.SetShaderValue(explosion.explosionarray[i].shader,explosion.explosionarray[i].shaderframe,&animframe,ShaderUniformDataType.Int);
										Raylib.SetShaderValue(explosion.explosionarray[i].shader,explosion.explosionarray[i].grey,&grey,ShaderUniformDataType.Int);
									}
									Raylib.SetShaderValueMatrix(explosion.explosionarray[i].shader,explosion.explosionarray[i].modelMatrix,explosion.explosionarray[i].model.Transform);
									Raylib.EndShaderMode();	
									if(added==0)
									{
										Raylib.BeginTextureMode(additivetexture);
										Raylib.ClearBackground(new Color(0,0,0,0));
									}
									unsafe
									{	
										Raylib.DrawMesh(explosion.explosionarray[i].model.Meshes[0],explosion.explosionarray[i].model.Materials[0],explosion.explosionarray[i].model.Transform);
									}
									added++;
									if(added>maxadditive)
									{
										Raylib.EndTextureMode();
										Raylib.BeginTextureMode(explosiontexture);
										Raylib.BeginShaderMode(explosionshader);
										Raylib.DrawTextureRec(additivetexture.Texture,rect,origin,Color.White);
										Raylib.EndShaderMode();
										Raylib.EndTextureMode();
										added = 0;
									}
								}
							}
						}
						if(added>0)
						{
							Raylib.EndTextureMode();
							Raylib.BeginTextureMode(explosiontexture);
							Raylib.BeginShaderMode(explosionshader);
							Raylib.DrawTextureRec(additivetexture.Texture,rect,origin,Color.White);
							Raylib.EndShaderMode();
							Raylib.EndTextureMode();
							added = 0;
						}
					}		
					Raylib.EndBlendMode();
					Raylib.EndMode3D();			
					if(transitiontime==0 || transitiontime>20)
					{
						Raylib.BeginTextureMode(ui);
						Raylib.ClearBackground(Color.Black);
						Raylib.BeginMode3D(camera);
						Raylib.DrawModel(spacebk.SPACE2.model,camera.Position,0.75f,Color.White);
						Raylib.EndMode3D();
						Raylib.BeginShaderMode(lasershader);
						Raylib.DrawTextureRec(lasertexture.Texture, rect, origin, Color.White);
						Raylib.EndShaderMode();
						Raylib.BeginShaderMode(postprocessingshader);
						int amb = ambientocclusion;
						float pixelwidth = 1f / resx;
						float pixelheight = 1f / resy;
						unsafe
						{
							Raylib.SetShaderValueV(postprocessingshader,ppswidth,&pixelwidth,ShaderUniformDataType.Float,1);
							Raylib.SetShaderValueV(postprocessingshader,ppsheight,&pixelheight,ShaderUniformDataType.Float,1);
							Raylib.SetShaderValueV(postprocessingshader,ppsambient,&amb,ShaderUniformDataType.Int,1);
							if(ambientocclusion!=0)
							{
								Raylib.SetShaderValueTexture(postprocessingshader,ppsambienttex,ambientocclusiontex.Texture);
							}
						}	
						Raylib.DrawTextureRec(screentexture.Texture, rect, origin, Color.White);
						Raylib.EndShaderMode();
						Raylib.BeginBlendMode(BlendMode.Additive);
						Raylib.BeginShaderMode(explosionshader);
						Raylib.DrawTextureRec(explosiontexture.Texture, rect, origin, Color.White);
						//Raylib.DrawTexturePro(explosiontexture.Texture,new Rectangle(0,0,resx/2,-resy/2),new Rectangle(0,0,resx,resy),origin,0,Color.White);
						Raylib.EndShaderMode();
						Raylib.EndBlendMode();
						
						GameUI.DoShitAndDrawInterface(camera);
						GameUI.DrawHealth(camera);
						GameUI.Messages();
						Raylib.DrawTextureEx(GameUI.overlay2,new Vector2(0,0),0,GameUI.gscale,Color.White);
						Profile.rendertime-=Profile.timer.ElapsedMilliseconds;
						if(Raylib.IsKeyReleased(KeyboardKey.F12))
						{
							takescreenshot = 1;
						}
						else
						{
							Profile.drawdebuginfo();
						}
						if(GameUI.showfps!=0)
						{
							GameUI.DrawText(""+fps,GameUI.RescaleX(1790+55-20),GameUI.RescaleY(925+35),40,Color.Yellow);							
						}
						Raylib.EndTextureMode();
						if(transitiontime==0)
						{
							Raylib.BeginDrawing();
							Raylib.DrawTextureRec(ui.Texture,new Rectangle(0,0,resx,-resy),new Vector2(0,0),Color.White);
							Raylib.EndDrawing();
						}
					}
					if(transitiontime>0)
					{
						float alpha = 255f * transitiontime / 20f;
						if(transitiontime > 20)
						{
							alpha = 255f * (20f - (transitiontime - 20f))/20f;
						}
						if(alpha<0)
						{
							alpha = 0;
						}
						if(alpha>255)
						{
							alpha = 255;
						}
						Color ccc = new Color(0,0,0,(int)alpha);
						Raylib.BeginDrawing();
						Raylib.BeginShaderMode(uitransitionshader);
						float ttime = (float)transitiontime;
						unsafe
						{
							Raylib.SetShaderValueV(uitransitionshader,ui_transition,&ttime,ShaderUniformDataType.Float,1);
						}
						Raylib.DrawTextureRec(ui.Texture,new Rectangle(0,0,resx,-resy),new Vector2(0,0),Color.White);
						Raylib.EndShaderMode();
						Raylib.DrawRectangle(0,0,resx,resy,ccc);
						Raylib.EndDrawing();
					}
					if(gamestate==GROUNDBATTLE)
					{
						camera.FovY = 45;
						GameUI.togglespace = 0;
					}
					else
					{
						if(GameUI.mx < GameUI.menu_x || GameUI.mx > GameUI.menu_x + GameUI.menu_w || GameUI.my < GameUI.menu_y2 || GameUI.my > GameUI.menu_y2 + GameUI.menu_h)
						{
							if(GameUI.lpress!=0)
							{
								GameUI.mpressxy = 1;
							}
							if(GameUI.lclick!=0 && GameUI.mpressxy == 1)
							{
								gamestate = GROUNDBATTLE;
								camera.FovY = 45;
								GameUI.togglespace = 0;
							}
						}
					}
				}//if gamestate==SPACEBATTLE
				if(randomspacescreenshot!=0) //don't use this...bad
				{
					if(ship.random.Next(0,1000)<5)
					{
						takescreenshot = 1;
					}
				}
				if(takescreenshot==1)
				{
					takescreenshot=0;
					screenshot++;
					string zframe = "" + screenshot;
					while(zframe.Length<8)
					{
						zframe = "0" + zframe;
					}
					Raylib.TakeScreenshot("img_"+zframe+".png");
					System.IO.File.Move("img_"+zframe+".png","render/img_"+zframe+".png");
				}
				if(Raylib.IsKeyReleased(KeyboardKey.Space) && gamestate!=MENU) //replace this with space bar...
				{
					togglepause = 1 - togglepause;
					if(togglepause==1)
					{
						gametimer.Stop();
					}
					else
					{
						gametimer.Start();
					}
				}
			}
			Raylib.CloseWindow();
			Raylib.CloseAudioDevice();
			UnloadHelper.UnloadAll();
			Raylib.UnloadRenderTexture(ui);
			Raylib.UnloadRenderTexture(screentexture);
			Raylib.UnloadRenderTexture(ambientocclusiontex);
			Raylib.UnloadRenderTexture(compositetexture);
			Raylib.UnloadRenderTexture(additivetexture);
			Raylib.UnloadRenderTexture(firetexture);
			Raylib.UnloadRenderTexture(explosiontexture);
			Raylib.UnloadRenderTexture(lasertexture);
			for(int i=0;i<maxlayer;i++)
			{
				Raylib.UnloadRenderTexture(layertexture[i]);
			}
			Program.QUITGAME = 1;
			Audio.UpdateMusic();
			LocalStorage.finalise();
		}
	}

	class flyby
	{
		//this class is for the spaceship flybys that take place whenever
		//a friendly spaceship is built....and flys over the landscape
		//from one corner of the map to the other and out of sight
		//only really need some x/y/z coords and an index into the shiparray\
		//for the relevant ship
		
		
		//17aug2025 - add 8 more elements to this array
		//for use by the air strike option
		//so index elements 3 to 10 will be air strike ships - and heck, to make it easy, use any shiptype EXCEPT the cruiser....
		
		public static float[] x = new float[3+8]; //17aug2025 +8
		public static float[] y = new float[3+8];
		public static float[] z = new float[3+8];
		public static int[] id = new int[3+8];
		public static int[] airstrike = new int[3+8];
		
		public static float[] vx = new float[11];//17aug2025
		public static float[] vz = new float[11];
		public static float[] vy = new float[11];
		
		public static void ReInit()
		{
			for(int i=0;i<3;i++)
			{
				x[i] = 3000 - i * 100;
				y[i] = 45;
				z[i] = 3000;
			}
			for(int i=0;i<3;i++)
			{
				for(int j=0;j<ship.maxships;j++)
				{
					if(ship.shiparray[j].race==1 && ship.shiparray[j].shiptype==i+1 && j>0)
					{
						id[i] = j;
						break;
					}
				}
			}
			//now do the air strike ships
			for(int i=3;i<11;i++)
			{
				float angle = (float)ship.random.NextDouble()*12f;
				y[i] = 45f + (float)ship.random.NextDouble()*10f;
				x[i] = 2000.0f * (float) Math.Sin(angle);
				z[i] = 2000.0f * (float) Math.Cos(angle);
				vy[i] = 0;
				vz[i] = 0.8f*(- z[i] / 2000f) * 4f;
				vx[i] = 0.8f*(- x[i] / 2000f) * 4f;
				airstrike[i] = 0;
				for(int j=0;j<ship.maxships;j++)
				{
					if(ship.shiparray[j].race==1 && ((ship.shiparray[j].shiptype==2 && i < 7) || (ship.shiparray[j].shiptype==3 && i>=7)) && j>0)
					{
						id[i] = j;
						break;
					}
				}
			}
		}
	}

	class debris
	{
		public static int maxdebris = 75;
		public static debris[] debrisarray = new debris[maxdebris];
		public float x;
		public float y;
		public float z;
		public float vx;
		public float vy;
		public float vz;
		public float ay;
		public float lifetime;
		
		public debris()
		{
			
		}
		
		public static void DebrisExplosion(int i,int j)
		{
			//i = unit, j = building
			//tanks exploding and sometimes buildings.....
			UnitVertices tmp = null;
			float angle = 0;
			float msc = 0;
			Vector3 pos = new Vector3(0,0,0);
			if(i>=0)
			{
				tmp = Unit.unitarray[i].vertices[0];
				if(tmp==null)
				{
					tmp = Unit.unitarray[i].vertices[1];
				}
				msc = Unit.GetUnitScale(i);
				angle = Unit.unitarray[i].angle;
				pos = new Vector3(Unit.unitarray[i].x,Unit.unitarray[i].y,Unit.unitarray[i].z);
			}
			if(j>=0)
			{
				tmp = Building.buildingarray[j].vertices;
				msc = 7.5f*0.85f;
				pos = new Vector3(Building.buildingarray[j].x,Building.buildingarray[j].y,Building.buildingarray[j].z);
			}
			//tmp now has an appropriate unitvertices object
			if(tmp!=null)
			{
				if(tmp.Vertices!=null)
				{
					int aa = ship.random.Next(0,20);
					for(int v=aa;v<tmp.Vertices.Length;v+=20) //loop through them, creating debris explosions for every 20th vertex....positioned in world space properly.
					{
						Vector3 vertex = tmp.Vertices[v];
						vertex = Raymath.Vector3RotateByAxisAngle(vertex, new Vector3(0,1,0), angle);
						vertex = Raymath.Vector3Scale(vertex,0.3f+((float)ship.random.NextDouble()+0.4f)*msc);
						vertex = Raymath.Vector3Add(vertex,pos);
						//create our debris from here......
						createdebris(vertex.X,vertex.Y,vertex.Z);
					}
				}					
			}
		}
		
		public static void AnimalExplosion(int i) //yeah - animals are in a different list hence we need a different one of these, though we could have just had an (DebrisExplosion(i,j,k)) instead with k being for animals.
		{
			//same as above function really.
			//tanks exploding and sometimes buildings.....
			UnitVertices tmp = null;
			float angle = 0;
			float msc = 0;
			int animframe = (int)(Unit.animals[i].aframe);
			Vector3 pos = new Vector3(0,0,0);
			if(i>=0)
			{
				tmp = Unit.animals[i].vertices[animframe];
				msc = 7.5f;
				angle = Unit.animals[i].angle;
				pos = new Vector3(Unit.animals[i].x,Unit.animals[i].y,Unit.animals[i].z);
			}
			if(tmp!=null)
			{
				if(tmp.Vertices!=null)
				{
					for(int v=0;v<tmp.Vertices.Length;v+=20)
					{
						Vector3 vertex = tmp.Vertices[v];
						vertex = Raymath.Vector3RotateByAxisAngle(vertex, new Vector3(0,1,0), angle);
						vertex = Raymath.Vector3Scale(vertex,0.3f+(float)ship.random.NextDouble()*msc);
						vertex = Raymath.Vector3Add(vertex,pos);
						//create our debris from here......
						createdebris(vertex.X,vertex.Y,vertex.Z);
					}
				}					
			}
		}
		
		public static void init()
		{
			for(int i=0;i<maxdebris;i++)
			{
				debrisarray[i] = new debris();
				if(i%25==0)
				{
					GameUI.Loading("Please Wait....Loading.....FX",10,Program.resy - 56,GameUI.largefont,Color.LightGray,2);
				}
			}
		}
		
		public static void ReInit()
		{
			for(int i=0;i<maxdebris;i++)
			{
				debrisarray[i].lifetime = 0;
			}
		}
		
		public static void createdebris(float x,float y, float z)
		{
			if(Program.autooptimise>2)
			{
				int dice = ship.random.Next(0,Program.targetfps);
				if(dice > Program.fps)
				{
					return;
				}
			}
			
			for(int i=0;i<maxdebris;i++)
			{
				if(debrisarray[i].lifetime<=0)
				{
					debrisarray[i].x = x;
					debrisarray[i].y = y;
					debrisarray[i].z = z;
					debrisarray[i].lifetime = 90;
					debrisarray[i].ay = -0.05f;
					debrisarray[i].vx = (float)(ship.random.NextDouble()-0.5f)*1.5f;
					debrisarray[i].vy = (float)(ship.random.NextDouble()-0.5f)*1.5f;
					debrisarray[i].vz = (float)(ship.random.NextDouble()-0.5f)*1.5f;
					break;
				}
			}
		}
		
		public static void updatedebris()
		{
			int flashcreated = 0;
			for(int i=0;i<maxdebris;i++)
			{
				if(debrisarray[i].lifetime>0)
				{
					debrisarray[i].lifetime-=ship.delta;
					debrisarray[i].x+=debrisarray[i].vx*ship.delta;
					debrisarray[i].y+=debrisarray[i].vy*ship.delta;
					debrisarray[i].z+=debrisarray[i].vz*ship.delta;
					debrisarray[i].vy+=debrisarray[i].ay;
					if(debrisarray[i].y<0.01) //altered this from 10 today (9aug2025) - it might improve stuff....since we now know what height the ground is. (have known for a while)
					{
							debrisarray[i].lifetime = 0;
					}
					if(ship.random.Next(0,100)<30){explosion.createexplosiononground(debrisarray[i].x,debrisarray[i].y,debrisarray[i].z,(float)ship.random.NextDouble()*0.4f+1.5f);}
					if(flashcreated<8 && i%4==0)
					{
						Program.explosion_effects[flashcreated] = new Vector3(debrisarray[i].x,debrisarray[i].y,debrisarray[i].z);
						flashcreated++;
					}
				}
			}
		}
	}
	
	class spark
	{
		public spark()
		{
			scale = 1;
			x = new float[maxp];
			y = new float[maxp];
			z = new float[maxp];
			vx = new float[maxp];
			vy = new float[maxp];
			vz = new float[maxp];
			ay = new float[maxp];
			lifetime = new float[maxp];
		}
		public static int nextfreespark = -1;
		public int sectorx;
		public int sectorz;
		public static int maxspark = 200;
		public static int highest = 1;
		public static spark[] sparks = new spark[maxspark];
		public static int changed = 0;
		public float emitter_x;
		public float emitter_y;
		public float emitter_z;
		public Vector3 position;
		public int inview;
		public float emitter_rate;
		public float emitter_life;
		public static int maxp = 50;
		public float[] x;
		public int maxpi;
		public float[] y;
		public float[] z;
		public float[] vx;
		public float[] vy;
		public float[] vz;
		public float[] ay;
		public float[] lifetime;
		public float scale;
		public static Model cmodel;
		public static Texture2D cdiffuse;
		public static Shader cshader;
		public static int cshadertex0;
		public static int cmodelMatrix;
		public static int cprojectionMatrix;
		public static int cviewMatrix;
		public static int calpha;
		
		public static Random random;
		
		public static void createsparkemitter(float x,float y,float z)
		{
			
			if(nextfreespark>-1)
			{
				int i = nextfreespark;
				nextfreespark = -1;
				if(sparks[i].emitter_life<=0)
				{
					if(i>=highest)
					{
						highest = i + 1;
					}
					sparks[i].inview = 1;
					sparks[i].emitter_life = 5;
					sparks[i].emitter_y = y;
					sparks[i].emitter_x = x;
					sparks[i].emitter_z = z;
					sparks[i].position = new Vector3(x,y,z);
					sparks[i].emitter_rate = 0.25f+(float)random.NextDouble()*0.25f;
					for(int p=0;p<maxp;p++)
					{
						sparks[i].lifetime[p] = -1;
					}
					return;
				}
			}
			for(int i=0;i<maxspark;i++)
			{
				if(sparks[i].emitter_life<=0)
				{
					if(i>=highest)
					{
						highest = i + 1;
					}
					sparks[i].inview = 1;
					sparks[i].emitter_life = 5;
					sparks[i].emitter_y = y;
					sparks[i].emitter_x = x;
					sparks[i].emitter_z = z;
					sparks[i].position = new Vector3(x,y,z);
					sparks[i].emitter_rate = 0.25f+(float)random.NextDouble()*0.25f;
					for(int p=0;p<maxp;p++)
					{
						sparks[i].lifetime[p] = -1;
					}
					break;
				}
			}
		}
		
		public static void updatespark()
		{
			changed = 0;
			for(int i=0;i<maxspark;i++)
			{
				if(sparks[i].emitter_life>0)
				{
					sparks[i].emitter_life-=ship.delta;
					if(sparks[i].emitter_life<=0)
					{
						continue;
					}
					int create = 1;
					for(int p=0;p<maxp;p++)
					{
						if(sparks[i].lifetime[p]>0)
						{
							sparks[i].lifetime[p]-=ship.delta;
							sparks[i].x[p]+=sparks[i].vx[p]*ship.delta;
							sparks[i].y[p]+=sparks[i].vy[p]*ship.delta;
							sparks[i].z[p]+=sparks[i].vz[p]*ship.delta;
							sparks[i].sectorx = Program.GetSectorX(sparks[i].x[p],sparks[i].z[p]);
							sparks[i].sectorz = Program.GetSectorZ(sparks[i].x[p],sparks[i].z[p]);
							sparks[i].vy[p]+=sparks[i].ay[p];
							if(p>=sparks[i].maxpi)
							{
								sparks[i].maxpi = p + 1;
							}
							changed = 1;
						}
						else
						{
							if(create==1)
							{
								sparks[i].lifetime[p] = 120;
								sparks[i].x[p] = sparks[i].emitter_x;
								sparks[i].y[p] = sparks[i].emitter_y;
								sparks[i].z[p] = sparks[i].emitter_z;
								sparks[i].sectorx = Program.GetSectorX(sparks[i].x[p],sparks[i].z[p]);
								sparks[i].sectorz = Program.GetSectorZ(sparks[i].x[p],sparks[i].z[p]);
								sparks[i].vx[p] = (float)(ship.random.NextDouble()-0.5f)*2f*0.5f;
								sparks[i].vy[p] = (float)(ship.random.NextDouble()-0.5f)*2f*0.5f;
								sparks[i].vz[p] = (float)(ship.random.NextDouble()-0.5f)*2f*0.5f;
								sparks[i].ay[p] = -0.05f*0.5f;
								changed = 1;
								if(p>=sparks[i].maxpi)
								{
									sparks[i].maxpi = p+1;
								}
								create = 0;
							}
						}
					}
				}
				else
				{
					int anysparks = 0;
					for(int p=0;p<sparks[i].maxpi;p++)//maxp;p++)
					{
						if(sparks[i].lifetime[p]>0)
						{
							anysparks = 1;
							sparks[i].lifetime[p]-=ship.delta;
							sparks[i].x[p]+=sparks[i].vx[p]*ship.delta;
							sparks[i].y[p]+=sparks[i].vy[p]*ship.delta;
							sparks[i].z[p]+=sparks[i].vz[p]*ship.delta;
							sparks[i].vy[p]+=sparks[i].ay[p];
							sparks[i].sectorx = Program.GetSectorX(sparks[i].x[p],sparks[i].z[p]);
							sparks[i].sectorz = Program.GetSectorZ(sparks[i].x[p],sparks[i].z[p]);
							changed = 1;
						}
					}
					if(anysparks==0)
					{
						nextfreespark = i;
					}
				}
			}
		}
		
