		public static void createdirtclod(float x,float z)
		{
			int aa = 0;
			if(nextfreesmoke>-1)
			{
				aa = nextfreesmoke;
				nextfreesmoke = -1;
			}
			for(int i=aa;i<maxsmoke;i++)
			{
				if(smokes[i].emitter_y<0)
				{
					smokes[i].emitter_is_dirt = 1;
					if(i>=highest)
					{
						highest = i + 1;
					}
					smokes[i].emitter_life = 30;
					smokes[i].emitter_y = 10;
					smokes[i].emitter_x = x;
					smokes[i].emitter_z = z;
					smokes[i].position = new Vector3(x,10,z);
					smokes[i].inview = 1;
					smokes[i].emitter_rate = 0.02f+(float)random.NextDouble()*0.05f;
					for(int p=0;p<maxp;p++)
					{
						if(smokes[i].lifetime[p]<=0)
						{
							smokes[i].lifetime[p] = -1;
							if(p<10)
							{
								smokes[i].lifetime[p] = 180;
								smokes[i].x[p] = x + ((float)ship.random.NextDouble()*5f)-2.5f;
								smokes[i].z[p] = z + ((float)ship.random.NextDouble()*5f)-2.5f;
								smokes[i].y[p] = 10;
								smokes[i].sectorx = Program.GetSectorX(x,z);
								smokes[i].sectorz = Program.GetSectorZ(x,z);
								smokes[i].vy[p] = 0.3f;
								smokes[i].dirt[p] = 1;
								if(p>=smokes[i].maxpi)
								{
									smokes[i].maxpi = p + 1;
								}
								changed = 1;
							}
						}
					}
					break;
				}
			}
		}
		
