		{
			int aa = 0;
			if(nextfreesmoke>-1)
			{
				aa = nextfreesmoke;
				nextfreesmoke = -1;
			}
			for(int i=aa;i<maxsmoke;i++)
			{
				if(smokes[i].emitter_y<0)
				{
					if(i>=highest)
					{
						highest = i + 1;
					}
					smokes[i].emitter_is_dirt = 0;
					smokes[i].emitter_life = 60 * 30;
					smokes[i].emitter_y = 10;
					smokes[i].emitter_x = x;
					smokes[i].emitter_z = z;
					smokes[i].position = new Vector3(x,10,z);
