					smokes[i].emitter_rate = 0.02f+(float)random.NextDouble()*0.05f;
					for(int p=0;p<maxp;p++)
					{
						if(smokes[i].lifetime[p]<=0)
						{
							smokes[i].lifetime[p] = -1;
							smokes[i].dirt[p] = 0;
						}
					}
					break;
				}
			}
		}
		
		public static smoke[] QuickSort(smoke[] inarray)
		{
			if(inarray.Length<=1)
			{
				return inarray;
			}
			//check if already sorted
			int unsorted = 0;
			for(int i=1;i<inarray.Length;i++)
			{
				if(inarray[i].camdist<inarray[i-1].camdist)
				{
					unsorted = 1;
					break;
				}
			}
			if(unsorted==0)
			{
				return inarray;
			}
			int midpoint = inarray.Length / 2;
			float midvalue = inarray[midpoint].camdist;
			int countlower = 0;
			int countupper = 0;
			for(int i=0;i<inarray.Length;i++)
			{
				if(i==midpoint)
				{
					continue;
				}
				if(inarray[i].camdist > midvalue && inarray[i].emitter_y>=0)
				{
					countlower++;
				}
				if((inarray[i].camdist <= midvalue || inarray[i].emitter_y<0) && i!=midpoint)
				{
					countupper++;
				}
			}
			smoke[] lowerhalf = new smoke[countlower];
			smoke[] upperhalf = new smoke[countupper];
			int j = 0;
			if(countlower>0)
			{
				//Console.WriteLine("countlower:"+countlower);
				for(int i=0;i<inarray.Length;i++)
				{
					if(i==midpoint)
					{
						continue;
					}
					if(inarray[i].camdist > midvalue && inarray[i].emitter_y>=0)
					{
						//Console.WriteLine("j:"+j);
						lowerhalf[j] = inarray[i];
						j++;
					}
				}
				lowerhalf = QuickSort(lowerhalf);
			}
			if(countupper>0)
			{
				j = 0;
				//Console.WriteLine("countupper:"+countupper);
				for(int i=0;i<inarray.Length;i++)
				{
					if(i==midpoint)
					{
						continue;
					}
					if(inarray[i].camdist <= midvalue || inarray[i].emitter_y<0)
					{
						//Console.WriteLine("j:"+j);
						upperhalf[j] = inarray[i];
						j++;
					}
				}
				upperhalf =  QuickSort(upperhalf);
			}
			smoke[] returnarray = new smoke[1 + countlower + countupper];
			j = 0;
			for(int i=0;i<returnarray.Length;i++)
			{
				if(i<countlower)
				{
					returnarray[i] = lowerhalf[j];
					j++;
				}
				if(i==countlower)
				{
					returnarray[i] = inarray[midpoint];
					j = 0;
				}
				if(i>countlower)
				{
					returnarray[i] = upperhalf[j];
					j++;
				}
			}
			return returnarray;
		}
		
		public static void updatesmoke()
		{
			int anysmoke = 0;
			for(int i=0;i<maxsmoke;i++)
			{
				int create = 0;
				anysmoke = 0;
				if(smokes[i].emitter_y>=0)
				{
					smokes[i].emitter_life-=ship.delta;
					smokes[i].camdist = Raymath.Vector3Distance(explosion.campos,smokes[i].position);
					anysmoke = 1;
					if(smokes[i].emitter_life<=0)
					{
						smokes[i].emitter_y = -1;
					}
					if(random.NextDouble()<smokes[i].emitter_rate)
					{
						create = 1;
					}
					if(smokes[i].emitter_y==-1)
					{
						create = 0;
					}
				}
				for(int p=0;p<maxp;p++)
				{
					if(smokes[i].lifetime[p]>0)
					{
						anysmoke = 1;
						smokes[i].lifetime[p]-=ship.delta;
						if(smokes[i].dirt[p]!=0)
						{
							smokes[i].lifetime[p]-=ship.delta*4f;
						}
						smokes[i].x[p]+=smokes[i].vx[p]*ship.delta;
						smokes[i].y[p]+=smokes[i].vy[p]*ship.delta;
						smokes[i].z[p]+=smokes[i].vz[p]*ship.delta;
						smokes[i].sectorx = Program.GetSectorX(smokes[i].x[p],smokes[i].z[p]);
						smokes[i].sectorz = Program.GetSectorZ(smokes[i].x[p],smokes[i].z[p]);
						smokes[i].vy[p]+=smokes[i].ay[p];
						if(p>=smokes[i].maxpi)
						{
							smokes[i].maxpi = p + 1;
						}
						changed = 1;
					}
					else
					{
						if(create==1)
						{
							anysmoke = 1;
							smokes[i].lifetime[p] = 180;
							smokes[i].x[p] = smokes[i].emitter_x;
							smokes[i].y[p] = smokes[i].emitter_y;
							smokes[i].z[p] = smokes[i].emitter_z;
							smokes[i].sectorx = Program.GetSectorX(smokes[i].x[p],smokes[i].z[p]);
							smokes[i].sectorz = Program.GetSectorZ(smokes[i].x[p],smokes[i].z[p]);
							smokes[i].vy[p] = 0.3f;
							changed = 1;
							if(p>=smokes[i].maxpi)
							{
								smokes[i].maxpi = p + 1;
							}
							create = 0;
						}
					}
				}
				if(anysmoke==0)
				{
					nextfreesmoke = i;
				}
			}
		}
		
