	class scorchmark
	{
		//9aug2025 - see next comment maxscorches
		public static int maxscorches = 2000; //2000 is a heck of a lot - do we really need that many? try it with lower later...I really don't think you need that many. try a 1000 and see how it looks, then try 500..
		public static int maxcreated = 0;
		public static scorchmark[] scorches = new scorchmark[maxscorches];
		public static scorchmark[] bombers = new scorchmark[3]; //not many really
		public static int oldelement = -1;
		public static int newelement = -2;
		public float x;
		public float y;
		public float offy;
		public float z;
		public int sectorx;
		public int sectorz;
		public Vector3 position;
		public float angle;
		public float scale;
		public int inview;
