		public static Texture2D cdiffuse;
		public static Shader cshader;
		public static int cshadertex0;
		public static int cmodelMatrix;
		public static int cprojectionMatrix;
		public static int cviewMatrix;
		public static int cgroundfog;
		public static int cfoga;
		public static int cfogr;
		public static int cfogg;
		public static int cfogb;
		public static Model bmodel; //orbital bombardment
		public static Texture2D bdiffuse;
		public static Shader bshader;
		public static int bshadertex0;
		public static int bgroundfog;
		public static int bmodelMatrix;
