		public scorchmark()
		{
			scale = 1;
			y = -10;
			angle = (float)random.NextDouble()*7;
		}
		
		public static void ReInit()
		{
			maxcreated = 0;
			for(int i=0;i<maxscorches;i++)
			{
				scorches[i].y = -10;
				scorches[i].transformset = 0;
				scorches[i].position = new Vector3(scorches[i].x,0,scorches[i].z);
			}
			oldelement = -1;
			newelement = -2;
			for(int i=0;i<3;i++)
			{
				bombers[i].y = -10;
				bombers[i].transformset = 0;
				bombers[i].position = new Vector3(1011,0,1011);
			}
		}
		
		public static void updatebombers()
		{
			for(int i=0;i<3;i++)
			{
				if(Math.Abs(bombers[i].position.X)>1010 || Math.Abs(bombers[i].position.Z)>1010)
				{
					if(Program.orbitalbombardment>0)
					{
						bombers[i].position = new Vector3(0,0,0);
					}
				}
				if(bombers[i].position.X==0 && bombers[i].position.Y==0 && bombers[i].position.Z==0)
				{
					bombers[i].position = new Vector3(ship.random.Next(-10,-5)*100,10,ship.random.Next(-10,-5)*100); //not a perfect solution...but it should work.....it's unlikely that a 1 in 256 chance will come up the same number on three attempts that often.
				}
				Vector3 addpos = new Vector3(1,0,1);
				bombers[i].position = Raymath.Vector3Add(addpos,bombers[i].position);
				bombers[i].angle = (3.14159f/4f) + 3.14159f;
			}
		}
		
		public static void createscorchmark(float x,float z,float scale)
		{
			if(Grass.incover(x,z)!=0)
			{
				return;
			}
			float tolerance = 0.025f;
			float sdist = 10;
			//don't let the scorches overlap.....
			for(int i=0;i<maxscorches;i++)
			{
				if(scorches[i].y>=0)
				{
					float bscale = scale;
					if(scorches[i].scale > bscale)
					{
						bscale = scorches[i].scale;
					}
					if(Math.Abs(scorches[i].x - x)<sdist*bscale && Math.Abs(scorches[i].z - z)<sdist*bscale)
					{
						return;
					}
				}
			}
			if(ship.random.Next(0,100)<15)
			{
				for(int i=0;i<Obstacle.maxobstacles;i++)
				{
					if(Obstacle.obstaclearray[i].hp>0 || Obstacle.obstaclearray[i].y>0)
					{
						if(Math.Abs(x - Obstacle.obstaclearray[i].x)<20 && Math.Abs(z - Obstacle.obstaclearray[i].z)<20)
						{
							//remove this obstacle.....
							Obstacle.obstaclearray[i].y = -1000;
							break;
						}
					}
				}
			}
			
			for(int i=0;i<maxscorches;i++)
			{
				if(scorches[i].y<0)
				{
					scorches[i].y = 0.02f;
					if(i>=maxcreated)
					{
						maxcreated = i;
						//Profile.message = "Max Scorches:"+maxcreated;
					}
					scorches[i].angle = (float)random.NextDouble()*7;
					scorches[i].x = x;
					scorches[i].z = z;
					scorches[i].sectorx = Program.GetSectorX(x,z);
					scorches[i].sectorz = Program.GetSectorZ(x,z);
					scorches[i].offy = (float)random.NextDouble();
					for(int j=0;j<i;j++)
					{
						if(Math.Abs(x-scorches[j].x)<50 && Math.Abs(z-scorches[j].z)<50)
						{
							if(Math.Abs(scorches[i].offy - scorches[j].offy)<tolerance)
							{
								scorches[i].offy+=tolerance;
							}
						}
					}
					scorches[i].position = new Vector3(scorches[i].x,0,scorches[i].z);
					scorches[i].scale = scale;
					scorches[i].inview = 1;
					newelement = i;
					break;
				}
			}
		}
		
		public static void init()
		{
			random = new Random();
			scorches = new scorchmark[maxscorches];
			for(int i=0;i<maxscorches;i++)
			{
				scorches[i] = new scorchmark();
			}
			//cdiffuse = Raylib.LoadTexture("media/fx/scorch.png");
			cdiffuse = Program.atlas_diffuse;
			cdiffuse.Format = PixelFormat.UncompressedR8G8B8A8;
			//UnloadHelper.AddTexture(cdiffuse);
