	//alien trees
	class alientree
	{
		public static int maxalientrees = 1000;
		public static alientree[] alientrees = new alientree[maxalientrees];
		public static int[] orderarray = new int[maxalientrees];
		public float x;
		public float y;
		public float z;
		public Vector3 position;
		public float angle;
		public float scale;
		public int inview;
		public int drawn;
		public string objfile;
		public string texfile;
		public string specfile;
		public static Model[] cmodel = new Model[6];
		public static Texture2D cdiffuse;
		public static Shader cshader;
		public static int cshadertex0;
		public static int cmodelMatrix;
		public static int cgroundfog;
		public static int cfogr;
		public static int cfogg;
		public static int cfogb;
		public static int cfoga;
		public static int cprojectionMatrix;
		public static int cviewMatrix;
		public static int ambientocclusion;
		public Matrix4x4 transform;
		public int transformset;
		public static Random random;
		
		public alientree()
		{
			scale = (((float)random.NextDouble()+0.2f)*0.4f+1f);
			scale*=0.65f;
			y = -10;
			angle = (float)random.NextDouble()*7;
		}
		
		public static void ReInit()
		{
			for(int i=0;i<maxalientrees;i++)
			{
				alientrees[i].y = 0.01f;
				alientrees[i].inview = 1;
				alientrees[i].transformset = 0;
				int j = random.Next(0,Grass.maxgrasses-Grass.crateroffset);
				while(Grass.grassarray[j].gtype!=3 && Grass.grassarray[j].gtype!=6)
				{
					j++;
					if(j>Grass.maxgrasses-Grass.crateroffset)
					{
						j = 0;
					}
					alientrees[i].x = Grass.grassarray[j].x+(float)random.Next(-15,15);
					alientrees[i].z = Grass.grassarray[j].z+(float)random.Next(-15,15);
					alientrees[i].position = new Vector3(alientrees[i].x,0,alientrees[i].z);
				}
			}
			int uu = 0;
			for(int id=0;id<6;id++)
			{
				for(int i=0;i<maxalientrees;i++)
				{
					if(i%6==id)
					{
						orderarray[uu] = i;
						uu++;
					}
				}
			}
		}
		
		public static void createalientree(float x,float z,float scale)
		{
			for(int i=0;i<maxalientrees;i++)
			{
				if(alientrees[i].y<0)
				{
					alientrees[i].y = 0.01f;
					alientrees[i].angle = (float)random.NextDouble()*7;
					alientrees[i].x = x;
					alientrees[i].z = z;
					alientrees[i].position = new Vector3(x,0,z);
					alientrees[i].inview = 1;
					if(scale!=0){alientrees[i].scale = scale;}
					break;
				}
			}
		}
		
		public static void init()
		{
			random = new Random();
			alientrees = new alientree[maxalientrees];
			for(int i=0;i<maxalientrees;i++)
			{
				alientrees[i] = new alientree();
				alientrees[i].texfile = "media/tree/alientrees.png";
				alientrees[i].specfile = "";
				alientrees[i].objfile = "media/tree/plant_"+(i+1)+"_group.obj";
			}
			cdiffuse = Raylib.LoadTexture("media/tree/alientrees.png");
			UnloadHelper.AddTexture(cdiffuse);
			for(int i=0;i<6;i++)
			{
				cmodel[i] = Raylib.LoadModel("media/tree/plant_"+(i+1)+"_group.obj");
				UnloadHelper.AddModel(cmodel[i]);
			}
			if(Program.foliagenoise==1)
			{
				cshader = Raylib.LoadShader("media/shaders/basicvertexshadersnowing.vs","media/shaders/diffusepixelshader_withambientoption_withnoisea.fs");
				int debuglighting = Raylib.GetShaderLocation(cshader,"debuglighting");
				int debugl = Program.debuglighting;
				unsafe
				{
					Raylib.SetShaderValueV(cshader,debuglighting,&debugl,ShaderUniformDataType.Int,1);				
				}
			}
			else
			{
				cshader = Raylib.LoadShader("media/shaders/basicvertexshadersnowing.vs","media/shaders/diffusepixelshader_withambientoption.fs");
			}
				
			UnloadHelper.AddShader(cshader);
			cshadertex0 = Raylib.GetShaderLocation(cshader,"texture0");
			cmodelMatrix = Raylib.GetShaderLocation(cshader,"modelMatrix");
			cprojectionMatrix = Raylib.GetShaderLocation(cshader,"projectionMatrix");
			cviewMatrix = Raylib.GetShaderLocation(cshader,"viewMatrix");
			cgroundfog = Raylib.GetShaderLocation(cshader,"groundfog");
			cfogr = Raylib.GetShaderLocation(cshader,"fogr");
			cfogg = Raylib.GetShaderLocation(cshader,"fogg");
			cfogb = Raylib.GetShaderLocation(cshader,"fogb");
			cfoga = Raylib.GetShaderLocation(cshader,"foga");
			ambientocclusion = Raylib.GetShaderLocation(cshader,"ambientocclusion");
			Raylib.SetShaderValueTexture(cshader,cshadertex0,cdiffuse);
			unsafe
			{
				cmodel[0].Materials[0].Shader = cshader;
				Raylib.SetMaterialTexture(&cmodel[0].Materials[0], MaterialMapIndex.Albedo, cdiffuse);
				cmodel[1].Materials[0].Shader = cshader;
				Raylib.SetMaterialTexture(&cmodel[1].Materials[0], MaterialMapIndex.Albedo, cdiffuse);
				cmodel[2].Materials[0].Shader = cshader;
				Raylib.SetMaterialTexture(&cmodel[2].Materials[0], MaterialMapIndex.Albedo, cdiffuse);
				cmodel[3].Materials[0].Shader = cshader;
				Raylib.SetMaterialTexture(&cmodel[3].Materials[0], MaterialMapIndex.Albedo, cdiffuse);
				cmodel[4].Materials[0].Shader = cshader;
				Raylib.SetMaterialTexture(&cmodel[4].Materials[0], MaterialMapIndex.Albedo, cdiffuse);
				cmodel[5].Materials[0].Shader = cshader;
				Raylib.SetMaterialTexture(&cmodel[5].Materials[0], MaterialMapIndex.Albedo, cdiffuse);
			}
			Raylib.SetShaderValueTexture(cshader,cshadertex0,cdiffuse);
		}
	}
	
