		public static void createbeam(float x,float y, float z, float ex,float ey,float ez,int race, float damage)
		{
			Audio.PlayUnitSound(Audio.PILOTCHATTER,Audio.PILOTCHATTER);//17aug2025
			for(int i=0;i<maxlaser;i++)
			{
				if(laserarray[i].lifetime<=0)
				{
					laserarray[i].onground = 0;
					laserarray[i].isbeam = 1;
					laserarray[i].isrocket = 0;
					laserarray[i].x = x;
					laserarray[i].y = y;
					laserarray[i].z = z;
					laserarray[i].vx = 0;
					laserarray[i].vy = 0;
					laserarray[i].vz = 0;
					laserarray[i].position = new Vector3(x*0.1f,y*0.1f,z*0.1f);
					laserarray[i].direction = new Vector3(ex,ey,ez);
					laserarray[i].race = race;
					laserarray[i].damage = damage;
					laserarray[i].lifetime = 3;
					return;
				}
			}
		}
		
		public static void orbitalbombardment()
		{
			if(ship.random.NextDouble()>0.02)
			{
				return;
			}
			for(int j=0;j<Building.maxbuildings;j++)
			{
				if(Building.buildingarray[j].hp>0 && ship.random.NextDouble()<0.4)
				{
					Vector3 endpos = new Vector3(Building.buildingarray[j].x,Building.buildingarray[j].y,Building.buildingarray[j].z);
					Vector3 startpos = Raymath.Vector3Add(endpos,new Vector3(-1000,1000,-500));
					Vector3 dirn = Raymath.Vector3Scale(Raymath.Vector3Normalize(Raymath.Vector3Subtract(endpos,startpos)),2.5f);
					Building.buildingarray[j].hp-=4;
					if(Building.buildingarray[j].hp<=0)
					{
						Building.buildingarray[j].hp = 0;
						GameUI.msgtime = 120;
						GameUI.msg = "Building Lost";
						Audio.Notification();
						Audio.CalculateDistanceMultiplier(Program.demomode,Building.buildingarray[j].x,Building.buildingarray[j].y,Building.buildingarray[j].z);
						Audio.Building_Death();
						Audio.VoiceNotify(Audio.ALERT_BUILDINGLOST);
						Audio.distance_multiplier = 1;
						if(GameUI.portraitmsg=="")
						{
							GameUI.portraittime = 360;
							GameUI.portraitmsg = "Building Lost";
							GameUI.portraiton = GameUI.waveportraitid;
						}
					}
					Building.buildingarray[j].strucktime = 75;
					for(int i=0;i<maxlaser;i++)
					{
						if(laserarray[i].lifetime<=0)
						{
							laserarray[i].onground = 2;
							laserarray[i].smoketrail = 1;
							laserarray[i].isbeam = 0;
							laserarray[i].isrocket = 0;
							laserarray[i].x = startpos.X;
							laserarray[i].y = startpos.Y;
							laserarray[i].z = startpos.Z;
							laserarray[i].vx = dirn.X;
							laserarray[i].vy = dirn.Y;
							laserarray[i].vz = dirn.Z;
							laserarray[i].position = startpos;
							laserarray[i].direction = dirn;
							laserarray[i].race = 2;
							laserarray[i].damage = 5;
							laserarray[i].lifetime = 2000;
							return;
						}
					}		
				}
			}
			
			for(int j=0;j<Unit.maxunits;j++)
			{
				if(Unit.unitarray[j].hp>0 && ship.random.NextDouble()<0.05*(Unit.unitarray[j].shiptype%10)*(Unit.unitarray[j].shiptype%10) && Unit.unitarray[j].race==1)
				{
					Vector3 endpos = new Vector3(Unit.unitarray[j].x,Unit.unitarray[j].y,Unit.unitarray[j].z);
					Vector3 startpos = Raymath.Vector3Add(endpos,new Vector3(-1000,1000,-500));
					Vector3 dirn = Raymath.Vector3Scale(Raymath.Vector3Normalize(Raymath.Vector3Subtract(endpos,startpos)),2.5f);
					Unit.unitarray[j].hp-=2;
					if(Program.cheat!=0)
					{
						if(Unit.unitarray[j].race==1 && Unit.unitarray[j].hp<0)
						{
							Unit.unitarray[j].hp = Unit.unitarray[j].basehp;
						}
					}
					if(Unit.unitarray[j].hp<=0)
					{
						Unit.deadunit(j);
					}
					for(int i=0;i<maxlaser;i++)
					{
						if(laserarray[i].lifetime<=0)
						{
							laserarray[i].onground = 2;
							laserarray[i].isbeam = 0;
							laserarray[i].isrocket = 0;
							laserarray[i].x = startpos.X;
							laserarray[i].y = startpos.Y;
							laserarray[i].z = startpos.Z;
							laserarray[i].vx = dirn.X;
							laserarray[i].vy = dirn.Y;
							laserarray[i].vz = dirn.Z;
							laserarray[i].position = startpos;
							laserarray[i].direction = dirn;
							laserarray[i].race = 2;
							laserarray[i].damage = 5;
							laserarray[i].lifetime = 2000;
							return;
						}
					}		
				}
			}
		}
		
		public static void creategroundlaser(Vector3 startpos,Vector3 endpos,int race, float damage)
		{
			startpos.Y = STARTY;
			endpos.Y = ENDY;
			startpos.X+=OFFX;
			startpos.Z+=OFFZ;
			OFFX = 0;
			OFFZ = 0;
			STARTY = 6;
			ENDY = 6;
			endpos.X+=(float)ship.random.Next(-12,12);
			endpos.Z+=(float)ship.random.Next(-12,12);
			spark.createsparkemitter(endpos.X+15f*((float)ship.random.NextDouble()-0.5f),endpos.Y+15f*((float)ship.random.NextDouble()-0.5f),endpos.Z+15f*((float)ship.random.NextDouble()-0.5f));
			Vector3 dirn = Raymath.Vector3Scale(Raymath.Vector3Normalize(Raymath.Vector3Subtract(endpos,startpos)),2.5f);
			dirn.X*=(1.0f + (float)(random.NextDouble()*0.075-0.0375));
			dirn.Z*=(1.0f + (float)(random.NextDouble()*0.075-0.0375));
			for(int i=0;i<maxlaser;i++)
			{
				if(laserarray[i].lifetime<=0)
				{
					laserarray[i].onground = 1;
					laserarray[i].isbeam = 0;
					laserarray[i].isrocket = 0;
					laserarray[i].x = startpos.X;
					laserarray[i].y = startpos.Y;
					laserarray[i].z = startpos.Z;
					laserarray[i].vx = dirn.X;
					laserarray[i].vy = dirn.Y;
					laserarray[i].vz = dirn.Z;
					laserarray[i].position = startpos;
					laserarray[i].direction = dirn;
					laserarray[i].race = race;
					laserarray[i].damage = damage;
					laserarray[i].lifetime = 40;
					laserarray[i].smoketrail = SMOKETRAIL;
					return;
				}
			}
		}
		
		public static void createlaser(float x,float y,float z,float vx,float vy,float vz,int race,float damage)
		{
			float gscale = 2.5f;
			Audio.PlayUnitSound(Audio.PILOTCHATTER,Audio.PILOTCHATTER);//17aug2025
			for(int i=0;i<maxlaser;i++)
			{
				if(laserarray[i].lifetime<=0)
				{
					laserarray[i].onground = 0;
					laserarray[i].isbeam = 0;
					laserarray[i].isrocket = 0;
					laserarray[i].x = x + OFFX;
					laserarray[i].y = y + STARTY;
					laserarray[i].z = z + OFFZ;
					laserarray[i].vx = vx * gscale;
					laserarray[i].vy = vy * gscale;
					laserarray[i].vz = vz * gscale;
					laserarray[i].position = new Vector3(x,y,z);
					laserarray[i].direction = new Vector3(vx,vy,vz);
					laserarray[i].direction = Raymath.Vector3Normalize(laserarray[i].direction);
					laserarray[i].race = race;
					laserarray[i].damage = damage;
					laserarray[i].lifetime = 250;
					return;
				}
			}
		}
		
		public static void createrocket(float x,float y,float z,float vx,float vy,float vz,int target,float damage)
		{
			float gscale = 0.67f;
			Audio.PlayUnitSound(Audio.PILOTCHATTER,Audio.PILOTCHATTER);//17aug2025
			for(int i=0;i<maxlaser;i++)
			{
				if(laserarray[i].lifetime<=0)
				{
					laserarray[i].onground = 0;
					laserarray[i].isbeam = 0;
					laserarray[i].isrocket = 1;
					laserarray[i].x = x;
					laserarray[i].y = y;
					laserarray[i].z = z;
					laserarray[i].vx = vx * gscale;
					laserarray[i].vy = vy * gscale;
					laserarray[i].vz = vz * gscale;
					laserarray[i].position = new Vector3(x,y,z);
					laserarray[i].direction = new Vector3(vx,vy,vz);
					laserarray[i].direction = Raymath.Vector3Normalize(laserarray[i].direction);
					laserarray[i].race = target;
					laserarray[i].damage = damage * 5;
					laserarray[i].lifetime = 600;
					return;
				}
			}
		}
		
		public static void drawall(Camera3D camera)
		{
			Color c = new Color(255,255,255,255);
			if(Program.gamestate!=Program.SPACEBATTLE)
			{
				return;
			}
			AMBIENT = 0;
			float dscale = 0.2f;
			Vector3 xaxis = new Vector3(0,0,0);
			Vector3 yaxis = new Vector3(0,0,0);
			Vector3 zaxis = new Vector3(0,0,0);
			Raylib.BeginBlendMode(BlendMode.Additive);
			for(int i=0;i<maxlaser;i++)
			{
				if(laserarray[i].lifetime>0 && laserarray[i].onground==0)
				{
					{
						c.R = 255;
						c.G = 50;
						c.B = 50;
						c.A = 255;
						switch(laserarray[i].race)
						{
							case 1:
								c.R = 255;
								c.G = 50;
								c.B = 50;
								c.A = 255;
							break;
							case 2:
								c.R = 50;
								c.B = 50;
								c.G = 255;
								c.A = 255;
							break;
						}
						if(laserarray[i].isbeam==0)
						{
							int onscreen = 1;
							Vector3 position = laserarray[i].position;
							if(onscreen!=0)
							{
								Vector3 dirntoship = Raymath.Vector3Normalize(Raymath.Vector3Subtract(position,camera.Position));
								Vector3 dirntotarget = Raymath.Vector3Normalize(Raymath.Vector3Subtract(camera.Target,camera.Position));
								float dot = Raymath.Vector3DotProduct(dirntoship,dirntotarget);
								if(dot<=0)
								{
									onscreen = 0;
								}
								if(dot<0.6 && Raymath.Vector3Distance(position,camera.Position)>50)
								{
									onscreen = 0;
								}
							}
							if(onscreen==0)
							{
								continue;
							}
							/*
							if(Program.fps<Program.targetfps - 5)
							{
								if(i%2==0)
								{
									continue;
								}
							}
							if(Program.fps<Program.targetfps - 10)
							{
								if(i%3==0)
								{
									continue;
								}
							}
							Raylib.DrawCylinderEx(laserarray[i].position,Raymath.Vector3Add(laserarray[i].position,Raymath.Vector3Scale(laserarray[i].direction,6f*dscale)),0.33f*dscale,0.066f*dscale,5,c);
							*/
							zaxis.X = lasers.laserarray[i].direction.X;
							zaxis.Y = lasers.laserarray[i].direction.Y;
							zaxis.Z = lasers.laserarray[i].direction.Z;
							zaxis = Raymath.Vector3Normalize(zaxis);
							yaxis.X = 0;
							yaxis.Y = 1;
							yaxis.Z = 0;
							yaxis = Raymath.Vector3Normalize(yaxis);
							xaxis = Raymath.Vector3CrossProduct(yaxis,zaxis);
							xaxis = Raymath.Vector3Normalize(xaxis);
							Matrix4x4 flyer_rotation_matrix = new Matrix4x4(xaxis.X,yaxis.X,zaxis.X,0,xaxis.Y,yaxis.Y,zaxis.Y,0,xaxis.Z,yaxis.Z,zaxis.Z,0,0,0,0,1);
							float sc = 1; //adjust as needed
							lasers.rmodel.Transform = Raymath.MatrixIdentity();
							lasers.rmodel.Transform = Raymath.MatrixMultiply(Raymath.MatrixScale(sc,sc,sc),lasers.rmodel.Transform);
							lasers.rmodel.Transform = Raymath.MatrixMultiply(Raymath.MatrixTranslate(lasers.laserarray[i].position.X/sc,lasers.laserarray[i].position.Y/sc,lasers.laserarray[i].position.Z/sc),lasers.rmodel.Transform);
							lasers.rmodel.Transform = Raymath.MatrixMultiply(flyer_rotation_matrix,lasers.rmodel.Transform);
							if(lasers.laserarray[i].race==1)
							{
								Raylib.BeginShaderMode(lasers.rshader);
								Raylib.SetShaderValueMatrix(lasers.rshader,lasers.rmodelMatrix,lasers.rmodel.Transform);
								Raylib.EndShaderMode();
								unsafe
								{	
									Raylib.DrawMesh(lasers.rmodel.Meshes[0],lasers.rmodel.Materials[0],lasers.rmodel.Transform);
								}
							}
							else
							{
								Raylib.BeginShaderMode(lasers.gshader);
								Raylib.SetShaderValueMatrix(lasers.gshader,lasers.gmodelMatrix,lasers.rmodel.Transform);
								Raylib.EndShaderMode();
								unsafe
								{	
									Raylib.DrawMesh(lasers.gmodel.Meshes[0],lasers.gmodel.Materials[0],lasers.rmodel.Transform);
								}
							}
						}
						else
						{
							Vector3 tmp = Raymath.Vector3Subtract(laserarray[i].direction,laserarray[i].position);
							float dist = Raymath.Vector3Length(tmp) * (float)((int)(ship.frame) % 100)/100f;
							tmp = Raymath.Vector3Add(Raymath.Vector3Scale(Raymath.Vector3Normalize(tmp),dist),laserarray[i].position);
							Raylib.DrawCylinderEx(laserarray[i].position,tmp,0.33f*dscale,0.066f*dscale,5,c);
						}
					}
				}
			}
			Raylib.EndBlendMode();
		}
		
		public static void updatelasers()
		{
			float escale = 160f;
			int flashcreated = 0;
			for(int i=0;i<maxlaser;i++)
			{
				if(laserarray[i].lifetime>0 && laserarray[i].onground>=1)
				{
					laserarray[i].lifetime-=delta;
					laserarray[i].position = Raymath.Vector3Add(laserarray[i].position,Raymath.Vector3Scale(laserarray[i].direction,3));
					if(Grass.incover(laserarray[i].position.X,laserarray[i].position.Z)!=0)
					{
						laserarray[i].lifetime-=delta; //shorter range in cover.....
					}
					if(laserarray[i].position.Y<-10)
					{
						laserarray[i].lifetime=0;
						if(laserarray[i].onground==2)
						{
							explosion.createexplosiononground(laserarray[i].position.X+(float)random.Next(-10,10),0.01f,laserarray[i].position.Z+(float)random.Next(-10,10),3*laserarray[i].onground);
						}
					}
					if(laserarray[i].race==2)
					{
						for(int b=0;b<Building.maxbuildings;b++)
						{
							if(Building.buildingarray[b].hp>0)
							{
								Vector3 bpos = new Vector3(Building.buildingarray[b].x,Building.buildingarray[b].y,Building.buildingarray[b].z);
								if(Raymath.Vector3Distance(bpos,laserarray[i].position)<30)
								{
									laserarray[i].lifetime=0;
									if(ship.random.NextDouble()<0.2*laserarray[i].onground)
									{
										explosion.createexplosiononground(laserarray[i].position.X+(float)random.Next(-10,10),0.01f,laserarray[i].position.Z+(float)random.Next(-10,10),2*laserarray[i].onground);
										if(flashcreated<4 && i%4==0)
										{
											Program.explosion_effects[flashcreated] = new Vector3(laserarray[i].position.X,0.01f,laserarray[i].position.Z);
											flashcreated++;
										}
									}
									break;
								}
							}
						}
					}
					int u = Unit.GetCell(laserarray[i].position.X,laserarray[i].position.Z);//9aug2025
					if(u>=0)
					{
						if(Unit.unitarray[u].race!=laserarray[i].race && Unit.unitarray[u].hp>0)
						{
							laserarray[i].lifetime = 0;
						}
					}
				}
				if (laserarray[i].lifetime > 0 && laserarray[i].onground == 0)
				{
					laserarray[i].lifetime-=delta;
					laserarray[i].x+=laserarray[i].vx*delta;
					laserarray[i].y+=laserarray[i].vy*delta;
					laserarray[i].z+=laserarray[i].vz*delta;
					laserarray[i].position = new Vector3(laserarray[i].x,laserarray[i].y,laserarray[i].z);
					if(laserarray[i].isrocket!=0)
					{
						//race = target in this case
						if(laserarray[i].race>=0 && laserarray[i].race<ship.maxships)
						{
							int t = laserarray[i].race;
							if(ship.shiparray[t].hp>0)
							{
								Vector3 epos = new Vector3(ship.shiparray[t].x,ship.shiparray[t].y,ship.shiparray[t].z);
								Vector3 dirn = Raymath.Vector3Normalize(Raymath.Vector3Subtract(epos,laserarray[i].position));
								Vector3 vel = new Vector3(laserarray[i].vx,laserarray[i].vy,laserarray[i].vz);
								float length = Raymath.Vector3Length(vel);
								vel = Raymath.Vector3Normalize(vel);
								Vector3 nvel = Raymath.Vector3Scale(Raymath.Vector3Normalize(Raymath.Vector3Add(vel,Raymath.Vector3Scale(dirn,0.5f))),length);
								laserarray[i].vx = nvel.X;
								laserarray[i].vy = nvel.Y;
								laserarray[i].vz = nvel.Z;
								explosion.ISROCKET = 1;
								explosion.createexplosion(laserarray[i].x,laserarray[i].y,laserarray[i].z,0.1f,0.005f);
								explosion.ISROCKET = 0;
							}
							//now check for collisions.....
							for(int j=t;j<=t;j++)
							{
								Vector3 tmp = new Vector3(laserarray[i].x - ship.shiparray[j].x,laserarray[i].y - ship.shiparray[j].y,laserarray[i].z - ship.shiparray[j].z);
								float dist = Raymath.Vector3Length(tmp);
								if(ship.shiparray[j].hp>0 && ship.shiparray[j].race==ship.shiparray[t].race)
								{
									if(dist < ship.shiparray[j].maxvel * ship.shiparray[j].scale * 1f*escale)
									{
										//we've hit it...
										//check if our armour saved us....if so don't do damage....
										if(ship.random.Next(0,6)<ship.shiparray[j].armour) //random chance...//roll a dice.....
										{
											if(ship.random.NextDouble()<0.75)
											{
												laserarray[i].damage/=4; //no damage....
											}
										}
										laserarray[i].lifetime = 0;
										if(ship.shiparray[j].race==1)
										{
											//player team is more elite...lower numbers....so we have to give them a survival skill of sorts....
											if(ship.random.NextDouble()<0.2)
											{
												//dodged
												laserarray[i].damage = 0;
											}
										}
										else
										{
											//enemy team has the opposite of a dodge chance....they have a chance of taking extra damage....
											if(ship.random.NextDouble()<0.2)
											{
												laserarray[i].damage++;
											}
										}
										if(GameUI.spacesuperior!=0 && ship.shiparray[j].race==1)
										{
											ship.shiparray[j].hp-=laserarray[i].damage*0.25f;
										}
										else
										{
											ship.shiparray[j].hp-=laserarray[i].damage;
										}
										//ship.shiparray[j].strucktime = 45;
										//create explosion from hitting
										ship.ship_explosion(j,3.5f);
										//explosion.createexplosion(ship.shiparray[j].x,ship.shiparray[j].y,ship.shiparray[j].z,ship.shiparray[j].scale,3.5f);
										if(ship.shiparray[j].hp<=1)
										{
											//create a bigger explosion
											//explosion.createexplosion(ship.shiparray[j].x,ship.shiparray[j].y,ship.shiparray[j].z,ship.shiparray[j].scale,4f);
											ship.ship_explosion(j,4f);
											for(int k=0;k<2;k++)
											{
												//float offx = (float)(random.NextDouble()*1.0-0.5)*exscale*0.1f;
												//float offy = (float)(random.NextDouble()*1.0-0.5)*exscale*0.1f;
												//float offz = (float)(random.NextDouble()*1.0-0.5)*exscale*0.1f;
												ship.ship_explosion(j,2.5f);
												//explosion.createexplosion(ship.shiparray[j].x+offx,ship.shiparray[j].y+offy,ship.shiparray[j].z+offz,ship.shiparray[j].scale,2.5f);
											}
											if(ship.shiparray[j].shiptype==1)
											{
												//create an even bigger explosion....
												explosion.createexplosion(ship.shiparray[j].x,ship.shiparray[j].y,ship.shiparray[j].z,ship.shiparray[j].scale,4f);
												for(int k=0;k<2;k++)
												{
													//float offx = (float)(random.NextDouble()*1.0-0.5)*exscale*0.1f;
													//float offy = (float)(random.NextDouble()*1.0-0.5)*exscale*0.1f;
													//float offz = (float)(random.NextDouble()*1.0-0.5)*exscale*0.1f;
													ship.ship_explosion(j,2f);
													//explosion.createexplosion(ship.shiparray[j].x+offx,ship.shiparray[j].y+offy,ship.shiparray[j].z+offz,ship.shiparray[j].scale,2f);
												}
											}
										}
										break;
									}
								}
							}
						}
						
					}
					if(laserarray[i].isbeam!=0)
					{
						for(int j=0;j<ship.maxships;j++)
						{
							if(ship.shiparray[j].hp>0 && ship.shiparray[j].race!=laserarray[i].race && ship.shiparray[j].shiptype==1)
							{
								Vector3 tmp = new Vector3(ship.shiparray[j].x,ship.shiparray[j].y,ship.shiparray[j].z);
								float beamdist = Raymath.Vector3Distance(tmp,laserarray[i].direction);
								if(beamdist<250)
								{
									//we've hit it...
									laserarray[i].lifetime = 0;
									if(GameUI.spacesuperior!=0 && ship.shiparray[j].race==1)
									{
										ship.shiparray[j].hp-=laserarray[i].damage*0.5f;
									}
									else
									{
										ship.shiparray[j].hp-=laserarray[i].damage;
									}
									//create explosion from hitting
									if(ship.random.NextDouble()<0.3)
									{
										ship.ship_explosion(j,2f);
										//explosion.createexplosion(ship.shiparray[j].x,ship.shiparray[j].y,ship.shiparray[j].z,ship.shiparray[j].scale,(float)ship.random.NextDouble()*1.5f+1f);
									}
									//float offx = 0;
									//float offy = 0;
									//float offz = 0;
									if(ship.shiparray[j].hp<=20 && ship.shiparray[j].shiptype==1 && Program.followichangetime<=0 && ship.random.NextDouble()<0.1)
									{
									//	Program.followi = j;
									//	Program.followichangetime = 40;
									}
									if(ship.shiparray[j].hp<=1)
									{
										//create a bigger explosion
										//explosion.createexplosion(ship.shiparray[j].x,ship.shiparray[j].y,ship.shiparray[j].z,ship.shiparray[j].scale,1f);
										ship.ship_explosion(j,1f);
										for(int k=0;k<2;k++)
										{
											//explosion.createexplosion(ship.shiparray[j].x+offx,ship.shiparray[j].y+offy,ship.shiparray[j].z+offz,ship.shiparray[j].scale,2f);
											ship.ship_explosion(j,2f);
										}
									}
									break;
								}	
							}
						}
						
					}
					if(laserarray[i].isbeam==0 && laserarray[i].isrocket==0)
					{
						for(int j=0;j<ship.maxships;j++)
						{
							Vector3 tmp = new Vector3(laserarray[i].x - ship.shiparray[j].x,laserarray[i].y - ship.shiparray[j].y,laserarray[i].z - ship.shiparray[j].z);
							float dist = Raymath.Vector3Length(tmp);
							float bright = (3.0f - (dist / (ship.shiparray[j].maxvel * ship.shiparray[j].scale * 0.1f*escale*8f)))*0.25f;
							if(bright<0)
							{
								bright = 0;
							}
							ship.shiparray[j].laserbright += bright;
							if(ship.shiparray[j].laserbright<1)
							{
								ship.shiparray[j].laserbright = 1;
							}
							if(ship.shiparray[j].laserbright>10)
							{
								ship.shiparray[j].laserbright = 10;
							}
							if(ship.shiparray[j].hp>0 && ship.shiparray[j].race!=laserarray[i].race)
							{
								if(dist < ship.shiparray[j].maxvel * ship.shiparray[j].scale * 2.25f*escale)
								{
									//we've hit it...
									//check if our armour saved us....if so don't do damage....
									if(ship.random.Next(0,6)<ship.shiparray[j].armour) //random chance...//roll a dice.....
									{
										if(ship.random.NextDouble()<0.5)
										{
											laserarray[i].damage = 0; //no damage....
											ship.shiparray[j].armourdeflected=-30;
										}
									}
									laserarray[i].lifetime = 0;
									if(ship.shiparray[j].race==1) //player team gets a dodge chance....
									{
										if(ship.random.NextDouble()<0.2)
										{
											laserarray[i].damage = 0;
										}
									}
									else //enemy team has the opposite of a dodge chance...
									{
										if(ship.random.NextDouble()<0.2)
										{
											laserarray[i].damage++;
										}
									}
									if(ship.random.Next(0,10)<5)
									{
										if(GameUI.spacesuperior!=0 && ship.shiparray[j].race==1)
										{
											ship.shiparray[j].hp-=laserarray[i].damage*0.5f;
										}
										else
										{
											ship.shiparray[j].hp-=laserarray[i].damage;
										}
									}
									//create explosion from hitting
									//float exscale = 1f;
									//explosion.createexplosion(ship.shiparray[j].x,ship.shiparray[j].y,ship.shiparray[j].z,ship.shiparray[j].scale,2.5f);
									ship.ship_explosion(j,2.5f);
									if(ship.shiparray[j].hp<=1)
									{
										//create a bigger explosion
										//explosion.createexplosion(ship.shiparray[j].x,ship.shiparray[j].y,ship.shiparray[j].z,ship.shiparray[j].scale,4f);
										ship.ship_explosion(j,4f);
										for(int k=0;k<2;k++)
										{
											//float offx = (float)(random.NextDouble()*1.0-0.5)*exscale*0.1f;
											//float offy = (float)(random.NextDouble()*1.0-0.5)*exscale*0.1f;
											//float offz = (float)(random.NextDouble()*1.0-0.5)*exscale*0.1f;
											//explosion.createexplosion(ship.shiparray[j].x+offx,ship.shiparray[j].y+offy,ship.shiparray[j].z+offz,ship.shiparray[j].scale,2.5f);
											ship.ship_explosion(j,2.5f);
										}
										if(ship.shiparray[j].shiptype==1)
										{
											//create an even bigger explosion....
											explosion.createexplosion(ship.shiparray[j].x,ship.shiparray[j].y,ship.shiparray[j].z,ship.shiparray[j].scale,4f);
											for(int k=0;k<2;k++)
											{
//												float offx = (float)(random.NextDouble()*1.0-0.5)*exscale*0.1f;
//												float offy = (float)(random.NextDouble()*1.0-0.5)*exscale*0.1f;
//												float offz = (float)(random.NextDouble()*1.0-0.5)*exscale*0.1f;
												//explosion.createexplosion(ship.shiparray[j].x+offx,ship.shiparray[j].y+offy,ship.shiparray[j].z+offz,ship.shiparray[j].scale,2f);
												ship.ship_explosion(j,2f);
											}
										}
									}
									break;
								}
							}
						}	
					}					
				}
			}
		}
		
		public lasers()
		{
		}
		
	}
	
	class dust
	{
		public static int maxdust = 10000;
		public static dust[] dustarray = new dust[maxdust];
		public static Random random;
		public static float delta = 1f;
		public static float performance = 1000;	
		public float x;
		public float y;
		public float z;
		public Vector3 position;
		public static Model cmodel;
		public static Texture2D cdiffuse;
		public static Shader cshader;
		public static int cshadertex0;
		public static int cmodelMatrix;
		public static int cprojectionMatrix;
		public static int cviewMatrix;
		
		public static void initdust()
		{
			random = new Random();
			cdiffuse = Raylib.LoadTexture("media/fx/dusttex.png");
			UnloadHelper.AddTexture(cdiffuse);
			cmodel = Raylib.LoadModel("media/fx/dust.obj");
			UnloadHelper.AddModel(cmodel);
			cshader = Raylib.LoadShader("media/shaders/simpleshader.vs","media/shaders/simpleshader.fs");
			UnloadHelper.AddShader(cshader);
			cshadertex0 = Raylib.GetShaderLocation(cshader,"texture0");
			cmodelMatrix = Raylib.GetShaderLocation(cshader,"modelMatrix");
			cprojectionMatrix = Raylib.GetShaderLocation(cshader,"projectionMatrix");
			cviewMatrix = Raylib.GetShaderLocation(cshader,"viewMatrix");
			for(int i=0;i<maxdust;i++)
			{
				dustarray[i] = new dust();
				dustarray[i].x = (float)(random.NextDouble()*1000-500);
				dustarray[i].y = (float)(random.NextDouble()*1000-500);
				dustarray[i].z = (float)(random.NextDouble()*1000-500);
				dustarray[i].position = new Vector3(dustarray[i].x,dustarray[i].y,dustarray[i].z);
				if(i%50==0)
				{
					GameUI.Loading("Please Wait....Loading.....SPACE SHIPS",10,Program.resy - 56,GameUI.largefont,Color.LightGray,1);
				}
			}
		}
		
		public dust()
		{
			
		}
		
	}
	
	class spacebk
	{
		public static Random random;
		public static int useshader = 0;
		public static spacebk SPACE;
		public static spacebk SPACE2;
		public Texture2D diffuse;
		public Model model;
		public Shader shader;
		public float x;
		public float y;
		public float z;
		public float scale;
		public int shadertex0;
		public int modelMatrix;
		public int projectionMatrix;
		public int viewMatrix;
		//public int ambientocclusion;
		
		public spacebk()
		{
			scale = 0.1f;
			x = 0;
			y = 0;
			z = 0;
		}
		
		public static void initspace()
		{
			random = new Random();
			SPACE = new spacebk();
			SPACE.diffuse = Raylib.LoadTexture("media/fx/sp0.png");
			UnloadHelper.AddTexture(SPACE.diffuse);
			SPACE.model = Raylib.LoadModel("media/fx/space.obj");
			UnloadHelper.AddModel(SPACE.model);
			SPACE2 = new spacebk();
			SPACE2.model = Raylib.LoadModel("media/fx/planet.obj");
			UnloadHelper.AddModel(SPACE2.model);
			
			if(useshader!=0)
			{
				//this is not actually in use, if you look carefully you'll see useshader is zero
				//for this entity
				//so the fact the vertex shader simple2a.vs doesn't exist doesn't matter at all
				//9aug2025 keep this here in case we do eventually use it
				SPACE.shader = Raylib.LoadShader("media/shaders/simple2a.vs","media/shaders/simple2a.fs"); //doesn't exist yet.....
				UnloadHelper.AddShader(SPACE.shader);
				SPACE.shadertex0 = Raylib.GetShaderLocation(SPACE.shader,"texture0");
				SPACE.modelMatrix = Raylib.GetShaderLocation(SPACE.shader,"modelMatrix");
				SPACE.projectionMatrix = Raylib.GetShaderLocation(SPACE.shader,"projectionMatrix");
				SPACE.viewMatrix = Raylib.GetShaderLocation(SPACE.shader,"viewMatrix");
				unsafe
				{
					for(int j=0;j<SPACE.model.MaterialCount;j++)
					{
						SPACE.model.Materials[j].Shader = SPACE.shader;
					}
				}
				Raylib.SetShaderValueTexture(SPACE.shader,SPACE.shadertex0,SPACE.diffuse);
									
			}
		}
	}
	
