		public static int[] QuickSort(int[] inarray)
		{
			if(inarray.Length<=1)
			{
				return inarray;
			}
			//check if already sorted
			int unsorted = 0;
			for(int i=1;i<inarray.Length;i++)
			{
				if(explosionarray[inarray[i]].camdist<explosionarray[inarray[i-1]].camdist)
				{
					unsorted = 1;
					break;
				}
			}
			if(unsorted==0)
			{
				return inarray;
			}
			int midpoint = inarray.Length / 2;
			float midvalue = explosionarray[inarray[midpoint]].camdist;
			int countlower = 0;
			int countupper = 0;
			for(int i=0;i<inarray.Length;i++)
			{
				if(i==midpoint)
				{
					continue;
				}
				if(explosionarray[inarray[i]].camdist > midvalue && explosionarray[inarray[i]].animframe>=0 && explosionarray[inarray[i]].inspace==0)
				{
					countlower++;
				}
				if((explosionarray[inarray[i]].camdist <= midvalue || explosionarray[inarray[i]].animframe<0 || explosionarray[inarray[i]].inspace!=0) && i!=midpoint)
				{
					countupper++;
				}
			}
			int[] lowerhalf = new int[countlower];
			int[] upperhalf = new int[countupper];
			int j = 0;
			if(countlower>0)
			{
				for(int i=0;i<inarray.Length;i++)
				{
					if(explosionarray[inarray[i]].camdist > midvalue && i!=midpoint && explosionarray[inarray[i]].animframe>=0 && explosionarray[inarray[i]].inspace==0)
					{
						lowerhalf[j] = inarray[i];
						j++;
					}
				}
				lowerhalf = QuickSort(lowerhalf);
			}
			if(countupper>0)
			{
				j = 0;
				for(int i=0;i<inarray.Length;i++)
				{
					if((explosionarray[inarray[i]].camdist <= midvalue || explosionarray[inarray[i]].animframe<0 || explosionarray[inarray[i]].inspace!=0) && i!=midpoint)
					{
						upperhalf[j] = inarray[i];
						j++;
					}
				}
				upperhalf =  QuickSort(upperhalf);
			}
			int[] returnarray = new int[1 + countlower + countupper];
			j = 0;
			for(int i=0;i<returnarray.Length;i++)
			{
				if(i<countlower)
				{
					returnarray[i] = lowerhalf[j];
					j++;
				}
				if(i==countlower)
				{
					returnarray[i] = midpoint;
					j = 0;
				}
				if(i>countlower)
				{
					returnarray[i] = upperhalf[j];
					j++;
				}
			}
			return returnarray;
		}
		
		public static void createexplosiononground(float x,float y,float z,float size)
		{
			if(Program.autooptimise>2)
			{
				int dice = ship.random.Next(0,Program.targetfps);
				if(dice > Program.fps)
				{
					return;
				}
			}
			if(Program.gamestate!=Program.GROUNDBATTLE)
			{
				return;
			}
			if(ship.random.NextDouble()<0.02)
			{
				scorchmark.createscorchmark(x,z,4.0f);
				smoke.createsmokeemitter(x,z);
			}
			int docrater=1;
			if(size<1){docrater=0;}
			if(Program.orbitalbombardment>0)
			{
				docrater = 0; //yes...I know.....
			}
			if(docrater!=0)
			{				
				for(int i=Grass.maxgrasses - Grass.crateroffset;i<Grass.maxgrasses;i++)
				{
					if(Grass.grassarray[i].y>0 && Grass.grassarray[i].gtype==4)
					{
						if(Raymath.Vector2Length(new Vector2(x - Grass.grassarray[i].x,z  - Grass.grassarray[i].z))<40)
						{
							docrater = 0;
							break;
						}
					}
				}
				if(ship.random.Next(0,100)<10)
				{
					for(int i=0;i<Obstacle.maxobstacles;i++)
					{
						if(Obstacle.obstaclearray[i].hp>0)
						{
							if(Math.Abs(x - Obstacle.obstaclearray[i].x)<30 && Math.Abs(z - Obstacle.obstaclearray[i].z)<30)
							{
								Obstacle.obstaclearray[i].hp-=ship.random.Next(1,4);
								break;
							}
						}
					}
				}
			}
			if(ship.random.NextDouble()<0.15 && docrater==1)
			{
				for(int i=Grass.maxgrasses - Grass.crateroffset;i<Grass.maxgrasses;i++)
				{
					if(Grass.grassarray[i].gtype==4 && Grass.grassarray[i].y<-10)//crater
					{
						Grass.grassarray[i].x = x;
						Grass.grassarray[i].y = 0.01f;
						Grass.grassarray[i].z = z;
						Grass.grassarray[i].angle = (float)ship.random.NextDouble()*7.0f;
						Grass.setcover(x,z,40);
						break;
					}
				}
			}
			int k = 1;
			int aa = nextfreeexplosion;
			if(aa<0)
			{
				aa = 0;
				nextfreeexplosion = -1;
			}
			for(int i=aa;i<maxexplosions;i++)
			{
				if(i % 8==7)
				{
					continue;
				}
				if(i>fpsmaxexplosions)
				{
					return;
				}
				if(explosionarray[i].animframe<-12 || explosionarray[i].animframe>63)
				{
					explosionarray[i].animframe = - (float)(ship.random.NextDouble()*11.0) + 9;
					explosionarray[i].offscreen = 0;
					explosionarray[i].onground = 1;
					explosionarray[i].x = x;
					explosionarray[i].y = y;
					explosionarray[i].z = z;
					explosionarray[i].epos = new Vector3(explosionarray[i].x,explosionarray[i].y,explosionarray[i].z);
					explosionarray[i].size = size;
					explosionarray[i].scale = 1;
					explosionarray[i].isrocket=0;
					explosionarray[i].transformset = 0;
					explosionarray[i].inspace = 0;
					if(i>=maxcreated)
					{
						maxcreated = i;
					}
					k--;
					if(k<=0)
					{
						return;
					}
				}
			}
		}
		
