		public static void createexplosion(float x,float y, float z,float size,float scale)
		{
			if(Program.autooptimise>2)
			{
				int dice = ship.random.Next(0,Program.targetfps);
				if(dice > Program.fps)
				{
					return;
				}
			}
			
			//float escale = 0.1f;
			if(ISROCKET==0)
			{
				size*=3;
			}
			if(size<0.001)
			{
				size = 0.001f;
			}
			if(scale==0)
			{
				scale = 0.001f;
			}
			int k = random.Next(1,5);
			if(ISROCKET!=0)
			{
				k=1;
			}
			if(fpsmaxexplosions<maxexplosions)
			{
				if(Program.fps>Program.targetfps - 5 && Program.videomode==0)
				{
					fpsmaxexplosions++;
				}
			}
			for(int i=0;i<maxexplosions;i++)
			{
				if(i>fpsmaxexplosions)
				{
					return;
				}
				if(i%8==7)
				{
					continue;
				}
				if(explosionarray[i].animframe<-12 || explosionarray[i].animframe>63)
				{
					explosionarray[i].animframe = - (float)(ship.random.NextDouble()*11.0) + 9;
					explosionarray[i].offscreen = 0;
					explosionarray[i].onground = 0;
					explosionarray[i].inspace = 1;
					if(i>=maxcreated)
					{
						maxcreated = i;
					}
					if(ISROCKET==0)
					{
						explosionarray[i].x = x + (float)(ship.random.NextDouble()-0.5)*20f;// * escale ;//* 1.0025f * (float)(2.0*(random.NextDouble() - 0.5));
						explosionarray[i].y = y + (float)(ship.random.NextDouble()-0.5)*20f;// * escale ;//* 1.0025f * (float)(2.0*(random.NextDouble() - 0.5));
						explosionarray[i].z = z + (float)(ship.random.NextDouble()-0.5)*20f;// * escale ;//* 1.0025f * (float)(2.0*(random.NextDouble() - 0.5));
					}
					else
					{
						explosionarray[i].x = x;
						explosionarray[i].y = y;
						explosionarray[i].z = z;
					}
					explosionarray[i].epos = new Vector3(explosionarray[i].x,explosionarray[i].y,explosionarray[i].z);
					explosionarray[i].size = size * 2.75f;
					explosionarray[i].scale = 0.1f;//scale;
					explosionarray[i].transformset = 0;
					if(ISROCKET!=0)
					{
						explosionarray[i].isrocket=1;
					}
					else
					{
						explosionarray[i].isrocket=0;
					}
					k--;
					if(k<=0)
					{
						return;
					}
				}
			}
		}

		public static void drawall(Camera3D camera)
		{
			if(useshader!=0)
			{
				return;
			}
			Raylib.BeginBlendMode(BlendMode.AddColors);
			Rectangle source = new Rectangle(0,0,1024,1024);
			for(int i=0;i<explosion.maxexplosions;i++)
			{
				if(i%8==7)
				{
					continue;
				}
				if(explosion.explosionarray[i].animframe >=0 && explosion.explosionarray[i].animframe < 64)
				{
					int sx = (int)explosion.explosionarray[i].animframe % 8;
					int sy = ((int)explosion.explosionarray[i].animframe - sx)/8;
					source.X = sx * 128;
					source.Y = sy * 128;
					source.Width = 128;
					source.Height = 128;
					Raylib.DrawBillboardRec(camera,explosion.explosionarray[i].diffuse,source,Raymath.Vector3Scale(new Vector3(explosion.explosionarray[i].x,explosion.explosionarray[i].y,explosion.explosionarray[i].z),explosion.explosionarray[i].scale),new Vector2(4*explosion.explosionarray[i].size,4*explosion.explosionarray[i].size),Color.White);
				}
			}
			Raylib.EndBlendMode();
		}
		
		public static void updateexplosions()
		{
			changed = 0;
			for(int i=0;i<=maxcreated;i++)
			{
				if(i%8==7)
				{
					if(explosionarray[i].issmoke<60*30 && explosionarray[i].issmoke>0)
					{
						changed = 1;
						if(ship.random.NextDouble()<0.033)
						{
							explosionarray[i].animframe+=ship.delta;
						}
						explosionarray[i].y+=0.025f;
						explosionarray[i].size+=0.00025f;
						explosionarray[i].x+=0.0125f;
						if(explosionarray[i].animframe>63)
						{
							explosionarray[i].animframe = 0;
						}
						explosionarray[i].sectorx = Program.GetSectorX(explosionarray[i].x,explosionarray[i].z);
						explosionarray[i].sectorz = Program.GetSectorZ(explosionarray[i].x,explosionarray[i].z);
						explosionarray[i].camdist = Raymath.Vector3Distance(campos,explosionarray[i].epos);
						if(explosionarray[i].animframe==0)
						{
							explosionarray[i].issmoke++;
							if(explosionarray[i].issmoke>=60*30)
							{
								explosionarray[i].issmoke = 0;
							}
						}
					}
				}
				else
				{
					if(explosionarray[i].animframe>=-12)
					{
						changed = 1;
						explosionarray[i].animframe+=ship.delta;
						explosionarray[i].sectorx = Program.GetSectorX(explosionarray[i].x,explosionarray[i].z);
						explosionarray[i].sectorz = Program.GetSectorZ(explosionarray[i].x,explosionarray[i].z);
						explosionarray[i].camdist = Raymath.Vector3Distance(campos,explosionarray[i].epos);
						if(explosionarray[i].animframe > 63)
						{
							explosionarray[i].animframe = -100;
							nextfreeexplosion = i;
						}
					}
				}
			}
		}
		
		public static void initexplosions()
		{
			random = new Random();
			for(int i=0;i<maxexplosions;i++)
			{
				explosionarray[i] = new explosion();
				explosionarray[i].scale = 1;
				explosionarray[i].size = 1;
				explosionarray[i].animframe = -100;
				if(i%25==0)
				{
					GameUI.Loading("Please Wait....Loading.....FX",10,Program.resy - 56,GameUI.largefont,Color.LightGray,1);
				}
				
				if(i==0)
				{
					explosionarray[i].noisetex = Raylib.LoadTexture("media/fx/expnoise.png");
					UnloadHelper.AddTexture(explosionarray[i].noisetex);
				}
				else
				{
					explosionarray[i].noisetex = explosionarray[0].noisetex;
				}
				if(i>7)
				{
					explosionarray[i].diffuse = explosionarray[i % 8].diffuse;
					if(useshader!=0)
					{
						explosionarray[i].model = explosionarray[i % 8].model;
						explosionarray[i].shader = explosionarray[i % 8].shader;
						explosionarray[i].shadertex0 = explosionarray[i % 8].shadertex0;
						explosionarray[i].shadertex1 = explosionarray[i % 8].shadertex1;
						explosionarray[i].shaderframe = explosionarray[i % 8].shaderframe;
						explosionarray[i].modelMatrix = explosionarray[i % 8].modelMatrix;
						explosionarray[i].projectionMatrix = explosionarray[i % 8].projectionMatrix;
						explosionarray[i].viewMatrix = explosionarray[i % 8].viewMatrix;
						unsafe
						{
							for(int j=0;j<explosionarray[i].model.MaterialCount;j++)
							{
								explosionarray[i].model.Materials[j].Shader = explosionarray[i].shader;
								Raylib.SetMaterialTexture(&explosionarray[i].model.Materials[0], MaterialMapIndex.Albedo, explosionarray[i].diffuse);
								Raylib.SetMaterialTexture(&explosionarray[i].model.Materials[0], MaterialMapIndex.Metalness, explosionarray[i].noisetex);
							}
						}
						Raylib.SetShaderValueTexture(explosionarray[i].shader,explosionarray[i].shadertex0,explosionarray[i].diffuse);
						Raylib.SetShaderValueTexture(explosionarray[i].shader,explosionarray[i].shadertex1,explosionarray[i].noisetex);
					}
				}
				else
				{
					
					if(i<7)
					{
						explosionarray[i].diffuse = Raylib.LoadTexture("media/fx/explosion00"+(1+(i % 8))+".png");
					}
					else
					{
						explosionarray[i].diffuse = Raylib.LoadTexture("media/fx/smoke.png");
					}
					Raylib.SetTextureFilter(explosionarray[i].diffuse, TextureFilter.Bilinear);
					explosionarray[i].diffuse.Format = PixelFormat.UncompressedR8G8B8A8;
					UnloadHelper.AddTexture(explosionarray[i].diffuse);
					if(useshader!=0)
					{
						explosionarray[i].model = Raylib.LoadModel("media/fx/explosion"+(1+(i % 8))+".obj");
						UnloadHelper.AddModel(explosionarray[i].model);
						explosionarray[i].shader = Raylib.LoadShader("media/shaders/basicvertexshader8b8.vs","media/shaders/animated8by8pixelshader0a.fs");
						int debuglighting = Raylib.GetShaderLocation(explosionarray[i].shader,"debuglighting");
						int debugl = Program.debuglighting;
						unsafe
						{
							Raylib.SetShaderValueV(explosionarray[i].shader,debuglighting,&debugl,ShaderUniformDataType.Int,1);				
						}
						UnloadHelper.AddShader(explosionarray[i].shader);
						explosionarray[i].shadertex0 = Raylib.GetShaderLocation(explosionarray[i].shader,"texture0");
						explosionarray[i].shadertex1 = Raylib.GetShaderLocation(explosionarray[i].shader,"texture1");
						explosionarray[i].shaderframe = Raylib.GetShaderLocation(explosionarray[i].shader,"shaderframe");
						explosionarray[i].grey = Raylib.GetShaderLocation(explosionarray[i].shader,"greyscale");
						explosionarray[i].modelMatrix = Raylib.GetShaderLocation(explosionarray[i].shader,"modelMatrix");
						explosionarray[i].projectionMatrix = Raylib.GetShaderLocation(explosionarray[i].shader,"projectionMatrix");
						explosionarray[i].viewMatrix = Raylib.GetShaderLocation(explosionarray[i].shader,"viewMatrix");
						unsafe
						{
							for(int j=0;j<explosionarray[i].model.MaterialCount;j++)
							{
								explosionarray[i].model.Materials[j].Shader = explosionarray[i].shader;
								Raylib.SetMaterialTexture(&explosionarray[i].model.Materials[j], MaterialMapIndex.Albedo, explosionarray[i].diffuse);
								Raylib.SetMaterialTexture(&explosionarray[i].model.Materials[j], MaterialMapIndex.Metalness, explosionarray[i].noisetex);
								
							}
							Raylib.SetShaderValueTexture(explosionarray[i].shader,explosionarray[i].shadertex0,explosionarray[i].diffuse);
							Raylib.SetShaderValueTexture(explosionarray[i].shader,explosionarray[i].shadertex1,explosionarray[i].noisetex);
						}
					}
				}
			}
			int oi = 0;
			for(int ii = 0;ii<8;ii++)
			{
				for(int i=0;i<maxexplosions;i++)
				{
					if(i%8==ii)
					{
						orderarray[oi] = i;
						oi++;
					}
				}
			}
		}
	}
	
