		public float targettime;
		public float targetdelay;
		public int shiptype; //1-3, 1 = cruiser, 2 = fighter, 3 = bomber
		public int race ;//1 = earth (efighter etc) 2== alien (afighter etc)
		
		public float deploytroopstime; //for enemy cruisers....
		public float deploytroopsdelay;
		public int dodeploy;
		
		public float scale;
		//shader stuff
		public int shadertex0;
		public int ambientocclusion;
		public int modelMatrix;
		public int projectionMatrix;
		public int viewMatrix;
		public int eyepos;
		public int colormultiplier;	
		public Matrix4x4 rotationmatrix;
		public Vector3 pos;
		public Vector3 xaxis;
		public Vector3 yaxis;
		public Vector3 zaxis;
		public Vector3 vscale;
		public static int exframe = 0;
		
		public static float AttackFromX(int i)
		{
			float dist = 650;
			//if(GameUI.sandbox!=0)
			//{
			//	i = 1;
			//}
			switch(i % 4)
			{
				case 0:
					//along x = -400
					return -dist;
				case 1:
					//along x = +400
					return dist;
				case 2:
					//along z = -400
					return (float)(random.NextDouble()*(2*dist)-dist);
				case 3:
					//along z = 400
					return (float)(random.NextDouble())*(2*dist)-dist;
			}
			return -dist;
		}
		
		public static float AttackFromZ(int i)
		{
			float dist = 650;
			switch(i % 4)
			{
				case 0:
					//along z = -400
					return (float)(random.NextDouble()*(2*dist)-dist);
				case 1:
					//along z = 400
					return (float)(random.NextDouble()*(2*dist)-dist);
				case 2:
					//along x = -400
					return -dist;
				case 3:
					//along x = +400
					return dist;
			}
			return -dist;
		}
		
		public static void updateships()
		{
			exframe++;
			for(int i=0;i<3;i++)//flyby
			{
				if(flyby.x[i]<3000)
				{
					flyby.x[i]+=3f;
					flyby.z[i]+=1f;
					
				}
				else
				{
					flyby.y[i]=(float)ship.random.Next(50,70);
				}
			}
			for(int i=3;i<11;i++)//airstrike //17aug2025
			{
				if(flyby.airstrike[i]!=0)
				{
					flyby.x[i]+=flyby.vx[i]; //air strike craft fly over..
					flyby.z[i]+=flyby.vz[i];
					if(Math.Abs(flyby.x[i])>3000 || Math.Abs(flyby.z[i])>3000) //if it's out of range...and put it back into space
					{
						flyby.airstrike[i] = 0;
						float angle = (float)ship.random.NextDouble()*12f;
						flyby.y[i] = 45f + (float)ship.random.NextDouble()*10f;
						flyby.x[i] = 2000.0f * (float) Math.Sin(angle);
						flyby.z[i] = 2000.0f * (float) Math.Cos(angle);
						flyby.vy[i] = 0;
						flyby.vz[i] = 0.8f*(- flyby.z[i] / 2000f) * 4f;
						flyby.vx[i] = 0.8f*(- flyby.x[i] / 2000f) * 4f;
						//don't put back into space - otherwise player can cheat and keep the fleet alive by keeping them permanently on ground strike missions
						//eg there's no penalty for using them if you just rebuild the fleet as soon as the air strike is over.
						
						/*
						if(i<7)
						{
							GameUI.BuildShip(2);
						}
						else
						{
							GameUI.BuildShip(3);
						}
						*/
					}
					else
					{
						//launch attacks on enemy ground targets if we're inside a certain boundary.....
						if(Math.Abs(flyby.x[i])<500 && Math.Abs(flyby.z[i])<500)
						{
							//random chance - alter this if too much/too little
							int jjj = 1;
							if(i>7)
							{
								jjj = 4;
							}
							if(ship.random.Next(0,10000)<5000)
							{
								for(int jj=0;jj<jjj;jj++)
								{
									int j = ship.random.Next(0,Unit.unitarray.Length);
									if(Unit.unitarray[j].race==2 && Unit.unitarray[j].hp>0 && Math.Abs(Unit.unitarray[j].x)<650 && Math.Abs(Unit.unitarray[j].z)<650)
									{
										//random target chosen, it's alive, it's an enemy and it's within close range of the player's base
										float damage = 2; //adjust this as needed
										lasers.STARTY = flyby.y[i];
										lasers.OFFX = 0;
										lasers.OFFZ = 0;
										lasers.creategroundlaser(new Vector3(flyby.x[i],flyby.y[i],flyby.z[i]),new Vector3(Unit.unitarray[j].x,Unit.unitarray[j].y,Unit.unitarray[j].z),1,damage);
										Unit.unitarray[j].hp-=damage;
										if(Unit.unitarray[j].hp<=0)
										{
											Unit.deadunit(j); //handle explosions as well
											//potentially do some explosions here as well...potentially...
										}
									}
								}
							}
						}
					}
				}
				
			}
			for(int i=0;i<maxships;i++)
			{
				if(shiparray[i].hp<=0)
				{
					shiparray[i].deadframe+=delta;
					if(shiparray[i].deadframe<4)
					{
						//explosion.createexplosion(shiparray[i].x,shiparray[i].y,shiparray[i].z,shiparray[i].scale,10*((float)random.NextDouble()*2.5f + 1));
						ship.ship_explosion(i,2f);
						shiparray[i].deadframe = 4;
						if(shiparray[i].race==1 && shiparray[i].shiptype==1)
						{
							if(GameUI.portraitmsg=="")
							{
								GameUI.portraittime = 360;
								GameUI.portraitmsg = "Battlecruiser has been lost!";
								Audio.Notification();
								Audio.VoiceNotify(Audio.ALERT_BATTLECRUISERLOST);
								GameUI.portraiton = GameUI.starshipportraitid;
							}
						}
					}
					//respawning ships
					if(shiparray[i].deadframe>1000 && (shiparray[i].race==2 || Scenario.ms.fleets_active==0)) //fleets active = 0 means there's no real space battle going on....not really.....not that impacts the game in any way...but we do this by just letting the space battle play out with everybody respawning not just the enemy
					{
						shiparray[i].hp = shiparray[i].basehp ; // spawns back to life.
						shiparray[i].z+=1000;
						if(shiparray[i].race==1)
						{
								shiparray[i].z-=2000;
						}
						shiparray[i].deadframe = 0;
						shiparray[i].dodeploy = 0;
					}
				}
				if(shiparray[i].hp>0)
				{
					if(shiparray[i].deploytroopsdelay>0)
					{
						shiparray[i].deploytroopsdelay-=delta;
					}
					int debugging = 0;
					//ground units enemy respawns are handled in here when the enemy cruisers get close enough
					if(Program.wavedelay>0)
					{
						debugging = 1; 
					}
					if(Program.briefingframe>0)
					{
						Program.wavedelay = 60 * 40;
					}				
					if(((Program.tutorialstage>=7 || Program.tutorial==0) && debugging==0 && Program.noenemies==0 && GameUI.sandbox==0) || Profile.stresstest!=0)
					{
						if((shiparray[i].shiptype==1 && shiparray[i].race==2 && ((shiparray[i].hp<shiparray[i].basehp - shiparray[i].basehp/3) || shiparray[i].dodeploy==1 || Program.deploy>0)))
						{
							Program.deploy--;

							if(Program.deploying<=0){Program.deploying = 300;Audio.VoiceNotify(Audio.ALERT_ENEMYWAVEINBOUND);}
							if(shiparray[i].deploytroopstime == 0)
							{
								shiparray[i].deploytroopstime = 60 * 10;
							}
							
							if(shiparray[i].deploytroopsdelay<=0)
							{
								shiparray[i].deploytroopsdelay = shiparray[i].deploytroopstime;
								//deploy units on the planet's surface....
								
								//we want to limit the maximum number of troops we send against
								//the player to no more than three times their current quantity
								//of soldiers on the battlefield....down to a minimum of 10.
								int enemycount = 0;
								int playercount = 0;
								for(int j=0;j<Unit.maxunits;j++)
								{
									if(Unit.unitarray[j].race==1 && Unit.unitarray[j].hp>0)
									{
										playercount+=3; 
									}
									if(Unit.unitarray[j].race==2 && Unit.unitarray[j].hp>0)
									{
										enemycount++;
									}
								}
								int ucount = 4 + playercount / 6;
								int fscount = 0;
								int escount = 0;
								//the more enemy ships in space compared to ours the more infantry they can land......
								//makes it worthwhile to send ships to space.......
								for(int j=0;j<maxships;j++)
								{
									if(shiparray[j].hp>0 && shiparray[j].race==1)
									{
										fscount++;
									}
									if(shiparray[j].hp>0 && shiparray[j].race==2)
									{
										escount++;
									}
								}
								if(escount>fscount)
								{
									ucount+=1;
								}
								if(escount>fscount+3)
								{
									ucount+=1;
								}
								if(escount>fscount+5)
								{
									ucount+=1;
								}
								if(escount>fscount+7)
								{
									ucount+=1;
								}
								
								if(Program.gamelength > 300)
								{
									ucount+=12; //massive waves after a few minutes
								}
								if(Program.gamelength > 900)
								{
									ucount+=25; //massive waves even bigger waves
								}
								if(Program.gamelength > 1200)
								{
									ucount+=37; //ridiculous sized waves
								}
								if(Profile.stresstest!=0 && Program.gamelength>60)
								{
									ucount+=40;
								}
								//difficulty setting......
								ucount/=Program.difficulty;
								if(Program.gamelength > 360)
								{
									ucount+=20;
								}
								if(Program.gamelength > 540)
								{
									ucount+=20;
								}
								if(Program.gamelength > 720)
								{
									ucount+=20;
								}
								if(ucount<4)
								{
									ucount = 4;
								}
								if(Program.IsReleased(2,Program.doubledeploy_release,Program.gametimer.ElapsedMilliseconds)!=0)
								{
									ucount*=2;
								}
								if(Program.IsReleased(2,Program.doubledoubledeploy_release,Program.gametimer.ElapsedMilliseconds)!=0)
								{
									ucount*=2;
								}
								if(Program.IsReleased(2,Program.doubledoubledoubledeploy_release,Program.gametimer.ElapsedMilliseconds)!=0)
								{
									ucount*=2;
								}
								
								int oucount = ucount;
								Audio.Notification();
								if(ucount>10)
								{
									if(GameUI.portraitmsg=="")
									{
										GameUI.portraittime = 360;
										GameUI.portraitmsg = "Enemy Wave Approaching";
										
										GameUI.portraiton = GameUI.waveportraitid;
									}
								}
								else
								{
									if(GameUI.portraitmsg=="")
									{
										GameUI.portraittime = 360;
										GameUI.portraitmsg = "Large Enemy Wave Approaching";
										GameUI.portraiton = GameUI.waveportraitid;
									}
								}
								int diffcount = enemycount - playercount; //playercount is 3* playercount in reality...
								//also if the number of tanks on the field by the enemy is greater than say
								//10 then don't add any more stuff on the field...
								//less is more - the game is more fun when there's less stuff on the map....
								//it just becomes cluttered and ridiculous when there's too much stuff
								int vehiclecount = 0;
								int infantrycount = 0;
								for(int j=0;j<Unit.maxunits;j++)
								{
									if(Unit.unitarray[j].race==2 && Unit.unitarray[j].shiptype%10>1 && Unit.unitarray[j].hp>0)
									{
										if(Unit.unitarray[j].immobilised==0)
										{
											vehiclecount++;
										}
									}
									if(Unit.unitarray[j].race==2 && Unit.unitarray[j].shiptype%10==1 && Unit.unitarray[j].hp>0)
									{
										infantrycount++;
									}
								}
								//basically I've implemented a unit cap because the game gets ridiculous
								//when the numbers get too high....
								//this will help both keep the game fun and keep the framerate high.
								if(diffcount > 0 || vehiclecount>Unit.enemyvehiclecap || infantrycount>Unit.enemyinfantrycap)
								{
									//computer player has more than three times the human player's
									//units on the battlefield. Therefore add no more.....
									//DO NOTHING
								}
								else
								{
									//Profile.message = "ucount:"+ucount;
									int qrs = 0;
									int tankchance = ship.random.Next(0,100);
									int heavytankchance = ship.random.Next(0,100);
									int tmax = ship.random.Next(2,12);
									if(heavytankchance<15 && ucount>=3)
									{
										int tcount = 0;
										for(int j=0;j<Unit.maxunits;j++)
										{
											if(Unit.unitarray[j].hp<=0 && Unit.unitarray[j].race==2 && Unit.unitarray[j].shiptype==4)
											{
												qrs = ship.random.Next(0,5);		
												for(int qqrr=0;qqrr<2;qqrr++)
												{
													if(qrs!=Program.qrs_preferred && Program.qrs_preferred>=0)
													{
														qrs = ship.random.Next(0,5);		
													}
												}
												if(Program.difficulty<=2 || Program.gamelength>=150 || (Program.difficulty>=3 && Program.gamelength < 150 && ship.random.Next(0,100)<25))
												{
													Unit.unitarray[j].hp = Unit.unitarray[j].basehp;
													Unit.unitarray[j].x = AttackFromX(qrs);
													Unit.unitarray[j].z = AttackFromZ(qrs);
													Unit.unitarray[j].amode = 0;
													Unit.unitarray[j].soldiertype = -1;
													Unit.unitarray[j].PrepareUnit();
													Unit.unitarray[j].ping = 180;
												}
												ucount-=Program.difficulty;
												deploycount++;
												tcount++;
												if(ucount<=0 || tcount>tmax)
												{
													break;
												}
											}
										}
									}
									int defenderchance = ship.random.Next(0,100);
									int dmax = ship.random.Next(3,12);
									if(defenderchance<15 && ucount >= 4)
									{
										qrs = ship.random.Next(0,5);
										for(int qqrr=0;qqrr<2;qqrr++)
										{
											if(qrs!=Program.qrs_preferred && Program.qrs_preferred>=0)
											{
												qrs = ship.random.Next(0,5);		
											}
										}
														
										int dcount = 0;
										for(int j=0;j<Unit.maxunits;j++)
										{
											if(Unit.unitarray[j].hp<=0 && Unit.unitarray[j].race==2 && Unit.unitarray[j].shiptype==21)
											{
												if(Program.difficulty<=2 || Program.gamelength>=150 || (Program.difficulty>=3 && Program.gamelength < 150 && ship.random.Next(0,100)<25))
												{
													Unit.unitarray[j].hp = Unit.unitarray[j].basehp;
													Unit.unitarray[j].x = AttackFromX(qrs);
													Unit.unitarray[j].z = AttackFromZ(qrs);
													Unit.unitarray[j].amode = 0;
													Unit.unitarray[j].soldiertype = 0;
													Unit.unitarray[j].PrepareUnit();
													Unit.unitarray[j].ping = 180;
												}
												ucount-=Program.difficulty;
												deploycount++;
												dcount++;
												if(ucount<=0 || dcount>dmax)
												{
													break;
												}
											}
										}
									}
									int assaultchance = ship.random.Next(0,100);
									int amax = ship.random.Next(4,12);
									if(assaultchance<20 && ucount >= 6)
									{
										qrs = ship.random.Next(0,5);
										for(int qqrr=0;qqrr<2;qqrr++)
										{
											if(qrs!=Program.qrs_preferred && Program.qrs_preferred>=0)
											{
												qrs = ship.random.Next(0,5);		
											}
										}
																						
										int acount = 0;
										for(int j=0;j<Unit.maxunits;j++)
										{
											if(Unit.unitarray[j].hp<=0 && Unit.unitarray[j].race==2 && Unit.unitarray[j].shiptype==11)
											{
												if(Program.difficulty<=2 || Program.gamelength>=150 || (Program.difficulty>=3 && Program.gamelength < 150 && ship.random.Next(0,100)<25))
												{
													Unit.unitarray[j].hp = Unit.unitarray[j].basehp;
													Unit.unitarray[j].x = AttackFromX(qrs);
													Unit.unitarray[j].z = AttackFromZ(qrs);
													Unit.unitarray[j].amode = 0;
													Unit.unitarray[j].soldiertype = 0;
													Unit.unitarray[j].PrepareUnit();
													Unit.unitarray[j].ping = 180;
												}
												ucount-=Program.difficulty;
												deploycount++;
												acount++;
												if(ucount<=0 || acount>amax)
												{
													break;
												}
											}
										}
									}
									int oneboardedgechance = ship.random.Next(0,100); //added at library
									if(oneboardedgechance>80)
									{
										oneboardedgechance = 1;
									}
									else
									{
										oneboardedgechance = 0;
									}
									qrs = ship.random.Next(0,5);  //added at library
									for(int qqrr=0;qqrr<2;qqrr++)
									{
										if(qrs!=Program.qrs_preferred && Program.qrs_preferred>=0)
										{
											qrs = ship.random.Next(0,5);		
										}
									}
												
									if(ucount<4)
									{
										ucount = 4;
									}
									if(ucount>0)
									{
										for(int j=0;j<Unit.maxunits;j++)
										{
											
											int specialtankchance = ship.random.Next(0,1000);
											if(((tankchance<10 && ucount<=3 && oucount > 5) || specialtankchance<25) && Program.IsReleased(2,Program.hovertank_release,Program.gametimer.ElapsedMilliseconds)!=0)
											{
												if((((Unit.unitarray[j].hp<=0 || Unit.unitarray[j].amode==100) && Unit.unitarray[j].race==2 && Unit.unitarray[j].shiptype==2))) //|| Unit.unitarray[j].unborn==1) && Unit.unitarray[j].race==2)
												{
													if(Program.difficulty<=2  || Program.gamelength>=150 || (Program.difficulty>=3 && Program.gamelength < 150 && ship.random.Next(0,100)<25))
													{
														Unit.unitarray[j].hp = Unit.unitarray[j].basehp;
														if(oneboardedgechance==0){qrs = ship.random.Next(0,5);}
														Unit.unitarray[j].x = AttackFromX(qrs);
														Unit.unitarray[j].z = AttackFromZ(qrs);
														Unit.unitarray[j].amode = 0;
														Unit.unitarray[j].immobilised = 0;
														Unit.unitarray[j].PrepareUnit();
														Unit.unitarray[j].ping = 180;
													}
													ucount-=Program.difficulty;
													deploycount++;
													if(ucount<=0)
													{
														break;
													}
												}									
											}
											else
											{
												int dice1 = ship.random.Next(1,11); //roll a 1/10 to get a tank.....
												if((((Unit.unitarray[j].hp<=0 || Unit.unitarray[j].amode==100) && Unit.unitarray[j].race==2 && ((Unit.unitarray[j].shiptype==1 && dice1<8) || (Unit.unitarray[j].shiptype==11 && dice1>7) || (Unit.unitarray[j].shiptype==21 && dice1>8) || (Unit.unitarray[j].shiptype==4 && dice1>9 && Program.IsReleased(2,Program.tank_release,Program.gametimer.ElapsedMilliseconds)!=0))))) //|| Unit.unitarray[j].unborn==1) && Unit.unitarray[j].race==2)
												{
													if(Program.difficulty<=2 || Program.gamelength>=150 || (Program.difficulty>=3 && Program.gamelength < 150 && ship.random.Next(0,100)<25))
													{
														Unit.unitarray[j].hp = Unit.unitarray[j].basehp;
														if(oneboardedgechance==0){qrs = ship.random.Next(0,5);}
														Unit.unitarray[j].x = AttackFromX(qrs);
														Unit.unitarray[j].z = AttackFromZ(qrs);
														Unit.unitarray[j].amode = 0;
														Unit.unitarray[j].soldiertype = 0;
														Unit.unitarray[j].PrepareUnit();
														Unit.unitarray[j].ping = 180;
													}
													ucount-=Program.difficulty;
													deploycount++;
													if(ucount<=0)
													{
														break;
													}
												}
											}
										}
									}
								}
							}
						}
					}
					debugging = 0;
					if(shiparray[i].armourdeflected<0)
					{
						shiparray[i].armourdeflected+=delta;
						//explosion.createexplosion(shiparray[i].x,shiparray[i].y,shiparray[i].z,shiparray[i].scale,0.65f*(float)random.NextDouble()*2.5f + 1);
						ship.ship_explosion(i,2.5f);
					}
					if(shiparray[i].armourdeflected>0)
					{
						shiparray[i].armourdeflected=0;
					}
					shiparray[i].deadframe= 0;
					if(exframe % maxships==i)
					{
						if((float)random.NextDouble()>4.0f*shiparray[i].hp/shiparray[i].basehp)
						{
							if(Program.fps>Program.targetfps - 10)
							{
								//explosion.createexplosion(shiparray[i].x,shiparray[i].y,shiparray[i].z,shiparray[i].scale,(float)random.NextDouble()*2.5f + 1);
								ship.ship_explosion(i,2.5f);
							}
						}
						int qq = (int)(shiparray[i].basehp - shiparray[i].hp);
						if(qq>20)
						{
							qq=20;
						}
						if(qq<0)
						{
							qq=0;
						}
						for(int k=0;k<qq;k++)
						{
							if(shiparray[i].hp < shiparray[i].basehp && (float)random.NextDouble()<0.005)
							{
								//explosion.createexplosion(shiparray[i].x+(float)(random.NextDouble()-0.5)*50f,shiparray[i].y+(float)(random.NextDouble()-0.5)*50f,shiparray[i].z+(float)(random.NextDouble()-0.5)*50f,shiparray[i].scale,0.25f*((float)random.NextDouble()*0.5f + 0.5f));
								ship.ship_explosion(i,1f);
							}
						}
					}
					shiparray[i].laserbright = 1;
					shiparray[i].firedelay -= delta*1.5f; //edited 2025aug15 to 1.5
					shiparray[i].targetdelay -= delta * 5;
					if (shiparray[i].targetdelay <= 0)
					{
						shiparray[i].targetdelay = shiparray[i].targettime;
						if(shiparray[i].targetid==-3)
						{
							shiparray[i].targetid = -1;	
						}
						else
						{
							shiparray[i].targetdelay = shiparray[i].targettime / 8;
						}
						
					}
					if((int)random.Next(0,1000)<10)
					{
						shiparray[i].targetid=-1;
						shiparray[i].targetdelay = shiparray[i].targettime/2;
					}
					if (shiparray[i].targetid==-1)
					{
						//find a suitable target
						float maxdist = 0;
						int targetsame = -1;
						int	targetany = -1;
						int targetrnd = (int)random.Next(0,maxships);
						if(targetrnd>=0 && targetrnd<maxships && shiparray[i].shiptype>1)
						{
							if(shiparray[targetrnd].race!=shiparray[i].race && shiparray[targetrnd].hp>0)
							{
								shiparray[i].targetid = targetrnd;
							}
						}
						if(shiparray[i].targetid==-1)
						{
							for(int j=0;j<maxships;j++)
							{
								//pick whichever one is furthest from us
								//and the same class of ship 
								//failing that just pick whichever one we can
								if(shiparray[j].race!=shiparray[i].race && shiparray[j].hp>0)
								{
									if(shiparray[j].shiptype==shiparray[i].shiptype)
									{
										float dist = (shiparray[j].x - shiparray[i].x)*(shiparray[j].x - shiparray[i].x)+(shiparray[j].y - shiparray[i].y)*(shiparray[j].y - shiparray[i].y)+(shiparray[j].z - shiparray[i].z)*(shiparray[j].z - shiparray[i].z);
										if(dist>maxdist)
										{
											maxdist = dist;
											targetsame = j;
										}
									}
									targetany = j;
								}
							}
							if(targetsame!=-1)
							{
								shiparray[i].targetid = targetsame;
							}
							else
							{
								if(shiparray[i].shiptype==1 && shiparray[i].race==2)
								{
									shiparray[i].dodeploy = 1;
								}
								else
								{
									shiparray[i].dodeploy = 0;
								}
								if(targetany!=-1)
								{
									shiparray[i].targetid = targetany;
								}
							}
						}
					}
					if(shiparray[i].targetid==-2)
					{
						shiparray[i].targetid = -3;
						shiparray[i].dx = (float)(random.NextDouble()*500-250)*5;
						shiparray[i].dy = (float)(random.NextDouble()*500-250)*5;
						shiparray[i].dz = (float)(random.NextDouble()*500-250)*5;
					}
					
					
					if(shiparray[i].firedelay<=0 && shiparray[i].shiptype>1)
					{
						for(int j=0;j<maxships;j++)
						{
							if(shiparray[j].race!=shiparray[i].race && shiparray[j].hp>0)
							{
								Vector3 myvel = new Vector3(shiparray[i].vx,shiparray[i].vy,shiparray[i].vz);
								myvel = Raymath.Vector3Normalize(myvel);
								Vector3 mypos = new Vector3(shiparray[i].x,shiparray[i].y,shiparray[i].z);
								Vector3 enemypos = new Vector3(shiparray[j].x,shiparray[j].y,shiparray[j].z);
								Vector3 dirntoenemy = Raymath.Vector3Subtract(enemypos,mypos);
								dirntoenemy = Raymath.Vector3Normalize(dirntoenemy);
								float gundot = Raymath.Vector3DotProduct(dirntoenemy,myvel);
								if(gundot>0.75 && Raymath.Vector3Length(Raymath.Vector3Subtract(enemypos,mypos))<750 && Raymath.Vector3Length(Raymath.Vector3Subtract(enemypos,mypos))>400)
								{
									if(shiparray[i].shiptype==3)//bomber
									{
										shiparray[i].firedelay = shiparray[i].firetime;
										if(random.NextDouble()<0.025) //reduced rocket chance
										{
											//1 in 3 chance of firing a rocket....
											lasers.createrocket(shiparray[i].x,shiparray[i].y,shiparray[i].z,myvel.X * shiparray[i].maxvel * 2.5f,myvel.Y * shiparray[i].maxvel * 2.5f,myvel.Z * shiparray[i].maxvel * 2.5f,j,shiparray[i].shiptype*4);
											if(Program.followichangetime<=0)
											{
												Program.followi = i;
												Program.followichangetime = 120;
											}
											break;
										}
										
									}
								}
								if(gundot>0.9 && Raymath.Vector3Length(Raymath.Vector3Subtract(enemypos,mypos))<500)
								{
									//shoot at the enemy....
									shiparray[i].firedelay = shiparray[i].firetime/3;
									lasers.STARTY = 0;
									lasers.OFFX = 0;
									lasers.OFFZ = 0;
									if(shiparray[i].race==1)
									{
										lasers.OFFX = 14;
										lasers.OFFZ = 4;
										if(shiparray[i].leftrightbarrel==1)
										{
											lasers.OFFX = -14;
										}
									}
									else
									{
										lasers.OFFX = 7;
										lasers.OFFZ = 0;
										if(shiparray[i].leftrightbarrel==1)
										{
											lasers.OFFX = -7;
										}
									}
									updatevectors_lasers(i);
									shiparray[i].leftrightbarrel++;
									shiparray[i].leftrightbarrel%=2;
									lasers.createlaser(shiparray[i].x*shiparray[i].scale,shiparray[i].y*shiparray[i].scale,shiparray[i].z*shiparray[i].scale,myvel.X * shiparray[i].scale * shiparray[i].maxvel * 5.0f,myvel.Y * shiparray[i].scale * shiparray[i].maxvel * 5.0f,myvel.Z * shiparray[i].scale * shiparray[i].maxvel * 5.0f,shiparray[i].race,shiparray[i].shiptype);
									if(shiparray[Program.followi].shiptype>1 && Program.followichangetime<=0)
									{
										Program.followi = i;
										Program.followichangetime = 120;
									}
									break;
								}
							}
						}
					}
					
					if(shiparray[i].targetid>=0)
					{
						//check if we can shoot our target......
						shiparray[i].dx = shiparray[shiparray[i].targetid].x - shiparray[i].x;
						shiparray[i].dy = shiparray[shiparray[i].targetid].y - shiparray[i].y;
						shiparray[i].dz = shiparray[shiparray[i].targetid].z - shiparray[i].z;
						
						if(shiparray[i].firedelay<=0)
						{
							shiparray[i].firedelay = shiparray[i].firetime * 0.66f;
							Vector3 tmp = new Vector3(shiparray[i].dx,shiparray[i].dy,shiparray[i].dz);
							float damage = 1f;
							if(shiparray[i].shiptype==3)
							{
								damage = 1.5f;
								
							}
							if(shiparray[i].shiptype==1)
							{
								damage = 3f;
							}
							int beamfired = 0;
							if(Raymath.Vector3Length(tmp)<800 && shiparray[i].shiptype==1)
							{
								Vector3 vel = new Vector3(shiparray[i].vx,shiparray[i].vy,shiparray[i].vz);
								Vector3 tmp2 = Raymath.Vector3Normalize(tmp);
								vel = Raymath.Vector3Normalize(vel);
								float gdot = Raymath.Vector3DotProduct(tmp2,vel);
								if(shiparray[i].shiptype==1 && shiparray[shiparray[i].targetid].shiptype==1)
								{	
									if(gdot > 0.8)
									{
										int t = shiparray[i].targetid;
										if(shiparray[i].race==2)
										{
											shiparray[i].dodeploy = 1;
										}
										lasers.createbeam(shiparray[i].x*shiparray[i].scale,shiparray[i].y*shiparray[i].scale,shiparray[i].z*shiparray[i].scale,shiparray[t].x*shiparray[t].scale,shiparray[t].y*shiparray[t].scale,shiparray[t].z*shiparray[t].scale,shiparray[i].race,1);
										shiparray[i].firedelay = 0;	
										shiparray[i].targetdelay = 10;
										if(Program.followichangetime<=0 && random.NextDouble()<0.1)
										{
											Program.followi = i;
											Program.followichangetime = 120;
										}
										beamfired = 1;
									}
								}
							}
							
							if(Raymath.Vector3Length(tmp)<550 && beamfired == 0)
							{
								Vector3 vel = new Vector3(shiparray[i].vx,shiparray[i].vy,shiparray[i].vz);
								tmp = Raymath.Vector3Normalize(tmp);
								int forwards = 0;
								if(Raymath.Vector3Length(vel)>shiparray[i].maxvel*0.6f)
								{
									forwards = 1;
								}
								vel = Raymath.Vector3Normalize(vel);
								float gdot = Raymath.Vector3DotProduct(tmp,vel);
								if(gdot > 0.98 && forwards==1)
								{
									//we can shoot
									lasers.STARTY = 0;
									lasers.OFFX = 0;
									lasers.OFFZ = 0;
									if(shiparray[i].race==1)
									{
										lasers.OFFX = 14;
										lasers.OFFZ = 4;
										if(shiparray[i].leftrightbarrel==1)
										{
											lasers.OFFX = -14;
										}
									}
									else
									{
										lasers.OFFX = 7;
										lasers.OFFZ = 0;
										if(shiparray[i].leftrightbarrel==1)
										{
											lasers.OFFX = -7;
										}
									}
									updatevectors_lasers(i);
									lasers.createlaser(shiparray[i].x*shiparray[i].scale,shiparray[i].y*shiparray[i].scale,shiparray[i].z*shiparray[i].scale,vel.X * shiparray[i].scale * shiparray[i].maxvel * 5.0f,vel.Y * shiparray[i].scale * shiparray[i].maxvel * 5.0f,vel.Z * shiparray[i].scale * shiparray[i].maxvel * 5.0f,shiparray[i].race,damage);
									if(shiparray[Program.followi].shiptype>1 && Program.followichangetime<=0)
									{
										Program.followi = i;
										Program.followichangetime = 120;
									}
									shiparray[i].targetdelay = shiparray[i].targettime; //stay on target, stay on target!
									shiparray[i].firedelay/=2;
								}
								if(gdot > 0.2 && gdot < 0.7 && shiparray[i].hp>50)
								{
									//big ship can shoot sideways
									int q = random.Next(2,5);
									for(int j=0;j<q;j++)
									{
										float offx = shiparray[i].scale * 0.15f * (float)(random.Next()-0.5);
										float offy = shiparray[i].scale * 0.15f * (float)(random.Next()-0.5);
										float offz = shiparray[i].scale * 0.15f * (float)(random.Next()-0.5);
										offx*=10f;
										offy*=10f;
										offz*=10f;
										lasers.createlaser(shiparray[i].x*shiparray[i].scale,shiparray[i].y*shiparray[i].scale,shiparray[i].z*shiparray[i].scale,offx+tmp.X * shiparray[i].scale * shiparray[i].maxvel * 5.0f,offy+tmp.Y * shiparray[i].scale * shiparray[i].maxvel * 5.0f,offz+tmp.Z * shiparray[i].scale * shiparray[i].maxvel * 5.0f,shiparray[i].race,damage);
									}
								}
							}
							
							
							
						}
						//adjust our vx vy vz to point towards the target somewhat........
						float dist = shiparray[i].dx*shiparray[i].dx+shiparray[i].dy*shiparray[i].dy+shiparray[i].dz*shiparray[i].dz;
						if(dist<40*40)
						{
							if(shiparray[i].race==1)
							{
								shiparray[i].dx+=shiparray[i].dx*0.5f;
								shiparray[i].dy+=shiparray[i].dy*0.5f;
							}
							else
							{
								shiparray[i].dx-=shiparray[i].dx*0.5f;
								shiparray[i].dy-=shiparray[i].dy*0.5f;
							}
						}
						//test this and then see if we can do the avoiding targets thing for avoiding collisions and passing through each other...
					}
					if(shiparray[i].x<-500 || shiparray[i].x>500 || shiparray[i].y<-500 || shiparray[i].y>500 || shiparray[i].z < -500 || shiparray[i].z>500)
					{
						shiparray[i].dx = - shiparray[i].x;
						shiparray[i].dy = - shiparray[i].y;
						shiparray[i].dz = - shiparray[i].z;
						shiparray[i].targetid = -3;
						shiparray[i].targetdelay = shiparray[i].targettime;
					}
					Vector3 a1 = new Vector3(0,0,0);
					for(int j=0;j<maxships;j++)
					{
						if(i!=j && shiparray[j].hp>0)
						{
							float dxx = shiparray[i].x - shiparray[j].x;
							float dyy = shiparray[i].y - shiparray[j].y;
							float dzz = shiparray[i].z - shiparray[j].z;
							Vector3 tmp2 = new Vector3(dxx,dyy,dzz);
							float tmp2length = Raymath.Vector3Length(tmp2);
							if(tmp2length<350)
							{
								a1 = new Vector3(dxx,dyy,dzz);
								a1 = Raymath.Vector3Normalize(a1);
								if(shiparray[i].shiptype==1)
								{
									a1 = Raymath.Vector3Scale(a1,100);
								}
								else
								{
									a1 = Raymath.Vector3Scale(a1,250);
								}
								break;
							}
							if(tmp2length<50.0 + shiparray[i].basehp*0.125f + shiparray[j].basehp*0.125f)
							{
								//collision!.......
								shiparray[i].hp-=shiparray[j].basehp/3.0f;
								shiparray[j].hp-=shiparray[i].basehp/3.0f;
								//explosion.createexplosion(ship.shiparray[j].x,ship.shiparray[j].y,ship.shiparray[j].z,ship.shiparray[j].scale,2f);
								//explosion.createexplosion(ship.shiparray[i].x,ship.shiparray[i].y,ship.shiparray[i].z,ship.shiparray[j].scale,2f);
								ship.ship_explosion(i,2f);
								ship.ship_explosion(j,2f);
							}
						}
					}
					Vector3 adjustspeed = new Vector3(shiparray[i].dx,shiparray[i].dy,shiparray[i].dz);
					adjustspeed = Raymath.Vector3Add(a1,adjustspeed);
					adjustspeed = Raymath.Vector3Normalize(adjustspeed);
					shiparray[i].vx += adjustspeed.X * shiparray[i].maxaccel;
					shiparray[i].vy += adjustspeed.Y * shiparray[i].maxaccel;
					shiparray[i].vz += adjustspeed.Z * shiparray[i].maxaccel;
					Vector3 speed = new Vector3(shiparray[i].vx,shiparray[i].vy,shiparray[i].vz);
					speed = Raymath.Vector3Normalize(speed);
					shiparray[i].vx = speed.X * shiparray[i].maxvel;
					shiparray[i].vy = speed.Y * shiparray[i].maxvel;
					shiparray[i].vz = speed.Z * shiparray[i].maxvel;
					//delta = 0; //delta = 0
					shiparray[i].x+=shiparray[i].vx*delta;
					shiparray[i].y+=shiparray[i].vy*delta;
					shiparray[i].z+=shiparray[i].vz*delta;
					//delta = 1;
					shiparray[i].updatevectors();
				}
			}
		}
		
		public static void ship_explosion(int i,float size)
		{
			if(ship.random.Next(0,100)<55)
			{
				return; //don't draw a tonne of explosions with the ships...there were too many before....
			}
			size*=0.65f;
			int a = ship.random.Next(0,19);
			Vector3 xaxis = new Vector3(0,0,0);
			Vector3 yaxis = new Vector3(0,0,0);
			Vector3 zaxis = new Vector3(0,0,0);
			Vector3 vertex = new Vector3(0,0,0);
			Vector3 pos = new Vector3(shiparray[i].x,shiparray[i].y,shiparray[i].z);
			zaxis.X = shiparray[i].vx;
			zaxis.Y = shiparray[i].vy;
			zaxis.Z = shiparray[i].vz;
			zaxis = Raymath.Vector3Normalize(zaxis);
			//zaxis = forwards
			//yaxis = up vector
			//xaxis = right vector
			if(shiparray[i].vz!=0)
			{
				yaxis.X = shiparray[i].vy;
				yaxis.Y = -shiparray[i].vx;
				yaxis.Z = 0;
			}
			else
			{
				yaxis.X = 0;
				yaxis.Y = 0;
				yaxis.Z = 1;
				
			}
			yaxis = Raymath.Vector3Normalize(yaxis);
			xaxis = Raymath.Vector3CrossProduct(yaxis,zaxis);
			xaxis = Raymath.Vector3Normalize(xaxis);
			Matrix4x4 rotationmatrix = new Matrix4x4(xaxis.X,yaxis.X,zaxis.X,0,xaxis.Y,yaxis.Y,zaxis.Y,0,xaxis.Z,yaxis.Z,zaxis.Z,0,0,0,0,1);
			//for(int v=a;v<shiparray[i].vertices.Vertices.Length;v+=20) //loop through them, creating debris explosions for every 20th vertex....positioned in world space properly.
			int v = ship.random.Next(0,shiparray[i].vertices.Vertices.Length);
			//{
				vertex = shiparray[i].vertices.Vertices[v];
				vertex = Raymath.Vector3Add(pos,Raymath.Vector3Transform(new Vector3((vertex.X)*shiparray[i].scale,(vertex.Y)*shiparray[i].scale,(vertex.Z)*shiparray[i].scale),rotationmatrix));
				//create explosion at vertex position	
				explosion.createexplosion(vertex.X,vertex.Y,vertex.Z,shiparray[i].scale,size);
			//}				
		}
		
		public static void updatevectors_lasers(int i)
		{
			if(lasers.OFFX==0)
			{
				return;
			}
			Vector3 xaxis = new Vector3(0,0,0);
			Vector3 yaxis = new Vector3(0,0,0);
			Vector3 zaxis = new Vector3(0,0,0);
			zaxis.X = shiparray[i].vx;
			zaxis.Y = shiparray[i].vy;
			zaxis.Z = shiparray[i].vz;
			zaxis = Raymath.Vector3Normalize(zaxis);
			//zaxis = forwards
			//yaxis = up vector
			//xaxis = right vector
			if(shiparray[i].vz!=0)
			{
				yaxis.X = shiparray[i].vy;
				yaxis.Y = -shiparray[i].vx;
				yaxis.Z = 0;
			}
			else
			{
				yaxis.X = 0;
				yaxis.Y = 0;
				yaxis.Z = 1;
				
			}
			yaxis = Raymath.Vector3Normalize(yaxis);
			xaxis = Raymath.Vector3CrossProduct(yaxis,zaxis);
			xaxis = Raymath.Vector3Normalize(xaxis);
			Matrix4x4 rotationmatrix = new Matrix4x4(xaxis.X,yaxis.X,zaxis.X,0,xaxis.Y,yaxis.Y,zaxis.Y,0,xaxis.Z,yaxis.Z,zaxis.Z,0,0,0,0,1);
			Vector3	laserpos = Raymath.Vector3Transform(new Vector3((lasers.OFFX)*shiparray[i].scale,(lasers.STARTY)*shiparray[i].scale,(lasers.OFFZ)*shiparray[i].scale),rotationmatrix);
			lasers.OFFX = laserpos.X;
			lasers.STARTY = laserpos.Y;
			lasers.OFFZ = laserpos.Z;
			
		}
		
		public void updatevectors()
		{
			
			pos.X = 0;//x;
			pos.Y = 0;//y;
			pos.Z = 0;//z;
			zaxis.X = vx;
			zaxis.Y = vy;
			zaxis.Z = vz;
			zaxis = Raymath.Vector3Normalize(zaxis);
			//zaxis = forwards
			//yaxis = up vector
			//xaxis = right vector
			if(vz!=0)
			{
				yaxis.X = vy;
				yaxis.Y = -vx;
				yaxis.Z = 0;
			}
			else
			{
				yaxis.X = 0;
				yaxis.Y = 0;
				yaxis.Z = 1;
				
			}
			yaxis = Raymath.Vector3Normalize(yaxis);
			xaxis = Raymath.Vector3CrossProduct(yaxis,zaxis);
			xaxis = Raymath.Vector3Normalize(xaxis);
			rotationmatrix = new Matrix4x4(xaxis.X,yaxis.X,zaxis.X,0,xaxis.Y,yaxis.Y,zaxis.Y,0,xaxis.Z,yaxis.Z,zaxis.Z,0,0,0,0,1);
		}
		
		public static void initships()
		{
			if(random==null)
			{
				random = new Random();
			}
			int dshiptype = 0;
			int race = 0;
			for(int i=0;i<maxships;i++)
			{
				GameUI.Loading("Please Wait....Loading.....SPACE SHIPS",10,Program.resy - 56,GameUI.largefont,Color.LightGray,2);
				race++;
				if(race>2)
				{
					race=1;
				}
				dshiptype++;
				if(i<maxships/2)
				{
					dshiptype%=3;
				}
				else
				{
					dshiptype%=6;
				}
				dshiptype++;
				int shiptype = 1;
				switch(dshiptype)
				{
						case 1:
							//yep a cruiser
							shiptype = 1;
						break;
						case 2:
							//a fighter
							shiptype = 2;
						break;
						case 3:
							//a bomber
							shiptype = 3;
						break;
						case 4:
							//a bomber
							shiptype = 3;
						break;
						case 5:
							//fighter
							shiptype = 2;
						break;
						case 6:
							//fighter
							shiptype = 2;
						break;
						case 7:
//							//fighter
							shiptype = 2;
						break;
				}
				shiparray[i] = new ship(shiptype,race,i);
				shiparray[i].firedelay = (float)i * 20.0f;
				shiparray[i].targetdelay = (float)i * 20.0f;
				shiparray[i].vx = 0f;
				shiparray[i].vy = 00f;
				shiparray[i].vz = 0.001f;
				shiparray[i].targetid = -1;
				shiparray[i].x = ((float)(random.NextDouble()*100) - 50f)*20f;
				shiparray[i].y = ((float)(random.NextDouble()*100) - 50f)*20f;
				shiparray[i].maxaccel*=0.3f*0.5f;
				if(shiparray[i].shiptype==1)
				{
					shiparray[i].maxaccel*=0.125f;
				}
				if(shiparray[i].shiptype==3)
				{
					shiparray[i].maxaccel*=0.65f;
				}
				shiparray[i].maxvel*=3f*0.5f;
				if(shiparray[i].shiptype==1)
				{
					shiparray[i].maxvel*=0.25f;
				}
				if(shiparray[i].shiptype==3)
				{
					shiparray[i].maxvel*=0.75f;
				}
				shiparray[i].maxvel*=0.5f;
				shiparray[i].maxaccel*=0.2f;
				shiparray[i].firetime*=1.5f;
				if(shiparray[i].hp<=0)
				{
					shiparray[i].hp = 20;
				}
				shiparray[i].basehp = shiparray[i].hp;
			}
		
			for(int i=0;i<maxships;i++)
			{
				if(shiparray[i].race==1)
				{
					shiparray[i].z = -3000 + shiparray[i].shiptype * 300;
				}
				else
				{
					shiparray[i].z = 3000 - shiparray[i].shiptype * 300;
				}
				if(shiparray[i].shiptype>1)
				{
					shiparray[i].firetime*=2.5f;
				}
			}
			int oi = 0;
			for(int ss=1;ss<=3;ss++)
			{
				for(int rr=1;rr<=2;rr++)
				{
					for(int i=0;i<maxships;i++)
					{
						if(shiparray[i].race==rr && shiparray[i].shiptype==ss)
						{
							orderarray[oi] = i;
							oi++;
						}
					}
				}
			}
		}
		
		public ship(int shiptype, int race,int id)
		{
			if(shiptype<1)
			{
				shiptype = 1;
			}
			if(shiptype>3)
			{
				shiptype = 3;
			}
			if(race<1)
			{
				race = 1;
			}
			if(race>2)
			{
				race = 2;
			}
			int stype = shiptype + (race - 1) * 3;
			if(stype<1)
			{
				stype = 1;
			}
			if(stype>6)
			{
				stype = 6;
			}
			scale = 1;//0.1f;
			xaxis = new Vector3(1,0,0);
			yaxis = new Vector3(0,1,0);
			zaxis = new Vector3(0,0,-1);
			shader = Raylib.LoadShader("media/shaders/basicvertexshader.vs", "media/shaders/spaceshippixelshader.fs"); //I know we probably shouldn't do it like this
			UnloadHelper.AddShader(shader);
			this.shiptype = shiptype;
			this.race = race;
			pos = new Vector3(0,0,150);
			vscale = new Vector3(1,1,1);
			string modelname = "";
			
			switch (shiptype)
			{
				case 1: //cruiser stuff
					hp = 300;
					armour = 4;
					maxvel = 1.75f;
					maxaccel = 0.7f;
					firetime = 12;
					targettime = 450;
					
					scale = 0.65f;
					if(race==2)
					{
						scale = 0.95f;
					}
				break;
				case 2: //fighter stuff
					hp = 20;
					armour = 2;
					maxvel = 3.75f;
					maxaccel = 1.2f;
					firetime = 10;
					targettime = 150;
					scale = 0.5f;
				break;
				case 3: //bomber stuff
					hp = 45;
					armour = 3;
					maxvel = 3.25f;
					maxaccel = 1.0f;
					firetime = 15;
					targettime = 400;
					scale = 0.5f;
				break;
				
			}
			scale*=0.1f;
			switch (stype)
			{
				case 1: //earth cruiser
					modelname = "ecruiser";
				break;
				case 2: //earth fighter
					modelname = "efighter";
				break;
				case 3: //earth bomber
					modelname = "ebomber";
				
				break;
				case 4: //alien cruiser
					modelname = "acruiser";
				break;
				case 5: //alien fighter
					modelname = "afighter";
					
				break;
				case 6: //alien bomber
					modelname = "abomber";
				break;
			}
			if(race==1)
			{
				vz = 1f;
				z = -1300f;
				
			}
			else
			{
				vz = -1f;
				z = 1300f;
			}
			//we don't want to have to load these more than once for each ship type
			int found = 0;
			for(int i=0;i<maxships;i++)
			{
				if(i<id)
				{
					if(shiparray[i]!=null)
					{
						if(shiparray[i].race==race && shiparray[i].shiptype==shiptype && shiparray[i].shadertex0!=0)
						{
							found = 1;
							diffuse = shiparray[i].diffuse;
							//specular = shiparray[i].specular;
							model = shiparray[i].model;
							vertices = shiparray[i].vertices;
							lod = shiparray[i].lod;
							shader = shiparray[i].shader;
							//noisetex = shiparray[i].noisetex;
						}
					}
				}
			}
			if(found==0)
			{
				model = Raylib.LoadModel("media/ships/"+modelname+"/"+modelname+".obj");			
				UnloadHelper.AddModel(model);
				vertices = new UnitVertices("media/ships/"+modelname+"/"+modelname+".obj",0,0);
				lod = Raylib.LoadModel("media/ships/"+modelname+"/"+modelname+"0.obj");			
				UnloadHelper.AddModel(lod);
				//diffuse = Raylib.LoadTexture("media/ships/"+modelname+texbasename+"color.png");
				diffuse = Raylib.LoadTexture("media/ships/"+modelname+"/texturemap.png");
				UnloadHelper.AddTexture(diffuse);
				//specular = Raylib.LoadTexture("media/ships/"+modelname+texbasename+"specular.png");
				//UnloadHelper.AddTexture(specular);
				//noisetex = Raylib.LoadTexture("media/fx/grime.png");
				//UnloadHelper.AddTexture(noisetex);
			}
			shadertex0 = Raylib.GetShaderLocation(shader,"texture0");
			//shadertex1 = Raylib.GetShaderLocation(shader,"texture1");
			//shadertex2 = Raylib.GetShaderLocation(shader,"texture2");
			ambientocclusion = Raylib.GetShaderLocation(shader,"ambientocclusion");
			colormultiplier = Raylib.GetShaderLocation(shader,"colormultiplier");
			modelMatrix = Raylib.GetShaderLocation(shader,"modelMatrix");
			projectionMatrix = Raylib.GetShaderLocation(shader,"projectionMatrix");
			viewMatrix = Raylib.GetShaderLocation(shader,"viewMatrix");
			eyepos = Raylib.GetShaderLocation(shader,"eyepos");
			Raylib.SetShaderValueTexture(shader,shadertex0,diffuse);
			//Raylib.SetShaderValueTexture(shader,shadertex1,diffuse);
			//Raylib.SetShaderValueTexture(shader,shadertex2,noisetex);
			unsafe
			{
				model.Materials[0].Shader = shader;
				Raylib.SetMaterialTexture(&model.Materials[0], MaterialMapIndex.Albedo, diffuse);
				//Raylib.SetMaterialTexture(&model.Materials[0], MaterialMapIndex.Specular, specular);
				//Raylib.SetMaterialTexture(&model.Materials[0], MaterialMapIndex.Normal, noisetex);
				lod.Materials[0].Shader = shader;
				Raylib.SetMaterialTexture(&lod.Materials[0], MaterialMapIndex.Albedo, diffuse);
				//Raylib.SetMaterialTexture(&lod.Materials[0], MaterialMapIndex.Specular, specular);
				//Raylib.SetMaterialTexture(&lod.Materials[0], MaterialMapIndex.Normal, noisetex);
			}
			scale = 0.1f;// 
		}

		
	}

