				if(vertices.Vertices!=null)
				{
					float count = 0;
					float minx = 10000;
					float maxx = -10000;
					float minz = 10000;
					float maxz = -10000;
					for(int k=0;k<vertices.Vertices.Length;k++)
					{
						count++;
						if(vertices.Vertices[k].X>maxx)
						{
							maxx = vertices.Vertices[k].X;
						}
						if(vertices.Vertices[k].Z>maxz)
						{
							maxz = vertices.Vertices[k].Z;
						}
						if(vertices.Vertices[k].X<minx)
						{
							minx = vertices.Vertices[k].X;
						}
						if(vertices.Vertices[k].Z<minz)
						{
							minz = vertices.Vertices[k].Z;
						}
						
					}
					if(count>0)
					{
						offx = 0.5f*(minx+maxx);
						offz = 0.5f*(minz+maxz);
					}
				}
			}
			UnloadHelper.AddModel(model);
