					Raylib.SetShaderValueV(shader,debuglighting,&debugl,ShaderUniformDataType.Int,1);				
				}
			
				UnloadHelper.AddShader(shader);
				shadertex0 = Raylib.GetShaderLocation(shader,"texture0");
				shadertex1 = Raylib.GetShaderLocation(shader,"texture1");
				shadertex2 = Raylib.GetShaderLocation(shader,"texture2");
				modelMatrix = Raylib.GetShaderLocation(shader,"modelMatrix");
				projectionMatrix = Raylib.GetShaderLocation(shader,"projectionMatrix");
				viewMatrix = Raylib.GetShaderLocation(shader,"viewMatrix");
				eyepos = Raylib.GetShaderLocation(shader,"eyepos");
				shadow = Raylib.GetShaderLocation(shader,"shadow");
				ambientocclusion = Raylib.GetShaderLocation(shader,"ambientocclusion");
				groundfog = Raylib.GetShaderLocation(shader,"groundfog");
				envmapping = Raylib.GetShaderLocation(shader,"debugenvmapping");
				healy = Raylib.GetShaderLocation(shader,"healy");//6aug2025
				muzzle = Raylib.GetShaderLocation(shader,"muzzle");
				fogr = Raylib.GetShaderLocation(shader,"fogr");
				fogg = Raylib.GetShaderLocation(shader,"fogg");
				fogb = Raylib.GetShaderLocation(shader,"fogb");
				foga = Raylib.GetShaderLocation(shader,"foga");
				unsafe
				{
					model.Materials[0].Shader = shader;
					Raylib.SetMaterialTexture(&model.Materials[0], MaterialMapIndex.Albedo, diffuse);
					Raylib.SetMaterialTexture(&model.Materials[0], MaterialMapIndex.Metalness, specular);
					Raylib.SetMaterialTexture(&model.Materials[0], MaterialMapIndex.Normal, noisetex);
					lod.Materials[0].Shader = shader;
					Raylib.SetMaterialTexture(&lod.Materials[0], MaterialMapIndex.Albedo, diffuse);
					Raylib.SetMaterialTexture(&lod.Materials[0], MaterialMapIndex.Metalness, specular);
					Raylib.SetMaterialTexture(&lod.Materials[0], MaterialMapIndex.Normal, noisetex);
				}
				Raylib.SetShaderValueTexture(shader,shadertex0,diffuse);
				Raylib.SetShaderValueTexture(shader,shadertex1,specular);
				Raylib.SetShaderValueTexture(shader,shadertex2,noisetex);
			}
			y = 0;
			x = 110f * (((i - 1) % 3) - 1);
			z = 110f * (((i - 1) - ((i - 1) % 3))/3) - 130;
		}

		public static int IsInside(float x,float z)
		{
			int ix = (int)(x) + 500;
			int iz = (int)(z) + 500;
			if(ix>=0 && iz>=0 && ix<1000 && iz<1000)
			{
				return inside[ix + 1000*iz];
			}
			return 0;
		}
		
		public static void SetInside(int i,float x, float z)
		{
			int ix = (int)(x) + 500;
			int iz = (int)(z) + 500;
			if(ix>=0 && iz>=0 && ix<1000 && iz<1000)
			{
			
				inside[ix + 1000 * iz]=i;
				UnitVertices tmp = Building.buildingarray[i].vertices;
				float msc = 7.5f*0.85f;
				Vector3 pos = new Vector3(Building.buildingarray[i].x,Building.buildingarray[i].y,Building.buildingarray[i].z);
				if(tmp!=null)
				{
					if(tmp.Vertices!=null)
					{
						for(int v=0;v<tmp.Vertices.Length;v++)
						{
							Vector3 vertex = tmp.Vertices[v];
							vertex = Raymath.Vector3RotateByAxisAngle(vertex, new Vector3(0,1,0), 0);
							vertex = Raymath.Vector3Scale(vertex,msc);
							vertex = Raymath.Vector3Add(vertex,pos);
							int jx = (int)(vertex.X) + 500;
							int jz = (int)(vertex.Z) + 500;
							if(jx>=0 && jz>=0 && jx<1000 && jz<1000)
							{
								inside[jx + 1000 * jz] = i;
							}
						}
					}					
				}	
			}
		}
		
