		public static int QtyCategoryAlive(int c) //added at library
		{
			int qty = 0;
			for(int i=0;i<maxbuildings;i++)
			{
				if(buildingarray[i].hp>0 && buildingarray[i].category==c)
				{
					qty++;
				}
			}
