		public static int IsCategoryAlive(int c)
		{
			for(int i=0;i<maxbuildings;i++)
			{
				if(buildingarray[i].hp>0 && buildingarray[i].category==c)
				{
					return 1;
				}
			}
			return 0;
		}
		
		public static int IsCategoryAlive(int c,int s)
		{
			for(int i=0;i<maxbuildings;i++)
			{
				if(buildingarray[i].hp>0 && buildingarray[i].category==c && buildingarray[i].selected==s)
				{
					return 1;
				}
			}
			return 0;
		}
		
		public static void updatebuildings()
		{
			changed = 0;
			frame++;
			categoryselected = 0;
			for(int i=0;i<maxbuildings;i++)
			{
				if(buildingarray[i].hp>0)
				{
					if(buildingarray[i].healingbary>=0)//6aug2025
					{
						buildingarray[i].healingbary+=ship.delta*(15f/60f);
						if(buildingarray[i].healingbary>50)
						{
							buildingarray[i].healingbary = -1;
						}
					}
					
					if(buildingarray[i].selected!=0)
					{
						categoryselected = buildingarray[i].category;
					}
					buildingarray[i].ohp  = buildingarray[i].hp;
					if(buildingarray[i].strucktime>0)
					{
						buildingarray[i].strucktime-=ship.delta;
					}
					if(buildingarray[i].category==Building.RADAR)
					{
						float oradardamage = GameUI.radardamage;
						GameUI.radardamage = 1.0f - buildingarray[i].hp / buildingarray[i].basehp;//added at library
						int oradar = (int)(oradardamage*10f);
						int nradar = (int)(GameUI.radardamage*10f);
						if(oradar!=nradar && nradar<oradar)
						{
							Audio.PlayUnitSound(Audio.INF,Audio.LOSINGRADAR);
						}
					}
				}
				else
				{
					if(Building.buildingarray[i].ohp>0)
					{
						changed = 1;
						Scoring.addtoscore(Scoring.BUILDINGDIE);
						Building.buildingarray[i].ohp = 0;
						debris.DebrisExplosion(-1,i);
						debris.DebrisExplosion(-1,i); //do two for extra effect.....
						Program.camerashake = Program.maxcamshake;
						int c = buildingarray[i].category;
						if(c==Building.AIRTRAFFICCONTROL)
						{
							Audio.PlayUnitSound(Audio.INF,Audio.LOSTAIR);
						}
						if(c==Building.ENGINEERING || c==Building.HEAVYVEHICLES || c==Building.SPACECOMMS)
						{
							Audio.PlayUnitSound(Audio.INF,Audio.LOSTFACTORY);
						}
						if(c==Building.BARRACKS)
						{
							Audio.PlayUnitSound(Audio.INF,Audio.LOSTBARRACKS);
						}
						if(c==Building.POWERGENERATOR)
						{
							Audio.PlayUnitSound(Audio.INF,Audio.LOSTPOWER);
						}
					}
					if(buildingarray[i].category==Building.RADAR)
					{
						GameUI.radardamage = 1;//added at library
					}
				}
			}
			if(GameUI.radardamage<0) //added at library
			{
				GameUI.radardamage = 0;
			}
			if(GameUI.radardamage>1)
			{
				GameUI.radardamage = 1;
			}
		}
		
		public static void initbuildings()
		{
			PrepareCircle();
			buildingarray = new Building[maxbuildings];
			for(int i=0;i<maxbuildings;i++)
			{
				buildingarray[i] = new Building(i);
				SetInside(i,buildingarray[i].x,buildingarray[i].z);
				GameUI.Loading("Please Wait....Loading.....FX",10,Program.resy - 56,GameUI.largefont,Color.LightGray,5);
			}
		}
		
	}
	
	class Obstacle
	{
		public static int useshader = 1;
		public static int maxobstacles = 500;
		public static Obstacle[] obstaclearray = new Obstacle[maxobstacles];
		public static int[] orderarray = new int[maxobstacles];
		public static int any = 0;
		public int drawn;
		public float distfromedge;
		public Model model;
		public Texture2D diffuse;
		public Texture2D specular;
		public Shader shader;
		public static float scale = 1f;
		public float angle;
		public int razorwire;
		public int tanktrap;
		public int inview;
		public float x;
		public float y;
		public float z;
		public int sectorx;
		public int sectorz;
		public Vector3 position;
		public Matrix4x4 transform;
		public int transformset;
		public string objfile;
		public string texfile;
		public string specfile;
		public int shadertex0;
		public int envmapping;
		public int healy;
		public int muzzle;
		public int ambientocclusion;
		public int shadertex1;
		public int modelMatrix;
		public int projectionMatrix;
		public int viewMatrix;
		public int eyepos;
		public int shadow;
		public int groundfog;
		public int foga;
		public int fogr;
		public int fogg;
		public int fogb;
		public int hp;
		public int basehp;
		
		public static void createobstacle(float x,float y, float z,int otype)
		{
			any = 1;
			for(int i=0;i<maxobstacles;i++)
			{
				if((obstaclearray[i].hp<=0 || obstaclearray[i].y<=0) && ((obstaclearray[i].razorwire==1 && otype%2==1) || obstaclearray[i].tanktrap==1 && otype%2==0))
				{
					obstaclearray[i].transformset = 0;
					obstaclearray[i].x = x;
					obstaclearray[i].y = 0.01f;
					obstaclearray[i].z = z;
					obstaclearray[i].sectorx = Program.GetSectorX(x,z);
					obstaclearray[i].sectorz = Program.GetSectorZ(x,z);
					obstaclearray[i].position = new Vector3(x,0,z);
					obstaclearray[i].inview = 1;
					obstaclearray[i].angle = (float)ship.random.NextDouble()*3.14159f*4f;
					obstaclearray[i].hp = obstaclearray[i].basehp;
					break;
				}
			}
		}
		
		public Obstacle(int i,int obstype)
		{
			hp = 0;
			basehp = 150;
			tanktrap = 1;
			if(obstype==1)
			{
				razorwire=1;
				tanktrap = 0;
				basehp = 10;
			}
			int found = 0;
			for(int ii=0;ii<i;ii++)
			{
				if(obstaclearray[ii].tanktrap==tanktrap && obstaclearray[ii].razorwire==razorwire)
				{
					if(ii<i)
					{
						found=1;
						
					}
				}
				if(found==1)
				{
					diffuse = obstaclearray[ii].diffuse;
					specular = obstaclearray[ii].specular;
					model = obstaclearray[ii].model;
					shader = obstaclearray[ii].shader;
					texfile = obstaclearray[ii].texfile;
					specfile = obstaclearray[ii].specfile;
					objfile = obstaclearray[ii].objfile;
					break;
				}
			}
			if(found==0)
			{
				if(razorwire==1)
				{
					diffuse =  Program.atlas_diffuse;//Raylib.LoadTexture("media/obstacles/razorwire.png");
					//UnloadHelper.AddTexture(diffuse);
					specular = Program.atlas_specular;//Raylib.LoadTexture("media/obstacles/razorwire_spec.png");
					//UnloadHelper.AddTexture(specular);
					model = Raylib.LoadModel("media/obstacles/_razorwire.obj");
					UnloadHelper.AddModel(model);
					shader = Raylib.LoadShader("media/shaders/basicvertexshaderwithextras.vs","media/shaders/diffusespecularpixelshader_withambientoption_a.fs");
					int debuglighting = Raylib.GetShaderLocation(shader,"debuglighting");
					int debugl = Program.debuglighting;
					unsafe
					{
						Raylib.SetShaderValueV(shader,debuglighting,&debugl,ShaderUniformDataType.Int,1);				
					}
			
					UnloadHelper.AddShader(shader);
					objfile = "media/obstacles/razorwire.obj";
					texfile = "media/obstacles/razorwire.png";
					specfile = "media/obstacles/razorwire_spec.png";
				}
				else
				{
					diffuse =  Raylib.LoadTexture("media/obstacles/tanktrap.png");
					UnloadHelper.AddTexture(diffuse);
					specular = Raylib.LoadTexture("media/obstacles/tanktrap_spec.png");
					UnloadHelper.AddTexture(diffuse);
					model = Raylib.LoadModel("media/obstacles/_tanktrap.obj");
					UnloadHelper.AddModel(model);
					shader = Raylib.LoadShader("media/shaders/basicvertexshaderwithextras.vs","media/shaders/diffusespecularpixelshader_withambientoption_a.fs");
					int debuglighting = Raylib.GetShaderLocation(shader,"debuglighting");
					int debugl = Program.debuglighting;
					unsafe
					{
						Raylib.SetShaderValueV(shader,debuglighting,&debugl,ShaderUniformDataType.Int,1);				
					}
			
					UnloadHelper.AddShader(shader);
					objfile = "media/obstacles/tanktrap.obj";
					texfile = "media/obstacles/tanktrap.png";
					specfile = "media/obstacles/tanktrap_spec.png";
				}
			}
			shadertex0 = Raylib.GetShaderLocation(shader,"texture0");
			shadertex1 = Raylib.GetShaderLocation(shader,"texture1");
			modelMatrix = Raylib.GetShaderLocation(shader,"modelMatrix");
			projectionMatrix = Raylib.GetShaderLocation(shader,"projectionMatrix");
			viewMatrix = Raylib.GetShaderLocation(shader,"viewMatrix");
			eyepos = Raylib.GetShaderLocation(shader,"eyepos");
			shadow = Raylib.GetShaderLocation(shader,"shadow");
			ambientocclusion = Raylib.GetShaderLocation(shader,"ambientocclusion");
			groundfog = Raylib.GetShaderLocation(shader,"groundfog");
			envmapping = Raylib.GetShaderLocation(shader,"debugenvmapping");
			healy = Raylib.GetShaderLocation(shader,"healy");
			muzzle = Raylib.GetShaderLocation(shader,"muzzle");
			fogr = Raylib.GetShaderLocation(shader,"fogr");
			fogg = Raylib.GetShaderLocation(shader,"fogg");
			fogb = Raylib.GetShaderLocation(shader,"fogb");
			foga = Raylib.GetShaderLocation(shader,"foga");
			unsafe
			{
				model.Materials[0].Shader = shader;
			}
			Raylib.SetShaderValueTexture(shader,shadertex0,diffuse);
			Raylib.SetShaderValueTexture(shader,shadertex1,specular);
		}
		
		
		public static void initobstacles()
		{
			obstaclearray = new Obstacle[maxobstacles];
			for(int i=0;i<maxobstacles;i++)
			{
				obstaclearray[i] = new Obstacle(i,i % 2);
				if(i%25==0)
				{
					GameUI.Loading("Please Wait....Loading.....GROUND UNITS",10,Program.resy - 56,GameUI.largefont,Color.LightGray,2);
				}
			}
			int uu = 0;
			for(int a=0;a<2;a++)
			{
				for(int i=0;i<maxobstacles;i++)
				{
					if(i%2==a)
					{
						orderarray[uu] = i;
						uu++;
					}
				}
			}
		}
		
	}
	
