								}
						
							}
							else
							{
								shader = Raylib.LoadShader("media/shaders/basicvertexshadersnowingwithcolorvariance.vs","media/shaders/diffusepixelshader_withambient_withshadow.fs");
							}
							UnloadHelper.AddShader(shader);
