							lod_2.Materials[0].Shader = shader;
							Raylib.SetMaterialTexture(&lod_2.Materials[0], MaterialMapIndex.Albedo, diffuse);
							Raylib.SetMaterialTexture(&lod_2.Materials[0], MaterialMapIndex.Metalness, snow);
						}
