							Raylib.SetMaterialTexture(&lod3.Materials[0], MaterialMapIndex.Albedo, diffuse);
							Raylib.SetMaterialTexture(&lod3.Materials[0], MaterialMapIndex.Metalness, snow);
							lod_3.Materials[0].Shader = shader;
							Raylib.SetMaterialTexture(&lod_3.Materials[0], MaterialMapIndex.Albedo, diffuse);
							Raylib.SetMaterialTexture(&lod_3.Materials[0], MaterialMapIndex.Metalness, snow);
						}
				
