			}
		}
		
		public static int istree(float x,float z)
		{
			int ix = (int)(x) + 500;
			int iz = (int)(z) + 500;
			if(ix>=0 && iz>=0 && ix<1000 && iz<1000)
			{
				if(cover[ix + 1000 * iz]==2)
				{
					return 1;
				}
			}
			return 0;
		}
		
		public static int IsInside(float x,float z)
		{
			int ix = (int)(x) + 500;
			int iz = (int)(z) + 500;
			if(ix>=0 && iz>=0 && ix<1000 && iz<1000)
			{
				return inside[ix + iz * 1000];
			}
			return -1;
		}
		
		public static int incover(float x,float z)
		{
			int ix = (int)(x) + 500;
			int iz = (int)(z) + 500;
			if(ix>=0 && iz>=0 && ix<1000 && iz<1000)
			{
				if(cover[ix + 1000 * iz]>0)
				{
					return 1;
				}
			}
			return 0;
		}
		
		public static void removetemporarycover(float x,float z,float radius)
		{
			int ix = (int)x + 500;
			int iz = (int)z + 500;
			for(int xx = ix - (int)radius;xx<=ix + (int)radius;xx++)
			{
				for(int zz = iz - (int)radius;zz<=iz+(int)radius;zz++)
				{
					if(xx>=0 && zz>=0 && xx<1000 && zz<1000)
					{
						//cover[xx + zz * 1000] = 1;
						if(cover[xx+zz*1000]==1 || cover[xx+zz*1000]==3)
						{
							cover[xx+zz*1000]=1;
						}
						else
						{
							cover[xx+zz*1000]=0;
						}
					}
				}
			}
		}
		
		public static void settemporarycover(float x,float z,float radius)
		{
			int ix = (int)x + 500;
			int iz = (int)z + 500;
			for(int xx = ix - (int)radius;xx<=ix + (int)radius;xx++)
			{
				for(int zz = iz - (int)radius;zz<=iz+(int)radius;zz++)
				{
					if(xx>=0 && zz>=0 && xx<1000 && zz<1000)
					{
						//cover[xx + zz * 1000] = 1;
						if(cover[xx+zz*1000]==1 || cover[xx+zz*1000]==3)
						{
							cover[xx+zz*1000]=3;
						}
						else
						{
							cover[xx+zz*1000]=2;
						}
					}
				}
			}
		}
		
		public static void setcover(float x, float z,float radius)
		{
			int ix = (int)x + 500;
			int iz = (int)z + 500;
			for(int xx = ix - (int)radius;xx<=ix + (int)radius;xx++)
			{
				for(int zz = iz - (int)radius;zz<=iz+(int)radius;zz++)
				{
					if(xx>=0 && zz>=0 && xx<1000 && zz<1000)
					{
						if(cover[xx+zz*1000]==0){cover[xx + zz * 1000] = 1;}
					}
				}
			}
		}
		
		public static void initgrasses()
		{
			Program.useatlas1 = 1; //just in case we've fucked up somehow and aren't using the atlas.
			if(Program.useatlas1!=0)
			{
				atlasdiffuse = Raylib.LoadTexture("media/atlas1/atlasfoliage.png");
				Raylib.SetTextureFilter(atlasdiffuse, TextureFilter.Bilinear);
				atlasdiffuse.Format = PixelFormat.UncompressedR8G8B8A8;
				UnloadHelper.AddTexture(atlasdiffuse);
				atlas = 1;
			}
			random = new Random();
			grassarray = new Grass[maxgrasses];
			///load bushes first
			bushdiffuse = Raylib.LoadTexture("media/atlas1/bushes1.png");
			Raylib.SetTextureFilter(bushdiffuse, TextureFilter.Bilinear);
			bushdiffuse.Format = PixelFormat.UncompressedR8G8B8A8;
			UnloadHelper.AddTexture(bushdiffuse);
			bush = Raylib.LoadModel("media/atlas1/bushes_a.obj");
			bushshader = Raylib.LoadShader("media/shaders/basicvertexshadersnowingwithcolorvariance.vs","media/shaders/diffusepixelshader_withambient_withshadow_withnoise.fs");
			int bdebuglighting = Raylib.GetShaderLocation(bushshader,"debuglighting");
			int bdebugl = Program.debuglighting;
			unsafe
			{
				Raylib.SetShaderValueV(bushshader,bdebuglighting,&bdebugl,ShaderUniformDataType.Int,1);				
			}
			
			UnloadHelper.AddShader(bushshader);
			//
			bshadertex0 = Raylib.GetShaderLocation(bushshader,"texture0");
			bmodelMatrix = Raylib.GetShaderLocation(bushshader,"modelMatrix");
			bprojectionMatrix = Raylib.GetShaderLocation(bushshader,"projectionMatrix");
			bviewMatrix = Raylib.GetShaderLocation(bushshader,"viewMatrix");
			bambientocclusion = Raylib.GetShaderLocation(bushshader,"ambientocclusion");
			beyepos = Raylib.GetShaderLocation(bushshader,"eyepos");
			bgroundfog = Raylib.GetShaderLocation(bushshader,"groundfog");
			benvmapping = Raylib.GetShaderLocation(bushshader,"debugenvmapping");
			bfogr = Raylib.GetShaderLocation(bushshader,"fogr");
			bfogg = Raylib.GetShaderLocation(bushshader,"fogg");
			bfogb = Raylib.GetShaderLocation(bushshader,"fogb");
			bfoga = Raylib.GetShaderLocation(bushshader,"foga");
			unsafe
			{
				bush.Materials[0].Shader = bushshader;
				Raylib.SetMaterialTexture(&bush.Materials[0], MaterialMapIndex.Albedo, bushdiffuse);
			}
			Raylib.SetShaderValueTexture(bushshader,bshadertex0,bushdiffuse);
			///
			for(int i=0;i<maxgrasses;i++)
			{
				int gtype = 0;
				if(i%50==0)
				{
					GameUI.Loading("Please Wait....Loading.....FX",10,Program.resy - 56,GameUI.largefont,Color.LightGray,10);
				}
				
				if(i<7)
				{
					gtype = i;
				}
				else
				{
					if(random.NextDouble()<0.05)
					{
						gtype = random.Next(1,3);
						if(gtype>2)
						{
							gtype = 1;
						}
						if(gtype<1)
						{
							gtype = 2;
						}
					}
					if(random.NextDouble()<0.075)
					{
						gtype = 3;
						if(random.NextDouble()<0.4 && i>10)
						{
							gtype = 6;
						}
					}
			//		if(random.NextDouble()<0.075)
			//		{
			//			gtype = 4;
			//		}
					if(gtype==0 && i>10)
					{
						if(random.NextDouble()<0.1)
						{
							gtype = 5;
						}
					}
				}
				if(i>=maxgrasses-crateroffset)
				{
						gtype = 4;
				}
				grassarray[i] = new Grass(i,gtype);
				grassarray[i].y = 0.01f;
				if(gtype==4)// && i>maxgrasses-crateroffset/2-crateroffset/6)
				{
					grassarray[i].y-=100; //hide it off map temporarily....
				}
				grassarray[i].x = (float)(random.NextDouble()*850.0-425.0);
				grassarray[i].z = (float)(random.NextDouble()*850.0-425.0);
				if(i>3000 && gtype!=4)
				{
					float radius = 475f + (float)ship.random.NextDouble()*200;
					float aangle = (float)ship.random.NextDouble()*314f;
					grassarray[i].x = (float)(radius * Math.Cos(aangle));
					grassarray[i].z = (float)(radius * Math.Sin(aangle));
				}
				Grass.grassarray[i].grassposition = new Vector3(Grass.grassarray[i].x,Grass.grassarray[i].y,Grass.grassarray[i].z);
				if(gtype==5)
				{
					if(Math.Abs(grassarray[i].x)<125 && Math.Abs(grassarray[i].z)<125)
					{
						for(int j = 0;j<10;j++)
						{
							if(Math.Abs(grassarray[i].x)<125)
							{
								grassarray[i].x = (float)(random.NextDouble()*850.0-425.0);
							}
							if(Math.Abs(grassarray[i].z)<125)
							{
								grassarray[i].z = (float)(random.NextDouble()*850.0-425.0);
							}
						}
					}
				}
				if(gtype==3 || gtype==6)
				{
					for(int j = 0;j<10;j++)
					{
						if(Math.Abs(grassarray[i].x)<115)
						{
							grassarray[i].x = (float)(random.NextDouble()*850.0-425.0);
						}
						if(Math.Abs(grassarray[i].z)<115)
						{
							grassarray[i].z = (float)(random.NextDouble()*850.0-425.0);
						}
					}
					int gx = (int)grassarray[i].x + 500;
					int gz = (int)grassarray[i].z + 500;
					if(gx>=0 && gz>=0 && gx<1000 && gz<1000)
					{
						//trees provide cover for a region about 5x5 in size...
						for(int ix=gx-20;ix<=gx+20;ix++)
						{
							for(int iz=gz-20;iz<=gz+20;iz++)
							{
								if(ix>=0 && iz>=0 && ix<1000 && iz<1000)
								{
									cover[ix + iz*1000] = 1;//soft cover from trees....
								}
							}
						}
					}
				}
				
			}
			int orderi = 0;
			for(int g=0;g<7;g++)
			{
				for(int i=0;i<maxgrasses-crateroffset;i++)
				{
					if(grassarray[i].gtype==g)
					{
						orderarray[orderi] = i;
						
						orderi++;
					}				
				}
				for(int i=maxgrasses-crateroffset;i<maxgrasses;i++)
				{
					orderarray[i] = i;
				}
			}
		}

		public static void ReInit()
		{
			
			for(int i=0;i<cover.Length;i++) //clear cover settings
			{
				cover[i] = 0;
				inside[i] = -1;
			}
			for(int i=0;i<maxgrasses;i++)
			{
				Grass.grassarray[i].distfromedge = 0;
				Grass.grassarray[i].transformset = 0;
				Grass.grassarray[i].grassposition = new Vector3(Grass.grassarray[i].x,Grass.grassarray[i].y,Grass.grassarray[i].z);
				Grass.grassarray[i].sectorx = Program.GetSectorX(Grass.grassarray[i].x,Grass.grassarray[i].z);
				Grass.grassarray[i].sectorz = Program.GetSectorZ(Grass.grassarray[i].x,Grass.grassarray[i].z);
				
				float sc = 3.75f + ((float)(i % 30)-30f)/15f ;//(-2,0)+ ;//((float)Math.Sin(i*11) - 1.0f);
				if(Grass.grassarray[i].gtype>0 && Grass.grassarray[i].gtype<3)
				{
					sc = 0.05f + (float)ship.random.NextDouble()*0.1f;
					Grass.grassarray[i].angle = (float)ship.random.NextDouble()*7f;
				}
				if(Grass.grassarray[i].gtype==3 || Grass.grassarray[i].gtype==6)
				{
					sc = (0.175f)+((float)(i % 30)-15f)*0.125f;// + (float)Math.Sin(i*11)*0.25f)*0.5f;
					if(sc<0.13)
					{
						sc=0.13f;
					}
					if(sc>0.19f)
					{
						sc=0.19f;
					}
				}
				if(Grass.grassarray[i].gtype==0 || Grass.grassarray[i].gtype==5)
				{
					sc*=0.45f;
				}
				if(Grass.grassarray[i].gtype==3 || Grass.grassarray[i].gtype==6)
				{
					sc*=1.75f;
					//place bushes
					for(int bb=0;bb<maxbush;bb++)
					{
						if(bushposx[bb]==0)
						{
							bushposx[bb] = Grass.grassarray[i].x;
							bushposz[bb] = Grass.grassarray[i].z;
							bushpos[bb] = new Vector3(bushposx[bb],0.01f,bushposz[bb]);
							if(bushposangle[bb]==0)
							{
								bushposangle[bb] = Grass.grassarray[i].x*123.0f + Grass.grassarray[i].z*321.0f;
								while(bushposangle[bb]>12)
								{
									bushposangle[bb]*=0.8f;
								}
								while(bushposangle[bb]<-12)
								{
									bushposangle[bb]*=0.8f;
								}
							}
							break;	
						}
					}
				}
				
				grassarray[i].sc = sc;
				if(grassarray[i].gtype==4) //reset craters
				{
					grassarray[i].y = -100;
				}
				if(grassarray[i].gtype==3 || grassarray[i].gtype==6) //redo cover setting
				{
					int gx = (int)grassarray[i].x + 500;
					int gz = (int)grassarray[i].z + 500;
					if(gx>=0 && gz>=0 && gx<1000 && gz<1000)
					{
						//trees provide cover for a region about 5x5 in size...
						inside[gx + gz * 1000] = i;
						for(int ix=gx-20;ix<=gx+20;ix++)
						{
							for(int iz=gz-20;iz<=gz+20;iz++)
							{
								if(ix>=0 && iz>=0 && ix<1000 && iz<1000)
								{
									if(ix==gx && iz==gz)
									{
										cover[ix + iz*1000] = 2;
									}
									if(cover[ix + iz*1000]==0){cover[ix + iz*1000] = 1;}//soft cover from trees....
								}
							}
						}
					}

				}
			}
			
			for(int i=0;i<10;i++)
			{
				createcrater((float)ship.random.Next(-300,300),(float)ship.random.Next(-300,300));
			}
			
		}
		
	}
	
	class UnitVertices
	{
		public Vector3[] Vertices;
		public int shiptype;
		public int race;
		public UnitVertices(string file,int s,int r)
		{
			Vertices = null; //do nothing for now...
			System.Globalization.NumberStyles style = System.Globalization.NumberStyles.AllowDecimalPoint | System.Globalization.NumberStyles.AllowLeadingSign; //22mar2021
			CultureInfo culture = CultureInfo.CreateSpecificCulture("en-US"); //22mar2021
			int countvertices = 0;
			shiptype = s;
			race = r;
			try
			{
				string[] cdata = System.IO.File.ReadAllLines(file);
				for(int i=0;i<cdata.Length;i++)
				{
					if(cdata[i].Length>3)
					{
						if(cdata[i].Substring(0,2) == "v ")
						{
							//vertex data
							countvertices++;
						}
					}
				}
				if(countvertices>0)
				{
					Vertices = new Vector3[countvertices];
					int index = 0;
					for(int i=0;i<cdata.Length;i++)
					{
						if(cdata[i].Length>3)
						{
							if(cdata[i].Substring(0,2) == "v ")
							{
								//vertex data
								string txt = cdata[i].Substring(2); 
								string[] vtxt = txt.Split(" ");
								if(vtxt!=null)
								{
									if(vtxt.Length==3)
									{
										float x = 0;
										float y = 0;
										float z = 0;
										Single.TryParse(vtxt[0],style,culture,out x);
										Single.TryParse(vtxt[1],style,culture,out y);
										Single.TryParse(vtxt[2],style,culture,out z);
										Vertices[index] = new Vector3(x,y,z);
										index++;
									}
								}
							}
						}
						if(index>=countvertices)
						{
							break;
						}
				}
					
				}
			}
			catch(Exception e)
			{
				Console.WriteLine("Error:"+e.Message);
			}
			
		}
	}
	
	class Unit // infantry
	{
		public static int[] unitmap = new int[300*300];
		
		public static void ResetUnitMap()
		{
			for(int i=0;i<unitmap.Length;i++)
			{
				unitmap[i] = -1;
			}
		}
		
		public static void ClearCell(float x, float z)
		{
			int ix = (int)((x+750f) / 12f);
			int iz = (int)((z+750f) / 12f);
			if(ix>=0 && iz>=0 && ix<300 && iz<300)
			{
				unitmap[ix + iz * 300] = -1;
			}
		}
		
		public static void SetCell(float x, float z,int i)
		{
			int ix = (int)((x+750f) / 12f);
			int iz = (int)((z+750f) / 12f);
			if(ix>=0 && iz>=0 && ix<300 && iz<300)
			{
				unitmap[ix + iz * 300] = i;
			}
		}
		
		public static int GetCell(float x,float z)
		{
			int ix = (int)((x+750f) / 12f);
			int iz = (int)((z+750f) / 12f);
			if(ix>=0 && iz>=0 && ix<300 && iz<300)
			{
				return unitmap[ix + iz * 300];
			}
			return -1;
		}
		
		public int drawn;
		public float distfromedge;
		public string[] objfile;
		public string texfile;
		public string specfile;
		public static Texture2D atlastexture;
