		public static int ValidAnim(int i,int animframe)
		{
			int shiptype = Unit.unitarray[i].shiptype;
			if(shiptype==1)
			{
				if(animframe>=2 && animframe<=29)
				{
					return 1;
				}
				if(animframe>=242 && animframe<=259)
				{
					return 1;
				}
				if(animframe>=380 && animframe<=395)
				{
					return 1;
				}
				if(animframe>=405 && animframe <=445)
				{
					return 1;
				}
				if(animframe>=465 && animframe<=520)
				{
					if(animframe%5!=0)
					{
						return 0;
					}
					return 1;
				}
				if(animframe>=685 && animframe<=725)
				{
					return 1;
				}
				if(animframe>=920 && animframe<=1010)
				{
					if(animframe%10!=0)
					{
						return 0;
					}
					return 1;
				}
				if(animframe==1019)
				{
					return 1;
				}
			}
			if(shiptype==21)
			{
				if(animframe>=2 && animframe<=29)
				{
					return 1;
				}
				if(animframe>=252 && animframe<=259)
				{
					return 1;
				}
				if(animframe>=380 && animframe<=395)
				{
					return 1;
				}
				if(animframe>=685 && animframe<=725)
				{
					return 1;
				}
				if(animframe>=920 && animframe<=1010)
				{
					if(animframe%10!=0)
					{
						return 0;
					}
					return 1;
				}
			}
			if(shiptype==11)
			{
				if(animframe>=10 && animframe<=90)
				{
					if(animframe%5!=0)
					{
						return 0;
					}
					return 1;
				}
				if(animframe>=370 && animframe<=410)
				{
					return 1;
				}
				if(animframe>=930 && animframe<=960)
				{
					return 1;
				}
				if(animframe>=2195 && animframe<=2235)
				{
					return 1;
				}
				if(animframe>=2810 && animframe<=2850)
				{
					return 1;
				}
			}
			if(shiptype==5)
			{
				if(animframe>=1 && animframe<=60)
				{
					return 1;
				}
				if(animframe>=400 && animframe<=430)
				{
					return 1;
				}
				if(animframe>=730 && animframe<=840)
				{
					if(animframe%5!=0)
					{
						return 0;
					}
					return 1;
				}
			
			}
			if(shiptype==6)
			{
				if(animframe>=1 && animframe<=60)
				{
					return 1;
				}
				if(animframe>=400 && animframe<=430)
				{
					return 1;
				}
				if(animframe>=850 && animframe<=950)
				{
					return 1;
				}
				if(animframe>=1980 && animframe<=1982)
				{
					return 1;
				}
				
			
			}
			if(shiptype==2 || shiptype==3 || shiptype==4 || shiptype==12)
			{
				if(animframe!=0)
				{
					return 0;
				}
				return 1;
			}
				
			return 0;
		}
			
		public static void WaveHelloMaybe(int i)
		{
			if(i<0 || i>maxunits)
