		public static float GetUnitScale(int i)
		{
			float msc = 7.5f;
			int stype = Unit.unitarray[i].soldiertype;
			if(Unit.unitarray[i].shiptype==12)
			{
				msc*=0.35f;
			}
			if(Unit.unitarray[i].shiptype==6)
			{
				msc*=0.44f;
			}
			
			if(Unit.unitarray[i].shiptype==1)
			{
				msc+=(float)Unit.unitarray[i].level*0.25f;
				if(Unit.unitarray[i].race==2)
				{
					msc += ((float)((i % 20)-10)/10.0f)*0.5f;
				}
				if(Unit.unitarray[i].level<2)
				{
					if(Unit.unitarray[i].kills>0)
					{
						float kl = (float)Unit.unitarray[i].kills;
						if(kl>15)
						{
							kl = 15;
						}
						msc+=kl*0.05f;
					}
				}
			}
			if(Unit.unitarray[i].chaosmarine!=0)
			{
				msc*=1.2f;
			}	
			if(stype==5)
			{
				msc = 9;
			}
			if(Unit.unitarray[i].shiptype==11) //assault marine
			{
				msc=9.5f; //not sure yet...
			}
			if(Unit.unitarray[i].shiptype==5)
			{
				msc*=0.112f*0.5f;
			}
			if(Unit.unitarray[i].shiptype==2)
			{
				msc*=0.025f;
			}
			if(Unit.unitarray[i].shiptype==3)
			{
				msc*=1f;
			}
			if(Unit.unitarray[i].shiptype==4)
			{
				msc*=0.41f;
			}
			if(Unit.unitarray[i].shiptype==21)
			{
				msc*=0.1f;
			}
			return msc;
		}
		
		public void PrepareUnit()
		{
			possiblepush = new int[maxunits];
			possibletarget = new int[maxunits];
			distj = new float[maxunits];
			for(int i=0;i<maxunits;i++)
			{
				possiblepush[i] = -1;
				distj[i] = -1;
				possibletarget[i] = -1;
			}
			maxpossiblepush = 0;
			maxpossibletarget = 0;
			healingbary = -100;//6aug2025
			cframe = 0;
			ordertoy = -200;
			orderframe = 0;
			kills = 0;
			working = 0;
			worktype = 0;
			immobilised = 0;
			selected = 0;
			disperse = 0;
			patrol = 0;
			leader = -1;
			soldiertype = 0;
			level = 0;
			cargo = 0;
			ammo = maxammo;
			if(shiptype==2 || shiptype==4 || shiptype==5 || shiptype==12 || shiptype==6)
			{
				soldiertype = -1;
				ammo = maxammo / 2;
			}
			if(shiptype==1)//10sep2025
			{
				numgrenades = ship.random.Next(2,7);
				if(race==2)
				{
					numgrenades /=2;
				}
			}
		}
		
		public static void deadunit(int i)
		{
			//doesn't work the way I want yet...
			//explosion.createsmokeonground(Unit.unitarray[i].x,15,Unit.unitarray[i].z,2.5f);
			float lsc = 2;
			Audio.Battle();
			if(Unit.unitarray[i].race==1)
			{
				Scoring.addtoscore(Scoring.DEATH);
				if(ship.random.NextDouble()<0.03)
				{
					Audio.CalculateDistanceMultiplier(Program.demomode,Unit.unitarray[i].x,Unit.unitarray[i].y,Unit.unitarray[i].z);
					Audio.PlayUnitSound(Audio.COMBAT,Audio.COMBAT);
					Audio.distance_multiplier = 1;
				}
			}
			else//17aug2025
			{
				GameUI.killcount++;
			}
			if(Unit.unitarray[i].shiptype%10>1)
			{
				lsc = 3.5f;
				if(Unit.unitarray[i].race==1)
				{
					Audio.VoiceNotify(Audio.ALERT_VEHICLELOST);
				}
			}
			if(Unit.unitarray[i].shiptype%10!=1)
			{
				Audio.CalculateDistanceMultiplier(Program.demomode,Unit.unitarray[i].x,Unit.unitarray[i].y,Unit.unitarray[i].z);
				Audio.PlayUnitSound(Audio.TANKDIE,Audio.TANKDIE);
				Audio.distance_multiplier = 1;
			}
			if(Unit.unitarray[i].shiptype==2 || Unit.unitarray[i].shiptype==4 || Unit.unitarray[i].shiptype==12 || Unit.unitarray[i].shiptype==6)
			{
				//main battle tanks....
				debris.DebrisExplosion(i,-1);
				Program.camerashake = Program.maxcamshake - 8;
			}
			if(Unit.unitarray[i].race==2)
			{
				Program.wavekills++;
				if(Program.wavekills>Program.wavekillsrequired)
				{
					Program.wavekills = 0;
					if(Program.wavekillsrequired<=0)
					{
						Program.wavekillsrequired = 10;
					}
					Program.wavekillsrequired+=20;
					if(Program.wavetime<=0)
					{
						Program.wavetime = 60 * 50;
						
					}
					Program.wavedelay = Program.wavetime;
				}
			}
			scorchmark.createscorchmark(Unit.unitarray[i].x,Unit.unitarray[i].z,lsc*(float)ship.random.Next(10,20)/15f);
			if(unitarray[i].shiptype%10!=1){smoke.createsmokeemitter(unitarray[i].x+(float)ship.random.Next(-40,40),unitarray[i].z+(float)ship.random.Next(-40,40));}
			if(Unit.unitarray[i].race==1 && Unit.unitarray[i].leader>-1 && Unit.unitarray[i].shiptype%10==1)
			{
				for(int j=0;j<maxunits;j++)
				{
					if(Unit.unitarray[j].leader == Unit.unitarray[i].leader && Unit.unitarray[j].soldiertype == Unit.medic && Unit.unitarray[j].hp>0 && i!=j)
					{
						//there's a medic in the unit.....(and it's not ourselves)
						int dice = random.Next(1,7);
						if(dice==1 || (dice<=2 && Unit.unitarray[i].soldiertype==Unit.sergeant)) // a 1 in 6 chance of a medic preventing the death.... (more for the sergeant)
						{
							Unit.unitarray[i].levelmsgtime = 300;
							Unit.unitarray[i].levelmsg = "MEDIC!";
							Unit.unitarray[i].hp = Unit.unitarray[i].basehp/3;
							Unit.unitarray[i].amode = 0;
							Unit.unitarray[i].aframe = 920;
						}
					}
				}
			}
		}
		
		public static void updatesquad(int i)
		{
			if(unitarray[i].leader!=i)
			{
				return;
			}
			int countsquad = 0;
			int k = i;
			for(int m=0;m<Unit.maxunits;m++)
			{
				if(Unit.unitarray[m].race==1 && Unit.unitarray[m].hp>0 && Unit.unitarray[m].leader==Unit.unitarray[i].leader && Unit.unitarray[m].soldiertype>=0)
				{
					countsquad++;
					if(countsquad>4 + Unit.unitarray[i].level)
					{
						return;
					}
				}
			}
			countsquad = 0;
			for(int m=0;m<Unit.maxunits;m++)
			{
				if(Unit.unitarray[m].race==1 && Unit.unitarray[m].hp>0 && Unit.unitarray[m].leader==-1 && Unit.unitarray[m].soldiertype>=0)
				{
					float dist = Raymath.Vector3Distance(Unit.unitarray[m].pos,Unit.unitarray[k].pos);		
					if(dist < 75)
					{
						countsquad++;
						Unit.unitarray[m].leader = Unit.unitarray[i].leader;
						if(countsquad>4 + Unit.unitarray[i].level)
						{
							return;
						}
					}
				}
			}
		}
		
		public static void updateanimals(Camera3D camera)
		{
			for(int i=0;i<maxanimals;i++)
			{
				
				float startx = animals[i].x;
				float startz = animals[i].z;
				animals[i].sectorx = Program.GetSectorX(startx,startz);
				animals[i].sectorz = Program.GetSectorZ(startx,startz);
				
				float ox = startx;
				float oz = startz;
				float oangle = animals[i].angle;
				if(animals[i].ordertox<-400)
				{
					animals[i].ordertox = -400;
				}
				if(animals[i].ordertox>400)
				{
					animals[i].ordertox = 400;
				}
				if(animals[i].ordertoz<-400)
				{
					animals[i].ordertoz = -400;
				}
				if(animals[i].ordertoz>400)
				{
					animals[i].ordertoz = 400;
				}
				if(Math.Abs(animals[i].ordertox)<110)
				{
					animals[i].ordertox = random.Next(-400,400);
				}
				if(Math.Abs(animals[i].ordertoz)<110)
				{
					animals[i].ordertoz = random.Next(-400,400);
				}
				float dist = 0;
				//push away from units too....
				for(int j=0;j<Unit.maxunits;j++)
				{
					if(Unit.unitarray[j].hp>0)
					{
						animals[i].pos = new Vector3(animals[i].x,0,animals[i].z);
						Vector3 upos = new Vector3(Unit.unitarray[j].x,0,Unit.unitarray[j].z);
						if(Raymath.Vector3Distance(animals[i].pos,upos)<80)
						{
							Vector3 dpos = Raymath.Vector3Normalize(Raymath.Vector3Subtract(animals[i].pos,upos));
							animals[i].ordertox+=dpos.X*20; 
							animals[i].ordertoz+=dpos.Z*20;
						}
					}
				}
				//push apart from buildings....
				for(int j=0;j<Building.maxbuildings;j++)
				{
					if(Building.buildingarray[j].hp>0)
					{
						animals[i].pos = new Vector3(animals[i].x,0,animals[i].z);
						Vector3 bpos = new Vector3(Building.buildingarray[j].x,Building.buildingarray[j].y,Building.buildingarray[j].z);
						dist = Raymath.Vector3Distance(animals[i].pos,bpos);
						float bdist = 45;
						if(j==2){bdist=60;}
						if(j==1){bdist=60;}
						if(Building.IsInside(animals[i].x,animals[i].z)==j && j>0)
						{
							dist = 0.001f;
						}
						if(dist<bdist)
						{
							Vector3 pushdirn = Raymath.Vector3Scale(Raymath.Vector3Normalize(Raymath.Vector3Subtract(animals[i].pos,bpos)),1f);
							animals[i].x+=pushdirn.X;
							animals[i].z+=pushdirn.Z;
							animals[i].vx = pushdirn.X;
							animals[i].vz = pushdirn.Z;
							animals[i].pos = new Vector3(animals[i].x,0,animals[i].z);
							//if the animals are pushing against a building...then give them a new target location....
							//to move to until they don't.....
							animals[i].ordertox = (float)ship.random.Next(-350,350);
							animals[i].ordertoz = (float)ship.random.Next(-350,350);
						}
					}
				}
				//end push apart
				
				
				Vector3 dirn = new Vector3(animals[i].ordertox,0,animals[i].ordertoz);
				animals[i].pos = new Vector3(animals[i].x,0,animals[i].z);
				dirn = Raymath.Vector3Subtract(dirn,animals[i].pos);
				dist = Raymath.Vector3Length(dirn);
				if(dist>20)
				{
					animals[i].orderframe = 240;
				}
				if(dist>5.0 && animals[i].orderframe>0)
				{
					animals[i].orderframe-=ship.delta;
					float speed = 0.075f;
					//take our speed and bring it into line with our 'vx'vz'
					Vector3 ndirn = Raymath.Vector3Scale(Raymath.Vector3Normalize(dirn),speed*ship.delta);
					animals[i].x += ndirn.X;
					animals[i].z += ndirn.Z;
					ndirn = Raymath.Vector3Normalize(ndirn);
					animals[i].vx = ndirn.X * speed;
					animals[i].vz = ndirn.Z * speed;
					animals[i].amode = 1;
					if(animals[i].aframe > 628)
					{
						animals[i].aframe = 598;
					}
					Vector3 up = new Vector3(0,0,1);
					animals[i].angle = Raymath.Vector3Angle(dirn,up).Y;
				}
				if(dist<=20)
				{
					animals[i].ordertox = animals[i].x + (float)random.Next(-50,50);
					animals[i].ordertoz = animals[i].z + (float)random.Next(-50,50);
				}
				animals[i].updatevectors();
				animals[i].aframe+=ship.delta*0.5f;
				float dx = animals[i].x - ox;
				float dz = animals[i].z - oz;
				animals[i].amode = 1;
				animals[i].angle = (float)Math.Atan2(-dz,dx) + 3.14159f/2f;
				int valid = 0;
				if(animals[i].aframe>=598 && animals[i].aframe<=628)
				{
					valid = 1;
				}
				if(valid==0)
				{
					animals[i].aframe = 598;
				}
				if(oangle!=animals[i].angle)
				{
					if(animals[i].anglechangetime>0)
					{
						animals[i].anglechangetime-=delta;
						animals[i].angle = oangle;
					}
					else
					{
						animals[i].anglechangetime = 2;
						float adirn = 1;
						if(Math.Abs(oangle-animals[i].angle)>3.14f)
						{
							adirn = -1;
						}
						double oangledx = Math.Cos(oangle);
						double oangledz = Math.Sin(oangle);
						double nangledx = Math.Cos(animals[i].angle);
						double nangledz = Math.Sin(animals[i].angle);
						double mydot = oangledx * nangledx + oangledz * nangledz;
						if(mydot<0.95)
						{
							if(animals[i].angle>oangle)
							{
								animals[i].angle = oangle+0.125f*adirn*ship.delta;
							}
							else
							{
								animals[i].angle = oangle-0.125f*adirn*ship.delta;
							}
						}
					}
				}
				if(animals[i].x!=startx || animals[i].z!=startz)
				{
					animals[i].imoved = 1;
				}
				else
				{
					animals[i].imoved = 0;
				}
			}
		}
		
		public static void updateunits(Camera3D camera)
		{
			int anyworking1 = 0;
			int anyworking2 = 0;
			int countenemy = 0;
			uframe++;
			for(int i=0;i<maxunits;i++)
			{
				int am_i_in_firing_range = 0;				
				float startx = unitarray[i].x;
				float startz = unitarray[i].z;
				if(Scenario.ms.etank_can_deploy==0)
				{
					if(unitarray[i].race==2 && unitarray[i].shiptype==4)
					{
						unitarray[i].hp = 0;
						unitarray[i].x = -10000;
						unitarray[i].z = -1000;
					}
				}
				if(Scenario.ms.ehover_can_deploy==0)
				{
					if(unitarray[i].race==2 && unitarray[i].shiptype==2)
					{
						unitarray[i].hp = 0;
						unitarray[i].x = -10000;
						unitarray[i].z = -1000;
					}
				}
				if(Scenario.ms.einfantry_can_deploy==0)
				{
					if(unitarray[i].race==2 && unitarray[i].shiptype==1)
					{
						unitarray[i].hp = 0;
						unitarray[i].x = -10000;
						unitarray[i].z = -1000;
					}
				}
				if(Scenario.ms.eassault_can_deploy==0)
				{
					if(unitarray[i].race==2 && unitarray[i].shiptype==11)
					{
						unitarray[i].hp = 0;
						unitarray[i].x = -10000;
						unitarray[i].z = -1000;
					}
				}
				if(Scenario.ms.edefender_can_deploy==0)
				{
					if(unitarray[i].race==2 && unitarray[i].shiptype==21)
					{
						unitarray[i].hp = 0;
						unitarray[i].x = -10000;
						unitarray[i].z = -1000;
					}
				}
				ClearCell(unitarray[i].x,unitarray[i].z);
				if(unitarray[i].hp>0)
				{
					unitarray[i].sectorx = Program.GetSectorX(unitarray[i].x,unitarray[i].z);
					unitarray[i].sectorz = Program.GetSectorZ(unitarray[i].x,unitarray[i].z);
					if(unitarray[i].healingbary>=0)//6aug2025
					{
						unitarray[i].healingbary+=ship.delta * (15f/60f);
						if(unitarray[i].healingbary>25) //tallest unit
						{
							unitarray[i].healingbary = -1;
						}
					}
				}
				else
				{
					unitarray[i].healingbary = -1;
				}
				if(unitarray[i].mefiredat>0)
				{
					unitarray[i].mefiredat-=ship.delta;
				}
				if(unitarray[i].shieldon>0)
				{
					unitarray[i].shieldon-=ship.delta;
					unitarray[i].firedelay = 5; //shielded units cannot fire.....
				}
				if(unitarray[i].burstdelay>0)
				{
					unitarray[i].burstdelay-=ship.delta;
				}
				if(unitarray[i].hp>0)
				{
					if(unitarray[i].hp<5 && unitarray[i].hpo>=5)
					{
						if(unitarray[i].race==1 && unitarray[i].shiptype%10==1)
						{
							Audio.CalculateDistanceMultiplier(Program.demomode,Unit.unitarray[i].x,Unit.unitarray[i].y,Unit.unitarray[i].z);
							Audio.PlayUnitSound(Audio.CRYMEDIC,Audio.CRYMEDIC);
							Audio.distance_multiplier = 1;
							unitarray[i].ping = 180;
						}
					}
					unitarray[i].hpo = unitarray[i].hp;
					unitarray[i].alivetime+=ship.delta;
					if(uframe % 2 == i % 2) //optimisation - change this if it doesn't work okay. //9aug2025
					{
						int k = 0;
						int kk = 0;
						unitarray[i].maxpossiblepush = 0;
						unitarray[i].maxpossibletarget = 0;
						for(int j=0;j<maxunits;j++)
						{
							unitarray[i].possiblepush[k] = -1;
							unitarray[i].possibletarget[kk] = -1;
							if(i!=j && unitarray[j].hp>0 && unitarray[j].shiptype!=3 && unitarray[i].shiptype!=3)
							{
								if(Math.Abs(unitarray[j].x-unitarray[i].x)<45 && Math.Abs(unitarray[j].z-unitarray[i].z)<45)
								{
									unitarray[i].possiblepush[k] = j;
									unitarray[i].maxpossiblepush = k + 1;
									k++;
								}
								if(Math.Abs(unitarray[j].x-unitarray[i].x)<450 && Math.Abs(unitarray[j].z-unitarray[i].z)<450 && unitarray[j].race!=unitarray[i].race)
								{
									unitarray[i].possibletarget[kk] = j;
									unitarray[i].maxpossibletarget = kk + 1;
									kk++;
								}
								
								if(unitarray[j].race==unitarray[i].race && unitarray[j].mefiredat>0 && unitarray[i].ordertime<=0)
								{
									//my friend is being fired at......
									//if they're within say 90 units of me...then I should help out.....
									if(Math.Abs(unitarray[j].x-unitarray[i].x)<unitarray[i].firerange*2 && Math.Abs(unitarray[j].z-unitarray[i].z)<unitarray[i].firerange*2)
									{
										if(unitarray[i].ordertoy<=-100)
										{
											unitarray[i].ordertoy = -90;
											unitarray[i].ordertox = unitarray[j].x + (float)random.Next(-20,20);
											unitarray[i].ordertoz = unitarray[j].z + (float)random.Next(-20,20);
											if(unitarray[i].race==1)
											{
												if(ship.random.NextDouble()<0.02)
												{
													Audio.CalculateDistanceMultiplier(Program.demomode,Unit.unitarray[i].x,Unit.unitarray[i].y,Unit.unitarray[i].z);
													Audio.PlayUnitSound(Audio.COMBAT,Audio.COMBAT);
													Audio.distance_multiplier = 1;
												}
											}
										}
									}
									
								}
							}
							
							//k++;
						}
					}
				}
				else
				{
					unitarray[i].alivetime = 0;
				}
				if(ship.random.Next(0,100)<5)
				{
					unitarray[i].direction_shot_at_from = new Vector3(0,0,0);
					if(unitarray[i].leader==i && unitarray[i].hp>0 && unitarray[i].race==1)//Sergeant
					{
						updatesquad(i);//Add to squad if we need to
					}
				}
				if(unitarray[i].amode==100)
				{
					continue;
				}
				if(unitarray[i].commanddelay>0)
				{
					unitarray[i].commanddelay-=ship.delta;
				}
				if(unitarray[i].race==2 && unitarray[i].shiptype==1 && i % 3==0)
				{
					unitarray[i].chaosmarine = 1; //call a spade a spade Matt....
				}
				else
				{
					if(unitarray[i].race==1 && unitarray[i].shiptype==1 && i % 6==0)
					{
						unitarray[i].chaosmarine = 1;	
					}
					else
					{
						unitarray[i].chaosmarine = 0;
					}
				}
				unitarray[i].vx*=0.98f;
				unitarray[i].vz*=0.98f;
				if(unitarray[i].shiptype==5)
				{
					unitarray[i].firetime = 13;
				}
				if((unitarray[i].shiptype==2 || unitarray[i].shiptype==4 || unitarray[i].shiptype==6) && unitarray[i].firetime<=0)
				{
					unitarray[i].firetime = 60;
				}
				else
				{
					if(unitarray[i].firetime<=0){unitarray[i].firetime = 20;}
				}
				if(unitarray[i].shiptype==12)
				{
					unitarray[i].firetime = 12;
				}
				if(unitarray[i].shiptype!=3) //flyers aren't bound by this
				{
					float odist = Raymath.Vector3Length(new Vector3(unitarray[i].ordertox,0,unitarray[i].ordertoz));
					if(odist>Ground.wsize)
					{
						float sco = Ground.wsize / odist;
						unitarray[i].ordertox*=sco;
						unitarray[i].ordertoz*=sco;
					}
				}
				int oamode = unitarray[i].amode;
				float oangle = unitarray[i].angle;
				
				float ox = unitarray[i].x;
				float oz = unitarray[i].z;
				float dtx = 0;
				float dtz = 0;
				if(unitarray[i].armourdeflected<0)
				{
					unitarray[i].armourdeflected+=delta;
				}
				else
				{
					unitarray[i].armourdeflected = 0;
				}
				if(unitarray[i].hp<=0 || unitarray[i].amode == 3)
				{
					unitarray[i].amode = 3;
					if(oamode!=3)
					{
						unitarray[i].aframe = 242;
						if(unitarray[i].shiptype==6)
						{
							unitarray[i].aframe = 850;
						}
						if(unitarray[i].shiptype==5)
						{
							unitarray[i].aframe = 730;
						}
						if(unitarray[i].shiptype==11)
						{
							unitarray[i].aframe = 2195;
						}
						unitarray[i].hp=0;
						if(unitarray[i].shiptype%10==1)
						{
							Audio.CalculateDistanceMultiplier(Program.demomode,Unit.unitarray[i].x,Unit.unitarray[i].y,Unit.unitarray[i].z);
							Audio.Death(i);
							Audio.distance_multiplier = 1;
							if(unitarray[i].race==1)
							{
								Namelist.addcasualty(unitarray[i].rank + " " + unitarray[i].name,unitarray[i].kills);
								unitarray[i].kills = 0;
								unitarray[i].levelmsg = "";
								unitarray[i].levelmsgtime = 0;
							}
							
							if(unitarray[i].soldiertype==Unit.sergeant)
							{
								if(GameUI.portraitmsg=="")
								{
									GameUI.portraiton = GameUI.waveportraitid;
									GameUI.portraittime = 300;
									GameUI.portraitmsg = Translation.translate("Sergeant")+" " + unitarray[i].name + " " + Translation.translate("is wounded!");
									for(int j=0;j<maxunits;j++)
									{
										if(unitarray[j].hp>0 && unitarray[j].leader == unitarray[i].leader)
										{
											unitarray[j].levelmsg = "Sarge is down!";
											unitarray[j].levelmsgtime = 360;
											//make this guy the new sergeant.....
											break;
										}
									}
									//do audio
								}
							}
						}
					}
					else
					{
						if(unitarray[i].shiptype==5 && unitarray[i].amode==2)
						{
							unitarray[i].aframe+=ship.delta*0.33f;
						}
						else
						{
							unitarray[i].aframe+=ship.delta;
						}
						if(unitarray[i].shiptype==1)
						{
							if(unitarray[i].aframe>259)
							{
								unitarray[i].aframe = 259;
								unitarray[i].hp = 0;
							}
						}
						if(unitarray[i].shiptype==6)
						{
							if(unitarray[i].aframe > 950)
							{
								unitarray[i].aframe = 950;
								unitarray[i].hp = 0;
								unitarray[i].amode = 100; //bugger this might fix it I hope.
							}
						}
						if(unitarray[i].shiptype==11)
						{
							
							if(unitarray[i].aframe > 2235)
							{
								unitarray[i].aframe = 2235;
								unitarray[i].hp = 0;
							}
						}
						if(unitarray[i].shiptype==5)
						{
							if(unitarray[i].aframe>840)
							{
								unitarray[i].aframe = 840;
								unitarray[i].hp = 0;
							}
						}
						
						
					}
				}
				else
				{
					if(unitarray[i].amode!=3)
					{
						//fix unittype/shiptype
						if(unitarray[i].shiptype==0 && unitarray[i].unittype!=0)
						{
							unitarray[i].shiptype = unitarray[i].unittype;
						}
						if(unitarray[i].unittype==0 && unitarray[i].shiptype!=0)
						{
							unitarray[i].unittype = unitarray[i].shiptype;
						}
						if(unitarray[i].shiptype!=3)
						{
							float odist = Raymath.Vector3Length(new Vector3(unitarray[i].ordertox,0,unitarray[i].ordertoz));
							if(odist>Ground.wsize)
							{
								float sco = Ground.wsize / odist;
								unitarray[i].ordertox*=sco;
								unitarray[i].ordertoz*=sco;
							}
						}
						
						//push apart....
						if(unitarray[i].race==2)
						{
							countenemy++;
						}
						unitarray[i].pos = new Vector3(unitarray[i].x,0,unitarray[i].z);
						if(unitarray[i].shiptype!=3 && unitarray[i].amode!=2 && unitarray[i].shiptype!=12)//flyer  //and we're not shooting....
						{
							//for(int jj=0;jj<maxunits;jj++)//22jul2025
							for(int jj=0;jj<unitarray[i].maxpossiblepush;jj++)//22jul2025
							{
								int j = unitarray[i].possiblepush[jj];
								if(j<0 || j>=maxunits)
								{
									continue;
								}
								if(unitarray[i].sizerank > unitarray[j].sizerank)
								{
									continue;
								}
								if(i!=j && unitarray[i].hp>0 && unitarray[i].immobilised==0 && unitarray[j].shiptype!=3)
								{
									if(unitarray[j].hp>0)
									{
										if(unitarray[j].shiptype%10==1 && (unitarray[i].shiptype==2 || unitarray[i].shiptype==4 || unitarray[i].shiptype==5))
										{
											continue; //can't be pushed around by smaller units (tanks can't get pushed by infantry)
										}
										unitarray[j].pos = new Vector3(unitarray[j].x,0,unitarray[j].z);
										float dist = Raymath.Vector3Distance(unitarray[i].pos,unitarray[j].pos);
										float da = 15;
										if(unitarray[i].shiptype==2 || unitarray[j].shiptype==2 || unitarray[i].shiptype==4 || unitarray[j].shiptype==4)
										{
											da = 35;
										}
										if(unitarray[i].shiptype==5 || unitarray[j].shiptype==5)
										{
											da = 22.5f;
										}
										if(unitarray[i].shiptype==6 || unitarray[j].shiptype==6)
										{
											da = 40;
										}
										if(dist<da && dist>3) 
										{
											Vector3 pushdirn = Raymath.Vector3Scale(Raymath.Vector3Normalize(Raymath.Vector3Subtract(unitarray[i].pos,unitarray[j].pos)),1f);
											unitarray[i].x+=pushdirn.X;
											unitarray[i].z+=pushdirn.Z;
											unitarray[i].vx = pushdirn.X;
											unitarray[i].vz = pushdirn.Z;
											unitarray[i].ordertox+=pushdirn.X*0.1f;
											unitarray[i].ordertoz+=pushdirn.Z*0.1f;
											unitarray[i].pos = new Vector3(unitarray[i].x,0,unitarray[i].z);
										}
									}
								}
							}
							//check trees...
							unitarray[i].pos = new Vector3(unitarray[i].x,0,unitarray[i].z);
							if(Grass.IsInside(unitarray[i].x,unitarray[i].z)>-1)
							{
								int jj = Grass.IsInside(unitarray[i].x,unitarray[i].z);
								Vector3 gpos = new Vector3(Grass.grassarray[jj].x,Grass.grassarray[jj].y,Grass.grassarray[jj].z);
								float dist = Raymath.Vector3Distance(unitarray[i].pos,gpos);
								if(dist < 20)
								{
									Vector3 pushdirn = Raymath.Vector3Scale(Raymath.Vector3Normalize(Raymath.Vector3Subtract(unitarray[i].pos,gpos)),1f);
									unitarray[i].x+=pushdirn.X;
									unitarray[i].z+=pushdirn.Z;
									unitarray[i].vx = pushdirn.X;
									unitarray[i].vz = pushdirn.Z;
									unitarray[i].pos = new Vector3(unitarray[i].x,0,unitarray[i].z);
								}
							}
							for(int j=0;j<Building.maxbuildings;j++)
							{
								if(Building.buildingarray[j].hp>0)
								{
									unitarray[i].pos = new Vector3(unitarray[i].x,0,unitarray[i].z);
									Vector3 bpos = new Vector3(Building.buildingarray[j].x,Building.buildingarray[j].y,Building.buildingarray[j].z);
									float dist = Raymath.Vector3Distance(unitarray[i].pos,bpos);
									float bdist = 45;
									if(j==2){bdist=60;}
									if(j==1){bdist=60;}
									if(Building.IsInside(unitarray[i].x,unitarray[i].z)==j && j>0)
									{
										dist = 0.001f;
									}
									if(dist<bdist)
									{
										Vector3 pushdirn = Raymath.Vector3Scale(Raymath.Vector3Normalize(Raymath.Vector3Subtract(unitarray[i].pos,bpos)),1f);
										unitarray[i].x+=pushdirn.X;
										unitarray[i].z+=pushdirn.Z;
										unitarray[i].vx = pushdirn.X;
										unitarray[i].vz = pushdirn.Z;
										unitarray[i].pos = new Vector3(unitarray[i].x,0,unitarray[i].z);
									}
								}
							}
							for(int j=0;j<Obstacle.maxobstacles;j++)
							{
								if(Obstacle.obstaclearray[j].hp>0 && Obstacle.obstaclearray[j].tanktrap!=0)
								{
									unitarray[i].pos = new Vector3(unitarray[i].x,0,unitarray[i].z);
									Vector3 opos = new Vector3(Obstacle.obstaclearray[j].x,0,Obstacle.obstaclearray[j].z);
									float dist = Raymath.Vector3Distance(unitarray[i].pos,opos);
									if(dist<35)
									{
										Vector3 pushdirn = Raymath.Vector3Scale(Raymath.Vector3Normalize(Raymath.Vector3Subtract(unitarray[i].pos,opos)),1f);
										unitarray[i].x+=pushdirn.X;
										unitarray[i].z+=pushdirn.Z;
										unitarray[i].vx = pushdirn.X;
										unitarray[i].vz = pushdirn.Z;
										unitarray[i].pos = new Vector3(unitarray[i].x,0,unitarray[i].z);
										if(unitarray[i].shiptype==6) //large mech just walks over the top of them....
										{
											Obstacle.obstaclearray[j].hp = 0;
											for(int jj=0;jj<3;jj++)
											{
												explosion.createexplosiononground(Obstacle.obstaclearray[j].x+(float)random.Next(-10,10),0.01f,Obstacle.obstaclearray[j].z+(float)random.Next(-10,10),ship.random.Next(1,3));
											}
										}
									}
								}
							}
						}
						//get camdist (for sound purposes)
						float avgx = (camera.Position.X + camera.Target.X)*0.5f;
						float avgy = (camera.Position.Y + camera.Target.Y)*0.5f;
						float avgz = (camera.Position.Z + camera.Target.Z)*0.5f;
						unitarray[i].camdist = Raymath.Vector3Distance(unitarray[i].pos,new Vector3(avgx,avgy,avgz));
						int nootherorders = 1;
						if(unitarray[i].working>0)
						{
							if(unitarray[i].worktype==1)
							{
								anyworking1 = 1;
							}
							else
							{
								anyworking2 = 1;
							}
						}
						int level = unitarray[i].kills/3;
						if(unitarray[i].levelmsgtime>0)
						{
							unitarray[i].levelmsgtime-=ship.delta;
							if(unitarray[i].levelmsgtime<=0)
							{
								if(unitarray[i].levelmsg == "Sarge is down!")
								{
									//I'm the new sergeant!
									unitarray[i].soldiertype=Unit.sergeant;
									{
										unitarray[i].rank="Sgt.";
									}
								}
							}
						}
						if(level>unitarray[i].level && unitarray[i].race==1 && unitarray[i].shiptype%10==1 && level<6)
						{
							unitarray[i].level = level;
							if(unitarray[i].rank=="Sgt." && level>1)
							{
								unitarray[i].rank = "Lt.";
							}
							if(level==3 && unitarray[i].rank=="Lt.")
							{
								unitarray[i].rank = "Maj.";
							}
							if(level==4 && unitarray[i].rank=="Maj.")
							{
								unitarray[i].rank = "Col.";
							}
							if(level==5 && unitarray[i].rank=="Col.")
							{
								unitarray[i].rank = "Gen.";
							}
							if(GameUI.portraitmsg=="")
							{
								GameUI.portraiton = GameUI.levelupportraitid;
								GameUI.portraitmsg = GameUI.levelupmsg(level);
								GameUI.portraittime = 360;
							}
							unitarray[i].levelmsg = GameUI.levelupmsg(level);
							unitarray[i].levelmsgtime = 360;
							//do audio
						}
						if(unitarray[i].firedelay>0)
						{
							if(unitarray[i].clearingobstacles==0 || unitarray[i].shiptype==2 || unitarray[i].shiptype==4){unitarray[i].firedelay-=delta;}
						}
						if(unitarray[i].ordertime>0)
						{
							unitarray[i].ordertime-=delta;
						}
						else
						{
							//do our thing if we're a medic or an engineer....
							if(unitarray[i].soldiertype==medic)
							{
								if(ship.random.NextDouble()<0.02) //this was down inside the loop...but....we can avoid doing the whole loop inside here by taking it outside the loop for mostly the same effect
								{
									//medics treat anyone nearby....or in the same squad..if we're in a squad...
									for(int j=0;j<maxunits;j++)
									{
										if(unitarray[j].race==1 && unitarray[j].soldiertype>=0 && unitarray[j].hp>0 && unitarray[j].hp<unitarray[j].basehp)
										{
											float dist = Raymath.Vector3Distance(unitarray[j].pos,unitarray[i].pos);
											float upgradedist = 5 * GameUI.upgradelevel[GameUI.upgrade_medic_range];
											if(dist<65+upgradedist)
											{
												if(unitarray[i].leader>-1)
												{
													if(unitarray[j].leader==unitarray[i].leader)
													{
														//we're in the same squad....
														if(dist>40)
														{
															unitarray[i].ordertoy = -35;
															unitarray[i].ordertox = unitarray[j].x;
															unitarray[i].ordertoz = unitarray[j].z;
															unitarray[i].orderframe = 40;
														}
														else
														{
															unitarray[i].ordertoy = - 200;
															unitarray[i].orderframe = 0;
														}
														//if(ship.random.NextDouble()<0.02)
														{
															unitarray[j].hp+=2.5f;
															if(unitarray[j].hp>unitarray[j].basehp)
															{
																unitarray[j].hp = unitarray[j].basehp;
																break;
															}
															else
															{
																if(unitarray[j].healingbary<0)//6aug2025
																{
																	unitarray[j].healingbary = 0;
																}
															}
														}
													}
												}
												else
												{
													if(dist>40)
													{
														unitarray[i].ordertoy = -55;
														unitarray[i].ordertox = unitarray[j].x;
														unitarray[i].ordertoz = unitarray[j].z;
														unitarray[i].orderframe = 40;
													}
													else
													{
														unitarray[i].ordertoy = -200;
														unitarray[i].orderframe = 0;
													}
												//	if(ship.random.NextDouble()<0.015)//taken outside loop
													{
														unitarray[j].hp+=2.5f;
														if(unitarray[j].hp>unitarray[j].basehp)
														{
															unitarray[j].hp = unitarray[j].basehp;
															break;
														}
														else
														{
															if(unitarray[j].healingbary<0)//6aug2025
															{
																unitarray[j].healingbary = 0;
															}
														}
													}
												}
											}
										}
									}
								}
							}
							if(unitarray[i].soldiertype==engineer)
							{
								int donework = 0;
								if(ship.random.NextDouble()<0.02)
								{
									for(int j=0;j<Building.maxbuildings;j++)
									{
										if(Building.buildingarray[j].hp>0 && Building.buildingarray[j].hp<Building.buildingarray[j].basehp)
										{
											Vector3 bpos = new Vector3(Building.buildingarray[j].x,0,Building.buildingarray[j].z);
											float upgradedist = 5 * GameUI.upgradelevel[GameUI.upgrade_eng_range];
											if(Raymath.Vector3Distance(bpos,unitarray[i].pos)<65+upgradedist)
											{
												unitarray[i].ordertoy = -35;
												unitarray[i].ordertox = Building.buildingarray[j].x;
												unitarray[i].ordertoz = Building.buildingarray[j].z;
												unitarray[i].orderframe = 40;
												//if(ship.random.NextDouble()<0.02)
												{
													Building.buildingarray[j].hp++;
													if(Building.buildingarray[j].hp>Building.buildingarray[j].basehp)
													{
														Building.buildingarray[j].hp = Building.buildingarray[j].basehp;
														donework = 1;
														break;
													}
													else
													{
														if(Building.buildingarray[j].healingbary<0)//6aug2025
														{
															Building.buildingarray[j].healingbary = 0;
														}
													}
												}
											}
										}
									}
								}
								if(donework==0)
								{
									if(ship.random.NextDouble()<0.02)
									{
										for(int j=0;j<maxunits;j++)
										{
											if(unitarray[j].race==1 && (unitarray[j].shiptype==2 || unitarray[j].shiptype==5 || unitarray[j].shiptype==12) && unitarray[j].hp>0 && unitarray[j].hp<unitarray[j].basehp)
											{
												float dist = Raymath.Vector3Distance(unitarray[j].pos,unitarray[i].pos);
												if(dist<50)
												{
													//if(ship.random.NextDouble()<0.02)
													{
														unitarray[j].hp++;
														if(unitarray[j].hp>unitarray[j].basehp)
														{
															unitarray[j].hp = unitarray[j].basehp;
															break;
														}
														else
														{
															if(unitarray[j].healingbary<0)//6aug2025
															{
																unitarray[j].healingbary = 0;
															}
														}
													}
												}
											}
										}		
									}
								}
							}
							if(unitarray[i].shiptype==3)//Program.IsReleased(1,Program.transport_release,Program.gametimer.ElapsedMilliseconds)!=0)
							{
								//error corrections
								unitarray[i].hp = unitarray[i].basehp;
								//
								if(unitarray[i].cargostate==Unit.CARGOFLYING)
								{
									unitarray[i].offy = 0;
									if(unitarray[i].cargo>0)
									{
										//do nothing..taken care of below....
									}
									else
									{
										unitarray[i].ordertoy = -90;
										unitarray[i].ordertox = 3000;
										unitarray[i].ordertoz = 3000;
										unitarray[i].orderframe = 300;
									}
								}
								if(unitarray[i].cargostate==Unit.CARGOUNLOAD)
								{
									unitarray[i].offy = -55;
								}
								
								//
								//only race 1 has these.....
								//gunships that are designed to drop off troops.....
								//not sure what should go here yet....
								if(Building.IsCategoryAlive(Building.AIRTRAFFICCONTROL)==0)
								{
									//don't land here....
									unitarray[i].ordertoy = -90;
									unitarray[i].ordertox = 3000;
									unitarray[i].ordertoz = 3000;
									unitarray[i].orderframe = 300;
								}
								else
								{
									if(unitarray[i].cargo>0 && Building.IsCategoryAlive(Building.AIRTRAFFICCONTROL)!=0 && GameUI.requestdropship!=0)
									{
										if(Math.Abs(unitarray[i].x)>900 || Math.Abs(unitarray[i].z)>900)
										{
											unitarray[i].cargostate = Unit.CARGOFLYING;
											//potentially give us an order to fly back to the centre of the map....
											//do so randomly 
											int debugtransport = 1; //yep leave this in for now...
											if(ship.random.NextDouble()<0.02*0.05 || debugtransport!=0)
											{
												//1 time per 60 seconds....on average.....
												//we get a dice throw....on a roll of 
												//5 or 6 we get an inbound troop transport
												//on a 5+ on a standard dice we get a troop transport....
												//scratch that - make it 10%....
												if(ship.random.Next(1,11)>9) //on 1/10 chance we get a 
												{
													unitarray[i].ordertoy = -90;
													unitarray[i].ordertox = (float)ship.random.Next(-50,50);
													unitarray[i].ordertoz = (float)ship.random.Next(-50,50);
													unitarray[i].orderframe = 300;
												}
											}
										}
										if(Math.Abs(unitarray[i].x)<60 && Math.Abs(unitarray[i].z)<60)
										{
											switch(unitarray[i].cargostate)
											{
												case Unit.CARGOFLYING: //initial state before descent
													if(unitarray[i].cargo>0)
													{
														unitarray[i].cargostate = Unit.CARGODESCENT;
													}
												break;
												case Unit.CARGODESCENT: //dropping to ground
													if(unitarray[i].offy>-55)
													{
														unitarray[i].offy-=0.5f;
													}
													else
													{
														unitarray[i].cargostate = Unit.CARGOUNLOAD;
													}
												break;
												case Unit.CARGOUNLOAD: //letting the troops out
													if(unitarray[i].cargo<=0)
													{
														unitarray[i].cargostate = Unit.CARGOASCENT;
														Audio.VoiceNotify(Audio.ALERT_SUPPORTRECEIVED);
													}
												break;
												case Unit.CARGOASCENT: //going back up;;;;
													if(unitarray[i].offy<0)
													{
														unitarray[i].offy+=0.5f;
													}
													else
													{
														unitarray[i].cargostate = Unit.CARGOFLYING;
													}
												break;
											}
											if(unitarray[i].cargo<=0)
											{
												if(unitarray[i].cargostate==Unit.CARGOFLYING)
												{
													unitarray[i].ordertoy = -90;
													unitarray[i].ordertox = 3000;
													unitarray[i].ordertoz = 3000;
													unitarray[i].orderframe = 300;
												}
											}
											else
											{
												if(ship.random.NextDouble()<0.04)
												{
													if(unitarray[i].cargostate==Unit.CARGOUNLOAD)
													{
														unitarray[i].cargo--;
														Unit.CARGODROP = i;
														GameUI.BuildUnit(1);
														Unit.CARGODROP = -1;
														if(unitarray[i].cargo<=0)
														{
															unitarray[i].cframe = (float)ship.random.NextDouble()*6.3f;
														}
													}
												}
											}
										}
									}
									else
									{
										if(GameUI.requestdropship!=0)
										{
											switch(unitarray[i].cargostate)
											{
												case Unit.CARGOFLYING: //we're flying away now.....
												 //keep flying away....
												break;
												case Unit.CARGODESCENT: //dropping to ground
													if(unitarray[i].offy>-55)
													{
														unitarray[i].offy-=0.5f;
													}
													else
													{
														unitarray[i].cargostate = Unit.CARGOUNLOAD;
													}
												break;
												case Unit.CARGOUNLOAD: //letting the troops out
													if(unitarray[i].cargo<=0)
													{
														unitarray[i].cargostate = Unit.CARGOASCENT;
														Audio.VoiceNotify(Audio.ALERT_SUPPORTRECEIVED);
													}
												break;
												case Unit.CARGOASCENT: //going back up;;;;
													if(unitarray[i].offy<0)
													{
														unitarray[i].offy+=0.5f;
													}
													else
													{
														unitarray[i].cargostate = Unit.CARGOFLYING;
													}
												break;
											}
											if(unitarray[i].cargostate==Unit.CARGOFLYING)
											{
												unitarray[i].ordertoy = -90;
												unitarray[i].ordertox = 3000.0f * (float)Math.Sin(unitarray[i].cframe);
												unitarray[i].ordertoz = 3000.0f * (float)Math.Cos(unitarray[i].cframe);
												unitarray[i].orderframe = 30;
											}
											if(Math.Abs(unitarray[i].x)>900 || Math.Abs(unitarray[i].z)>900)
											{
												unitarray[i].cargo = 8;
												GameUI.requestdropship=0;
											}
										}
									}
								}
							}
							//check if there are enemy nearby......
							if(unitarray[i].amode==2){unitarray[i].amode = 0;}
							if(unitarray[i].amode==5){unitarray[i].amode = 0;}//fix?
							if(unitarray[i].shiptype!=3) //these are troop transports, don't fire any weapons
							{
								float dist = 0;
								float mindist = 10000;
								int choosenewtarget = 0;
								if(unitarray[i].targetj>=0)
								{
									if(unitarray[unitarray[i].targetj].hp<=0)
									{
										choosenewtarget = 1;
									}
									if(choosenewtarget==0)
									{
										// ?
									}
								}
								else
								{
									if(unitarray[i].targetj==-1 && unitarray[i].ordertime<=0)
									{
										choosenewtarget = 1;
									}
									else
									{
										//we must have given a move order that we want to
										//potentially override our selection of a target
										//we should respect this until we are near our 
										//move order position....
										if(Math.Abs(unitarray[i].x-unitarray[i].ordertox)<30 && Math.Abs(unitarray[i].z-unitarray[i].ordertoz)<30 && unitarray[i].ordertime<=0)
										{
											unitarray[i].targetj=-1;
											choosenewtarget = 1;
										}
										else
										{
											choosenewtarget = -1;
										}
									}
								}
								if(choosenewtarget==1 || (ship.random.Next(0,100)<5 && choosenewtarget>=0) || (unitarray[i].shiptype==6 && ship.random.Next(0,1000)<7))
								{
									unitarray[i].targetj = -1;
									for(int jjj=0;jjj<unitarray[i].maxpossibletarget;jjj++)//
									{
										int j = unitarray[i].possibletarget[jjj];
										if(j<0)
										{
											continue;
										}
										if(unitarray[j].hp>0 && unitarray[j].race!=unitarray[i].race && unitarray[j].shiptype!=3)
										{
											if(unitarray[j].imoved!=0 || unitarray[j].immobilised==1)
											{
												unitarray[i].distj[j] = -1;
											}
											if(unitarray[j].imoved==0) //if a unit isn't moving it should still have its distance checked...from time to time....think of it like being hidden in long grass...the soldiers know there's enemy roughly there, but unless it moves or gets noticed they will mostly ignore those soldiers.
											{
												if(ship.random.NextDouble()<0.025)
												{
													unitarray[i].distj[j] = -1;
												}
											}
											if(unitarray[i].distj[j]==-1)
											{
												unitarray[i].pos = new Vector3(unitarray[i].x,0,unitarray[i].z);
												unitarray[j].pos = new Vector3(unitarray[j].x,0,unitarray[j].z);
												dist = Raymath.Vector3Distance(unitarray[i].pos,unitarray[j].pos);
												unitarray[i].distj[j] = dist;
											}
											if(unitarray[i].distj[j]<mindist)
											{
												mindist = unitarray[i].distj[j];
												unitarray[i].targetj = j;
											}									
											if(unitarray[j].shiptype==21 && unitarray[i].shiptype==11 && unitarray[i].race==2) //enemy is defenders, we are melee (enemy units) //added at library
											{
												if(unitarray[i].distj[j]<mindist*1.5) //unit 21 is at the end of the list...so if we're searching through to this point we can be sure we're not going to have to worry about the other types of units...since these are the last of the infantry units in the game array.
												{
													mindist = unitarray[i].distj[j];
													unitarray[i].targetj = j;
												}									
											}
											
										}
									}
								}
								if(unitarray[i].targetj>=0)
								{
								for(int j=unitarray[i].targetj;j<=unitarray[i].targetj;j++)
								{
									if(unitarray[j].hp>0 && unitarray[j].race!=unitarray[i].race && unitarray[j].shiptype!=3 && j==unitarray[i].targetj)
									{
										unitarray[i].pos = new Vector3(unitarray[i].x,0,unitarray[i].z);
										unitarray[j].pos = new Vector3(unitarray[j].x,0,unitarray[j].z);
										dist = Raymath.Vector3Distance(unitarray[i].pos,unitarray[j].pos);
										float rangefactor = 1;
										
										if(Program.usegrenades!=0)
										{
											if(dist<unitarray[i].firerange * rangefactor && unitarray[i].throwinggrenade<=0 && unitarray[j].shiptype%10==1 && unitarray[i].numgrenades>0) //10sep2025 altered shiptype[j]%10==1
											{
												if(unitarray[i].numgrenades>0)
												{
													if(Grass.incover(unitarray[j].x,unitarray[j].z)==1)
													{
														am_i_in_firing_range = 1;
														//enemy is in cover, in range and we have grenades.....
														//only time we ever throw grenades.....assuming we have any
														unitarray[i].ordertoy = -200;
														int dice = random.Next(1,7); //1-6
														float damage = unitarray[i].damage;
														double misschance = (double)unitarray[j].kills/20.0;
														if(misschance>0.5)
														{
															misschance = 0.5;
														}
														if(random.NextDouble()<misschance)
														{
															damage/=2;
														}
														if(dice<unitarray[j].armour)
														{
															damage/=2;
															unitarray[j].armourdeflected = -45;
														}
														if(unitarray[i].firedelay<=0)
														{
															
															unitarray[i].throwinggrenade = 40;
															//friendly units get a dodge chance.....call it home ground advantage if you will
															if(unitarray[j].race==1)
															{
																if(ship.random.NextDouble()<0.2)
																{
																	damage/=2;
																}
															}
															else // and the opposite for the enemy team, call it a hostile crowd if you want.
															{
																if(ship.random.NextDouble()<0.2) 
																{
																	damage*=1.25f;
																}
															}
															if(unitarray[i].leader>-1) //if we're part of a squad
															{
																if(unitarray[unitarray[i].leader].hp>0) //and our squad leader is alive.
																{
																	damage*=1.25f;
																}
															}
															if(unitarray[i].soldiertype==Unit.sergeant) //leader gets an extra bonus
															{
																damage*=1.33f;
															}
															//check for friendly sergeant's nearby if we're being shot at....
															//we get a bonus to our defense.....if we're in a squad....
															if(unitarray[j].leader>-1) //if unit shot at is part of a squad...
															{
																if(unitarray[unitarray[j].leader].hp>0) //sergeant is still alive
																{
																	damage*=0.75f;
																}
															}
															unitarray[j].hp-=damage;
															
															//splash damage........
															int splashcount = 3;
															Program.explosion_effects[ship.random.Next(0,8)] = new Vector3(unitarray[j].x,unitarray[j].y,unitarray[j].z);
															for(int k=0;k<maxunits;k++)
															{
																if(unitarray[k].hp>0 && unitarray[k].shiptype!=2 && unitarray[k].shiptype!=4 && unitarray[k].shiptype!=12 && unitarray[k].amode!=3 && unitarray[k].race!=unitarray[i].race && unitarray[k].shiptype!=3)
																{
																	//splash damage...
																	Vector3 kpos = new Vector3(unitarray[k].x,0,unitarray[k].z);
																	if(Raymath.Vector3Distance(kpos,unitarray[j].pos)<25)
																	{
																		splashcount--;
																		//if(random.NextDouble()<0.95)
																		//{
																			explosion.createexplosiononground(unitarray[k].x+(float)random.Next(-10,10),0.01f,unitarray[k].z+(float)random.Next(-10,10),ship.random.Next(1,3));
																		//}					
																		dice = random.Next(1,7);//1-6
																		if(dice>=unitarray[k].armour)
																		{
																			unitarray[k].hp-=damage/2;
																			if(unitarray[k].hp<=0)
																			{
																				if(unitarray[i].race==1){unitarray[i].kills++;}
																			}
																		}
																	}
																}
																if(splashcount<=0)
																{
																	break;
																}
															}
															
														}
														if(Program.cheat!=0)
														{
															if(Unit.unitarray[j].race==1 && Unit.unitarray[j].hp<0)
															{
																Unit.unitarray[j].hp = Unit.unitarray[j].basehp;
															}
														}
														if(unitarray[j].hp<=0)
														{
															Unit.deadunit(j);
															if(unitarray[i].shiptype==6)
															{
																debris.DebrisExplosion(j,-1);
															}
															if(unitarray[i].race==1){unitarray[i].kills++;}
															if(random.NextDouble()<0.2)
															{
																explosion.createexplosiononground(unitarray[j].x+(float)random.Next(-10,10),0.01f,unitarray[j].z+(float)random.Next(-10,10),ship.random.Next(1,3));
															}
															if(unitarray[j].shiptype==2 || unitarray[j].shiptype==4 || unitarray[j].shiptype==5 || unitarray[j].shiptype==12 || unitarray[j].shiptype==6)
															{
																for(int k=0;k<3;k++)
																{
																	explosion.createexplosiononground(unitarray[j].x+(float)random.Next(-10,10),0.01f,unitarray[j].z+(float)random.Next(-10,10),ship.random.Next(1,3));												
																}
																Program.explosion_effects[ship.random.Next(0,8)] = new Vector3(unitarray[j].x,unitarray[j].y,unitarray[j].z);
															}
														}
