											unitarray[i].ordertoz = unitarray[unitarray[i].leader].z + (float)ship.random.Next(-35,35);
										}
										else
										{
											//if we're in squad distance....then check if there's cover nearby
											//and take shelter.....
											if(Grass.incover(unitarray[i].x,unitarray[i].z)==0 && unitarray[i].ordertoy<=-100)
											{
