												if(Grass.incover(unitarray[i].x+cx,unitarray[i].z+cz)!=0)
												{
													unitarray[i].ordertoy = -65;
													unitarray[i].ordertox = unitarray[i].x+cx;
													unitarray[i].ordertoz = unitarray[i].z+cz;
												}
