											}
										}
									}
								}
							}
						}
						unitarray[i].clearingobstacles = 0;
						//if the enemy is infantry then seek cover along the route to the target......
						if(unitarray[i].race==2)//added at library (all inside)
						{
							if(unitarray[i].shiptype%10==1)
							{
								//infantry
