														//head slightly in direction 1,0,-1 "ish"
														unitarray[i].ordertoz+=50; //this will get reset when we redo our movement target
														break;
													}
													else
													{
														//head slightly in direction -1"ish",0,1
														unitarray[i].ordertoz-=50;//this will get reset when we redo our movement target anyway
														break;
													}
												}
												else
												{
													//quadarant 3
													//we're heading in direction 1,0,-1
													if(i%2==0)
													{
														//head slightly in direction 1,0,1"ish"
														unitarray[i].ordertoz+=50;
														break;
													}
													else
													{
														//head slightly in direction -1"ish",0,-1
														unitarray[i].ordertox-=50;
														break;
													}
												}
											}
											else
											{
												if(unitarray[i].pos.Z<0)
												{
													//quadrant 2
													//we're heading in direction -1,0,1
													if(i%2==0)
													{
														//head slightly in direction -1,0,-1"ish"
														unitarray[i].ordertoz-=50;
														break;
													}
													else
													{
														//head slightly in direction 1"ish",0,1
														unitarray[i].ordertox+=50;
														break;
													}
												}
												else
												{
													//quadrant 4
													//we're heading in direction -1,0,-1
													if(i%2==0)
													{
														//head slightly in direction -1,0,1"ish"
