													else
													{
														//head slightly in direction 1"ish",0,-1
														unitarray[i].ordertox+=50;
													}
												}
											}
										}											
									}
									if(Obstacle.obstaclearray[j].hp<=0 && Obstacle.obstaclearray[j].tanktrap==1)
