											{
												speed*=0.25f;
												if(unitarray[i].race==2)
												{
													unitarray[i].clearingobstacles = 1;
													//if their health is greater than basehp*0.5 then deduct a point while walking through it
													if(unitarray[i].hp>unitarray[i].basehp*0.5)
													{
														unitarray[i].hp-=0.05f; //light damage for walking through razor wire....
													}
												}
											}
											break;
										}
										if(Obstacle.obstaclearray[j].hp<=0 && Obstacle.obstaclearray[j].razorwire==1)
										{
											break; //we've reached the end of the obstacles....that have been placed...
										}
									}
								}
								//}
								if(unitarray[i].shiptype==2 || unitarray[i].shiptype==4)
								{
									//tanks blocked by obstacles......
									for(int j=0;j<Obstacle.maxobstacles;j++)
									{
										if(Obstacle.obstaclearray[j].y>0 && Obstacle.obstaclearray[j].hp>0 && Obstacle.obstaclearray[j].tanktrap==1)
										{
											//our speed is significantly slowed if we're within say about 10 units of it.....
											Vector3 rpos = new Vector3(Obstacle.obstaclearray[j].x,0,Obstacle.obstaclearray[j].z);
											float rdist = Raymath.Vector3Distance(rpos,unitarray[i].pos);
											if(rdist<40) //adjusted from whatever low number it was before..10 or something
											{
												speed*=0.2f;
												unitarray[i].clearingobstacles = 1;
											}
											break;
										}
										if(Obstacle.obstaclearray[j].hp<=0 && Obstacle.obstaclearray[j].tanktrap==1)
										{
											break; //we've reached the end of the obstacles....that have been placed...
										}
									}
								}
								//take our speed and bring it into line with our 'vx'vz'
								if(unitarray[i].shiptype==11)
								{
									speed*=1.075f;
								}
								if(unitarray[i].shiptype==21)
								{
									speed*=0.35f;
								}
								if(unitarray[i].shiptype==3 && GameUI.fasterdropship>=100)
								{
									speed*=1.15f;
								}
								float cspeed = Raymath.Vector2Length(new Vector2(unitarray[i].vx,unitarray[i].vz));
								speed = cspeed + (speed - cspeed) * 0.1f;
								if(unitarray[i].immobilised==0 && (am_i_in_firing_range==0 || (am_i_in_firing_range!=0 && unitarray[i].shiptype==11)))
