									else
									{
										ndirn.X = (Unit.lastd*3f) * ndirn.X + (1f - (Unit.lastd*3f)) * unitarray[i].lastdx;
										ndirn.Z = (Unit.lastd*3f) * ndirn.Z + (1f - (Unit.lastd*3f)) * unitarray[i].lastdz;
									}
									unitarray[i].x += ndirn.X;
									unitarray[i].z += ndirn.Z;
									unitarray[i].lastdx = ndirn.X;
									unitarray[i].lastdz = ndirn.Z;
									ndirn = Raymath.Vector3Normalize(ndirn);
									unitarray[i].vx = ndirn.X * speed;
									unitarray[i].vz = ndirn.Z * speed;
									unitarray[i].amode = 1;
									if(unitarray[i].shiptype==1 || unitarray[i].shiptype==21)
