								unitarray[i].anglechangetime = 2;
								float dirn = 1;
								if(Math.Abs(oangle-unitarray[i].angle)>3.14f)
								{
									dirn = -1;
								}
								if(unitarray[i].shiptype%10==1)
								{
									dirn*=1.25f;
								}
								double oangledx = Math.Cos(oangle);
								double oangledz = Math.Sin(oangle);
								double nangledx = Math.Cos(unitarray[i].angle);
								double nangledz = Math.Sin(unitarray[i].angle);
								double mydot = oangledx * nangledx + oangledz * nangledz;
								if(mydot<0.95)
								{
									float dangle = 0;
									if(unitarray[i].angle>oangle)
									{
										dangle = 0.125f*dirn*ship.delta;
										{
											dangle = Unit.lastd * dangle + (1f - Unit.lastd) * unitarray[i].lastdangle;
										}
										unitarray[i].angle = oangle+dangle;
									}
									else
									{
										dangle = -0.125f*dirn*ship.delta;
										{
											dangle = Unit.lastd * dangle + (1f - Unit.lastd) * unitarray[i].lastdangle;
										}
										unitarray[i].angle = oangle+dangle;
									}
									unitarray[i].lastdangle = dangle;
									if(dangle!=0)
									{
										if(unitarray[i].firedelay<3) //don't shoot when we're not pointing at our enemy...
										{
											unitarray[i].firedelay = 3;
										}
									}
								}
								else
								{
									unitarray[i].lastdangle = 0;
								}
							}
						}
					}
					
				}
				if(unitarray[i].x!=startx || unitarray[i].z!=startz)
				{
					unitarray[i].imoved = 1;
				}
				else
				{
					unitarray[i].imoved = 0;
				}
				if(unitarray[i].hp>0 && unitarray[i].shiptype!=3)
				{
					SetCell(unitarray[i].x,unitarray[i].z,i);
				}
			}
			if(countenemy==0)
			{
				for(int i=0;i<maxunits;i++)
				{
					if(unitarray[i].kills>10 && unitarray[i].race==1 && unitarray[i].hp>0 && unitarray[i].basehp > unitarray[i].hp)
					{
						//regenerate....we've gained sufficient experience......
						if(random.NextDouble()<(double)unitarray[i].kills/10000.0)
						{
							unitarray[i].hp++;
							if(unitarray[i].hp>unitarray[i].basehp)
							{
								unitarray[i].hp = unitarray[i].basehp;
							}
						}
					}
				}
			}
			if(RTSInput.selectedunits!=null)
			{
				for(int i=0;i<RTSInput.selectedunits.Length;i++)
				{
					int t = RTSInput.selectedunits[i];
					if(unitarray[t].hp>0 && unitarray[t].race==1)
					{
						unitarray[t].selected = 1;
					}
				}
			}
			if(anyworking1==0)
			{
				GameUI.working1 = 0;
			}
			if(anyworking2==0)
			{
				GameUI.working2 = 0;
			}
		}
		
		public static int flankingfire(int i,int j)
		{
			Vector3 firer = new Vector3(unitarray[i].x,0,unitarray[i].z);
			Vector3 target = new Vector3(unitarray[j].x,0,unitarray[j].z);
			if(Raymath.Vector3Length(unitarray[j].direction_shot_at_from)<=0)
			{
				unitarray[j].direction_shot_at_from = Raymath.Vector3Normalize(Raymath.Vector3Subtract(target,firer));
				//return 0 since no one else is shooting at us....
				return 0;
			}
			Vector3 newshooterdirn = Raymath.Vector3Normalize(Raymath.Vector3Subtract(target,firer));
			float mydot = Raymath.Vector3DotProduct(newshooterdirn,unitarray[j].direction_shot_at_from);
			if(mydot<=0)
			{
				//our second or subsequent firer is firing from a greater than 90 degree angle at us
				//therefore return '1'
				return 1;
			}
			return 0;
		}
		
		public static int smokebetweenus(int i,int j)
		{
			Vector3 firer = new Vector3(unitarray[i].x,0,unitarray[i].z);
			Vector3 target = new Vector3(unitarray[j].x,0,unitarray[j].z);
			
			for(int s=0;s<smoke.maxsmoke;s++)
			{
				if(smoke.smokes[s].emitter_life>0)
				{
					Vector3 smokepos = new Vector3(smoke.smokes[s].emitter_x,0,smoke.smokes[s].emitter_z);
					Vector3 direction_to_target = Raymath.Vector3Subtract(target,firer);
					Vector3 direction_to_smoke = Raymath.Vector3Subtract(smokepos,firer);
					if(Raymath.Vector3Length(direction_to_smoke)<Raymath.Vector3Length(direction_to_target))
					{
						direction_to_target = Raymath.Vector3Normalize(direction_to_target);
						direction_to_smoke = Raymath.Vector3Normalize(direction_to_smoke);
						float mydot = Raymath.Vector3DotProduct(direction_to_target,direction_to_smoke);
						if(mydot > 0.9)
						{
							//smoke gets in your eyes..la la la la
							//it just means the smoke is closer to us than the target and in a similar
							//direction to us as our target is to us....so we can say it obscures
							//our line of fire....
							return 1;
						}
					}
				}
			}
			return 0;
		}
		
		public void updatevectors()
		{
			
			pos.X = 0;//x;
			pos.Y = 0;//y;
			pos.Z = 0;//z;
			
			zaxis.X = vx;
			zaxis.Y = vy;
			zaxis.Z = vz;
			zaxis = Raymath.Vector3Normalize(zaxis);
			
			//zaxis = forwards
			//yaxis = up vector
			//xaxis = right vector
			if(vz!=0)
			{
				yaxis.X = vy;
				yaxis.Y = -vx;
				yaxis.Z = 0;
			}
			else
			{
				yaxis.X = 0;
				yaxis.Y = 0;
				yaxis.Z = 1;
				
			}
			yaxis = Raymath.Vector3Normalize(yaxis);
			xaxis = Raymath.Vector3CrossProduct(yaxis,zaxis);
			xaxis = Raymath.Vector3Normalize(xaxis);
			rotationmatrix = new Matrix4x4(xaxis.X,yaxis.X,zaxis.X,0,xaxis.Y,yaxis.Y,zaxis.Y,0,xaxis.Z,yaxis.Z,zaxis.Z,0,0,0,0,1);
		}
		
		public static void SetupBattlefield()
		{
			float x = 0;
			float z = 0;
			float scale = 1;
			for(int i=0;i<80;i++)
			{
				x = (float)ship.random.Next(-350,350);
				z = (float)ship.random.Next(-350,350);
				scale = 1.0f + (float)ship.random.NextDouble()*2.25f;
				scorchmark.createscorchmark(x,z,scale);
			}
			for(int i=0;i<25;i++)
			{
				x = (float)ship.random.Next(-350,350);
				z = (float)ship.random.Next(-350,350);
				Grass.createcrater(x,z);
			}
		}
		
