			Namelist.casualtykills = new int[Namelist.maxcasualties];
			Unit.prioritytarget = -1;

			int race = 0;
			int placedgunship = 0;
			int placedboss = 0;//don't include this yet...it doesn't work right.
			int shiptype = 1;
			for(int i=0;i<maxunits;i++)
			{
				race++;
				if(race>2)
				{
					race=1;
				}
				if(race<1)
				{
					race = 1;
				}
				if(i<80)
				{
					shiptype = 1;
				}
				if(i>= 80 && i < 120)
				{
					shiptype = 2;
				}
				if(i >= 120 && i < 160)
				{
					if(race==1)
					{
						shiptype = 5;
					}
					else
					{
						shiptype = 4;
					}
				}
				if(i>=160 && i<184)
				{
					shiptype = 1;
					if(i>=174 && race==1)
					{
						shiptype = 12;
					}
				}
				if(i>=184 && i<272)//extras
				{
					shiptype = 11; // assaultmarine
				}
				if(i>=272 && i<360)//extras
				{
					shiptype = 21; //defender marine
				}
				if(i>=360 && i<390)//extras added at library //not sure this change will work properly....
				{
					shiptype = 4; 
					if(i%4<2)
					{
						shiptype = 1 + 10 * (i % 3);
					}
					if(placedboss==0 && race==2)
					{
						shiptype = 6;
						placedboss = 1;
					}
				}
				if(i>=360 && i<390 && race==1)//sentry guns
				{
