			cmodel = Raylib.LoadModel("media/humaninfantry/_circle.obj");
			UnloadHelper.AddModel(cmodel);
			cshader = Raylib.LoadShader("media/shaders/basicvertexshaderflag.vs","media/shaders/basicpixelshadervariant.fs");
			int debuglighting = Raylib.GetShaderLocation(cshader,"debuglighting");
			int debugl = Program.debuglighting;
			unsafe
			{
				Raylib.SetShaderValueV(cshader,debuglighting,&debugl,ShaderUniformDataType.Int,1);				
			}
			
			UnloadHelper.AddShader(cshader);
			cshadertex0 = Raylib.GetShaderLocation(cshader,"texture0");
