			PrepareCircle();
			int shiptype = 0;
			int race = 0;
			int placedgunship = 0;
			int placedboss = 0; //don't include this yet...it doesn't work right
			for(int i=0;i<maxunits;i++)
			{
				if(i%10==0)
				{
					GameUI.Loading("Please Wait....Loading.....GROUND UNITS",10,Program.resy - 56,GameUI.largefont,Color.LightGray,3);
				}
				
				race++;
				if(race>2)
				{
					race=1;
				}
				if(race<1)
				{
					race = 1;
				}
				if(i<80)
				{
					shiptype = 1;
				}
				if(i>= 80 && i < 120)
				{
					shiptype = 2;
				}
				if(i >= 120 && i < 160)
				{
					if(race==1)
					{
						shiptype = 5;
					}
					else
					{
						shiptype = 4;
					}
				}
				if(i>=160 && i<184)
				{
					shiptype = 1;
					if(i>=174 && race==1)
					{
						shiptype = 12;
					}
				}
				if(i>=184 && i<272)//extras
				{
					shiptype = 11; // assaultmarine
				}
				if(i>=272 && i<360)//extras
				{
					shiptype = 21; //defender marine
				}
				if(i>=360 && i<390)//extras added at library //not sure this change will work properly....
				{
					shiptype = 4; 
					if(i%4<2)
					{
						shiptype = 1 + 10 * (i % 3);
					}
					if(placedboss==0 && race==2)
					{
						shiptype = 6;
						placedboss = 1;
					}
				}
				if(i>=360 && i<390 && race==1)
				{
					shiptype = 12;
				}
				if(i>=390 && i<410)
				{
					shiptype = 1 + 10 * (i % 3);
					if(race==2) //6aug2025
					{
						shiptype = 2; 
						if(i%4==1)
						{
							shiptype = 4;
						}
						if(i%4>=2)
						{
							shiptype = 1;
						}
					}
				}
				if(i>=410 && i<430)
				{
					shiptype = 1 + 10 * (i % 3);
					if(shiptype==1 && race==1)
					{
						shiptype = 12;
					}
				}
				if(race==1)
				{
					if(placedgunship==0)
					{
						placedgunship=1;
						shiptype = 3;
					}
				}
				unitarray[i] = new Unit(shiptype,race,i);
				unitarray[i].ordertoy = -100;
				unitarray[i].firedelay = (float)i * 20.0f;
				unitarray[i].vx = 0f;
				unitarray[i].vy = 0f;
				unitarray[i].vz = 0.001f;
				unitarray[i].x = (float)random.NextDouble()*300 - 150f;
				unitarray[i].z = (float)random.NextDouble()*300 - 150f;
				unitarray[i].y = 3;
				unitarray[i].hp = 20;
				unitarray[i].basehp = 20;
				unitarray[i].maxvel = 1;
				unitarray[i].firerange = 75;
				unitarray[i].damage = 1;
				unitarray[i].firetime = 15;
				if(unitarray[i].firedelay>unitarray[i].firetime)
				{
					unitarray[i].firedelay = ship.random.Next(0,(int)unitarray[i].firetime+1);
				}
			}
			for(int i=0;i<maxunits;i++)
			{
				if(unitarray[i].race==2)
				{
					unitarray[i].hp = 0;
				}
				if(unitarray[i].race==1)
				{
					if(i>20 && unitarray[i].shiptype!=3)
					{
						unitarray[i].hp = 0;
					}
				}
			}
			for(int i=0;i<maxanimals;i++)
			{
				animals[i] = new Unit(-1,0,i,0);
				animals[i].ordertoy = -100;
				animals[i].vx = 0f;
				animals[i].vy = 0f;
				animals[i].vz = 0.001f;
				int its = 0;
				while(Math.Abs(animals[i].x)<175 && Math.Abs(animals[i].z)<175)
				{
					its++;
					if(its>100)
					{
						break;
					}
					animals[i].x = 2f*((float)random.NextDouble()*300 - 150f);
					animals[i].z = 2f*((float)random.NextDouble()*300 - 150f);
				}
				animals[i].ordertox = animals[i].x + (float)random.Next(-50,50);
				animals[i].ordertoz = animals[i].z + (float)random.Next(-50,50);
				animals[i].y = 3;
				animals[i].hp = 20;
				animals[i].basehp = 20;
				animals[i].maxvel = 1;
				animals[i].aframe = 598 + ship.random.Next(0,20);
				animals[i].amode = 1;
				
				
			}
		}
		
		public Unit(int shiptype, int race,int id,int dummy) //animal
		{
			xaxis = new Vector3(1,0,0);
			yaxis = new Vector3(0,1,0);
