			{
				animframes[j] = 1;
			}
			//model
			model = new Model[4000];
			vertices = new UnitVertices[4000];
			
			int found = 0;
			for(int i=0;i<id;i++)
			{
				if(animals[i].race==race && animals[i].shiptype==shiptype)
				{
					found = 1;
					diffuse = animals[i].diffuse;
					specular = animals[i].specular;
					texfile = animals[i].texfile;
					specfile = animals[i].specfile;
					noisetex = animals[i].noisetex;
					//envmap = animals[i].envmap;
