					{
						if(animframes[j]==1)
						{
							model[j] = animals[i].model[j];
							objfile[j] = animals[i].objfile[j];
							vertices[j] = animals[i].vertices[j];
						}
					}
					shader = animals[i].shader;
					break;
				}
			}
			if(found==0)
			{
				//diffuse = Raylib.LoadTexture("media/animal/diffuse.png");	
				diffuse = Program.atlas_diffuse;
				//UnloadHelper.AddTexture(diffuse);
				//specular = Raylib.LoadTexture("media/animals/specular.png");
				specular = Program.atlas_specular;
				//UnloadHelper.AddTexture(specular);
				noisetex = Raylib.LoadTexture("media/fx/noise.png");
				UnloadHelper.AddTexture(noisetex);
				//load the models...
				for(int j=0;j<1200;j++)
				{
					if(animframes[j]==1)
					{
						model[j] = Raylib.LoadModel("media/animal/_"+j+".obj");
						objfile[j] = "media/animal/_"+j+".obj";
						vertices[j] = new UnitVertices("media/animal/_"+j+".obj",0,0);
						UnloadHelper.AddModel(model[j]);
					}
				}
				texfile = "media/animal/diffuse.png";
				specfile = "media/animals/specular.png";
				shader = Raylib.LoadShader("media/shaders/basicvertexshaderwithextras.vs","media/shaders/diffusespecularpixelshader_withambientoption_a.fs");
				int debuglighting = Raylib.GetShaderLocation(shader,"debuglighting");
				int debugl = Program.debuglighting;
				unsafe
				{
					Raylib.SetShaderValueV(shader,debuglighting,&debugl,ShaderUniformDataType.Int,1);				
				}
			
				UnloadHelper.AddShader(shader);
			}
			ambientocclusion = Raylib.GetShaderLocation(shader,"ambientocclusion");
			shadertex0 = Raylib.GetShaderLocation(shader,"texture0");
			shadertex1 = Raylib.GetShaderLocation(shader,"texture1");
			shadertex2 = Raylib.GetShaderLocation(shader,"texture2");
			//shadertex3 = Raylib.GetShaderLocation(shader,"texture3");
			modelMatrix = Raylib.GetShaderLocation(shader,"modelMatrix");
			projectionMatrix = Raylib.GetShaderLocation(shader,"projectionMatrix");
			viewMatrix = Raylib.GetShaderLocation(shader,"viewMatrix");
			eyepos = Raylib.GetShaderLocation(shader,"eyepos");
			shadow = Raylib.GetShaderLocation(shader,"shadow");
			stype = Raylib.GetShaderLocation(shader,"stype");
			envmapping = Raylib.GetShaderLocation(shader,"debugenvmapping");
			groundfog = Raylib.GetShaderLocation(shader,"groundfog");
			fogr = Raylib.GetShaderLocation(shader,"fogr");
			fogg = Raylib.GetShaderLocation(shader,"fogg");
			fogb = Raylib.GetShaderLocation(shader,"fogb");
			foga = Raylib.GetShaderLocation(shader,"foga");
			healy = Raylib.GetShaderLocation(shader,"healy");//6aug2025
			muzzle = Raylib.GetShaderLocation(shader,"muzzle");
			if(atlas!=0)
			{
				shaderframe = Raylib.GetShaderLocation(shader,"shaderframe");
				shaderframespec = Raylib.GetShaderLocation(shader,"shaderframespec");
			}
			Raylib.SetShaderValueTexture(shader,shadertex0,diffuse);
			Raylib.SetShaderValueTexture(shader,shadertex1,specular);
			Raylib.SetShaderValueTexture(shader,shadertex2,noisetex);
			//now set the material to the shader....
			int ii = 0;
			unsafe
			{
				for(ii=0;ii<1200;ii++)
				{
					if(animframes[ii]==1)
					{
						model[ii].Materials[0].Shader = shader;
						Raylib.SetMaterialTexture(&model[ii].Materials[0], MaterialMapIndex.Albedo, diffuse);
						Raylib.SetMaterialTexture(&model[ii].Materials[0], MaterialMapIndex.Metalness, specular);
						Raylib.SetMaterialTexture(&model[ii].Materials[0], MaterialMapIndex.Normal, noisetex);
						//Raylib.SetMaterialTexture(&model[ii].Materials[0], MaterialMapIndex.Roughness, magenta);
					}
				}
			}
			Raylib.SetShaderValueTexture(shader,shadertex0,diffuse);
			Raylib.SetShaderValueTexture(shader,shadertex1,specular);
			Raylib.SetShaderValueTexture(shader,shadertex2,noisetex);
			//Raylib.SetShaderValueTexture(shader,shadertex3,magenta);
		}
		
		
