	class Scoring
	{
		public static long score;
		public static long highscore;
		public static long pointsperframe = 3 * (10000/3600);
		public static long pointsperbuild = -30 * (10000/3600);
		public static long pointsperdeath  = - 60 * (10000/3600);
		public static long pointsperbuilding  = -100 * (100000/3600);
		public static long pointsperpause = -1 * (10000/3600);
		public static long maxframes = 60*60*10;
		public static long frame;
		public static long gameover = 0;
		public static long maxscore;
	
		public static void EndGame()
		{
			frame  = maxframes + 1;
			if(score>highscore)
			{
				highscore = score;
				recordscore();
			}
		}
	
		public static void resetscore()
		{
			string txtscore = LocalStorage.getitem("highscore");
			if(txtscore=="")
			{
				txtscore = "0";
			}
			Int64.TryParse(txtscore,out highscore);
			score = 0;
			frame = 0;
			gameover = 0;
			pointsperframe = 3 * (10000/3600);
			pointsperbuild = -3000 * (10000/3600);
			pointsperdeath  = - 6000 * (10000/3600);
			pointsperbuilding  = -10000 * (10000/3600);
			pointsperpause = -1 * (10000/3600);
			maxscore = pointsperframe * maxframes * 10000;
		}
		
		public static void recordscore()
		{
			LocalStorage.setitem("highscore",""+highscore);
			LocalStorage.finalise();
		}
		
		
		public const int BUILD = 1;
		public const int DEATH = 2;
		public const int BUILDINGDIE = 3;
		
		public static string displayscore()
		{
			return "" + (score / 1000) + " / MAXIMUM: " + maxscore;
		}
		public static string displayhighscore()
		{
			return "" + (score/ 1000);
		}
		
		public static void addtoscore(int c)
		{
			long factor = 20;
			if(frame>=maxframes)
			{
				return;
			}
			switch(c)
			{
				case BUILD:
				score+=pointsperbuild*factor;
				break;
				case DEATH:
				score+=pointsperdeath*factor;
				break;
				case BUILDINGDIE:
				score+=pointsperbuilding*factor;
				break;
			}
		}
		
		public static void updatescore()
		{
			if(score<0)
			{
				score=0;
			}
			if(score>maxscore)
			{
				score = maxscore;
			}
			if(Program.substate==1)
			{
				return;
			}
			if(frame >= maxframes)
			{
				gameover++;
				if(gameover==1)
				{
					if(score>highscore)
					{
						highscore = score;
						recordscore();
					}
				}
				return;
			}
			if(Program.gamestate==Program.MENU || Program.togglepause==1)
			{
				score+=(long)((float)pointsperpause*ship.delta*100f);
			}
			else
			{
				score+=(long)((float)pointsperframe*ship.delta*100f);	
			}
		}
	}
	
	class Ground
	{
		public static float wsize = 650;
		public static int useshader = 1;
		public static Model model;
		public static Texture2D diffuse;
		public static Texture2D[] alt_diffuse;
		public static Texture2D snow;
		public static Texture2D noisetex;
		
		public static Shader shader;
		
