		public static void initground()
		{
			snow = Raylib.LoadTexture("media/ground/snow2ground.png");
			UnloadHelper.AddTexture(snow);
			noisetex = Raylib.LoadTexture("media/fx/noise.png");
			UnloadHelper.AddTexture(noisetex);
			diffuse = Raylib.LoadTexture("media/ground/groundmap2.png");
			UnloadHelper.AddTexture(diffuse);
			alt_diffuse = new Texture2D[4];
			for(int i=0;i<4;i++)
			{
				alt_diffuse[i] = Raylib.LoadTexture("media/ground/altdiffuse"+(i+1)+".png");
				texfile = "media/ground/altdiffuse"+(i+1)+".png";
				specfile = "";
				UnloadHelper.AddTexture(alt_diffuse[i]);
			}
			fogtex = Raylib.LoadTexture("media/ground/fog.png");
			UnloadHelper.AddTexture(fogtex);
			model = Raylib.LoadModel("media/ground/ground.obj");
			objfile = "media/ground/ground.obj";
			UnloadHelper.AddModel(model);
			fogmodel = Raylib.LoadModel("media/ground/fog.obj");
			UnloadHelper.AddModel(fogmodel);
			
			skymodel = Raylib.LoadModel("media/ground/sky2.obj");
			UnloadHelper.AddModel(skymodel);
			skydiffuse = Raylib.LoadTexture("media/ground/sky.png");
			//skydiffuse = Raylib.LoadTexture("media/fx/noise.png");
			UnloadHelper.AddTexture(skydiffuse);
			skyshader = Raylib.LoadShader("media/shaders/skyvshader.vs","media/shaders/skyfshader.fs");
			int debuglighting = Raylib.GetShaderLocation(skyshader,"debuglighting");
			int debugl = Program.debuglighting;
			unsafe
			{
				Raylib.SetShaderValueV(skyshader,debuglighting,&debugl,ShaderUniformDataType.Int,1);				
			}
			
			UnloadHelper.AddShader(skyshader);
			skymodelMatrix = Raylib.GetShaderLocation(skyshader,"modelMatrix");
			skyprojectionMatrix = Raylib.GetShaderLocation(skyshader,"projectionMatrix");
			skyviewMatrix = Raylib.GetShaderLocation(skyshader,"viewMatrix");
			skyshadertex0 =  Raylib.GetShaderLocation(skyshader,"texture0");
			skyfogr = Raylib.GetShaderLocation(skyshader,"fogr");
			skyfogg = Raylib.GetShaderLocation(skyshader,"fogg");
			skyfogb = Raylib.GetShaderLocation(skyshader,"fogb");
			skyfoga = Raylib.GetShaderLocation(skyshader,"foga");
			skystep = Raylib.GetShaderLocation(skyshader,"skystep");
			unsafe
			{
				skymodel.Materials[0].Shader = skyshader;
				Raylib.SetMaterialTexture(&skymodel.Materials[0], MaterialMapIndex.Albedo, skydiffuse);
			}
			Raylib.SetShaderValueTexture(skyshader,skyshadertex0,skydiffuse);
				
				
			if(useshader!=0)
			{
				if(Program.foliagenoise==1)
				{
					shader = Raylib.LoadShader("media/shaders/basicvertexshadersnowing.vs","media/shaders/diffusepixelshader_withambientoption_withnoise2a.fs");
					int sdebuglighting = Raylib.GetShaderLocation(shader,"debuglighting");
					int sdebugl = Program.debuglighting;
					unsafe
					{
						Raylib.SetShaderValueV(shader,sdebuglighting,&sdebugl,ShaderUniformDataType.Int,1);				
					}
			
				}
				else
				{
					shader = Raylib.LoadShader("media/shaders/basicvertexshadersnowing.vs","media/shaders/diffusepixelshader_withambientoption2.fs");
				}
				UnloadHelper.AddShader(shader);
				fogshader = Raylib.LoadShader("media/shaders/basicvertexshadersnowing.vs","media/shaders/diffusepixelshader_withambientoption.fs");
				UnloadHelper.AddShader(fogshader);
				
				ambientocclusion = Raylib.GetShaderLocation(shader,"ambientocclusion");
				shadertex0 = Raylib.GetShaderLocation(shader,"texture0");
				shadertex1 = Raylib.GetShaderLocation(shader,"texture1");
				shadertex2 = Raylib.GetShaderLocation(shader,"texture2");
				modelMatrix = Raylib.GetShaderLocation(shader,"modelMatrix");
				projectionMatrix = Raylib.GetShaderLocation(shader,"projectionMatrix");
				viewMatrix = Raylib.GetShaderLocation(shader,"viewMatrix");
				snowing = Raylib.GetShaderLocation(shader,"snowing");
				shadow = Raylib.GetShaderLocation(shader,"shadow");
				eyepos = Raylib.GetShaderLocation(shader,"eyepos");
				groundfog = Raylib.GetShaderLocation(shader,"groundfog");
				fogr = Raylib.GetShaderLocation(shader,"fogr");
				fogg = Raylib.GetShaderLocation(shader,"fogg");
				fogb = Raylib.GetShaderLocation(shader,"fogb");
				foga = Raylib.GetShaderLocation(shader,"foga");
				fogambientocclusion = Raylib.GetShaderLocation(fogshader,"ambientocclusion");
				fogshadertex0 = Raylib.GetShaderLocation(fogshader,"texture0");
				fogmodelMatrix = Raylib.GetShaderLocation(fogshader,"modelMatrix");
				fogprojectionMatrix = Raylib.GetShaderLocation(fogshader,"projectionMatrix");
				fogviewMatrix = Raylib.GetShaderLocation(fogshader,"viewMatrix");
				fogsnowing = Raylib.GetShaderLocation(fogshader,"snowing");

				unsafe
				{
					model.Materials[0].Shader = shader;
					Raylib.SetMaterialTexture(&model.Materials[0], MaterialMapIndex.Albedo, diffuse);
					Raylib.SetMaterialTexture(&model.Materials[0], MaterialMapIndex.Metalness, snow);
					Raylib.SetMaterialTexture(&model.Materials[0], MaterialMapIndex.Normal, noisetex);
				}
				Raylib.SetShaderValueTexture(shader,shadertex0,diffuse);
				Raylib.SetShaderValueTexture(shader,shadertex1,snow);
				Raylib.SetShaderValueTexture(shader,shadertex2,noisetex);
				//fog
				unsafe
				{
					fogmodel.Materials[0].Shader = fogshader;
					Raylib.SetMaterialTexture(&fogmodel.Materials[0], MaterialMapIndex.Albedo, fogtex);
				}
				Raylib.SetShaderValueTexture(fogshader,fogshadertex0,fogtex);
			}
		}		
	
		public static void SwitchTexture(int i)
		{
			unsafe
			{
				Raylib.SetMaterialTexture(&model.Materials[0], MaterialMapIndex.Albedo, alt_diffuse[i]);
			}
			Raylib.SetShaderValueTexture(shader,shadertex0,alt_diffuse[i]);
		}
	
		public static void SwitchTexture()
		{
			int i = ship.random.Next(0,5);
			if(i==4)
			{
				unsafe
				{
					Raylib.SetMaterialTexture(&model.Materials[0], MaterialMapIndex.Albedo, diffuse);
				}
				Raylib.SetShaderValueTexture(shader,shadertex0,diffuse);
			}
			else
			{
				unsafe
				{
					Raylib.SetMaterialTexture(&model.Materials[0], MaterialMapIndex.Albedo, alt_diffuse[i]);
				}
				Raylib.SetShaderValueTexture(shader,shadertex0,alt_diffuse[i]);
			}
		}
	}
	
	class UnloadHelper
	{
		public static Model[] models = new Model[10000];
		public static int maxmodels = 0;
		public static Shader[] shaders = new Shader[10000];
		public static int maxshaders = 0;
		public static Texture2D[] textures = new Texture2D[10000];
		public static int maxtextures;
		public static Sound[] sounds = new Sound[10000];
		public static int maxsounds;
		
		public static Font[] fonts = new Font[10000];
		public static int maxfonts;
		
		public static void AddFont(Font font)
		{
			fonts[maxfonts] = font;
			maxfonts++;
		}
		
		public static void AddModel(Model model)
		{
			models[maxmodels] = model;
			maxmodels++;
		}
		
		public static void AddSound(Sound sound)
		{
			sounds[maxsounds] = sound;
			maxsounds++;
		}
		
		
		public static void AddShader(Shader shader)
		{
			shaders[maxshaders] = shader;
			maxshaders++;
		}
		
		public static void AddTexture(Texture2D texture)
		{
			textures[maxtextures] = texture;
			maxtextures++;
		}
		public static void UnloadAll()
		{
			for(int i = 0;i<maxmodels;i++)
			{
				Raylib.UnloadModel(models[i]);
			}
			for(int i=0;i<maxshaders;i++)
			{
				Raylib.UnloadShader(shaders[i]);
			}
			for(int i=0;i<maxtextures;i++)
			{
				Raylib.UnloadTexture(textures[i]);
			}
			for(int i=0;i<maxsounds;i++)
			{
				Raylib.UnloadSound(sounds[i]);
			}
			for(int i=0;i<maxfonts;i++)
			{
				Raylib.UnloadFont(fonts[i]);
			}
		}
	}
	
	public class RTSInput
	{
		public static int audioplayed = 0;
		public static float smx;
		public static float smy;
		public static float fmx;
		public static float fmy;
		
		public static int mousestate = 0;
		
		public static int[] selectedunits;
		public static float MOUSEOVERCHECKFRAME;
		public static int previousid = -1;
		
		
		public static int mouseoverunit(Camera3D camera)
		{
			MOUSEOVERCHECKFRAME+=ship.delta;
			if(MOUSEOVERCHECKFRAME>30)
			{
				MOUSEOVERCHECKFRAME = 0;
			}
			else
			{
				return previousid;
			}
			int id = -1;
			float mindist = 1000f;
			Vector2 mousepos = new Vector2(Raylib.GetMouseX(),Raylib.GetMouseY());
			for(int i=0;i<Unit.maxunits;i++)
			{
				if(Unit.unitarray[i].hp>0 && Unit.unitarray[i].race==1 && Unit.unitarray[i].shiptype!=3)
				{
					Vector3 pos = new Vector3(Unit.unitarray[i].x,Unit.unitarray[i].y,Unit.unitarray[i].z);
					Vector2 screenpos = Raylib.GetWorldToScreen(pos, camera);
					float dist = Raymath.Vector2Distance(screenpos,mousepos);
					if(dist < 100)
					{
						//we're moderately close to a unit.....
						if(Unit.unitarray[i].vertices!=null)
						{
							int animframe = (int)Unit.unitarray[i].aframe;
							float msc = Unit.GetUnitScale(i);
							float angle = Unit.unitarray[i].angle;
							if(Unit.unitarray[i].shiptype==1)
							{
								if(animframe>920 && animframe<1020)
								{
									animframe-=animframe%=10;
								}
								if(animframe>=465 && animframe <=520)
								{
									animframe-=animframe%5;
								}
							}
							if(Unit.unitarray[i].shiptype==11)
							{
								if(animframe>10 && animframe<90)
								{
									animframe-=animframe%=5;
								}
								
							}
							if(Unit.unitarray[i].shiptype==21)
							{
								if(animframe>920 && animframe<1010)
								{
									animframe-=animframe%=10;
								}
								
							}
							if(Unit.unitarray[i].shiptype==2 || Unit.unitarray[i].shiptype==4 || Unit.unitarray[i].shiptype==12)
							{
								animframe = 0;
							}
									
							if(Unit.unitarray[i].vertices[animframe]!=null)
							{
								UnitVertices tmp = Unit.unitarray[i].vertices[animframe];
								if(tmp!=null)
								{
									if(tmp.Vertices!=null)
									{
										for(int v=0;v<tmp.Vertices.Length;v++)
										{
											Vector3 vertex = tmp.Vertices[v];
											//rotate this vertex around the y axis.....
											//and scale it depending on the type of unit
											vertex = Raymath.Vector3RotateByAxisAngle(vertex, new Vector3(0,1,0), angle);
											vertex = Raymath.Vector3Scale(vertex,msc);
											vertex = Raymath.Vector3Add(vertex,pos);
											Vector2 vscreenpos = Raylib.GetWorldToScreen(vertex, camera);
											dist = Raymath.Vector2Distance(vscreenpos,mousepos);
											if(dist<25 && dist<mindist)
											{
												mindist = dist;
												id = i;
												if(dist<5)
												{
													break;	
												}
											}
										}
									}
								}
							}
						}
					}							
				}
			}
			previousid = id;
			if(id!=-1)
			{
				Unit.WaveHelloMaybe(id);
			}
			if(id==-1)
			{
				//maybe we're over a building?
				for(int i=0;i<Building.maxbuildings;i++)
				{
					if(Building.buildingarray[i].hp>0)
					{
						if(Building.buildingarray[i].vertices!=null)
						{
							float msc = 7.5f*0.85f;
							{
								UnitVertices tmp = Building.buildingarray[i].vertices;
								if(tmp!=null)
								{
									if(tmp.Vertices!=null)
									{
										Vector3 pos = new Vector3(Building.buildingarray[i].x,Building.buildingarray[i].y,Building.buildingarray[i].z);
										for(int v=0;v<tmp.Vertices.Length;v++)
										{
											Vector3 vertex = tmp.Vertices[v];
											//rotate this vertex around the y axis.....
											//and scale it depending on the type of unit
											//vertex = Raymath.Vector3RotateByAxisAngle(vertex, new Vector3(0,1,0), angle);
											vertex = Raymath.Vector3Scale(vertex,msc);
											vertex = Raymath.Vector3Add(vertex,pos);
											Vector2 vscreenpos = Raylib.GetWorldToScreen(vertex, camera);
											float dist = Raymath.Vector2Distance(vscreenpos,mousepos);
											if(dist<25 && dist<mindist)
											{
												//Audio.Notification();
												mindist = dist;
												id = i;
												if(dist<5)
												{
													break;	
												}
											}
										}
									}
								}
							}
						}
					}
				}
				if(id!=-1)
				{
					previousid = id;
				}
			}
			
			return id;
		}
		
		public static void querymousetargetenemy(Camera3D camera)
		{
			
			int id = -1;
			//look through all the units nearby...and transform their vertices....
			//and see if any of THESE are closer....
			float mindist = 1000f;
			Vector2 mousepos = new Vector2(Raylib.GetMouseX(),Raylib.GetMouseY());
			for(int i=0;i<Unit.maxunits;i++)
			{
				if(Unit.unitarray[i].hp>0 && Unit.unitarray[i].race==2)
				{
					Vector3 pos = new Vector3(Unit.unitarray[i].x,Unit.unitarray[i].y,Unit.unitarray[i].z);
					Vector2 screenpos = Raylib.GetWorldToScreen(pos, camera);
					float dist = Raymath.Vector2Distance(screenpos,mousepos);
					if(dist < 250)
					{
						//we're moderately close to a unit.....
						if(Unit.unitarray[i].vertices!=null)
						{
							int animframe = (int)Unit.unitarray[i].aframe;
							float msc = Unit.GetUnitScale(i);
							float angle = Unit.unitarray[i].angle;
							if(Unit.unitarray[i].shiptype==1)
							{
								if(animframe>920 && animframe<1020)
								{
									animframe-=animframe%=10;
								}
								if(animframe>=465 && animframe <=520)
								{
									animframe-=animframe%5;
								}
							}
							
							if(Unit.unitarray[i].shiptype==11)
							{
								if(animframe>=10 && animframe <=90)
								{
									animframe-=animframe%5;
								}
							}
							if(Unit.unitarray[i].shiptype==21)
							{
								if(animframe>=920 && animframe <=1010)
								{
									animframe-=animframe%10;
								}
							}
							if(Unit.unitarray[i].shiptype==2 || Unit.unitarray[i].shiptype==4 || Unit.unitarray[i].shiptype==12)
							{
								animframe = 0;
							}
									
							if(Unit.unitarray[i].vertices[animframe]!=null)
							{
								UnitVertices tmp = Unit.unitarray[i].vertices[animframe];
								if(tmp!=null)
								{
									if(tmp.Vertices!=null)
									{
										for(int v=0;v<tmp.Vertices.Length;v++)
										{
											Vector3 vertex = tmp.Vertices[v];
											//rotate this vertex around the y axis.....
											//and scale it depending on the type of unit
											vertex = Raymath.Vector3RotateByAxisAngle(vertex, new Vector3(0,1,0), angle);
											vertex = Raymath.Vector3Scale(vertex,msc);
											vertex = Raymath.Vector3Add(vertex,pos);
											Vector2 vscreenpos = Raylib.GetWorldToScreen(vertex, camera);
											dist = Raymath.Vector2Distance(vscreenpos,mousepos);
											if(dist<25 && dist<mindist)
											{
												Audio.Notification();
												mindist = dist;
												id = i;
												if(dist<5)
												{
													break;	
												}
											}
										}
									}
								}
							}
						}
					}							
				}
			}
			if(id!=-1)
			{
				//yep we clicked on an enemy unit.......
				//therefore.....
				//tell all the selected units to target this enemy.....
				for(int i=0;i<selectedunits.Length;i++)
				{
					int j = selectedunits[i];
					if(j!=-1)
					{
						if(Unit.unitarray[j].hp>0 && Unit.unitarray[j].race==1 && Unit.unitarray[j].shiptype!=3)
						{
							Unit.unitarray[j].targetj = id;
							GameUI.SetMouseTargetType(GameUI.TARGETFIRE);
							GameUI.SetMouseTargetXZ(-1000,id);
							Unit.unitarray[j].distj[id] = -1;
							Vector3 tpos = new Vector3(Unit.unitarray[id].x,0,Unit.unitarray[id].z);
							Vector3 spos = new Vector3(Unit.unitarray[j].x,0,Unit.unitarray[j].z);
							float tdist = Raymath.Vector3Distance(tpos,spos);
							Vector3 ndirn = Raymath.Vector3Subtract(tpos,spos);
							if(tdist > Unit.unitarray[j].firerange)
							{
								ndirn = Raymath.Vector3Scale(Raymath.Vector3Normalize(ndirn),tdist - Unit.unitarray[j].firerange);
								spos = Raymath.Vector3Add(spos,ndirn);
								Unit.unitarray[j].ordertox = spos.X;
								Unit.unitarray[j].ordertoz = spos.Z;
								
							}
							
						}
					}
				}
			}
		}
		
		public static void updatemouse(Camera3D camera)
		{
			if(GameUI.rclick!=0)//Raylib.IsMouseButtonReleased(MouseButton.Right))
			{
				//check if an enemy unit is underneath our mouse position.....
				Unit.prioritytarget = selectenemy(camera);
				if(selectedunits!=null)
				{
					if(Unit.unitarray[selectedunits[0]].race==1)
					{
						float tx = (float)Raylib.GetMouseX();
						float ty = (float)Raylib.GetMouseY();
						orderunits(ScreenToWorldX(camera,tx,ty),ScreenToWorldZ(camera,tx,ty));
						//We should check if there is an enemy unit beneath this position....
						//
						//
						//
						querymousetargetenemy(camera);
						Audio.Click();
					}
				}
			}
			
			if(GameUI.lclick!=0)//Raylib.IsMouseButtonReleased(MouseButton.Left))
			{
				if(Program.briefingframe<=0 && GameUI.NoDeselect==0){selectunits(camera);}
				mousestate = 0;
				smx = 0;
				smy = 0;
				fmx = 0;
				fmy = 0;
			}
			else
			{
				if(GameUI.ldown!=0 && GameUI.JustClickedSelectionIcon>=0)//Raylib.IsMouseButtonDown(MouseButton.Left))
				{
					fmx = (int)Raylib.GetMouseX();
					fmy = (int)Raylib.GetMouseY();
					if(Program.briefingframe<=0 && GameUI.NoDeselect==0){selectunits(camera);}
					mousestate = 1;
					
				}
			}
			if(mousestate==0)
			{
				smx = (int)Raylib.GetMouseX();
				smy = (int)Raylib.GetMouseY();
				fmx = smx;
				fmy = smy;
				audioplayed = 0;
			}
		}
		
