			}
			selectedunits = null;
		}
		
		public static void orderunits(float tmx,float tmz)
		{
			if(Program.briefingframe>0)
			{
				return;
			}
			
			if(selectedunits!=null)
			{
				for(int i=0;i<selectedunits.Length;i++)
				{
					if(Unit.unitarray[selectedunits[i]].hp>0 && Unit.unitarray[selectedunits[i]].race==1 && Unit.unitarray[selectedunits[i]].shiptype!=3)
					{
						Unit.unitarray[selectedunits[i]].commanddelay = 0;
						Unit.unitarray[selectedunits[i]].patrol = 0;
						Unit.unitarray[selectedunits[i]].disperse = 0;
						Unit.unitarray[selectedunits[i]].ordertoy = -90;
						Unit.unitarray[selectedunits[i]].orderframe = 300;
						Unit.unitarray[selectedunits[i]].ordertox = tmx;
						Unit.unitarray[selectedunits[i]].ordertoz = tmz;
						Unit.unitarray[selectedunits[i]].ordertime = 120;
						Unit.unitarray[selectedunits[i]].targetid = Unit.prioritytarget;
						Unit.unitarray[selectedunits[i]].targetj = -2;
						Unit.unitarray[selectedunits[i]].worktype = 0;
						Unit.unitarray[selectedunits[i]].working = 0;
						if(Unit.unitarray[selectedunits[i]].leader!=-1) //if we give an order to a squad, also give the order to the squad leader
						{
							int li = Unit.unitarray[selectedunits[i]].leader;
							if(Unit.unitarray[li].hp>0 && Unit.unitarray[li].race==1 && Unit.unitarray[li].shiptype!=3)
							{
								//the rest of the squad will follow if we do this as the sergeant moves
								Unit.unitarray[li].commanddelay = 0;
								Unit.unitarray[li].patrol = 0;
								Unit.unitarray[li].disperse = 0;
								Unit.unitarray[li].ordertoy = -90;
								Unit.unitarray[li].orderframe = 300;
								Unit.unitarray[li].ordertox = tmx;
								Unit.unitarray[li].ordertoz = tmz;
								Unit.unitarray[li].ordertime = 120;
								Unit.unitarray[li].targetid = Unit.prioritytarget;
								Unit.unitarray[li].targetj = -2;
								Unit.unitarray[li].worktype = 0;
								Unit.unitarray[li].working = 0;
							}
						}
						GameUI.SetMouseTargetType(GameUI.TARGETMOVE);
						GameUI.SetMouseTargetXZ(tmx,tmz);
						if(Unit.unitarray[selectedunits[i]].shiptype%10==1 && audioplayed==0)
						{
							//audioplayed = 1;
							//Audio.MoveInfantry();
						}
						if(i==0 && audioplayed==0)
						{
							audioplayed = 1;
							int id = selectedunits[i];
							Audio.CalculateDistanceMultiplier(Program.demomode,Unit.unitarray[id].x,Unit.unitarray[id].y,Unit.unitarray[id].z);
							switch(Unit.unitarray[id].shiptype%10)
							{
								case 1: //infantry
									switch(Unit.unitarray[id].soldiertype)
									{
										case 0: //normal
											Audio.PlayUnitSound(Audio.INF,Audio.MOV);
										break;
										case Unit.MEDIC:
											Audio.PlayUnitSound(Audio.MED,Audio.MOV);
										break;
										case Unit.ENGINEER:
											Audio.PlayUnitSound(Audio.ENG,Audio.MOV);
										break;
										case Unit.SERGEANT:
											Audio.PlayUnitSound(Audio.SGT,Audio.MOV);
										break;
										case Unit.HEAVY:
											Audio.PlayUnitSound(Audio.HVY,Audio.MOV);
										break;
									}
								break;
								case 2://hover tank
									Audio.PlayUnitSound(Audio.TNK,Audio.MOV);
								break;
								case 4://tank
									Audio.PlayUnitSound(Audio.TNK,Audio.MOV);
								break;
								case 5://walker
									Audio.PlayUnitSound(Audio.WLK,Audio.MOV);
								break;
							}
							Audio.distance_multiplier = 1;
						}					
					}
				}
			}
		}
		
		public static float ScreenToWorldX(Camera3D camera,float x,float y)
		{
			Vector2 mpos = new Vector2(x,y);
			float mindist = 10000;
			float X = 0;
			float Z = 0;
			float wx = 0;
			float wz = 0;
			for(wx=-700;wx<700;wx+=30)
			{
				for (wz=-700;wz<700;wz+=30)
				{
					Vector2 screenpos = Raylib.GetWorldToScreen(new Vector3(wx,0,wz), camera);
					float dist = Raymath.Vector2Distance(mpos,screenpos);
					if(dist<mindist)
					{
						X = wx;
						Z = wz;
						mindist = dist;
					}
				}
			}
			mindist = 10000;
			wx = X;
			wz = Z;
			for(float wxx=wx-60;wxx<wx+60;wxx+=3)
			{
				for (float wzz=wz-60;wzz<wz+60;wzz+=3)
				{
					Vector2 screenpos = Raylib.GetWorldToScreen(new Vector3(wxx,0,wzz), camera);
					float dist = Raymath.Vector2Distance(mpos,screenpos);
					if(dist<mindist)
					{
						X = wxx;
						Z = wzz;
						mindist = dist;
					}
				}
			}
			
			return X;
		}
		
