		public static void drawselection(Camera3D camera)
		{
			//updatemouse should have been called.....
			if(smx!=fmx && smy!=fmy)
			{
				int tsmx = (int)smx;
				int tsmy = (int)smy;
				if(tsmx>fmx)
				{
					tsmx = (int)fmx;
				}
				if(tsmy>fmy)
				{
					tsmy = (int)fmy;
				}
				int tw = (int)Math.Abs(fmx-smx);
				int th = (int)Math.Abs(fmy-smy);
				for(int d=0;d<3;d++)
				{
					Raylib.DrawRectangleLines((int)tsmx - d + 5, (int)tsmy - d - 20, (int)(tw) + 2*d, (int)(th) + 2*d , Color.Green);
				}
				if(tw>100 || th>100)
				{
					GameUI.NoExitToMenu = 1;
				}
			}
		}
		
		public static int selectenemy(Camera3D camera)
		{
			//i don't think this function is used anymore...or even called...
			Vector2 mousepos = new Vector2(Raylib.GetMouseX(),Raylib.GetMouseY());
			int id = -1;
			//if(selectedunits==null) //if we have nothing selected currently...
			{
				float mindist = 1000;
				for(int i=0;i<Unit.maxunits;i++)
				{
					if(Unit.unitarray[i].hp>0 && Unit.unitarray[i].race==2 && Unit.unitarray[i].shiptype==1)
					{
						Vector2 screenpos = Raylib.GetWorldToScreen(Unit.unitarray[i].pos, camera);
						screenpos.Y-=25;
						float dist = Raymath.Vector2Distance(screenpos,mousepos);
						if(dist<mindist && (dist < 50 || (dist < 80 && (Unit.unitarray[i].shiptype==2 || Unit.unitarray[i].shiptype==4 || Unit.unitarray[i].shiptype==6))))
						{
							mindist = dist;
							id = i;
						}
					}
				}
				if(id==-1)
				{
					mindist = 1000;
					for(int i=0;i<Unit.maxunits;i++)
					{
						if(Unit.unitarray[i].hp>0 && Unit.unitarray[i].race==2 && (Unit.unitarray[i].shiptype==2 || Unit.unitarray[i].shiptype==4 || Unit.unitarray[i].shiptype==6))
						{
							Vector2 screenpos = Raylib.GetWorldToScreen(Unit.unitarray[i].pos, camera);
							screenpos.Y-=25;
							float dist = Raymath.Vector2Distance(screenpos,mousepos);
							if(dist<mindist && (dist < 30 || (dist < 80 && (Unit.unitarray[i].shiptype==2 || Unit.unitarray[i].shiptype==4 || Unit.unitarray[i].shiptype==6))))
							{
								mindist = dist;
								id = i;
							}
						}
					}
				}
			}
			if(id!=-1)
			{
				Audio.Click();
			}
			return id;
		}
		
		public static void selectunits(Camera3D camera)
		{
				//single click or close to it....
				if(GameUI.lclick!=0)//Raylib.IsMouseButtonPressed(MouseButton.Left))
				{
					GameUI.eselect = -1;	
					Vector2 mousepos = new Vector2(Raylib.GetMouseX(),Raylib.GetMouseY());
					int id = -1;
					
					//look through all the units nearby...and transform their vertices....
					//and see if any of THESE are closer....
					float mindist = 1000f;
					for(int i=0;i<Unit.maxunits;i++)
					{
						if(Unit.unitarray[i].shiptype!=3 && Unit.unitarray[i].hp>0 && Unit.unitarray[i].race==1)// && Unit.unitarray[i].shiptype!=12)
						{
							Vector3 pos = new Vector3(Unit.unitarray[i].x,Unit.unitarray[i].y,Unit.unitarray[i].z);
							Vector2 screenpos = Raylib.GetWorldToScreen(pos, camera);
							float dist = Raymath.Vector2Distance(screenpos,mousepos);
							if(dist < 250)
							{
								//we're moderately close to a unit.....
								if(Unit.unitarray[i].vertices!=null)
								{
									int animframe = (int)Unit.unitarray[i].aframe;
									float msc = Unit.GetUnitScale(i);
									float angle = Unit.unitarray[i].angle;
									if(Unit.unitarray[i].shiptype==1)
									{
										if(animframe>920 && animframe<1020)
										{
											animframe-=animframe%=10;
										}
										if(animframe>=465 && animframe <=520)
										{
											animframe-=animframe%5;
										}
									}
									if(Unit.unitarray[i].shiptype==11)
									{
										if(animframe>=10 && animframe <=90)
										{
											animframe-=animframe%5;
										}
									}
									
									if(Unit.unitarray[i].shiptype==21)
									{
										if(animframe>=920 && animframe <=1010)
										{
											animframe-=animframe%10;
										}
									}
									if(Unit.unitarray[i].shiptype==2 || Unit.unitarray[i].shiptype==4 || Unit.unitarray[i].shiptype==12)
									{
										animframe = 0;
									}
									if(Unit.unitarray[i].vertices[animframe]!=null)
									{
										UnitVertices tmp = Unit.unitarray[i].vertices[animframe];
										if(tmp!=null)
										{
											if(tmp.Vertices!=null)
											{
												for(int v=0;v<tmp.Vertices.Length;v++)
												{
													Vector3 vertex = tmp.Vertices[v];
													//rotate this vertex around the y axis.....
													//and scale it depending on the type of unit
													vertex = Raymath.Vector3RotateByAxisAngle(vertex, new Vector3(0,1,0), angle);
													vertex = Raymath.Vector3Scale(vertex,msc);
													vertex = Raymath.Vector3Add(vertex,pos);
													Vector2 vscreenpos = Raylib.GetWorldToScreen(vertex, camera);
													dist = Raymath.Vector2Distance(vscreenpos,mousepos);
													if(dist<25 && dist<mindist)
													{
														Audio.Notification();
														mindist = dist;
														id = i;
														if(dist<5)
														{
															break;	
														}
													}
												}
											}
										}
									}
								}
							}							
						}
					}
					if(id==-1)//now let's do the same but for enemies.....
					{
						//why do enemies - because we might want to see their info.....
						mindist = 1000f;
						for(int i=0;i<Unit.maxunits;i++)
						{
							if(Unit.unitarray[i].shiptype!=3 && Unit.unitarray[i].hp>0 && Unit.unitarray[i].race==2 && Unit.unitarray[i].shiptype!=12)
							{
								Vector3 pos = new Vector3(Unit.unitarray[i].x,Unit.unitarray[i].y,Unit.unitarray[i].z);
								Vector2 screenpos = Raylib.GetWorldToScreen(pos, camera);
								float dist = Raymath.Vector2Distance(screenpos,mousepos);
								if(dist < 250)
								{
									//we're moderately close to a unit.....
									if(Unit.unitarray[i].vertices!=null)
									{
										int animframe = (int)Unit.unitarray[i].aframe;
										float msc = Unit.GetUnitScale(i);
										float angle = Unit.unitarray[i].angle;
										if(Unit.unitarray[i].shiptype==1)
										{
											if(animframe>920 && animframe<1020)
											{
												animframe-=animframe%=10;
											}
											if(animframe>=465 && animframe <=520)
											{
												animframe-=animframe%5;
											}
										}
										if(Unit.unitarray[i].shiptype%10>1 && Unit.unitarray[i].shiptype!=6)
										{
											animframe = 0;
										}
										if(Unit.unitarray[i].shiptype==11)
										{
											if(animframe>=10 && animframe <=90)
											{
												animframe-=animframe%5;
											}
										}
										if(Unit.unitarray[i].shiptype==21)
										{
											if(animframe>=920 && animframe <=1010)
											{
												animframe-=animframe%10;
											}
										}
										if(Unit.unitarray[i].vertices[animframe]!=null)
										{
											UnitVertices tmp = Unit.unitarray[i].vertices[animframe];
											if(tmp!=null)
											{
												if(tmp.Vertices!=null)
												{
													for(int v=0;v<tmp.Vertices.Length;v++)
													{
														Vector3 vertex = tmp.Vertices[v];
														//rotate this vertex around the y axis.....
														//and scale it depending on the type of unit
														vertex = Raymath.Vector3RotateByAxisAngle(vertex, new Vector3(0,1,0), angle);
														vertex = Raymath.Vector3Scale(vertex,msc);
														vertex = Raymath.Vector3Add(vertex,pos);
														Vector2 vscreenpos = Raylib.GetWorldToScreen(vertex, camera);
														dist = Raymath.Vector2Distance(vscreenpos,mousepos);
														if(dist<25 && dist<mindist)
														{
															Audio.Notification();
															mindist = dist;
															id = i;
															if(dist<5)
															{
																break;	
															}
														}
													}
												}
											}
										}
									}
								}							
							}
						}
						if(id!=-1)
						{
							//we've picked an enemy....do things slightly differently from here...
							if(selectedunits==null)
							{
								GameUI.eselect = id;
								Audio.Click();	
								//GameUI.lclick = 0;
								//GameUI.drawingabox = 0;
								return;
							}
						}
					}				
					if(id==-1)
					{
						mindist = 1000;
						for(int i=0;i<Unit.maxunits;i++)
						{
							if(Unit.unitarray[i].shiptype!=3 && Unit.unitarray[i].hp>0 && Unit.unitarray[i].race==1 && Unit.unitarray[i].shiptype%10==1)// && Unit.unitarray[i].shiptype!=12)
							{
								Vector2 screenpos = Raylib.GetWorldToScreen(Unit.unitarray[i].pos, camera);
								screenpos.Y-=25;
								float dist = Raymath.Vector2Distance(screenpos,mousepos);
								if(dist<mindist && (dist < 50 || (dist < 80 && Unit.unitarray[i].shiptype==2)))
								{
									mindist = dist;
									id = i;
								}
							}
						}
						if(id==-1)
						{
							mindist = 1000;
							for(int i=0;i<Unit.maxunits;i++)
							{
								//if(Unit.unitarray[i].shiptype!=12 && Unit.unitarray[i].shiptype!=3 && Unit.unitarray[i].hp>0 && Unit.unitarray[i].race==1 && (Unit.unitarray[i].shiptype==2 || Unit.unitarray[i].shiptype==5))
								if(Unit.unitarray[i].shiptype!=3 && Unit.unitarray[i].hp>0 && Unit.unitarray[i].race==1 && (Unit.unitarray[i].shiptype==2 || Unit.unitarray[i].shiptype==5))
								{
									Vector2 screenpos = Raylib.GetWorldToScreen(Unit.unitarray[i].pos, camera);
									screenpos.Y-=25;
									float dist = Raymath.Vector2Distance(screenpos,mousepos);
									if(dist<mindist && (dist < 30 || (dist < 80 && (Unit.unitarray[i].shiptype==2 || Unit.unitarray[i].shiptype==5))))
									{
										mindist = dist;
										id = i;
									}
								}
							}
						}
					}
					if(id!=-1)
					{
						selectedunits = new int[1];
						selectedunits[0] = id;
						Audio.Click();
						Unit.WaveHello(id);
						Audio.CalculateDistanceMultiplier(Program.demomode,Unit.unitarray[id].x,Unit.unitarray[id].y,Unit.unitarray[id].z);
						switch(Unit.unitarray[id].shiptype%10)
						{
							case 1: //infantry
								if(Unit.unitarray[id].shiptype>1)
								{
									if(Unit.unitarray[id].shiptype==11)
									{
										Audio.CalculateDistanceMultiplier(Program.demomode,Unit.unitarray[id].x,Unit.unitarray[id].y,Unit.unitarray[id].z);
										Audio.PlayUnitSound(Audio.SGT,Audio.SEL);
										Audio.distance_multiplier = 1;
									}
									if(Unit.unitarray[id].shiptype==21)
									{
										Audio.CalculateDistanceMultiplier(Program.demomode,Unit.unitarray[id].x,Unit.unitarray[id].y,Unit.unitarray[id].z);
										Audio.PlayUnitSound(Audio.HVY,Audio.SEL);
										Audio.distance_multiplier = 1;
									}
								}
								else
								{
									Audio.CalculateDistanceMultiplier(Program.demomode,Unit.unitarray[id].x,Unit.unitarray[id].y,Unit.unitarray[id].z);
									switch(Unit.unitarray[id].soldiertype)
									{
										case 0: //normal
											Audio.PlayUnitSound(Audio.INF,Audio.SEL);
										break;
										case Unit.MEDIC:
											Audio.PlayUnitSound(Audio.MED,Audio.SEL);
										break;
										case Unit.ENGINEER:
											Audio.PlayUnitSound(Audio.ENG,Audio.SEL);
										break;
										case Unit.SERGEANT:
											Audio.PlayUnitSound(Audio.SGT,Audio.SEL);
										break;
										case Unit.HEAVY:
											Audio.PlayUnitSound(Audio.HVY,Audio.SEL);
										break;
									}
									Audio.distance_multiplier = 1;
								}
							break;
							case 2://hover tank
								Audio.PlayUnitSound(Audio.TNK,Audio.SEL);
							break;
							case 4://tank
								Audio.PlayUnitSound(Audio.TNK,Audio.SEL);
							break;
							case 5://walker
								Audio.PlayUnitSound(Audio.WLK,Audio.SEL);
							break;
							case 12://sentry gun
								Audio.PlayUnitSound(Audio.WLK,Audio.SEL);
							break;
						}
						Audio.distance_multiplier = 1;
					}
					if(id==-1)
					{
						//maybe we clicked a building.....
						//but make sure we're not over any buttons......
						for(int i=0;i<Building.maxbuildings;i++)
						{
							if(Building.buildingarray[i].hp>0)
							{
								if(Building.buildingarray[i].selected!=0)
								{
									if(GameUI.NoDeselect==1)
									{
										return;
									}
								}
							}
						}
						for(int i=0;i<Building.maxbuildings;i++)
						{
							Building.buildingarray[i].selected = 0;
							if(Building.buildingarray[i].hp>0)
							{
								//we're moderately close to a unit.....
								if(Building.buildingarray[i].vertices!=null)
								{
									float msc = 7.5f*0.85f;
									{
										UnitVertices tmp = Building.buildingarray[i].vertices;
										if(tmp!=null)
										{
											if(tmp.Vertices!=null)
											{
												Vector3 pos = new Vector3(Building.buildingarray[i].x,Building.buildingarray[i].y,Building.buildingarray[i].z);
												for(int v=0;v<tmp.Vertices.Length;v++)
												{
													Vector3 vertex = tmp.Vertices[v];
													//rotate this vertex around the y axis.....
													//and scale it depending on the type of unit
													//vertex = Raymath.Vector3RotateByAxisAngle(vertex, new Vector3(0,1,0), angle);
													vertex = Raymath.Vector3Scale(vertex,msc);
													vertex = Raymath.Vector3Add(vertex,pos);
													Vector2 vscreenpos = Raylib.GetWorldToScreen(vertex, camera);
													float dist = Raymath.Vector2Distance(vscreenpos,mousepos);
													if(dist<25 && dist<mindist)
													{
														Audio.Notification();
														mindist = dist;
														id = i;
														if(dist<5)
														{
															break;	
														}
													}
												}
											}
										}
									}
								}
							}
						}
						if(id!=-1)
						{
							RTSInput.selectedunits = null;
							Building.buildingarray[id].selected = 1;
						}
					}
				}
			if(smx!=fmx && smy!=fmy)
			{
				int ucount = 0;
				float tsmx = smx;
				float tsmy = smy;
				float tfmx = fmx;
				float tfmy = fmy;
				if(smx>fmx)
				{
					tsmx = fmx;
					tfmx = smx;
				}
				if(smy>fmy)
				{
					tsmy = fmy;
					tfmy = smy;
				}
				for(int i=0;i<Unit.maxunits;i++)
				{
					if(Unit.unitarray[i].hp<=0 && (Unit.unitarray[i].aframe>=259 && Unit.unitarray[i].aframe<270 && Unit.unitarray[i].shiptype==1) || Unit.unitarray[i].amode==100)
					{
						continue;
					}
					if(Unit.unitarray[i].shiptype==3 || Unit.unitarray[i].shiptype==12)
					{
						continue;
					}
					if(Unit.unitarray[i].hp>0 && Unit.unitarray[i].race==1)
					{
						//get world screen
						Vector3 position = new Vector3(Unit.unitarray[i].x,Unit.unitarray[i].y,Unit.unitarray[i].z);
						Vector2 screenpos = Raylib.GetWorldToScreen(position, camera);
						if(screenpos.X >= tsmx && screenpos.X <=tfmx && screenpos.Y >= tsmy && screenpos.Y <= tfmy)
						{
							ucount++;
						}
					}
				}
				if(ucount>0)
				{
					
					if(ucount>Unit.MAXSELECT) //maximum selectionsize
					{
						ucount = Unit.MAXSELECT;
					}
					selectedunits = new int[ucount];
					int uindex = 0;
					for(int i=0;i<Unit.maxunits;i++)
					{
						if(Unit.unitarray[i].shiptype==3 || Unit.unitarray[i].shiptype==12)
						{
							continue;
						}
						if(Unit.unitarray[i].hp>0 && Unit.unitarray[i].race==1)
						{
							//get world screen
							Vector3 position = new Vector3(Unit.unitarray[i].x,Unit.unitarray[i].y,Unit.unitarray[i].z);
							Vector2 screenpos = Raylib.GetWorldToScreen(position, camera);
							if(screenpos.X >= tsmx && screenpos.X <=tfmx && screenpos.Y >= tsmy && screenpos.Y <= tfmy)
							{
								selectedunits[uindex] = i;
								if(uindex==0 && audioplayed==0)
								{
									audioplayed = 1;
									Audio.CalculateDistanceMultiplier(Program.demomode,Unit.unitarray[i].x,Unit.unitarray[i].y,Unit.unitarray[i].z);
									switch(Unit.unitarray[i].shiptype%10)
									{
										case 1: //infantry
											if(Unit.unitarray[i].shiptype>1)
											{
												if(Unit.unitarray[i].shiptype==11)
												{
													Audio.PlayUnitSound(Audio.SGT,Audio.SEL);
												}
												else
												{
													Audio.PlayUnitSound(Audio.HVY,Audio.SEL);
												}
											}
											else											
											{
												switch(Unit.unitarray[i].soldiertype)
												{
													case 0: //normal
														Audio.PlayUnitSound(Audio.INF,Audio.SEL);
													break;
													case Unit.MEDIC:
													Audio.PlayUnitSound(Audio.MED,Audio.SEL);
													break;
													case Unit.ENGINEER:
													Audio.PlayUnitSound(Audio.ENG,Audio.SEL);
													break;
													case Unit.SERGEANT:
													Audio.PlayUnitSound(Audio.SGT,Audio.SEL);
													break;
													case Unit.HEAVY:
													Audio.PlayUnitSound(Audio.HVY,Audio.SEL);
													break;
												}
											}
										break;
										case 2://hover tank
										Audio.PlayUnitSound(Audio.TNK,Audio.SEL);
										break;
										case 4://tank
										Audio.PlayUnitSound(Audio.TNK,Audio.SEL);
										break;
										case 5://walker
										Audio.PlayUnitSound(Audio.WLK,Audio.SEL);
										break;
									}
									Audio.distance_multiplier = 1;
								}
								uindex++;
								if(uindex>=ucount)
								{
									break;
								}
							}
						}
					}
				}
				else
				{
					selectedunits = null;
				}
			}
			if(Program.togglepause!=0)
			{
				for(int i=0;i<Unit.maxunits;i++)
				{
					Unit.unitarray[i].selected = 0;
				}
				if(selectedunits!=null)
				{
					for(int j=0;j<selectedunits.Length;j++)
					{
						if(Unit.unitarray[selectedunits[j]].race==1)
						{
							Unit.unitarray[selectedunits[j]].selected = 1;
						}
					}	
				}
			}
		}
		
	}
	
