		public static void DrawText(string txt,int x,int y,int fontsize,Color c)
		{
			if(language=="" || language=="en")
			{
				if(Program.textbk==1)
				{
					Raylib.DrawText(txt,x+1,y+1,fontsize,new Color(0,0,0,(int)c.A));
				}
				Raylib.DrawText(txt,x,y,fontsize,c);
			}
			else
			{
				if(Translation.ready==0)
				{
					Translation.init(Program.fontfile,"media/txt/"+language+".txt");
					gamefont = Translation.myfont;
					smallfont = smallfont + RescaleY(5);
					normalfont = normalfont + RescaleY(8);
					largefont = largefont + RescaleY(14);
					
				}
				txt = Translation.translate(txt);
				if(Program.textbk==1)
				{
					Raylib.DrawTextEx(gamefont,txt,new Vector2(x+1,y+1),fontsize,fontsize/8,new Color(0,0,0,(int)c.A));
				}
				Raylib.DrawTextEx(gamefont,txt,new Vector2(x,y),fontsize,fontsize/8,c);
			}
		}
