		public static void CommsDamage()
		{
			for(int i=0;i<Building.maxbuildings;i++)
			{
				if(Building.buildingarray[i].category==Building.SPACECOMMS)
				{
					float pct = Building.buildingarray[i].hp / Building.buildingarray[i].basehp;
					if(pct < ship.random.NextDouble())
					{
						//draw static
						Raylib.DrawTextureEx(whitenoise2[ship.random.Next(0,8)],new Vector2(RescaleX(1200),RescaleY(815)),0,gscale,Color.White);						
					}
				}
			}
		}
		
		public static void SetMouseTargetXZ(float x,float z)
		{
			targetx = x;
			targetz = z;
			targetj = -1;
			if(x==-1000 && (int)z>=0 && (int)z<Unit.maxunits)
			{
				targetj = (int)z;
			}
		}
		
		public static void SetMouseTargetType(int i)
		{
			targettime = 90;
			targettype = i;
			targetx = -1000;
			targetz = -1000;
			if(targettype>2)
			{
				targettype = 0;
			}
			if(targettype<0)
			{
				targettype = 0;
			}
			if(targettype==0)
			{
				targettime = 5;
			}
		}
		
		public static void DoMouseTarget(Camera3D camera)
		{
			//in groundbattle
			int mx = Raylib.GetMouseX();
			int my = Raylib.GetMouseY();
			if(targettime>0)
			{
				targettime-=ship.delta*2f;
			}
			else
			{
				targettype = -1;
				targetj = -1;
			}
			float tmx = -1000;
			float tmy = -1000;
			if(targetx>-1000 && targetz>-1000)
			{
				Vector2 tm = Raylib.GetWorldToScreen(new Vector3(targetx,0.01f,targetz),camera);
				tmx = tm.X;
				tmy = tm.Y;
			}
			if(targetj!=-1)
			{
				Vector2 tm = Raylib.GetWorldToScreen(new Vector3(Unit.unitarray[targetj].x,0.01f,Unit.unitarray[targetj].z),camera);
				tmx = tm.X;
				tmy = tm.Y;
			}
			if(targettime<=0)
			{
				switch(targettype)
				{
					case TARGET:
					Raylib.DrawTextureEx(targetmouse,new Vector2(mx-32f*gscale,my-32f*gscale),0,0.5f*gscale,Color.White);
					break;
					case TARGETFIRE:
					Raylib.DrawTextureEx(targetfire,new Vector2(tmx-32*gscale,tmy-32*gscale),0,0.5f*gscale,Color.White);
					targettype = TARGETMOVE;
					break;
					case TARGETMOVE:
					Raylib.DrawTextureEx(targetmove,new Vector2(tmx-32*gscale,tmy-32*gscale),0,0.5f*gscale,Color.White);
					break;
				}
			}
			else
			{
				Vector2 v2 = new Vector2(mx,my);
				if(targettype!=TARGET)
				{
					v2 = new Vector2(tmx,tmy);
				}
				float scalef = 0.95f + 0.25f * (float)Math.Sin(Program.gametimer.ElapsedMilliseconds/120);
				v2.X -= 32f*scalef;
				v2.Y -= 32f*scalef;
				switch(targettype)
				{
					case TARGET:
					Raylib.DrawTextureEx(targetmouse,v2,0,0.5f*gscale*scalef,Color.White);
					break;
					case TARGETFIRE:
					Raylib.DrawTextureEx(targetfire,v2,0,0.5f*gscale*scalef,Color.White);
					break;
					case TARGETMOVE:
					Raylib.DrawTextureEx(targetmove,v2,0,0.5f*gscale*scalef,Color.White);
					break;
				}
				
			}
		}
		
		
		public static void doupgrade()
		{
			if(Program.togglepause!=0)
			{
				return;
			}
			if(Building.IsCategoryAlive(Building.SCIENCEFACILITY)==0)
			{
				return;
			}
			if(upgradeselected!=-1)
			{
				upgradepercent[upgradeselected]+=upgraderate*(1.0f - (float)upgradelevel[upgradeselected]*0.125f);//6aug2025
				int olevel = upgradelevel[upgradeselected];
				if(upgradepercent[upgradeselected]>100)
				{
					upgradepercent[upgradeselected] = 0;
					upgradelevel[upgradeselected]++;
					if(olevel==4)
					{
						Audio.VoiceNotify(Audio.ALERT_RESEARCHCOMPLETE);
					}
				}
				
				if(upgradelevel[upgradeselected]>4)
				{
					upgradepercent[upgradeselected] = 0;
					upgradelevel[upgradeselected] = 5;
				}
			}
		}
		
