		public static void drawminimap(Vector2 mouseposa)
		{
			if(Program.gamestate!=Program.GROUNDBATTLE)
			{
				return;
			}
			float actualx = -1000;
			float actualy = -1000;
			Raylib.DrawTextureEx(minimap,new Vector2(RescaleX(minimap_x),RescaleY(minimap_y)),0,1*gscale,Color.White);
			if(ship.random.NextDouble()<GameUI.radardamage) //radardamage goes from 0 to 1 //added at library
			{
				//draw static.......
				Raylib.DrawTextureEx(whitenoise[ship.random.Next(0,8)],new Vector2(RescaleX(minimap_x),RescaleY(minimap_y)),0,1*gscale,Color.White); //have to draw static texture first....
				return;
			}
			int cx = RescaleX(minimap_x) + RescaleX(165); //centre of the minimap
			int cy = RescaleY(minimap_y) + RescaleY(165);
			{
				int gmx = Raylib.GetMouseX() - RescaleX(minimap_x);
				int gmy = Raylib.GetMouseY() - RescaleY(minimap_y);
				if(gmx>=0 && gmy>=0 && gmx<RescaleX(330) && gmy<RescaleY(330))
				{
					gmx-=RescaleX(165);
					gmy-=RescaleY(165);
					actualy = 0.5f*(gmx+gmy);
					actualx = 0.5f*(gmx-gmy);
					//now scale it up....
					actualx*=4f;
					actualy*=4f;
					//now tell the camera to go this spot.....
					if(GameUI.ldown!=0)
					{
						if(Math.Abs(actualx)<450 && Math.Abs(actualy)<450)
						{
							GameUI.cameramovetox = actualx;
							GameUI.cameramovetoz = actualy;
							GameUI.cameramoveto = 1;
							GameUI.lclick = 0;
						}
					}
					if(GameUI.rclick!=0)
					{
						if(Math.Abs(actualx)<450 && Math.Abs(actualy)<450)
						{
							if(RTSInput.selectedunits!=null)
							{
								RTSInput.orderunits(actualx,actualy);
								GameUI.rclick = 0;
							}
						}
					}
				}
			}
			//place the trees on the map....need a special array for this....
			//place the buildings on the map....
			for(int i=0;i<Building.maxbuildings;i++)
			{
				if(Building.buildingarray[i].hp>0)
				{
					float x = Building.buildingarray[i].x;
					float y = Building.buildingarray[i].z;
					//rotate by 45 degrees around the cx/cz
					//and scale it as well.....
					//so first of all scale it to fit within a region that is 300x300*0.333 square....
					x*=0.185f;
					y*=0.185f;
					//now rotate it by 45 degrees around the cx/cy position....
					float nx = (cx + RescaleX(x + y));
					float ny = (cy + RescaleY(y - x));
					Raylib.DrawRectangle((int)nx-3,(int)ny-3,6,6,Color.White);
				}
			}
			//place the units on the map...
			for(int i=0;i<Unit.maxunits;i++)
			{
				if(Unit.unitarray[i].hp>0)
				{
					float x = Unit.unitarray[i].x;
					float y = Unit.unitarray[i].z;
					x*=0.185f;
					y*=0.185f;
					float nx = (cx + RescaleX(x + y));
					float ny = (cy + RescaleY(y - x));
					if(Math.Abs(x+y)<130 && Math.Abs(y-x)<130)
					{
						int aw = 0;
						if(Unit.unitarray[i].ping>0)
						{
							aw = 16 - ((int)((Unit.unitarray[i].ping*6))%181)/15; //ping goes from 0 to 180
						}
						if(Unit.unitarray[i].race==1)
						{
							Raylib.DrawRectangle((int)nx,(int)ny,4,4,Color.Green);
							if(Unit.unitarray[i].ping>0)
							{
								Raylib.DrawRectangleLines((int)nx-aw,(int)ny-aw,4+aw*2,4+aw*2,Color.Green);
							}
						}
						if(Unit.unitarray[i].race==2)
						{
							Raylib.DrawRectangle((int)nx,(int)ny,4,4,Color.Red);
							if(Unit.unitarray[i].ping>0)
							{
								Raylib.DrawRectangleLines((int)nx-aw,(int)ny-aw,4+aw*2,4+aw*2,Color.Red);
							}
						}
						if(Unit.unitarray[i].ping>0)
						{
							Unit.unitarray[i].ping-=ship.delta;
						}
					}
				}
			}
			if(Math.Abs(actualx)<450 && Math.Abs(actualy)<450)
			{
				float zf = 0.75f*Program.ZOOM / 45f;
				int minx = Raylib.GetMouseX() - RescaleX((int)(80f*zf));
				int miny = Raylib.GetMouseY() - RescaleY((int)(80f*zf));
				int widthx = (int)RescaleX(160f*zf);
				int heighty = (int)RescaleY(160f*zf);
				int lx = RescaleX(minimap_x + 36);
				int ly = RescaleY(minimap_y + 36);
				int rx = RescaleX(minimap_x) +  (int)(330f*gscale) - RescaleX(32);//RescaleX(minimap_x + (160f*0.75f) - 26);
				int ry = RescaleY(minimap_y) +  (int)(330f*gscale) - RescaleY(32);//RescaleY(minimap_y + (160f*0.75f) - 26);
				Color cc = Color.White;
				if(minx<lx)
				{
					minx = lx;
				}
				if(miny<ly)
				{
					miny = ly;
				}
				if(minx + widthx > rx)
				{
					minx = rx - widthx;
				}
				if(miny + heighty > ry)
				{
					miny = ry - heighty;
				}
				Raylib.DrawRectangleLines(minx,miny,widthx,heighty,cc);
				GameUI.NoMoveCam = 1;
			}
		}
		
		public static void handleupgrade(Vector2 mouseposa)
		{
			GameUI.NoMoveCam = 0;
			if(Building.IsCategoryAlive(Building.SCIENCEFACILITY,1)==0)
			{
				return;
			}
			for(int i=0;i<10;i++)
			{
				if(upgradename[i]!="")
				{
					Raylib.DrawTextureEx(button01,new Vector2(RescaleX(upgrade_x[i]),RescaleY(upgrade_y[i])),0,0.33f*gscale,Color.White);
					if(mouseposa.X > upgrade_x[i] && mouseposa.X < upgrade_x[i] + upgrade_w[i] && mouseposa.Y > upgrade_y[i] && mouseposa.Y < upgrade_y[i] + upgrade_h[i])
					{
						if(GameUI.lpress!=0)
						{
							GameUI.mpressxy = upgrade_x[i] + upgrade_y[i]*1920;
						}
						GameUI.NoMoveCam = 1;
						GameUI.NoDeselect = 1;
						Raylib.DrawTextureEx(button01a,new Vector2(RescaleX(upgrade_x[i]),RescaleY(upgrade_y[i])),0,0.33f*gscale,Color.White);
						if(lclick!=0 || Raylib.IsMouseButtonReleased(MouseButton.Left))
						{
							if(GameUI.mpressxy==upgrade_x[i] + upgrade_y[i]*1920)
							{
								Audio.Click();
								upgradeselected = i;
								lclick = 0;
							}
						}
						//show research message "info about the research" //6aug2025 //remember to add in the translation texts.
						if(GameUI.upgradelevel[i]<5)
						{
							GameUI.portraiton = GameUI.researchportraitid;
							GameUI.portraittime = 120;
							switch(i)
							{
								case upgrade_basic_training:
								GameUI.portraitmsg = "More Survivable Infantry";
								break;
								case upgrade_better_ammo:
								GameUI.portraitmsg = "Increased Infantry Damage";
								break;
								case upgrade_bigger_ammo_belt:
								GameUI.portraitmsg = "More Ammo For Infantry";
								break;
								case upgrade_build_rate:
								GameUI.portraitmsg = "Upgrade Production Rate";
								break;
								case upgrade_eng_range:
								GameUI.portraitmsg = "Upgrade Engineer Repair Range";
								break;
								case upgrade_firing_range:
								GameUI.portraitmsg = "Upgrade Unit Firing Range";
								break;
								case upgrade_improved_armour:
								GameUI.portraitmsg = "Upgrade Infantry Armour";
								break;
								case upgrade_tank_armour:
								GameUI.portraitmsg = "Upgrade Tank Armour";
								break;
								case upgrade_medic_range:
								GameUI.portraitmsg = "Upgrade Medic Healing Range";
								break;
							}
							settooltip(GameUI.portraitmsg);
						}
					}
					Raylib.DrawRectangle(RescaleX(upgrade_x[i]+10),RescaleY(upgrade_y[i]+upgrade_h[i]-84),RescaleX((int)(upgradepercent[i])*0.8f),RescaleY(20),Color.SkyBlue);
					if(upgradelevel[i]<5)
					{
						GameUI.DrawText(Translation.translate("Level:")+upgradelevel[i],RescaleX(upgrade_x[i]+25),RescaleY(upgrade_y[i]+10),normalfont,Color.White);
						
						GameUI.DrawText(""+((int)upgradepercent[i])+"%",RescaleX(upgrade_x[i]+25),RescaleY(upgrade_y[i]+upgrade_h[i]-60),normalfont,Color.White);
					}
					else
					{
						GameUI.DrawText("Max. Level",RescaleX(upgrade_x[i]+17),RescaleY(upgrade_y[i]+10),normalfont,Color.White);						
						
					}
					GameUI.DrawText(upgradename[i],RescaleX(upgrade_x[i]+12),RescaleY(upgrade_y[i]+upgrade_h[i]-30),smallfont,Color.White);
				}
			}
		}
		
		public static void resetupgrades()
		{
			RTSInput.selectedunits = null;
			eselect = -1;
			fighterbuild = 0;
			tanktreadimprove = 0;
			fasterdropship = 0;
			mechupgrade = 0;
			bomberbuild = 0;
			cruiserbuild = 0;
			infantrybuild = 0;
			tankbuild = 0;
			mechbuild = 0;
			requestdropship = 0;
			requestairstrike = 0;//17aug2025
			buildfighters = 0;
			buildbombers = 0;
			buildcruisers = 0;
			buildinfantry = 0;
			buildassaultinfantry = 0;
			builddefenders = 0;
			buildtank = 0;
			buildmech = 0;
			upgradeselected = -1;
			for(int i=0;i<10;i++)
			{
				upgrade_x[i] = 1570 + 110 * (i % 3);
				upgrade_y[i] = 705 + 110 * ((i - (i % 3))/3);
				upgrade_w[i] = 110;
				upgrade_h[i] = 110;
				upgradepercent[i] = 0;
				upgradelevel[i] = 0;
				upgradename[i] = "";
				switch(i)
				{
					case upgrade_basic_training:
					upgradename[i] = Translation.translate("Training")+" ";
					break;
					case upgrade_better_ammo:
					upgradename[i] = Translation.translate("Damage") + " ";
					break;
					case upgrade_bigger_ammo_belt:
					upgradename[i] = Translation.translate("Ammo") + " ";
					break;
					case upgrade_firing_range:
					upgradename[i] = Translation.translate("Range") + " ";
					break;
					case upgrade_improved_armour:
					upgradename[i] = Translation.translate("Armour") + " ";
					break;
					case upgrade_eng_range:
					upgradename[i] = Translation.translate("Engineer") + " ";
					break;
					case upgrade_medic_range:
					upgradename[i] = Translation.translate("Medic") + " ";
					break;
					case upgrade_build_rate:
					upgradename[i] = Translation.translate("Build Rate") + " ";
					break;
					case upgrade_tank_armour:
					upgradename[i] = Translation.translate("Tank Armor") + " ";
					break;
					/*
					case 7:
					
					break;
					case 8:
					
					break;
					case 9:
					
					break;
					*/
				}
			}
		}
		
		
