		public static void DoToolTips()
		{
			if(tooltiptime<=0)
			{
				return;
			}
			Raylib.DrawRectangle((int)GameUI.RescaleX(tooltip_x),(int)GameUI.RescaleY(tooltip_y),(int)RescaleX(tooltip_w),(int)RescaleY(tooltip_h),new Color(0,0,0,(int)((128.0f*tooltiptime)/120f)));	
			GameUI.DrawText(tooltip,GameUI.RescaleX(tooltip_x + 10),RescaleY(tooltip_y + 10),smallfont,new Color(255,255,255,(int)((255.0f*tooltiptime)/120f)));
		}
		
		public static void Messages()
		{
			if(tooltiptime>0)
			{
				tooltiptime-=ship.delta*2.0f;
			}
			
			if(Program.briefingframe > 200 && Program.briefingframe < 60 * 19 && Program.gamestate==Program.GROUNDBATTLE)
			{
				Raylib.DrawTextureEx(briefing, new Vector2(GameUI.RescaleX(Program.resx/2-50),GameUI.RescaleY(Program.resy/2)-80),0,gscale,Color.White);
				
			}
			if(Program.togglepause==1 && Program.gamestate!=Program.MENU)
			{
				GameUI.DrawText("Paused",Program.resx/2 - 50*3,Program.resy/2,50,Color.White);

			}
			if(Program.GuiFlashOnRelease(1,Program.medic_release,Program.gametimer.ElapsedMilliseconds)==1 && Program.gamestate==Program.GROUNDBATTLE)
			{
				portraittime = 360;
				portraitmsg = "Medical Units Researched";
			}
			if(Program.GuiFlashOnRelease(1,Program.engineer_release,Program.gametimer.ElapsedMilliseconds)==1 && Program.gamestate==Program.GROUNDBATTLE)
			{
				portraittime = 360;
				portraitmsg = "Engineering Units Researched";
			}
			if(Program.GuiFlashOnRelease(1,Program.heavy_release,Program.gametimer.ElapsedMilliseconds)==1 && Program.gamestate==Program.GROUNDBATTLE)
			{
				portraittime = 360;
				portraitmsg = "Anti Tank Personnel Researched";
			}
			if(Program.GuiFlashOnRelease(1,Program.sergeant_release,Program.gametimer.ElapsedMilliseconds)==1 && Program.gamestate==Program.GROUNDBATTLE)
			{
				portraittime = 360;
				portraitmsg = "Leadership Skill Researched";
			}
			if(Program.GuiFlashOnRelease(1,Program.hovertank_release,Program.gametimer.ElapsedMilliseconds)==1 && Program.gamestate==Program.GROUNDBATTLE)
			{
				portraittime = 360;
				portraitmsg = "Hovertanks Researched";
			}
			if(Program.GuiFlashOnRelease(1,Program.walker_release,Program.gametimer.ElapsedMilliseconds)==1 && Program.gamestate==Program.GROUNDBATTLE)
			{
				portraittime = 360;
				portraitmsg = "WarMachines Researched";
			}
			if(Program.GuiFlashOnRelease(1,Program.transport_release,Program.gametimer.ElapsedMilliseconds)==1 && Program.gamestate==Program.GROUNDBATTLE)
			{
				portraittime = 360;
				portraitmsg = "Troop Transports Available";
			}
			if((Program.gamestate==Program.GROUNDBATTLE ))// || portraiton>=3)
			{
				int showportrait = 0;
				if(RTSInput.selectedunits!=null && portraitmsg=="" && EasterEggTime<=0)
				{
					portraiton = 0;
					for(int j=0;j<RTSInput.selectedunits.Length;j++)
					{
						int uu = RTSInput.selectedunits[j];
						if(Unit.unitarray[uu].hp>0 && Unit.unitarray[uu].race==1)
						{
							showportrait = 1;
							if(Unit.unitarray[uu].shiptype==1 && portraiton==0)
							{
								portraiton = 0;
							}
							if(Unit.unitarray[uu].shiptype==11 && portraiton<1)
							{
								portraiton = 1;
							}
							if(Unit.unitarray[uu].shiptype==21 && portraiton<2)
							{
								portraiton = 2;
							}
							if(Unit.unitarray[uu].soldiertype>0 && portraiton<1)
							{
								portraiton = 1;
							}
							if(Unit.unitarray[uu].soldiertype==Unit.SERGEANT && portraiton<2)
							{
								portraiton = 2;
							}
							if(Unit.unitarray[uu].shiptype==2 && portraiton<3)
							{
								portraiton = 3;
							}
							if(Unit.unitarray[uu].shiptype==5 && portraiton<4)
							{
								portraiton = 4;
								break;
							}
						}
					}
				}
				if(portraiton>4 && portraiton<researchportraitid)
				{
					portraiton%=5; //12
				}
				if((((portraiton>=0 && portraiton<5) || portraiton>=researchportraitid) && (portraitmsg!="" || showportrait!=0)) || EasterEggTime>0)
				{
					portraitframe+=0.2f*ship.delta;
					if(portraiton>=researchportraitid)
					{
						portraitframe+=0.2f*ship.delta;
					}
					if(portraiton<3)
					{
						if(portraitframe>28)
						{
							portraitframe=0;
						}
					}
					if(portraiton>=3 && portraiton<=4)
					{
						if(portraitframe>19)
						{
							portraitframe = 0;
						}
					}
					if(portraiton>4 && portraiton<10)
					{
						if(portraitframe>19)
						{
							portraitframe = 0;
						}
					}
					
					int frame = (int)portraitframe + portraiton * 29;
					int x = frame % 10;
					int y = (frame - (frame % 10))/10;
					x*=150;
					y*=225;
					if(portraiton>=3 && portraiton<=4)
					{
						frame = (int)portraitframe + (portraiton-3) * 20;
						x = frame % 8;
						y = (frame - (frame % 8))/8;
						x*=150;
						y*=225;
					}
					if(portraiton>4)
					{
						frame = (int)portraitframe;// + portraiton * 20;
						x = frame % 8;
						y = (frame - (frame % 8))/8;
						x*=150;
						y*=225;
					}
					if(portraiton>=researchportraitid)
					{
						if(portraitframe>127)
						{
							portraitframe = 0;
						}
						frame = (int)portraitframe;// + portraiton * 20;
						x = frame % 12;
						y = (frame - (frame % 12))/12;
						x*=150;
						y*=225;
					}
					Rectangle src = new Rectangle(x+4,y+4,150-8,225-8);
					if(EasterEggTime>0)
					{
						portraiton = 1;
						portraitframe = 441.0f*((float)(EasterEggTime)/(60f*90f));
						if(portraitframe>441)
						{
							portraitframe = 0;
						}
						frame = (int)portraitframe;// + portraiton * 20;
						x = frame % 21;
						y = (frame - (frame % 21))/21;
						x*=160;
						y*=90;
						portraitmsg = "All your base, are belong to us!";
						if(EasterEggTime>0)
						{
							EasterEggTime++;
						}
						if(Program.fps<60 && EasterEggTime>0)
						{
							EasterEggTime++;
						}
						if(Program.fps<30 && EasterEggTime>0)
						{
							EasterEggTime++;
						}
						if(EasterEggTime>60*90)
						{
							EasterEggTime = -1; //never play again during this session...
						}
						src = new Rectangle(x,y,160,90);
					}
					
					int px = 345;
					int py = 810;
					if(Program.gamestate!=Program.MENU)
					{
						if(oportraiton>-30 && EasterEggTime<=0)
						{
							oportraiton--;
							if(portraitframe>7)
							{
								portraitframe = 0;
							}
							frame = (int)portraitframe;// + portraiton * 20;
							x = frame % 8;
							y = 0;
							x*=150;
							y*=225;
							src = new Rectangle(x,y,150,225);
							Raylib.DrawTexturePro(portraitnoise,src,new Rectangle(RescaleX(px),RescaleY(py),RescaleX(150),RescaleY(225)),new Vector2(0,0),0,Color.White);
						}
						else
						{
							if(portraiton<3)
							{
								if(EasterEggTime>0)
								{
									px = 1200;
									py = 820;
									Raylib.DrawTexturePro(EasterEggAnim,src,new Rectangle(RescaleX(px),RescaleY(py),RescaleX(352),RescaleY(198)),new Vector2(0,0),0,Color.White);
								}
								else
								{
									Raylib.DrawTexturePro(portrait,src,new Rectangle(RescaleX(px),RescaleY(py),RescaleX(150),RescaleY(225)),new Vector2(0,0),0,Color.White);
								}
							}
							else
							{
								if(portraiton<5)
								{
									Raylib.DrawTexturePro(portrait2,src,new Rectangle(RescaleX(px),RescaleY(py),RescaleX(150),RescaleY(225)),new Vector2(0,0),0,Color.White);
								}
								else
								{
									if(portraiton==researchportraitid)
									{
										Raylib.DrawTexturePro(research,src,new Rectangle(RescaleX(px),RescaleY(py),RescaleX(150),RescaleY(225)),new Vector2(0,0),0,Color.White);
									}
									if(portraiton==starshipportraitid)
									{
										Raylib.DrawTexturePro(starship,src,new Rectangle(RescaleX(px),RescaleY(py),RescaleX(150),RescaleY(225)),new Vector2(0,0),0,Color.White);
									}
									if(portraiton==waveportraitid)
									{
										Raylib.DrawTexturePro(wave,src,new Rectangle(RescaleX(px),RescaleY(py),RescaleX(150),RescaleY(225)),new Vector2(0,0),0,Color.White);
									}
								}
							}
						}
						if(portraitmsg!=""){GameUI.DrawText(portraitmsg,GameUI.RescaleX(350),GameUI.RescaleY(750),GameUI.largefont,Color.LightGray);}
						if(portraittime<=0)
						{
							portraittime = 360;
						}
						else
						{
							portraittime-=ship.delta;
							if(portraittime<=0)
							{
								portraitmsg = "";
								oportraiton = -1;
							}
						}
					}
				}
				else
				{
					portraitmsg = "";
					oportraiton = -1;
					{GameUI.DrawText("F5 to toggle Ground View",GameUI.RescaleX(350),GameUI.RescaleY(750),GameUI.largefont,Color.LightGray);}
						
				}
			}
			Raylib.DrawTextureEx(GameUI.button02,new Vector2(GameUI.RescaleX(10),GameUI.RescaleY(20)),0,0.33f*GameUI.gscale*2,Color.White);
			if(GameUI.survivaltime!="") //survival time
			{
				GameUI.DrawText(GameUI.survivaltime,GameUI.RescaleX(40),GameUI.RescaleY(60),GameUI.largefont,Color.LightGray);
			}
			else
			{
				GameUI.DrawText("Welcome to Conflict 3049",GameUI.RescaleX(40),GameUI.RescaleY(60),GameUI.largefont,Color.LightGray);
				
			}
			if(GameUI.msg!="" && GameUI.msgtime>0) //ship created etc
			{
				string msg = GameUI.msg;
				GameUI.DrawText(msg,GameUI.RescaleX(40),GameUI.RescaleY(90),GameUI.largefont,Color.LightGray);
			}
			if(GameUI.killcount>0)//17aug2025
			{
				GameUI.DrawText("Kills:",GameUI.RescaleX(240),GameUI.RescaleY(60),GameUI.largefont,Color.LightGray);
				GameUI.DrawText(""+GameUI.killcount,GameUI.RescaleX(330),GameUI.RescaleY(60),GameUI.largefont,Color.LightGray);
			}
			if(Program.gamestate == Program.MENU)
			{
				return;
			}
			int offy1 = 0;
			if(Program.deploying>0)
			{
				offy1 = 30;
				GameUI.DrawText("Enemy Troops Deploying",GameUI.RescaleX(40),GameUI.RescaleY(120),GameUI.largefont,Color.LightGray);
			}
			if(Program.orbitalbombardment>0)
			{
				GameUI.DrawText("Orbital Bombardment",GameUI.RescaleX(40),GameUI.RescaleY(120+offy1),GameUI.largefont,Color.LightGray);
			}
			if(GameUI.sandbox!=0)
			{
				GameUI.DrawText("This is SANDBOX mode.",GameUI.RescaleX(40),GameUI.RescaleY(120+offy1),GameUI.largefont,Color.LightGray);				
			}
			if(Profile.debugon!=0){GameUI.DrawText(""+Program.fps,GameUI.RescaleX(40),GameUI.RescaleY(300),GameUI.smallfont,Color.LightGray);}
			
		}
		
