		public static void BuildShip(int shiptype)
		{
			for(int i=0;i<ship.maxships;i++)
			{
				if(ship.shiparray[i].hp<=0 && ship.shiparray[i].race==1 && ship.shiparray[i].shiptype==shiptype)
				{
					ship.shiparray[i].hp = ship.shiparray[i].basehp ; // spawns back to life.
					GameUI.msgtime = 120;
					switch(shiptype)
					{
						case 1:
						GameUI.msg = "Cruiser Launched";
						flyby.x[0] = -3000;
						flyby.z[0] = -1000;
						if(GameUI.portraitmsg=="")
						{
							GameUI.portraitmsg = "Battle cruiser entering sector.";
							GameUI.portraiton = GameUI.starshipportraitid;
						}
						break;
						case 2:
						GameUI.msg = "Fighter Launched";
						flyby.x[1] = -2900;
						flyby.z[1] = -1000;
						if(GameUI.portraitmsg=="")
						{
							GameUI.portraitmsg = "Entering your sector, commander!";
							GameUI.portraiton = GameUI.starshipportraitid;
						}
						break;
						case 3:
						GameUI.msg = "Bomber Launched";
						flyby.x[2] = -2800;
						flyby.z[2] = -1000;
						if(GameUI.portraitmsg=="")
						{
							GameUI.portraitmsg = "Entering your sector, commander!";
							GameUI.portraiton = GameUI.starshipportraitid;
						}
						break;
					}
					ship.shiparray[i].z+=1000;
					if(ship.shiparray[i].race==1)
					{
							ship.shiparray[i].z-=2000;
					}
					ship.shiparray[i].deadframe = 0;
					break;
				}
			}
		}
		
		public static void DrawHealth(Camera3D camera)
		{
			if(GameUI.togglehp==0)
			{
				return;
			}
			int gmx = Raylib.GetMouseX();
			int gmy = Raylib.GetMouseY();
			float scalef = (45f/Program.ZOOM);
			if(Program.gamestate==Program.GROUNDBATTLE)
			{
				if(GameUI.targettime<=1)
				{
					int id = RTSInput.mouseoverunit(camera);
					if(id!=-1)
					{
						GameUI.SetMouseTargetType(GameUI.TARGET);
							
					}
				}
				for(int j=0;j<Unit.maxunits;j++)
				{
					Vector2 screenposHead = Raylib.GetWorldToScreen(new Vector3(Unit.unitarray[j].x,Unit.unitarray[j].y + 15,Unit.unitarray[j].z),camera);
					Vector2 screenposHeadUp = Raylib.GetWorldToScreen(new Vector3(Unit.unitarray[j].x,Unit.unitarray[j].y + 24,Unit.unitarray[j].z),camera);
					Vector2 screenposHeadLeft = Raylib.GetWorldToScreen(new Vector3(Unit.unitarray[j].x - 10,Unit.unitarray[j].y + 15,Unit.unitarray[j].z),camera);
					Vector2 screenposHeadRight = Raylib.GetWorldToScreen(new Vector3(Unit.unitarray[j].x + 10,Unit.unitarray[j].y + 15,Unit.unitarray[j].z),camera);
					Vector2 screenposFeet = Raylib.GetWorldToScreen(new Vector3(Unit.unitarray[j].x,Unit.unitarray[j].y,Unit.unitarray[j].z),camera);
					if((Unit.unitarray[j].race==1 || GameUI.eselect==j) && Unit.unitarray[j].hp>0)
					{
						if(Unit.unitarray[j].ammo<=0 && Unit.unitarray[j].race==1 && Unit.unitarray[j].shiptype%10==1 && Unit.unitarray[j].hp>0)
						{
							Raylib.DrawTextureEx(GameUI.outofammo,new Vector2((int)screenposHead.X - (int)GameUI.RescaleX(128),(int)screenposHead.Y - (int)GameUI.RescaleY(32)),0,gscale,Color.White);
							if(Math.Abs(gmx-screenposHead.X)<100 && Math.Abs(gmy-screenposHead.Y - GameUI.RescaleY(32))<100)
							{
								int bonusammo = 50 * GameUI.upgradelevel[GameUI.upgrade_bigger_ammo_belt];
								Unit.unitarray[j].ammo = Unit.maxammo + bonusammo;
							}
						}
							
					}
					if(Unit.unitarray[j].hp>0 && (Unit.unitarray[j].shiptype==2 || Unit.unitarray[j].shiptype==4) && Unit.unitarray[j].immobilised!=0)
					{
						screenposHead.Y-=RescaleY(32f*scalef);
						GameUI.DrawText("Immobilised",(int)screenposHead.X,(int)screenposHead.Y,smallfont,Color.LightGray);
					}
					if(Unit.unitarray[j].hp>0 && (Unit.unitarray[j].race==1 || j==GameUI.eselect))
					{
						if(Unit.unitarray[j].selected!=0 || j==GameUI.eselect)//(screenposHead.X>gmx-RescaleX(50f*scalef) && screenposHead.X<gmx+RescaleX(50f*scalef) && screenposFeet.Y>gmy && screenposHead.Y<gmy)
						{
							if(Grass.incover(Unit.unitarray[j].x,Unit.unitarray[j].z)==1)
							{
								Raylib.DrawTextureEx(cover,new Vector2(screenposHeadRight.X - 0.5f*32f*gscale*scalef,screenposHead.Y-0.5f*32f*gscale*scalef),0,0.5f*gscale*scalef,Color.White);
							}	
							
							switch(Unit.unitarray[j].soldiertype)
							{
								case Unit.medic:
								Raylib.DrawTextureEx(medic,new Vector2(screenposHeadLeft.X - 0.5f*32f*gscale*scalef,screenposHead.Y-0.5f*32f*gscale*scalef),0,0.5f*gscale*scalef,Color.White);
								break;
								case Unit.sergeant:
								Raylib.DrawTextureEx(sergeant,new Vector2(screenposHeadLeft.X - 0.5f*32f*gscale*scalef,screenposHead.Y-0.5f*32f*gscale*scalef),0,0.5f*gscale*scalef,Color.White);
								break;
								case Unit.engineer:
								Raylib.DrawTextureEx(engineer,new Vector2(screenposHeadLeft.X - 0.5f*32f*gscale*scalef,screenposHead.Y-0.5f*32f*gscale*scalef),0,0.5f*gscale*scalef,Color.White);
								break;
								case Unit.heavy:
								Raylib.DrawTextureEx(heavy,new Vector2(screenposHeadLeft.X - 0.5f*32f*gscale*scalef,screenposHead.Y-0.5f*32f*gscale*scalef),0,0.5f*gscale*scalef,Color.White);
								break;
							}
							int fullhealth = (int)((screenposHeadRight.X - screenposHeadLeft.X)*scalef*0.5f);
							int healthh = (int)(8f*scalef);
							int pcthealth = (int)((Unit.unitarray[j].hp * (float)fullhealth) / Unit.unitarray[j].basehp);
							int pctdamage = fullhealth - pcthealth;
							Raylib.DrawRectangle((int)screenposHead.X-fullhealth/2-healthh/2,(int)screenposHeadUp.Y-healthh/4,fullhealth+healthh/2+healthh/2,healthh,new Color((int)Color.Green.R,(int)Color.Green.G,(int)Color.Green.B,64));
							for(int pcthealthi = 0;pcthealthi<pcthealth;pcthealthi+=healthh/2+1)
							{
								Raylib.DrawRectangle((int)screenposHead.X - fullhealth/2 + pcthealthi,(int)screenposHeadUp.Y,healthh/2,healthh/2,Color.Green);
							}
							for(int pctdamagei = 0;pctdamagei<pctdamage;pctdamagei+=healthh/2)
							{
								Raylib.DrawRectangle((int)screenposHead.X - fullhealth/2 + pcthealth + pctdamagei,(int)screenposHeadUp.Y,healthh/2,healthh/2,Color.Red);
							}
						}
						if(Unit.unitarray[j].levelmsgtime>0 && Unit.unitarray[j].race==1)
						{
							if(Unit.unitarray[j].levelmsg!="")
							{
								GameUI.DrawText(Unit.unitarray[j].levelmsg,(int)screenposHead.X,(int)screenposHead.Y - GameUI.smallfont*3,(int)((float)GameUI.smallfont*scalef),Color.LightGray);
							}
						}
					}
				}
				for(int i=1;i<Building.maxbuildings;i++)
				{
					if(Building.buildingarray[i].hp>0 && Program.demomode==0 && Program.videomode==0)
					{
						Vector2 screenpos = Raylib.GetWorldToScreen(new Vector3(Building.buildingarray[i].x,Building.buildingarray[i].y,Building.buildingarray[i].z),camera);
						screenpos.Y-=GameUI.RescaleY(100);
						int fullhealth = (int)(64f * 45f/Program.ZOOM);
						int healthh = (int)(8f * 45f / Program.ZOOM);
						int pcthealth = (int)((Building.buildingarray[i].hp * (float)fullhealth) / Building.buildingarray[i].basehp);
						int pctdamage = fullhealth - pcthealth;
						if(Building.buildingarray[i].selected!=0)
						{
							GameUI.DrawText(Building.buildingarray[i].name,(int)screenpos.X-fullhealth/2-healthh/4,(int)screenpos.Y-healthh/4 - (int)((float)GameUI.normalfont * 45f / Program.ZOOM),(int)((float)GameUI.normalfont * 45f / Program.ZOOM),Color.White);
						}
						else
						{
							GameUI.DrawText(Building.buildingarray[i].name,(int)screenpos.X-fullhealth/2-healthh/4,(int)screenpos.Y-healthh/4 - (int)((float)GameUI.normalfont * 45f / Program.ZOOM),(int)((float)GameUI.normalfont * 45f / Program.ZOOM),Color.LightGray);
						}
						Raylib.DrawRectangle((int)screenpos.X-fullhealth/2-healthh/4,(int)screenpos.Y-healthh/4,fullhealth+healthh/2,healthh,new Color((int)Color.Green.R,(int)Color.Green.G,(int)Color.Green.B,64));
						for(int pcthealthi = 0;pcthealthi<pcthealth;pcthealthi+=healthh/2+1)
						{
							Raylib.DrawRectangle((int)screenpos.X - fullhealth/2 + pcthealthi,(int)screenpos.Y,healthh/2,healthh/2,Color.Green);
						}
						for(int pctdamagei = 0;pctdamagei<pctdamage;pctdamagei+=healthh/2)
						{
							Raylib.DrawRectangle((int)screenpos.X - fullhealth/2 + pcthealth + pctdamagei,(int)screenpos.Y,healthh/2,healthh/2,Color.Red);
						}
						if(Building.buildingarray[i].strucktime>0)
						{
							if(Building.buildingarray[i].strucktime % 20 < 10)
							{
								for(int pcthealthi = 0;pcthealthi<pcthealth;pcthealthi+=healthh/2)
								{
									Raylib.DrawRectangle((int)screenpos.X - fullhealth/2 + pcthealthi,(int)screenpos.Y,healthh/2,healthh/2,Color.Yellow);
								}
								for(int pctdamagei = 0;pctdamagei<pctdamage;pctdamagei+=healthh/2)
								{
									Raylib.DrawRectangle((int)screenpos.X - fullhealth/2 + pcthealth + pctdamagei,(int)screenpos.Y,healthh/2,healthh/2,Color.Red);
								}
							}
						}
					}
				}	
			}
		}
		
		public static void BuildEnemy(int unittype)
		{
			for(int j=0;j<Unit.maxunits;j++)
			{
				if(Unit.unitarray[j].hp<=0 && Unit.unitarray[j].race==2 && Unit.unitarray[j].shiptype==unittype)
				{
					Unit.unitarray[j].ping = 180;
					Unit.unitarray[j].hp = Unit.unitarray[j].basehp;
					int qrs = ship.random.Next(0,5);
					for(int qqrr=0;qqrr<2;qqrr++)
					{
						if(qrs!=Program.qrs_preferred && Program.qrs_preferred>=0)
						{
							qrs = ship.random.Next(0,5);		
						}
					}
												
												
					Unit.unitarray[j].x = ship.AttackFromX(qrs);
					Unit.unitarray[j].z = ship.AttackFromZ(qrs);
					Unit.unitarray[j].amode = 0;
					Unit.unitarray[j].immobilised = 0;
					Unit.unitarray[j].PrepareUnit();
					break;
				}
			}								
		}
		
		public static void BuildUnit(int unittype)
		{
			if(unittype%10==1)
			{
				int countinf = 0;
				//I'm sticking a unit cap in to the game for the player as I realised that tactical options
				//are more interesting in the game with lower unit numbers than higher unit numbers
				for(int i=0;i<Unit.maxunits;i++)
				{
					if(Unit.unitarray[i].race==1 && Unit.unitarray[i].hp>0 && Unit.unitarray[i].shiptype%10==1)
					{
						countinf++;
						if(countinf>=Unit.maxplayerinfantry)
						{
							return;
						}
					}
				}
			}
			for(int i=0;i<Unit.maxunits;i++)
			{
				if(Unit.unitarray[i].race==1 && Unit.unitarray[i].hp<=0 && Unit.unitarray[i].shiptype==unittype)
				{
					//and if type == 1
					Unit.unitarray[i].hp = Unit.unitarray[i].basehp;
					Unit.unitarray[i].PrepareUnit();
					Unit.unitarray[i].ping = 180;
					GameUI.msgtime = 120;
					if(unittype%10==1)
					{
						GameUI.msg = "Infantry Trained";
						Unit.unitarray[i].name = Namelist.pickname();
						Unit.unitarray[i].rank = "Pvt.";
						Unit.unitarray[i].kills = 0;
						Unit.unitarray[i].level = 0;
						
						if(GameUI.portraitmsg=="" && GameUI.NOPORTRAIT==0)
						{
							GameUI.portraitmsg = "Pvt " + Unit.unitarray[i].name + " "+Translation.translate("reporting for duty, Sir!");
							GameUI.portraiton = 1;//ship.random.Next(0,3);
						}
					}
					else
					{
						if(unittype==5)
						{
							GameUI.msg = "WarMachine Produced";
							if(GameUI.portraitmsg=="" && GameUI.NOPORTRAIT==0)
							{
								GameUI.portraitmsg = "WarMachine ready to go, Sir!";
								GameUI.portraiton = 3;//ship.random.Next(0,3);
							}							
						}
						else
						{
							if(unittype==12)
							{
								GameUI.msg = "Sentry Produced";
								if(GameUI.portraitmsg=="" && GameUI.NOPORTRAIT==0)
								{
									GameUI.portraitmsg = "Sentry Gun Ready, Sir!";
									GameUI.portraiton = 1;//ship.random.Next(0,3);
								}
							}
							else
							{
								GameUI.msg = "Tank Produced";
								if(GameUI.portraitmsg=="" && GameUI.NOPORTRAIT==0)
								{
									GameUI.portraitmsg = "Tank ready to go, Sir!";
									GameUI.portraiton = 2;//ship.random.Next(0,3);
								}
							}
						}
					}
					float x = (float) ship.random.NextDouble()*300-150f;
					float z = (float) ship.random.NextDouble()*300-150f;
					float dist = -1;
					int its = 0;
					while(dist<50 && its<1000 && Program.intromode==0)
					{
						its++;
						x = (float) ship.random.NextDouble()*300-150f;
						z = (float) ship.random.NextDouble()*300-150f;
						float mindist = 10000;
						for(int j=0;j<Building.maxbuildings;j++)
						{
							if(Building.buildingarray[j].hp>0)
							{
								float xb = Building.buildingarray[j].x;
								float zb = Building.buildingarray[j].z;
								dist = (float)Math.Sqrt((x-xb)*(x-xb)+(z-zb)*(z-zb));
								if(dist<mindist)
								{
									mindist = dist;
								}
							}
						}
						dist = mindist;
					}
					Unit.unitarray[i].x = x;
					Unit.unitarray[i].z = z;
					if(Unit.unitarray[i].shiptype%10==1 && Program.intromode==0)
					{
						for(int j=0;j<Building.maxbuildings;j++)
						{
							if(Building.buildingarray[j].hp>0)
							{
								if(Building.buildingarray[j].category==Building.BARRACKS)
								{
									Unit.unitarray[i].x = Building.buildingarray[j].x + 10;
									Unit.unitarray[i].z = Building.buildingarray[j].z + 10;
									break;
								}
							}
						}
					}
					else
					{
						if(Program.intromode==0)
						{
							for(int j=0;j<Building.maxbuildings;j++)
							{
								if(Building.buildingarray[j].hp>0)
								{
									if(Building.buildingarray[j].category==Building.HEAVYVEHICLES && unittype==2)
									{
										Unit.unitarray[i].x = Building.buildingarray[j].x + 10;
										Unit.unitarray[i].z = Building.buildingarray[j].z + 10;
										break;
									}
									if(Building.buildingarray[j].category==Building.ENGINEERING && unittype==5)
									{
										Unit.unitarray[i].x = Building.buildingarray[j].x + 10;
										Unit.unitarray[i].z = Building.buildingarray[j].z + 10;
										break;
									}
								}
							}
						}
					}
					its = 0;
					while(true)
					{
						its++;
						if(its>100)
						{
							break;
						}
						Unit.unitarray[i].ordertox = Unit.unitarray[i].x + ship.random.Next(-50,50);
						Unit.unitarray[i].ordertoz = Unit.unitarray[i].z + ship.random.Next(-50,50);
						if(Math.Abs(Unit.unitarray[i].ordertox - Unit.unitarray[i].x)>15 || Math.Abs(Unit.unitarray[i].ordertoz - Unit.unitarray[i].z)>15)
						{
							break;
						}
					}
					Unit.unitarray[i].ordertoy = -90;
					if(Unit.CARGODROP!=-1)
					{
						x = Unit.unitarray[Unit.CARGODROP].x;
						z = Unit.unitarray[Unit.CARGODROP].z;
						Unit.unitarray[i].x = x;
						Unit.unitarray[i].z = z;
						Unit.unitarray[i].ordertoy = -90;
						
						Unit.unitarray[i].ordertox = x + ship.random.Next(-70,70);
						Unit.unitarray[i].ordertoz = z + ship.random.Next(-70,70);
					}
					else
					{
						if(Unit.unitarray[i].shiptype%10==1)
						{
							if(ship.random.Next(0,100)<50)
							{
								Audio.VoiceNotify(Audio.ALERT_UNITREADY);
							}
							else
							{
								Audio.CalculateDistanceMultiplier(Program.demomode,Unit.unitarray[i].x,Unit.unitarray[i].y,Unit.unitarray[i].z);
								Audio.PlayUnitSound(Audio.INFREADY,Audio.INFREADY);
								Audio.distance_multiplier = 1;
							}
						}
						else
						{
							if(ship.random.Next(0,100)<50)
							{
								Audio.VoiceNotify(Audio.ALERT_VEHICLEREADY);
							}
							else
							{
								Audio.CalculateDistanceMultiplier(Program.demomode,Unit.unitarray[i].x,Unit.unitarray[i].y,Unit.unitarray[i].z);
								if(Unit.unitarray[i].shiptype==2)
								{
									Audio.PlayUnitSound(Audio.TNKREADY,Audio.TNKREADY);
								}
								if(Unit.unitarray[i].shiptype==5)
								{
									Audio.PlayUnitSound(Audio.WLKREADY,Audio.WLKREADY);
								}
								Audio.distance_multiplier = 1;
							}
						}
					}
					if(Unit.unitarray[i].shiptype==12)
					{
						//get the x z coords of the unit that built it...it has worktype of -1
						for(int u=0;u<Unit.unitarray.Length;u++)
						{
							if(Unit.unitarray[u].worktype==-1)
							{
								Unit.unitarray[i].x = Unit.unitarray[u].x+1;
								Unit.unitarray[i].z = Unit.unitarray[u].z+1;
								Unit.unitarray[i].ordertox = Unit.unitarray[i].x + 1;
								Unit.unitarray[i].ordertoz = Unit.unitarray[i].z + 1;
								Unit.unitarray[i].ordertoy = -200;
								break;
								
							}
						}
					}
					Unit.unitarray[i].amode = 0;
					Unit.unitarray[i].immobilised = 0;
					if(Unit.unitarray[i].shiptype==5)
					{
						if(GameUI.mechupgrade>=100)
						{
							Unit.unitarray[i].armour++;
							Unit.unitarray[i].bursttime--;
						}
					}
					Scoring.addtoscore(Scoring.BUILD);
					break;
				}
			}
		}
		
		public static void BuildBuilding(int btype)
		{
			for(int i=0;i<Building.maxbuildings;i++)
			{
				if(Building.buildingarray[i].hp<Building.buildingarray[i].basehp && Building.buildingarray[i].hp>0)
				{
					Building.buildingarray[i].hp++;
					if(Building.buildingarray[i].hp>=Building.buildingarray[i].basehp)
					{
						GameUI.msgtime = 120;
						GameUI.msg = "Building Repaired";
						Building.buildingarray[i].hp = Building.buildingarray[i].basehp;
					}
				}
			}
		}
		
