		public static void InfoMouseOver()
		{
			if(Raylib.GetMouseY()>RescaleY(700))
			{
				return;
			}
			if(mouseoverworldx==-1000)
			{
				return;
			}
			{
				//are we over some cover
				if(Grass.incover(mouseoverworldx,mouseoverworldz)!=0)
				{
					GameUI.DrawText("Cover:Protection from Direct Fire",Raylib.GetMouseX()+32,Raylib.GetMouseY(),normalfont,Color.LightGray);
				}
				//are we over an animal
				for(int i=0;i<Unit.maxanimals;i++)
				{
					if(Unit.animals[i].hp>0)
					{
						if(Math.Abs(Unit.animals[i].x-mouseoverworldx)<35 && Math.Abs(Unit.animals[i].z - mouseoverworldz)<35)
						{
							GameUI.DrawText("Harmless Wildlife",Raylib.GetMouseX()+32,Raylib.GetMouseY()+normalfont+normalfont/2,normalfont,Color.LightGray);
							if(GameUI.lclick!=0)
							{
								Audio.AnimalNoise();
								Unit.animals[i].click++;
								if(Unit.animals[i].click>10)
								{
									debris.AnimalExplosion(i);
									Unit.animals[i].x = ship.random.Next(-500,500);
									Unit.animals[i].z = ship.random.Next(-500,500);
									Unit.animals[i].click = 0;
								}
							}
						}
					}
				}
				
			}
		}
		
		public static void DoSelectionIcons()
		{
			if(Program.gamestate==Program.GROUNDBATTLE)
			{
				//draw the selection icons...
				if(RTSInput.selectedunits==null)
				{
					for(int i=0;i<Building.maxbuildings;i++)
					{
						if(Building.buildingarray[i].selected!=0 && Building.buildingarray[i].hp>0 && i>=1 && i<=9)
						{
							//show the relevant icon...depending on the unit's health
							int hp = (int)((Building.buildingarray[i].hp * 100) / Building.buildingarray[i].basehp);
							hp-=hp%10;
							hp/=10;
							//that's our frame...
							if(hp>8)
							{
								hp = 8;
							}
							int ux = 128 * (hp % 3);
							int uy = 128 * ((hp - (hp % 3))/3);
							Rectangle src = new Rectangle(ux,uy,128,128);
							Texture2D tmp = buildingicon[i-1]; 
							int offx = 0;
							int offy = 0;
							string stxt = "";
							switch(i)
							{
								case 1:
								stxt = "Produces space ships to fight the enemy in orbit.";
								break;
								case 2:
								stxt = "Produces heavy tanks to fight on land.";
								break;
								case 3:
								stxt = "Requests reinforcements from other battlefields.";
								break;
								case 4:
								stxt = "Trains infantry to fight on land.";
								break;
								case 5:
								stxt = "Generates power for your other structures.";
								break;
								case 6:
								stxt = "Scans the surrounding area for hostile activity";
								break;
								case 7:
								stxt = "Produces heavy combat vehicles, such as walkers.";
								break;
								case 8:
								stxt = "Researches new technology to aid in your defence.";
								break;
								case 9:
								stxt = "Generates power for your other structures.";
								break;
								
							}
							int x = RescaleX(535);
							int y = RescaleY(830);
							offx = RescaleX(offx);
							offy = RescaleY(offy);
							Raylib.DrawTexturePro(tmp,src,new Rectangle(x+offx,y+offy,RescaleX(180),RescaleY(180)),new Vector2(0,0),0,Color.White);
							x+=RescaleX(200);
							y+=RescaleY((int)((float)(normalfont+10)*1.4f));
							//now put text.....
							GameUI.DrawText(Building.buildingarray[i].name,x,y,normalfont,Color.LightGray);
							GameUI.DrawText((int)Building.buildingarray[i].hp + " / " + (int)Building.buildingarray[i].basehp + " HP",x,y + (normalfont + 10)*1,normalfont,Color.LightGray);
							GameUI.DrawText(stxt,x,y+(normalfont+10)*2,normalfont,Color.LightGray);
						}
					}
				}
				if(RTSInput.selectedunits!=null)
				{
					int column = 0;
					int row = 0;
					int selected = -1;
					for(int i = 0;i< RTSInput.selectedunits.Length; i++)
					{
						int x = column * RescaleX(110) + RescaleX(unit_x);
						int y = row * RescaleY(110) + RescaleY(unit_y);
						int j = RTSInput.selectedunits[i];
						
						if(Unit.unitarray[j].race==1 && Unit.unitarray[j].hp>0)
						{
							int hp = (int)((Unit.unitarray[j].hp * 100) / Unit.unitarray[j].basehp);
							hp-=hp%10;
							hp/=10;
							//that's our frame...
							if(hp>8)
							{
								hp = 8;
							}
							int ux = 128 * (hp % 3);
							int uy = 128 * ((hp - (hp % 3))/3);
							Rectangle src = new Rectangle(ux,uy,128,128);
							Texture2D tmp = standardicon;
							int offx = 0;
							int offy = 0;
							string uname = "Rifleman";
							string special = "";
							string health = (int)Unit.unitarray[j].hp + "/" + (int)Unit.unitarray[j].basehp;
							string level = "Level:"+Unit.unitarray[j].level;
							Color c = Color.LightGray;
							if(Unit.unitarray[j].soldiertype==Unit.MEDIC)
							{
								special = "Medic";
								c = Color.White;
							}
							if(Unit.unitarray[j].soldiertype==Unit.ENGINEER)
							{
								special = "Engineer";
								c = Color.Yellow;
							}
							if(Unit.unitarray[j].soldiertype==Unit.SERGEANT)
							{
								special = "Sergeant";
								c = Color.Purple;
							}
							if(Unit.unitarray[j].soldiertype==Unit.HEAVY)
							{
								special = "Heavy";
								c = new Color(50,255,255,255);
							}
							switch(Unit.unitarray[j].shiptype)
							{
								case 1:
									tmp = standardicon;
									offx = RescaleX(-14);
									offy = RescaleY(-11);
								break;
								case 12: //sentry
									tmp = sentryicon;
									uname = "Sentry Gun";
									offx = RescaleX(-6);
									offy = RescaleY(-8);
								break;
								case 11:
									tmp = assaulticon;
									uname = "Assault Inf.";
									offx = RescaleX(-6);
									offy = RescaleY(-16);
								break;
								case 21:
									tmp = defendericon;
									uname = "Defenders";
									offx = RescaleX(-18);
									offy = RescaleY(-18);
								break;
								case 2:
									tmp = tankicon;
									uname = "Tank";
									offx = RescaleX(-14);
									offy = RescaleY(-20);
								break;
								case 5:
									tmp = walkericon;
									uname = "Walker";
									offx = RescaleX(-16);
									offy = RescaleY(-13);
								break;
							}
							offx+=RescaleX(5);
							//first of all draw the button.....
							Raylib.DrawTextureEx(button01,new Vector2(x,y),0,gscale*0.33f,Color.White);
							if((mx*(float)Program.resx/1920f)>(x) && (my*(float)Program.resy/1080f)>(y) && (mx*(float)Program.resx/1920f)<(x) + 110 && (my*(float)Program.resy/1080f)<(y) + 110)
							{
								GameUI.NoDeselect = 1;
								Raylib.DrawTextureEx(button01a,new Vector2(x,y),0,gscale*0.33f,Color.White);
								if(GameUI.lpress!=0)
								{
									GameUI.mpressxy = x + y * 1920;
								}
								if(GameUI.lclick!=0 && GameUI.mpressxy == x + y * 1920)
								{
									selected = j;
								}
								if(special!="")
								{
									GameUI.settooltip(special,x + 15, y - 45,100,40);
								}
								else
								{
									if(uname!="")
									{
										GameUI.settooltip(uname,x + 15, y - 45,100,40);
									}
									
								}
							
							}
							Raylib.DrawTexturePro(tmp,src,new Rectangle(x+offx,y+offy,RescaleX(128),RescaleY(128)),new Vector2(0,0),0,Color.White);
							GameUI.DrawText(uname,x + 15,y + 15,smallfont,c);
							if(special!=""){GameUI.DrawText(special,x + 15,y +smallfont + 15 + 5,smallfont,c);}
							GameUI.DrawText(health,x + 15,y + smallfont * 2 + 15 + 10,smallfont,c);
							if(Unit.unitarray[j].level>0)
							{
								GameUI.DrawText(level,x +15,y + smallfont * 3 + 30,smallfont,c);
							}
						}
						column++;
						if(column>5)
						{
							column = 0;
							row++;
						}
					}
					if(selected!=-1)
					{
						RTSInput.selectedunits = null;
						RTSInput.selectedunits = new int[1];
						RTSInput.selectedunits[0] = selected;
						RTSInput.mousestate = 0;
						RTSInput.smx = 0;
						RTSInput.smy = 0;
						RTSInput.fmx = 0;
						RTSInput.fmy = 0;
						//clear out all selections.....
						for(int i=0;i<Unit.maxunits;i++)
						{
							Unit.unitarray[i].selected = 0;
						}
						Unit.unitarray[selected].selected = 1;
						Unit.WaveHello(selected);
						Audio.Notification();
						GameUI.lpress = 0;
						GameUI.lclick = 0;
						GameUI.ldown = 0;
						
					}
				}
			}
		}
		
		public static void DoShitAndDrawInterface(Camera3D camera)
		{
			if(Program.inprogress==0) //hardcoded crap sorry
			{
				options_x = 520;
				quit_x = 1000;
			}
			else
			{
				options_x = 280;
				quit_x = 520;
			}
			
			
			omx = mx;
			omy = my;
			mousehasmoved = 0;
			mx = (int)((float)Raylib.GetMouseX()*1920.0f/(float)Program.resx);
			my = (int)((float)Raylib.GetMouseY()*1080.0f/(float)Program.resy);
			
			if(omx!=mx || omy!=my)
			{
				mousehasmoved = 1;
			}
			if(mousehasmoved==0)
			{
				mouseoverchecktime-=ship.delta;
				if(mouseoverchecktime<=0)
				{
					mouseoverchecktime = 35;
					//check the mouse coordinates on the world....
					mouseoverworldx = RTSInput.ScreenToWorldX(camera,(float)Raylib.GetMouseX(),(float)Raylib.GetMouseY());
					mouseoverworldz = RTSInput.ScreenToWorldZ(camera,(float)Raylib.GetMouseX(),(float)Raylib.GetMouseY());
				}
			}
			else
			{
				mouseoverworldx = -1000;
				mouseoverworldz = -1000;
			}
			
			Vector2 mouseposa = new Vector2(Raylib.GetMouseX(),Raylib.GetMouseY());
			mouseposa.X*=(1920.0f/(float)Program.resx);
			mouseposa.Y*=(1080.0f/(float)Program.resy);
			doupgrade();
			if(GameUI.msgtime>0)
			{
				GameUI.msgtime-=ship.delta;
			}
			
			if(Raylib.IsKeyReleased(KeyboardKey.Escape))
			{
				if(Program.autoplay!=0 || Program.intromode!=0 || Program.exitmission==-1)
				{
					Program.QUITGAME = 1;
				}
				if(Program.gamestate==Program.MENU)
				{
					if(Program.inprogress==1)
					{
						if(Program.substate==2)
						{
							Program.substate = 0;	
						}
						else
						{
							if(Program.substate==0)
							{
								Program.substate = 1;
								Program.inprogress = 0;
								Program.tutorial = 0;
								Program.tutorialstage = 0;
								Program.gametimer.Reset();
								GameUI.inprogresschanged = 10;
								Scoring.EndGame();
							}
							else
							{
								Program.substate = 0;
							}
						}
					}			
					else
					{
						if(Program.substate!=0)
						{
							Program.substate=0;
						}
						else
						{
							Program.QUITGAME = 1;
						}
					}
				}
				else
				{
					if(Program.briefingframe>0)
					{
						Program.briefingframe = 0;
					}
					else
					{
						Program.oldstate = Program.gamestate;
						Program.gamestate = Program.MENU;
						Program.substate = 0;
						Program.inprogress = 1;
						Program.gametimer.Stop();
						Program.togglepause = 0;
						return;
					}
				}
			}
			
			int anybuildings = 0;
			
			if(Program.autoplay!=0 && Program.exitmission!=-1 && Program.intromode==0)
			{
				Program.exitmission = 1;
				for(int i=0;i<Unit.unitarray.Length;i++)
				{
					if(Unit.unitarray[i].shiptype!=3 && Unit.unitarray[i].race==1 && Unit.unitarray[i].hp>0)
					{
						Program.exitmission = 0;
						break;
					}
				}
			}
			if((Raylib.IsKeyReleased(KeyboardKey.F7) && Program.autoplay!=0 && Program.gamestate!=Program.MENU) && Program.intromode==0)
			{
				GameUI.gameovertime = 0;
				Program.substate = 1;
				GameUI.inprogresschanged = 10;
				Program.inprogress = 0;
				Program.tutorial = 0;
				Program.tutorialstage = 0;
				Program.gametimer.Stop();
				Program.gamestate=Program.MENU;
				Program.autoplay = 1;
				return;
			}
			if(Program.exitmission==-1 || Program.errorcondition!=0) //end of the intro
			{
				GameUI.gameovertime = 0;
				Program.substate = 0;
				Program.autoplay = 0;
				GameUI.inprogresschanged = 10;
				Program.inprogress = 0;
				Program.tutorial = 0;
				Program.tutorialstage = 0;
				Program.gametimer.Stop();
				Program.gamestate=Program.MENU;
				Program.exitmission = 0;
				return;
			}
			if(Program.gamestate!=Program.MENU)
			{
				for(int i=0;i<Building.maxbuildings;i++)
				{
					if(Building.buildingarray[i].hp>0)
					{
						anybuildings = 1;
						break;
					}
				}
				
				if(anybuildings==0 || victory==1 || Program.exitmission==1)
				{
					if(GameUI.gameovertime<600)
					{
						GameUI.gameovertime+=ship.delta;
						Scoring.EndGame();
					}
				}
				if(GameUI.gameovertime>=600)
				{
					GameUI.gameovertime = 0;
					Program.substate = 1;
					GameUI.inprogresschanged = 10;
					Program.inprogress = 0;
					Program.tutorial = 0;
					Program.tutorialstage = 0;
					Program.gametimer.Stop();
					Program.gamestate=Program.MENU;
					return;
				}
				if(Program.autoplay>(60*240) -2)
				{
					GameUI.gameovertime = 0;
					Program.substate = 1;
					GameUI.inprogresschanged = 10;
					Program.inprogress = 0;
					Program.tutorial = 0;
					Program.tutorialstage = 0;
					Program.gametimer.Stop();
					Program.gamestate=Program.MENU;
					return;
				}
			}

			if(Program.substate==5)//scenarios
			{
				Raylib.DrawTextureEx(debriefbk,new Vector2(0,0),0,gscale,Color.White);
				
				//display the missions.......
				int msy = RescaleY(mission_y);
				int mm = 0;
				for(int m=0;m<Scenario.maxscenarios;m++)
				{
					if(Scenario.scenarios[m]==null)
					{
						continue;
					}
					if(Scenario.scenarios[m].mission_length!=0)
					{
						GameUI.DrawText(Scenario.scenarios[m].description,RescaleX(mission_x+300),msy,largefont,Color.LightGray);
						GameUI.DrawText(Translation.translate("Scenario")+" "+(m),RescaleX(mission_x),msy,largefont,Color.LightGray);
						if(m==Scenario.scenario_in_play)
						{
							GameUI.DrawText(Translation.translate("Scenario")+" "+(m),RescaleX(mission_x),msy,largefont,Color.White);
						}	
						if(GameUI.lclick!=0)
						{
							if(mx>mission_x && mx<mission_x+mission_w && my>mission_y + mm*(mission_h+5) && my<mission_y+mission_y + mm*(mission_h+5))
							{
								Scenario.scenario_in_play = m;
								Scenario.pickscenario(m);
							}
						}					
						msy+=RescaleY(mission_h + 5);
						mm++;
					}
				}
				
				if(Program.autoplay!=0)
				{
					if(Program.inprogress==0 && Program.gamestate==Program.MENU && Program.substate==0)
					{
						GameUI.play();
						Program.substate = 0;
					}
				}
				
				if(GameUI.lclick!=0)
				{
					if(mx>menu_x && mx<menu_x+menu_w && my>menu_y && my<menu_y+menu_h)
					{
						Program.substate = 0;
						Audio.Click();
						GameUI.lclick = 0;
					}
					if(mx>play_x && mx<play_x+play_w && my>play_y && my<play_y+play_h)
					{
						GameUI.play();
						Program.substate = 0;
						Audio.Click();
						GameUI.lclick = 0;
					}
				}
				
				Raylib.DrawTextureEx(button03,new Vector2(RescaleX(play_x),RescaleY(play_y)),0,0.33f*gscale,Color.White);
				if(mouseposa.X > play_x && mouseposa.X < play_x + play_w && mouseposa.Y > play_y && mouseposa.Y < play_y + play_h)
				{
					Raylib.DrawTextureEx(button03a,new Vector2(RescaleX(play_x),RescaleY(play_y)),0,0.33f*gscale,Color.White);
				}
				GameUI.DrawText("Play Battle",RescaleX(play_x+16),RescaleY(play_y+play_h-40),GameUI.largefont,Color.White);
				
				
				Raylib.DrawTextureEx(button01,new Vector2(RescaleX(menu_x),RescaleY(menu_y+40)),0,0.33f*gscale,Color.White);
				if(mouseposa.X > menu_x && mouseposa.X < menu_x + menu_w && mouseposa.Y > menu_y + 40 && mouseposa.Y < menu_y + menu_h + 40)
				{
					Raylib.DrawTextureEx(button01a,new Vector2(RescaleX(menu_x),RescaleY(menu_y+40)),0,0.33f*gscale,Color.White);
				}
				GameUI.DrawText("Ok",RescaleX(menu_x+16),RescaleY(menu_y+menu_h),largefont,Color.White);
				return;
			}
			
			if(Program.substate==3)
			{
				DrawCredits();
				if(GameUI.lclick!=0)
				{
					if(mx>menu_x && mx<menu_x+menu_w && my>menu_y && my<menu_y+menu_h)
					{
						Program.substate = 0;
						Audio.Click();
						GameUI.lclick = 0;
					}
				}
				
				
				Raylib.DrawTextureEx(button01,new Vector2(RescaleX(menu_x),RescaleY(menu_y+40)),0,0.33f*gscale,Color.White);
				if(mouseposa.X > menu_x && mouseposa.X < menu_x + menu_w && mouseposa.Y > menu_y + 40 && mouseposa.Y < menu_y + menu_h + 40)
				{
					Raylib.DrawTextureEx(button01a,new Vector2(RescaleX(menu_x),RescaleY(menu_y+40)),0,0.33f*gscale,Color.White);
				}
				GameUI.DrawText("Ok",RescaleX(menu_x+16),RescaleY(menu_y+menu_h),largefont,Color.White);
				
				return;
				
			}
			
			if(Program.gamestate == Program.MENU && Program.substate==1) //debriefing
			{
				
				if(GameUI.lclick!=0 || Program.autoplay!=0)//Raylib.IsMouseButtonReleased(MouseButton.Left))
				{
					if(mx>menu_x && mx<menu_x+menu_w && my>menu_y && my<menu_y+menu_h)
					{
						Program.substate = 0;
						Audio.Click();
						GameUI.lclick = 0;
					}
					if(Program.autoplay!=0)
					{
						Program.substate = 0;
						GameUI.lclick = 0;
					}
				}
				GameUI.EasterEggTime = -1;
				Raylib.DrawTextureEx(debriefbk,new Vector2(0,0),0,gscale,Color.White);
				Raylib.DrawTextureEx(debriefpanel,new Vector2(RescaleX(dp_x),RescaleY(dp_y)),0,gscale,Color.White);
				//display debriefing text.....
				GameUI.DrawText(GameUI.survivaltime,RescaleX(survive_x),RescaleY(survive_y),largefont,Color.White);
				int totalkills = 0;
				int maxkills = 0;
				string bestsoldier = "";
				for(int i=0;i<Unit.maxunits;i++)
				{
					if(Unit.unitarray[i].race==1 && Unit.unitarray[i].hp>0)
					{
						totalkills+=Unit.unitarray[i].kills;
						if(Unit.unitarray[i].shiptype%10==1)
						{
							if(Unit.unitarray[i].kills>maxkills)
							{
								bestsoldier = Unit.unitarray[i].name;
								maxkills = Unit.unitarray[i].kills;
							}
						}
					}
				}
				for(int i=0;i<Namelist.maxcasualties;i++)
				{
					totalkills+=Namelist.casualtykills[i];
					if(Namelist.casualtykills[i]>maxkills)
					{
						maxkills = Namelist.casualtykills[i];
						bestsoldier = Namelist.casualtylist[i];
					}
				}
				GameUI.DrawText(Translation.translate("Enemy Losses:")+totalkills,RescaleX(totalkills_x),RescaleY(totalkills_y),largefont,Color.White);
				
				GameUI.DrawText(Translation.translate("Best Soldier:")+bestsoldier+"  -  " +maxkills+ " "+Translation.translate("Enemy Casualties"),RescaleX(bestsoldier_x),RescaleY(bestsoldier_y),largefont,Color.White);
				
				int maxncount = 13;
				int offset = (int)GameUI.offset;
				offset%=(Namelist.lastcasualty+2);
				GameUI.offset+=0.01f;
				if(GameUI.offset>Namelist.lastcasualty)
				{
					GameUI.offset = 0;
				}
				GameUI.DrawText("Casualty List - With Kills",RescaleX(casualty_x),RescaleY(casualty_y),largefont,Color.White);
				int ii = 0;
				for(int i=offset;i<offset+maxncount;i++)
				{
					if(i>=0 && i<Namelist.maxcasualties)
					{
						ii++;
						if(Namelist.casualtykills[i]>0)
						{
							
							GameUI.DrawText(Namelist.casualtylist[i]+ "  -  " + Namelist.casualtykills[i],RescaleX(casualtylist_x),RescaleY(casualtylist_y+ii*largefont-(int)(GameUI.offset*largefont)+offset*largefont),largefont,Color.White);
						}
					}
				}
				
				
				Raylib.DrawTextureEx(button01,new Vector2(RescaleX(menu_x),RescaleY(menu_y+40)),0,0.33f*gscale,Color.White);
				if(mouseposa.X > menu_x && mouseposa.X < menu_x + menu_w && mouseposa.Y > menu_y + 40 && mouseposa.Y < menu_y + menu_h + 40)
				{
					Raylib.DrawTextureEx(button01a,new Vector2(RescaleX(menu_x),RescaleY(menu_y+40)),0,0.33f*gscale,Color.White);
				}
				GameUI.DrawText("Ok",RescaleX(menu_x+16),RescaleY(menu_y+menu_h),largefont,Color.White);
				return;
			}
			
			if(Program.gamestate == Program.MENU && Program.substate==2) //graphical options //scrap that - just options...
			{
				
				if(GameUI.lclick!=0)//Raylib.IsMouseButtonReleased(MouseButton.Left))
				{
					if(mx>menu_x && mx<menu_x+menu_w && my>menu_y && my<menu_y+menu_h)
					{
						GameUI.lclick = 0;
						if(Program.inprogress!=0)
						{
							Program.substate = 0;
						}
						else
						{
							Program.substate = 0;
						}
						Audio.Click();
						
					}
					if(mx>blurfilter_x && mx<blurfilter_x+blurfilter_w && my>blurfilter_y && my<blurfilter_y+blurfilter_h)
					{
						Program.blurfilter = 1 - Program.blurfilter;
						Audio.Click();
						LocalStorage.setitem("blurfilter",""+Program.blurfilter);
					}
					
					if(mx>sandbox_x && mx<sandbox_x+sandbox_w && my>sandbox_y && my<sandbox_y+sandbox_h)
					{
						sandbox = 1 - sandbox;
						Audio.Click();
						
					}
					
					if(mx>freebuild_x && mx<freebuild_x + freebuild_w && my > freebuild_y && my < freebuild_y + freebuild_h)
					{
						GameUI.lclick = 0;
						Audio.Click();
						Program.noenemies = 1 - Program.noenemies;
					}
					
					if(mx>spacesuperior_x && mx<spacesuperior_x + spacesuperior_w && my > spacesuperior_y && my < spacesuperior_y + spacesuperior_h)
					{
						GameUI.lclick = 0;
						Audio.Click();
						spacesuperior = 1 - spacesuperior;
					}
					
					if(mx>groundfog_x && mx<groundfog_x + groundfog_w && my > groundfog_y && my < groundfog_y + groundfog_h)
					{
						GameUI.lclick = 0;
						Audio.Click();
