						GameUI.play();
						Program.substate = 0;
					}
				}
				
				if(GameUI.lclick!=0)//Raylib.IsMouseButtonReleased(MouseButton.Left))
				{
					if(mx>audio_x && mx<audio_x + audio_w && my>audio_y && my<audio_y + audio_h)
					{
						GameUI.audioon = 1 - GameUI.audioon;
						Audio.Click();
						GameUI.lclick = 0;
						if(GameUI.audioon==1)
						{
							LocalStorage.setitem("audio","on");
						}
						else
						{
							LocalStorage.setitem("audio","off");
						}
					}
					
					if(mx>music_x && mx<music_x + music_w && my>music_y && my<music_y + music_h)
					{
						GameUI.musicon = 1 - GameUI.musicon;
						Audio.Click();
