						}
						else
						{
							LocalStorage.setitem("music","off");
						}
					}
					
					if(mx>quit_x && mx<quit_x+quit_w && my>quit_y && my<quit_y+quit_h)
					{
						GameUI.lclick = 0;
						if(Program.inprogress==0)
						{
							if(Program.substate==0)
							{
								Audio.Click();
								Program.QUITGAME = 1;
							}
						}
						else
						{
							Program.inprogress = 0;
							Program.substate = 1;
							GameUI.inprogresschanged = 10;
							Program.tutorial = 0;
							Program.tutorialstage = 0;
							Program.gametimer.Reset();
							Audio.Click();
							Scoring.EndGame();
						}
						
					}
					
					if(mx>scenario_x && mx<scenario_x+scenario_w && my>scenario_y && my<scenario_y+scenario_h && Program.substate==0 && Program.gamestate == Program.MENU && Program.inprogress==0)
					{
						Program.substate = 5;
						Audio.Click();
						GameUI.lclick = 0;
					}

					for(int ll=0;ll<4;ll++)//languages //4aug2025
					{
						if(mx>language_x[ll] && mx<language_x[ll] + language_w[ll] & my>language_y[ll] && my<language_y[ll] + language_h[ll] && Program.substate==0 && Program.gamestate == Program.MENU && Program.inprogress==0 && GameUI.lclick!=0)
						{
							Audio.Click();
							GameUI.lclick = 0;
							//handle language translation code here....
							Translation.ResetLanguage(ll);
						}
					}
					
					
					if(mx>options_x && mx<options_x+options_w && my>options_y && my<options_y+options_h && Program.substate==0 && Program.gamestate == Program.MENU)
					{
						Program.substate = 2;
						Audio.Click();
						GameUI.lclick = 0;
					}

					if(mx>credits_x && mx<credits_x+credits_w && my>credits_y && my<credits_y+credits_h && Program.substate==0 && Program.gamestate == Program.MENU && Program.inprogress==0)
					{
						Program.substate = 3;
						Audio.Click();
						GameUI.lclick = 0;
						int chance = ship.random.Next(0,100);
						if(chance<2) 
						{
							GameUI.EasterEggTime = 0;
						}
					}
					if(mx>play_x && mx<play_x+play_w && my>play_y && my<play_y+play_h)
					{
						GameUI.play();
					}
