			{
				bmultiplier*= (1.0f + ((float)GameUI.upgradelevel[GameUI.upgrade_build_rate]*2f)/100f);
				//so..speed up by between 2% and 10%
			}
			if(buildcost!=0 && Program.togglepause==0 && Program.gamestate!=Program.MENU)
			{
				if(Building.IsCategoryAlive(Building.SPACECOMMS)!=0)
				{
					if(buildfighters==1){fighterbuild += bmultiplier*0.0095f*(fightercost / buildcost) * buildcapacity;}
					if(buildbombers==1){bomberbuild += bmultiplier*0.0085f*(bombercost / buildcost) * buildcapacity;}
					if(buildcruisers==1){cruiserbuild += bmultiplier*0.0095f*(cruisercost / buildcost) * buildcapacity;}
				}
				if(Building.IsCategoryAlive(Building.BARRACKS)!=0)
				{
					if(buildinfantry==1)
					{
						infantrybuild += bmultiplier*0.0075f*(infantrycost / buildcost) * buildcapacity;
						if(buildassaultinfantry!=0)
						{
							infantrybuild += bmultiplier*0.0038f*(infantrycost / buildcost) * buildcapacity;
						}
						if(builddefenders!=0)
						{
							infantrybuild -= bmultiplier*0.0025f*(infantrycost / buildcost) * buildcapacity;
						}
					}
				}
				if(Building.IsCategoryAlive(Building.HEAVYVEHICLES)!=0)
				{
					//added 1.75 because I think tanks take too long to be fun...at the moment.
					if(buildtank==1 && (tanktreadimprove==0 || tanktreadimprove>=100)){tankbuild += 1.75f*bmultiplier*0.0065f*(tankcost / buildcost) * buildcapacity;}//6aug2025
				}
				if(Building.IsCategoryAlive(Building.ENGINEERING)!=0)
				{
					if(buildmech==1 && (mechupgrade==0 || mechupgrade>=100)){mechbuild += bmultiplier*0.006f*(mechcost / buildcost) * buildcapacity;}//6aug2025
				}
				if(Profile.stresstest!=0)
				{
					infantrybuild+=1;
					tankbuild+=1;
				}
			}
		}
		
		public static int isairstrikeallowed()
		{
			if(requestdropship!=0)
			{
				//not permitted to have an airstrike at the same time as we're requesting reinforcements
				return 0;
			}
			if(fasterdropship>0 && fasterdropship<100)//nor if we're upgrading our air traffic controllers...
			{
				return 0;
			}
			for(int j=0;j<ship.shiparray.Length;j++)
			{
				//the j > 0 is a hack since I know for some reason that my spaceship combat has a bug with the first ship in the list...so I try to avoid using it...I really should fix it...but this is okay.
				if(ship.shiparray[j].race==1 && ship.shiparray[j].shiptype>=2 && ship.shiparray[j].hp>0 && j>0)
				{
					return 1;
				}
			}
			return 0;
		}
		
