		public static void callforairstrike() //17aug2025
		{
			//find the first airstrike slot that ISN'T currently in use
			for(int i=3;i<11;i++)
			{
				if(flyby.airstrike[i]==0)
				{
					if(i<7)//fighter
					{
						for(int j=0;j<ship.shiparray.Length;j++)
						{
							//the j > 0 is a hack since I know for some reason that my spaceship combat has a bug with the first ship in the list...so I try to avoid using it...I really should fix it...but this is okay.
							if(ship.shiparray[j].race==1 && ship.shiparray[j].shiptype==2 && ship.shiparray[j].hp>0 && j>0)
							{
								//yep grab this one
								flyby.airstrike[i] = 1;
								ship.shiparray[j].hp = 0; //make it temporarily 'dead' //we'll rebuild it as soon as the airstrike is over....
								Audio.VoiceNotify(Audio.ALERT_AIRSTRIKE);
								return;
							}
						}
					}
					else //bomber
					{
						for(int j=0;j<ship.shiparray.Length;j++)
						{
							//the j > 0 is a hack since I know for some reason that my spaceship combat has a bug with the first ship in the list...so I try to avoid using it...I really should fix it...but this is okay.
							if(ship.shiparray[j].race==1 && ship.shiparray[j].shiptype==3 && ship.shiparray[j].hp>0 && j>0)
							{
								//yep grab this one
								flyby.airstrike[i] = 1;
								ship.shiparray[j].hp = 0; //make it temporarily 'dead' //we'll rebuild it as soon as the airstrike is over...
								Audio.VoiceNotify(Audio.ALERT_AIRSTRIKE);
								return;
							}
						}
					}
				}
			}
			
		}
		
		public static void promoteunit(int k)
		{
			if(Unit.unitarray[k].race==1 && Unit.unitarray[k].hp>0 && Unit.unitarray[k].soldiertype==0 && Unit.unitarray[k].leader==-1)
			{
				Unit.unitarray[k].soldiertype=Unit.sergeant;
				Unit.unitarray[k].rank = "Sgt.";
				Unit.unitarray[k].leader = k;
				int countsquad = 4;
				for(int m=0;m<Unit.maxunits;m++)
				{
					if(Unit.unitarray[m].race==1 && Unit.unitarray[m].hp>0 && Unit.unitarray[m].leader==-1 && Unit.unitarray[m].soldiertype>=0)
					{
						float dist = Raymath.Vector3Distance(Unit.unitarray[m].pos,Unit.unitarray[k].pos);
						if(dist < 75)
						{
							countsquad--;
							Unit.unitarray[m].leader = k;
							if(countsquad<=0)
							{
								if(Unit.unitarray[m].rank=="Pvt."){Unit.unitarray[m].rank = "Cpl.";}
								break;
							}
						}
					}
				}
			}
		}
		
