	class Translation
	{
		//////The Translation Class Replaces Text at runtime in realtime.
		//////It uses a binary search through a sorted list of phrases to reduce time scanning
		//////the list.
		//////It would be better to replace all the text at load time however, or use some kind
		//////of "token" system to prevent searching the sorted list everytime you want to display
		//////the same piece of text
		//////Languages are chosen at load time however.
		//////There's no plan in place to allow language to be changed after load
		//////Although we could do so if we really wanted to.
		
		public static int ready = 0;
		public static int ON = 0;
		public static Font myfont;
		public static string[] enwords; //an alphabetically sorted list of words
		public static string[] mywords; //a matching list of words for the translation
		//two separate files..enwords is used to look up the other words
		public static bool sorted = false;
		
		public static void ResetLanguage(int i)//4aug2025
		{
			//
			if(GameUI.language!="")
			{
				//we need to remove the codepoints as well...somehow....
				for(int ii=0;ii<UnloadHelper.maxfonts;ii++)
				{
					Raylib.UnloadFont(UnloadHelper.fonts[ii]);
				}
				UnloadHelper.maxfonts = 0;
				GameUI.language = "";
				Program.fontfile = "";
				ready = 0;
				ON = 0;
				sorted = false;
				enwords = null;
				mywords = null;
				GameUI.smallfont = GameUI.RescaleY(12);
				GameUI.normalfont = GameUI.RescaleY(16);
				GameUI.largefont = GameUI.RescaleY(24);
			}
			if(i>0)
			{
				switch(i)
				{
					case 1:
					GameUI.language = "zh";
					Program.fontfile = "media/txt/lang01.ttf";
					break;
					case 2:
					GameUI.language = "kr";
					Program.fontfile = "media/txt/lang02.otf";
					break;
					case 3:
					GameUI.language = "th";
					Program.fontfile = "media/txt/lang03.ttf";
					break;
				}
			}
			//correct language should load next time a drawtext command is issued...
		}
		
		public static void init(string fontfile,string wordfile)
		{
			ON = 1;
			
			
			
			try
			{
				string[] cdata = System.IO.File.ReadAllLines(wordfile);
				mywords = cdata;
				string txt = "";
				for(int i=0;i<cdata.Length;i++)
				{
					txt+=cdata[i];
				}
				//All this unsafe stuff is because I'm being very careful to pass sbyte* and int*
				//values that are expected. Most of the library's functions can handle if you pass
				//not quite the right types, but this part of it needs the exact types to be passed.
				//I may have made some errors, but because it all happens once at load time it shouldn't
				//cause problems assuming the game is running once it starts....
				unsafe
				{
					UTF8Encoding utf8  = new UTF8Encoding();
					int bytecount = utf8.GetByteCount(txt);
					byte[] txtbytes = new byte[bytecount];
					utf8.GetBytes(txt,txtbytes);
					//to be honest I don't really understand this 'fixed' stuff in c#, I'm merely doing 
					//what seems to work to get this process to do what it's meant to do....
					//I could be wrong but I believe "fixed" ensures that the garbage collector doesn't
					//moved things around in memory which is very important when we're using pointers
					//to variables rather than merely variables in normal C# code.
					//Things could go bad if you were to refer to pointers and the garbage collector was
					//allowed to just up and move their locations anywhere they want in memory 
					//that's one of the reasons for the unsafe parts of the code
					//I'm used to using simple languages that don't deal with pointers and even garbage
					//collection. 
					fixed(byte* tp = txtbytes)
					{
						sbyte* txtp = (sbyte*) tp;
						int codepointcount = Raylib.GetCodepointCount(txtp);
						int* codepoints = Raylib.LoadCodepoints(txtp,&codepointcount);
						//remove duplicates.....
						int[] cps = new int[codepointcount]; //chatgpt09sep2025
						System.Runtime.InteropServices.Marshal.Copy((IntPtr)codepoints,cps,0,codepointcount);//chatgpt09sep2025
						int[] uniquecps = cps.Distinct().ToArray();//chatgpt09sep2025
						int uniquecount = uniquecps.Length;//chatgpt09sep2025
						byte[] filenamebytes = Encoding.ASCII.GetBytes(fontfile);
						fixed(byte* fp = filenamebytes)
						{
							sbyte* sfontfile = (sbyte*) fp;
							fixed (int* ucp = uniquecps)//chatgpt09sep2025
							{
								//myfont = Raylib.LoadFontEx(sfontfile,GameUI.largefont,codepoints,codepointcount);				
								myfont = Raylib.LoadFontEx(sfontfile,GameUI.largefont,ucp,uniquecount);	//chatgpt09sep2025			
							}
							UnloadHelper.AddFont(myfont);
						}
						Raylib.UnloadCodepoints(codepoints);
					}
				}
			}
			catch(Exception e)
			{
				Console.WriteLine("Error:"+e.Message);
			}
			try
			{
				enwords = System.IO.File.ReadAllLines("media/txt/enwords.txt");
			}
			catch(Exception e)
			{
				Console.WriteLine("Error:"+e.Message);
			}
			
			if(enwords.Length!=mywords.Length)
			{
				//error should not happen......
				enwords = null;
				mywords = null;
				ready = 1; 
				return;
			}
			sort();
			ready = 1;
			
		}
		
		private static void sort() //28mar2021
		{
			string[] sorteddefaultwords = new string[enwords.Length];
			string[] sortedforeignwords = new string[mywords.Length];
			bool[] sortedlist = new bool[enwords.Length];
			sorted = false;
			string biggestword = "";
			for(int i=0;i<enwords.Length;i++)
			{
				sorteddefaultwords[i] = "";
				sortedforeignwords[i] = "";
				sortedlist[i] = false;
			}
			while(!sorted)
			{
				//find the biggestword that has not been sorted
				int j = -1;
				biggestword = "";
				for(int i=0;i<enwords.Length;i++)
				{
					if(String.Compare(enwords[i],biggestword)>0 && sortedlist[i]==false && enwords[i]!="")
					{
						biggestword = enwords[i];
						j = i;
					}
				}
				//we now have the biggest unsorted word.....
				if(j!=-1)
				{
					//find the highest index value of sorteddefaultwords.....
					for(int k=sorteddefaultwords.Length-1;k>=0;k--)
					{
						if(sorteddefaultwords[k]=="" && sortedforeignwords[k]=="")
						{
							sorteddefaultwords[k] = enwords[j];
							sortedforeignwords[k] = mywords[j];
							sortedlist[j] = true;
							break;
						}
					}
				}
				else
				{
					sorted = true;
				}
				
			}
			if(sorted)
			{
				for(int i=0;i<enwords.Length;i++)
				{
					enwords[i] = sorteddefaultwords[i];
					mywords[i] = sortedforeignwords[i];
				}
			}
		}
		
		public static string translate(string word)
		{
			if(GameUI.language=="en" || GameUI.language=="")
			{
				return word;
			}
			if(mywords==null || enwords==null)
			{
				return word;
			}
			string value = "";
			int min = 0;
			int max = enwords.Length - 1;
			int mid = (min + max) / 2;
			int omid = mid - 1;
			int atleasttwice = 0;
			int pmid = (min + max);
			while(value=="" && omid!=mid)
			{
				omid = mid;
				string txt = enwords[mid];
				int cmp = String.Compare(enwords[mid],word);
				if(cmp==0)
				{
					value = mywords[mid];
					
					return value;
				}
				if((pmid)%2!=0)
				{
					if(mid + 1 <= max)
					{
						if(String.Compare(enwords[mid + 1],word)==0)
						{
							value = mywords[mid + 1];
							
							return value;
						}
					}
				}
				pmid = min + max;
				if(cmp>0)
				{
					max = mid;
					mid = (min + max)/2;
					
				}
				if(cmp<0)
				{
					min = mid;
					mid = (min + max)/2;
				}
				
				if(omid==mid)
				{
					atleasttwice++;
					if(atleasttwice<2)
					{
						omid = mid - 1;
					}
				}
			}
			return word;
		}
		
		public static string words(int i)
		{
			if(mywords==null)
			{
				return "err:(none)";
			}
			if(i<0 || i>=mywords.Length)
			{
				return "err:(out)";
			}
			return mywords[i];
		}
		
		public static Font font()
		{
			return myfont;
		}
	}
	
	class Profile
	{
		public static long updatetime;
		public static long rendertime;
		public static int ortime;
		
		public static long guitime;
		
		public static long frametime;
		public static long minframetime;
		public static long maxframetime;
		public static long avgframetime;
		public static int dumpdebug = 0;
		
		public static long[] frametimes = new long[600];
		public static int frame = -1;
		public static int endframe = 60 * 300;
		public static int pauseuntil = -1;
		public static long[] shadertime = new long[20];
		
		public static int debugon = 0;
		public static int stresstest = 0;
		public static Stopwatch timer;
		
		public static Stopwatch ftimer;
		
		public static string message = "";
		
		public static long[] updatetimes = new long[600];
		public static long[] rendertimes = new long[600];
		
		public static void updatedebugdata()
		{
			ortime++;
			ortime%=600;
			rendertimes[ortime] = rendertime;
			updatetimes[ortime] = updatetime;
			
		}
		
		public static void dumpdebugdata()
		{
			if(dumpdebug!=0)
			{
				dumpdebug = 0;
				string outtxt = "";
				for(int i=0;i<600;i++)
				{
					outtxt+="Update:"+updatetimes[i]+" - - - Render:" + rendertimes[i] + Environment.NewLine;
				}
				System.IO.File.WriteAllText("debugdump.txt",outtxt);
			}
		}
		
		public static void drawdebuginfo()
		{
			if(frame==-1)
			{
				if(Program.gamestate!=Program.MENU)
				{
					ftimer = new Stopwatch();
					ftimer.Start();
					minframetime = 100000;
					maxframetime = -100000;
				}
			}
			else
			{
				ftimer.Stop();
				if(frame<endframe && Program.gamestate!=Program.MENU)
				{
					frametime = ftimer.ElapsedMilliseconds;
					if(frame % 600==0)
					{
						minframetime = 100000;
						maxframetime = -100000;
						message = "";
					}
					if(frametime<minframetime)
					{
						minframetime = frametime;
					}
					if(frametime>maxframetime)
					{
						maxframetime = frametime;
					}
					frametimes[frame % 600] = frametime;
					long sum = 0;
					for(int k=0;k<600;k++)
					{
						sum+=frametimes[k];
					}
					avgframetime = sum / 600;
					ftimer.Reset();
					ftimer.Start();
				}
			}
			if(Program.gamestate!=Program.MENU && frame<endframe){frame++;}
			
			if(debugon==0)
			{
				return;
			}
			int maxe = 0;
			for(int ee=explosion.maxexplosions-1;ee>0;ee--)
			{
				if(explosion.explosionarray[ee].x!=0)
				{
					maxe = ee;
					break;
				}
			}
			GameUI.DrawText("Min Frame Time:"+minframetime,900,200,20,Color.White);
			GameUI.DrawText("Max Frame Time:"+maxframetime,900,230,20,Color.White);
			GameUI.DrawText("Avg Frame Time:"+avgframetime,900,260,20,Color.White);
			GameUI.DrawText("Frame Time:"+frametime,900,300,20,Color.White);
			GameUI.DrawText("Info:"+message,900,330,20,Color.White);
			
			
		}
		
	}

