		public static void CalculateDistanceMultiplier(int viewmode,float x,float y,float z)
		{
			distance_multiplier = 1;
			Vector3 pos = new Vector3(x,y,z);
			float dist = 0;
			if(viewmode==0)//normal RTS view
			{
				
				dist = Raymath.Vector3Distance(pos,Program.audiocamera.Target);
				if(dist<75)
				{
					distance_multiplier = 1;
				}
				else
				{
					distance_multiplier = 1f/(dist - 74f);
				}
			}
			else //ground level view
			{
				dist = Raymath.Vector3Distance(pos,Program.audiocamera.Position);
				if(dist<75)
				{
					distance_multiplier = 1;
				}
				else
				{
					distance_multiplier = 1f/(dist - 74f);
				}
			}
			distance_multiplier*=25f;
			if(distance_multiplier>1)
			{
				distance_multiplier = 1;
			}
			if(distance_multiplier<0.33)
			{
				distance_multiplier = 0.33f;
			}
		}
		
