		public static long lastunitsound;
		
		public static void PlayUnitSound(int u,int a)
		{
			if(u==COMBAT || a==COMBAT)
			{
				if(ship.random.NextDouble()<0.95)
				{
					return;
				}
			}
			if(u==CRYMEDIC || a==CRYMEDIC)
			{
				if(ship.random.NextDouble()<0.8)
				{
					return;
				}
			}
			if(soundtimer.ElapsedMilliseconds<lastunitsound)
			{
				return;
			}
			lastunitsound = soundtimer.ElapsedMilliseconds + 150;
			if(GameUI.audioon==0){return;}
			Sound[] tmp = null;
			switch(u)
			{
				case INF:
					if(a==SEL)
					{
						tmp = infantryselect;
					}
					if(a==MOV)
					{
						tmp = infantrymove;
					}
				break;
				case MED:
					if(a==SEL)
					{
						tmp = medicselect;
					}
					if(a==MOV)
					{
						tmp = medicmove;
					}
				break;
				case ENG:
				if(a==SEL)
					{
						tmp = engineerselect;
					}
					if(a==MOV)
					{
						tmp = engineermove;
					}
				break;
				case SGT:
				if(a==SEL)
					{
						tmp = sergeantselect;
					}
					if(a==MOV)
					{
						tmp = sergeantmove;
					}
				break;
				case HVY:
				if(a==SEL)
					{
						tmp = heavyselect;
					}
					if(a==MOV)
					{
						tmp = heavymove;
					}
				break;
				case TNK:
				if(a==SEL)
					{
						tmp = tankselect;
					}
					if(a==MOV)
					{
						tmp = tankmove;
					}
				break;
				case WLK:
				if(a==SEL)
					{
						tmp = walkerselect;
					}
					if(a==MOV)
					{
						tmp = walkermove;
					}
				break;
			}
			if(a==NOAMMO)
			{
				tmp = outofammo;
			}
			if(a==FLANKING)
			{
				tmp = flanking;
			}
			switch(a)
			{
				case LOSTBARRACKS:
				tmp = lostbarracks;
				break;
				case LOSTPOWER:
				tmp = lostpower;
				break;
				case LOSTFACTORY:
				tmp = lostfactory;
				break;
				case LOSTAIR:
				tmp = lostair;
				break;
				case LOSINGRADAR:
				tmp = losingradar;
				break;
				
			}
			if(u==COMBAT || a==COMBAT)
			{
				tmp = generalcombat;
			}
			if(u==CRYMEDIC || a==CRYMEDIC)
			{
				tmp = crymedic;
			}
			if(u==TANKDIE || a==TANKDIE)
			{
				tmp = tankdie;
			}
			if(u==INFREADY || a==INFREADY)
			{
				if(Program.intromode!=0)
				{
					return;
				}
				tmp = infantryready;
			}
			if(u==WLKREADY || a==WLKREADY)
			{
				if(Program.intromode!=0)
				{
					return;
				}
				tmp = walkerready;
			}
			if(u==TNKREADY || a==TNKREADY)
			{
				if(Program.intromode!=0)
				{
					return;
				}
				tmp = tankready;
			}
			if(u==PILOTCHATTER || a==PILOTCHATTER)//17aug2025
			{
				if(ship.random.Next(0,1000)>250) //adjust this as needed to increase/decrease the amount of pilot chatter, could be too much - if so reduce the probability
				{
					return;
				}
				if(Program.gamestate!=Program.SPACEBATTLE)
				{
					return;
				}
				tmp = pilotchatter;
			}
			else
			{
				//if we're not in ground combat then return
				if(Program.gamestate!=Program.GROUNDBATTLE)
				{
					return;
				}
			}
			if(tmp!=null)
			{
				if(tmp.Length>0)
				{
					int index = ship.random.Next(0,tmp.Length);
					int rcount = 0;
					norepeats[ship.random.Next(0,30)] = 0;
					for(int i=0;i<30;i++)
					{
						if(norepeats[i]==u * 10000 + a * 100 + index)
						{
							rcount++;
						}
					}
					if(rcount>=2)
					{
						return; //don't play the sound...too many repeats
					}
					audioframe++;
					audioframe%=30;
					norepeats[audioframe]=u * 10000 + a * 100 + index;
					float vol = mvolume;
					Raylib.SetSoundVolume(tmp[index],vol*distance_multiplier);
					Raylib.PlaySound(tmp[index]);
				}
			}
		}
		
		public static Sound[] LoadFromPath(string path)
		{
			Sound[] tmp = null;
			if(path=="")
			{
				return null;
			}
			string[] files = Directory.GetFiles(path);
			if(files!=null)
			{
				int count = 0;
				for(int i=0;i<files.Length;i++)
				{
					if(files[i].IndexOf(".wav")>=0 || files[i].IndexOf(".mp3")>=0 || files[i].IndexOf(".ogg")>=0)
					{
						count++;
					}
				}
				if(count>0)
				{
					tmp = new Sound[count];
					count = 0;
					for(int i=0;i<files.Length;i++)
					{
						if(files[i].IndexOf(".wav")>=0 || files[i].IndexOf(".mp3")>=0 || files[i].IndexOf(".ogg")>=0)
						{
							tmp[count] = Raylib.LoadSound(files[i]);
							UnloadHelper.AddSound(tmp[count]);
							count++;
						}
					}
				}
				else
				{
					tmp = null;
				}
			}
			return tmp;
		}
		
