		public static void UpdateMusic()
		{
			int changemusic = 0;
			//if(musictime!=omusictime && musictime%4==0)
			//{
			//	changemusic = 1;
			//}
			if(changemusic==0 && musicplaying>0)
			{
				if(Raylib.IsMusicStreamPlaying(music))
				{
					float duration = Raylib.GetMusicTimeLength(music);
					float time = Raylib.GetMusicTimePlayed(music);
					float pct = time / (duration+0.01f);
					if(pct>=0.98)
					{
						changemusic = 1;
					}
					Raylib.SetMusicVolume(music,mvolume);
					if(pct < 0.05)
					{
						Raylib.SetMusicVolume(music,mvolume*(pct / 0.05f));
					}
					if(pct > 0.925)
					{
						Raylib.SetMusicVolume(music,mvolume*(1f/pct));
					}
				}
			}
			
			
			if(Program.QUITGAME!=0)
			{
				if(musicplaying!=0)
				{
					Raylib.StopMusicStream(music);
					Raylib.UnloadMusicStream(music);
					musicplaying = 0;
				}
				return;
			}
			if(musicplaying>0)
			{
				if(Raylib.IsMusicStreamPlaying(music))
				{
					if(changemusic!=0)
					{
						Raylib.StopMusicStream(music);
						musicplaying = -1;
					}
					else
					{
						if(GameUI.musicon==0 || (GameUI.inprogresschanged!=Program.gamestate/2 || (GameUI.inprogresschanged==0 && Program.inprogress!=0)))
						{
							if(Program.inprogress!=1 || GameUI.musicon==0)
							{
								Raylib.StopMusicStream(music);
								musicplaying = -1;
							}
							else
							{
								Raylib.UpdateMusicStream(music);
							}
						}
						else
						{
							Raylib.UpdateMusicStream(music);
						}
					}
				}
				else
				{
					musicplaying = -1;
				}
				if(changemusic==0){return;}
			}
			if(GameUI.musicon==0)
			{
				omusicon = 0;
				return;
			}
			string path = "media/audio/music/";
			int ignore = 0;
			if(GameUI.musicon==1 && omusicon!=GameUI.musicon)
			{
				if(Program.inprogress==1)
				{
					ignore = 1;
				}
			}
			omusicon = GameUI.musicon;
			if(Program.inprogress!=0 && ignore==0 && changemusic==0)
			{
				return;
			}
			
			if(Program.gamestate==Program.MENU && (ignore==0 || Program.inprogress==0)) //not in a game....
			{
				path = "media/audio/menumusic/";
			}
			GameUI.inprogresschanged = Program.gamestate/2;	
			if(Program.inprogress!=0 && ignore==0)
			{
				GameUI.inprogresschanged = 0;
			}
			string[] files = Directory.GetFiles(path);
			if(files!=null)
			{
				
				int count = 0;
				int specialindex = -1;
				for(int i=0;i<files.Length;i++)
				{
					if((files[i].IndexOf(".wav")>=0 || files[i].IndexOf(".mp3")>=0 || files[i].IndexOf(".ogg")>=0) && i!=musici)
					{
						count++;
					}
					if(files[i].IndexOf("March of the Titans.mp3")>=0)
					{
						specialindex = count;
					}
				}
				if(count>0)
				{
					int index = 1 + random.Next(0,count);
					if(Program.intromode!=0 && specialindex>=0)
					{
						index = specialindex;
						musici = -1;
					}
					for(int i=0;i<files.Length;i++)
					{
						if((files[i].IndexOf(".wav")>=0 || files[i].IndexOf(".mp3")>=0 || files[i].IndexOf(".ogg")>=0) && i!=musici)
						{
							index--;
							if(index<=0)
							{
								//load and play this audio.....
								if(musicplaying<0)
								{
									Raylib.UnloadMusicStream(music);
								}
								music = Raylib.LoadMusicStream(files[i]);
								Raylib.PlayMusicStream(music);
								if(Program.gamestate!=Program.MENU) 
								{
									musici = i;	
								}
								musicplaying = 1;
								break;
							}
						}
					}
				}
				else
				{
					GameUI.musicon = 0;
				}
			}
			else
			{
				GameUI.musicon = 0;
			}
		}
		
