		public static void VoiceNotify(int i)
		{
			if(GameUI.audioon==0)
			{
				return;
			}
			float vol = mvolume;
			if(i>=0 && i<maxnotify)
			{
				norepeats[ship.random.Next(0,30)+30] = 0;
				int rcount = 0;
				int id = i + 100000;
				for(int a = 0;a<30;a++)
				{
					if(norepeats[a+30]==id)
					{
						rcount++;
					}
				}
				if(rcount>=2)
				{
					return;
				}
				audioframe++;
				audioframe%=30;
				norepeats[audioframe+30] = id;
				Raylib.SetSoundVolume(voicenotify[i],vol*distance_multiplier);
				Raylib.PlaySound(voicenotify[i]);
			}
		}
		
