			for(int i=0;i<9;i++)
			{
				infantry_death[i] = Raylib.LoadSound("media/audio/death/death0"+(i+1)+".wav");
			}
			for(int i=9;i<20;i++)
			{
				infantry_death[i] = Raylib.LoadSound("media/audio/death/death"+(i+1)+".wav");
			}
			for(int i=0;i<20;i++)
			{
				UnloadHelper.AddSound(infantry_death[i]);
			}
			for(int i=0;i<5;i++)
			{
				building_die[i] = Raylib.LoadSound("media/audio/buildingdie/"+i+".wav");
				UnloadHelper.AddSound(building_die[i]);
			}
			ImprovedUnitSoundLoad();
			PrepareBattleAudio();
		}
		
		public static void PrepareBattleAudio()
		{
			string path = "media/audio/battle/";
			string[] files = Directory.GetFiles(path);
			if(files!=null)
			{
				int count = 0;
				for(int i=0;i<files.Length;i++)
				{
					if(files[i].IndexOf(".wav")>=0 || files[i].IndexOf(".mp3")>=0 || files[i].IndexOf(".ogg")>=0)
					{
						count++;
					}
				}
				if(count>0)
				{
					battle = new Sound[count];
					count = 0;
					for(int i=0;i<files.Length;i++)
					{
						if(files[i].IndexOf(".wav")>=0 || files[i].IndexOf(".mp3")>=0 || files[i].IndexOf(".ogg")>=0)
						{
							battle[count] = Raylib.LoadSound(files[i]);
							UnloadHelper.AddSound(battle[count]);
							count++;
						}
					}
				
				}
				else
				{
					battle = null;
				}
			}
		}
		
