		public static void AnimalNoise()
		{
			if(soundtimer.ElapsedMilliseconds<animalnoisetime)
			{
				return;
			}
			animalnoisetime = soundtimer.ElapsedMilliseconds + 300;
			int i = ship.random.Next(0,animalnoise.Length);
			float vol = mvolume;
			Raylib.SetSoundVolume(animalnoise[i],vol*distance_multiplier);
			if(GameUI.audioon==1){Raylib.PlaySound(animalnoise[i]);}
