		public static void Notification()
		{
			long time = soundtimer.ElapsedMilliseconds;
			float vol = mvolume;
			if(Math.Abs(time-lastnotificationsound)<notificationdelay)
			{
				return;
			}
			lastnotificationsound = time;
			Raylib.SetSoundVolume(notification[0],vol*distance_multiplier);
			if(GameUI.audioon==1){Raylib.PlaySound(notification[0]);}
		}
		
		public static void Battle()
		{
			if(battle==null)
			{
				return;
			}
			if(Program.gamestate!=Program.GROUNDBATTLE)
			{
				return;
			}
			if(GameUI.audioon==0)
			{
				return;
			}
			long time = soundtimer.ElapsedMilliseconds;
			if(Math.Abs(time - lastbattlesound)<1000)
			{
				return;
			}
			lastbattlesound = time;
			int i = random.Next(0,battle.Length);
			float vol = mvolume * (float)(random.NextDouble()*0.25+0.1);
			if(mvolume>0.11)
			{
				vol*=(float)(random.NextDouble()*0.6+0.2);
			}
			if(GameUI.musicon!=0)
			{
				vol*=1.25f;
			}
			Raylib.SetSoundVolume(battle[i],vol);
			Raylib.PlaySound(battle[i]);
		}
		
