		public static void RifleFire(int j)
		{
			if(Program.gamestate!=Program.GROUNDBATTLE)
			{
				return;
			}
			if(random.NextDouble()>0.05)
			{
				return;
			}
			long time = soundtimer.ElapsedMilliseconds;
			if(Math.Abs(time-lastriflesound)<rifledelay)
			{
				return;
			}
			int i = random.Next(0,4);
			//if(Raylib.IsSoundPlaying(rifle_fire[i]))
			//{
			//	return;
			//}
			float vol = (float) random.NextDouble()*0.5f+0.2f;
			if(j>=0 && j<Unit.maxunits)
			{
				vol*=(1.0f - (Unit.unitarray[j].camdist) / 600.0f);
			}
			if(vol<0)
			{
				vol=0.01f;
			}
			if(vol>1)
			{
				vol = 1;
			}
			vol*=mvolume;
			Raylib.SetSoundVolume(rifle_fire[i],vol*distance_multiplier);
			if(GameUI.audioon==1){Raylib.PlaySound(rifle_fire[i]);}
			lastriflesound = soundtimer.ElapsedMilliseconds;
		}
		
		public static void Death(int j)
		{
			if(GameUI.audioon==0)
			{
				return;
			}
			if(Program.gamestate!=Program.GROUNDBATTLE)
			{
				return;
			}
			long time = soundtimer.ElapsedMilliseconds;
			if(Math.Abs(time-lastdeathsound)<deathdelay)
			{
				return;
			}
			int i = random.Next(0,20);
			//if(Raylib.IsSoundPlaying(rifle_fire[i]))
			//{
			//	return;
			//}
			float vol = (float) random.NextDouble()*0.5f+0.2f;
			if(j>=0 && j<Unit.maxunits)
			{
				vol*=(1.0f - (Unit.unitarray[j].camdist) / 600.0f);
			}

			vol*=0.6f;
			if(vol<0)
			{
				vol=0.01f;
			}
			if(vol>1)
			{
				vol = 1;
			}
			vol*=mvolume;
			Raylib.SetSoundVolume(infantry_death[i],vol*distance_multiplier);
			if(GameUI.audioon==1){Raylib.PlaySound(infantry_death[i]);}
			lastdeathsound = soundtimer.ElapsedMilliseconds;
		}
		
		public static void Building_Death()
		{
			if(Program.gamestate!=Program.GROUNDBATTLE)
			{
				return;
			}
			if(GameUI.audioon==0)
			{
				return;
			}
			int i = random.Next(0,5);
			float vol = (float) random.NextDouble()*0.5f+0.2f;
			vol*=0.6f;
			if(vol<0)
			{
				vol=0.01f;
			}
			if(vol>1)
			{
				vol = 1;
			}
			vol*=mvolume;
			Raylib.SetSoundVolume(building_die[i],vol*distance_multiplier);
			Raylib.PlaySound(building_die[i]);
		}
		
		public static void InitAudio()
		{
			LoadAudio();
			random = new Random();
			soundtimer = new Stopwatch();
			soundtimer.Reset();
			soundtimer.Start();
		}
	}

	class Namelist
	{
		public static string[] names;
		
		public static Random random;

		public static int maxcasualties = 100000;
		public static int lastcasualty = -1;
		public static string[] casualtylist = new string[maxcasualties];
		public static int[] casualtykills = new int[maxcasualties];
		
		public static void addcasualty(string name,int kills)
		{
			if(lastcasualty>=maxcasualties-1)
			{
				return;
			}
			lastcasualty++;
			if(lastcasualty>=0 && lastcasualty<maxcasualties)
			{
				casualtylist[lastcasualty] = name;
				casualtykills[lastcasualty] = kills;
			}
		}
		
		public static void init()
		{
				names = System.IO.File.ReadAllLines("media/txt/namelist.txt");
				random = new Random();
		}
		
		public static string pickname()
		{
			if(names!=null)
			{
				int i = random.Next(0,names.Length);
				return names[i];
			}
			else
			{
				return "Johnson";
			}
		}
		
	}
	
	
	class LocalStorage //12mar2021
	{
		////////////////////////////////////////////////////
		//DOCUMENTATION
		//Handles writing data to local storage (tmp area)
		//You likely don't need to touch this
		//This is from my C# SDL2 Engine....tried and tested...it works for years....
		public static string NETTITLE = "config3049_firebase";
		public static string filename;
		public static string[] data;

///////////////////Method Definition///////////////
		//public static void ClearLog()
		//{
		//	setitem("Log"," ");
		//}
///////////////////Method Definition///////////////
		//public static void WriteLog(string value)
		//{
		//	setitem("Log",getitem("Log") + "|" + value);
		//}
///////////////////Method Definition///////////////
		public static string getitem(string name)
		{
			//return the value of a name=value pair
			//from the localstorage.txt file
			if(filename=="")
			{
				return "";
			}
			if(data==null)
			{
				return "";
			}
			for(int i=0;i<data.Length;i++)
			{
				if(data[i].IndexOf("=")>0)
				{
					if(data[i].Substring(0,data[i].IndexOf("="))==name)
					{
						return Program.readstring(data[i]);
					}
				}
			}
			return "";
		}

///////////////////Method Definition///////////////
		public static void setitem(string name,string value)
		{
			//set a value of a name=value pair
			//in the localstorage.txt file
			bool found = false;
			if(filename=="")
			{
				return;
			}
			if(data==null)
			{
				return;
			}
			for(int i=0;i<data.Length;i++)
			{
				if(data[i].IndexOf("=")>0)
				{
					if(data[i].Substring(0,data[i].IndexOf("="))==name)
					{
						found = true;
						data[i] = name+"="+value;
						break;
					}
				}
			}
			if(!found)
			{
				Array.Resize<string>(ref data,data.Length + 1);
				data[data.Length - 1] = name+"="+value;		
			}
		}

///////////////////Method Definition///////////////
		public static void init()
		{
			//setup the localstorage.txt file for use
			try
			{
				string folderd = Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData)+"\\"+NETTITLE;
				if(!Directory.Exists(folderd))
				{
					Directory.CreateDirectory(folderd);
				}
			}
			catch(Exception e)
			{
				string message = e.Message;
			}
			filename = "";
			data = null;
			try
			{
				filename = Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData)+"\\"+NETTITLE + "\\localstorage.txt";			
			}
			catch(Exception e)
			{
				Console.WriteLine("Local Storage Error:"+e.Message);
				filename = "";
			}
			if(filename!="")
			{
				try
				{
					data = System.IO.File.ReadAllLines(filename);					
				}
				catch(Exception e)
				{
					Console.WriteLine("Local Storage Error:"+e.Message);
					data = new string[0];
				}
			}
			//ClearLog();
		}

///////////////////Method Definition///////////////
		public static void finalise()
		{
			//save the localstorage.txt file to disk.
			//typically called once at exit of the game
			if(filename==null)
			{
				return;
			}		
			if(filename=="")
			{
				return;
			}
			string txt = "";
			if(data==null)
			{
				return;
			}
			for(int i=0;i<data.Length;i++)
			{
				txt+=data[i]+Environment.NewLine;
			}
			try
			{
				System.IO.File.WriteAllText(filename,txt);
			}
			catch(Exception e)
			{
				Console.WriteLine("Local Storage Error:"+e.Message);
			}
		}
	}

