		public static void LoadScenarios()
		{
				int m = 0;
				scenarios[m] = new Scenario();
				ms = new Scenario();
				try
				{
					string[] cdata = System.IO.File.ReadAllLines("media/txt/scenarios.txt");
					for(int i=0;i<cdata.Length;i++)
					{
						if(cdata[i].IndexOf("=")>0)
						{
							switch(cdata[i].Substring(0,cdata[i].IndexOf("=")))
							{
								case "mission_id":
									m = Program.readint(cdata[i]);
									if(m<0)
									{
										m=0;
									}
									if(m>maxscenarios-1)
									{
										m%=maxscenarios;
									}
									scenarios[m] = new Scenario();
								break;
								case "description":
									scenarios[m].description = Translation.translate(Program.readstring(cdata[i]));
								break;
								case "mission_length":
									scenarios[m].mission_length = Program.readint(cdata[i]);
								break;
								case "fleets_active":
									scenarios[m].fleets_active = Program.readint(cdata[i]);
								break;
