		public static void pickscenario(int i)
		{
			ms.defaults();
			if(i<0)//20aug2025 - because I noticed users didn't pick the options correctly.
			{
				i = 0;
			}
			if(i<0 || i>maxscenarios-1)
			{
				return;
			}
			scenario_in_play = i;
			ms.mission_length = scenarios[i].mission_length;
			ms.fleets_active = scenarios[i].fleets_active;
			ms.description = scenarios[i].description;
			for(int ii=1;ii<10;ii++)
			{
				ms.building_alive[ii] = scenarios[i].building_alive[ii];
			}
			ms.tank_can_build = scenarios[i].tank_can_build;
			ms.walker_can_build = scenarios[i].walker_can_build;
			ms.infantry_can_build = scenarios[i].infantry_can_build;
			ms.assault_can_build = scenarios[i].assault_can_build;
			ms.defender_can_build = scenarios[i].defender_can_build;
			ms.etank_can_deploy = scenarios[i].etank_can_deploy;
			ms.ehover_can_deploy = scenarios[i].ehover_can_deploy;
			ms.einfantry_can_deploy = scenarios[i].einfantry_can_deploy;
			ms.eassault_can_deploy = scenarios[i].eassault_can_deploy;
			ms.edefender_can_deploy = scenarios[i].edefender_can_deploy;
			ms.start_assault_number = scenarios[i].start_assault_number;
			ms.start_defender_number = scenarios[i].start_defender_number;
			ms.start_infantry_number = scenarios[i].start_infantry_number;
			ms.start_tank_number = scenarios[i].start_tank_number;
			ms.start_walker_number = scenarios[i].start_walker_number;
			
		}

		public static void SetupBattlefield()
		{
			//inc/dec unit counts until reach start_numbers
			int countassault = 0;
			int countdefender = 0;
			int countinfantry = 0;
			int counttank = 0;
			int countwalker = 0;
			for(int i=0;i<Unit.maxunits;i++)
			{
				if(Unit.unitarray[i].race==1 && Unit.unitarray[i].hp>0)
				{
					if(Unit.unitarray[i].shiptype==1)
					{
						countinfantry++;
					}
					if(Unit.unitarray[i].shiptype==11)
					{
						countassault++;
					}
					if(Unit.unitarray[i].shiptype==21)
					{
						countdefender++;
					}
					if(Unit.unitarray[i].shiptype==2)
					{
						counttank++;
					}
					if(Unit.unitarray[i].shiptype==5)
					{
						countwalker++;
					}
				}
			}
			if(countassault!=ms.start_assault_number)
			{
				for(int a=0;a<ms.start_assault_number;a++)
				{
					GameUI.BuildUnit(11);
				}
			}
			if(countdefender!=ms.start_defender_number)
			{
				for(int a=0;a<ms.start_defender_number;a++)
				{
					GameUI.BuildUnit(21);
				}
			}
			if(countinfantry!=ms.start_infantry_number)
			{
				if(countinfantry<ms.start_infantry_number)
				{
					for(int a=0;a<ms.start_infantry_number-countinfantry;a++)
					{
						GameUI.BuildUnit(1);
					}	
				}
				else
				{
					int n = countinfantry - ms.start_infantry_number;
					for(int a=0;a<n;a++)
					{
						for(int i=0;i<Unit.maxunits;i++)
						{
							if(Unit.unitarray[i].race==1 && Unit.unitarray[i].hp>0 && Unit.unitarray[i].shiptype==1)
							{
								Unit.unitarray[i].hp = 0;
								break;
							}
						}
					}
				}
				
			}
			if(counttank!=ms.start_tank_number)
			{
				for(int a=0;a<ms.start_tank_number;a++)
				{
					GameUI.BuildUnit(2);
				}
			}
			if(countwalker!=ms.start_walker_number)
			{
				for(int a=0;a<ms.start_walker_number;a++)
				{
					GameUI.BuildUnit(5);
				}
			}
			for(int i=1;i<10;i++)
			{
				if(Scenario.ms.building_alive[i]==0)
				{
					Building.buildingarray[i].hp = 0;
					Building.buildingarray[i].ohp = 0;
				}
			}
		}
		
		public void defaults()
		{
			mission_length = -1;
			fleets_active = 1;
			for(int i=1;i<10;i++)
			{
				building_alive[i] = 1;
			}
			tank_can_build = 1;
			walker_can_build = 1;
			infantry_can_build = 1;
			assault_can_build = 1;
			defender_can_build = 1;
			etank_can_deploy = 1;
			ehover_can_deploy = 1;
			einfantry_can_deploy = 1;
			eassault_can_deploy = 1;
			edefender_can_deploy = 1;
			start_tank_number = 0;
			start_walker_number = 0;
			start_assault_number = 0;
			start_defender_number = 0;
			start_infantry_number = 12;
		}
		
		
		
		
	}
	
	
}
